window.BIBLE_DEUTERO = {"version":"قانونية ثانية","books":[{"id":901,"code":"Tob","name":"طوبيا (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["كان طوبيا وهو من سبط ومدينة نفتالي التي في الجليل الاعلى فوق نحشون وراء الطريق الاخذ غربا والى يسارها مدينة صفت","قد جلي في عهد شلمناسر ملك اشور الا انه مع كونه في الجلاء لم يفارق سبيل الحق","حتى كان كل ما يتيسر له يقسمه كل يوم على من جلي معه من اخوانه الذين من جنسه","ومع انه كان احدث الجميع في سبط نفتالي لم يكن على شيء من شؤون الاحداث","وكان اذا قصدوا كلهم عجول الذهب التي عملها ياربعام ملك اسرائيل يتخلف وحده عن سائرهم","فيمضي الى اورشليم الى هيكل الرب وهناك كان يسجد للرب اله اسرائيل ويوفي جميع بواكيره واعشاره","واذا كانت السنة الثالثة كان يجعل جميع اعشاره للدخلاء والغرباء","وعلى هذا وامثاله كان مثابرا منذ صبوته على وفق شريعة الله","ولما ان صار رجلا اتخذ له امراة من سبطه اسمها حنة فولد له منها ولد فسماه باسمه","وادبه منذ صغره على تقوى الله واجتناب كل خطيئة","ولما جلي مع امراته وولده الى مدينة نينوى حيث كانت كل عشيرته","وقد كانوا كلهم ياكلون من اطعمة الامم كان هو يصون نفسه ولم يتنجس قط بماكولاتهم","ولاجل انه كان يذكر الرب بكل قلبه اتاه الله حظوة لدى الملك شلمناسر","فاطلق له ان يذهب حيثما شاء ويفعل ما يريد","فكان يطوف على كل من كان في الجلاء ويرشدهم بنصائح الخلاص","ثم انه قدم راجيس مدينة ماداي وكان معه مما اثره به الملك عشرة قناطير من الفضة","فراى بين الجمهور الغفير الذي من جنسه رجلا من سبطه يقال له غابيلوس في فاقة فدفع اليه الزنة المذكورة من الفضة بصك","و كان بعد ايام كثيرة ان مات الملك شلمناسر فملك سنحاريب ابنه مكانه فوقع بنو اسرائيل عنده موقع الكراهة","وكان طوبيا يطوف كل يوم على جميع عشيرته ويعزيهم ويؤاسي كل واحد من امواله على قدر وسعه","فيطعم الجياع ويكسو العراة ويدفن الموتى والقتلى بغيرة شديدة","ولما قفل الملك سنحاريب من ارض يهوذا هاربا من الضربة التي حاقه الله بها بسبب تجديفه وطفق لحنقه يقتل كثيرين من بني اسرائيل كان طوبيا يدفن اجسادهم","فنما ذلك الى الملك فامر بقتله وضبط جميع ماله","فهرب طوبيا بولده وزوجته عاريا واختبا لان كثيرين كانوا يحبونه","وكان بعد خمسة واربعين يوما ان قتل الملك ابناه","فعاد طوبيا الى منزله ورد عليه كل ماله"],["وكان بعد ذلك في يوم عيد الرب ان صنعت مادبة عظيمة في بيت طوبيا","فقال لابنه هلم فادع بعضا من سبطنا من المتقين لله لياكلوا معنا","فانطلق ثم عاد فاخبره ان واحدا من بني اسرائيل مذبوح ملقى في السوق فلما سمع طوبيا نهض من موضعه مسرعا وترك العشاء وبلغ الجثة وهو صائم","فرفعها وحملها الى بيته سرا ليدفنها بالتحفظ بعد مغيب الشمس","وبعد ان خبا الجثة اكل الطعام باكيا مرتعدا","فذكر الكلام الذي تكلم به الرب على لسان عاموس النبي ايام اعيادكم تتحول الى عويل ونحيب","ولما غربت الشمس ذهب ودفنها","وكان جميع ذوي قرابته يلومونه قائلين لاجل هذا امر بقتلك وما كدت تنجو من قضاء الموت حتى عدت تدفن الموتى","و اما طوبيا فاذ كان خوفه من الله اعظم من خوفه من الملك كان لا يزال يخطف جثث القتلى ويخباها في بيته فيدفنها عند انتصاف الليل","و اتفق في بعض الايام وقد تعب من دفن الموتى انه وافى بيته فرمى بنفسه الى جانب الحائط ونام","فوقع ذرق من عش خطاف في عينيه وهو سخن فعمي","و انما اذن الرب ان تعرض له هذه التجربة لتكون لمن بعده قدوة صبره كايوب الصديق","فانه اذ كان لم ينفك عن تقوى الله منذ صغره وحافظا لوصاياه لم يكن يتذمر على الله لما ناله من بلوى العمى","و لكنه ثبت في خوف الله شاكرا له طول ايام حياته","و كما كان القديس ايوب يعيره الملوك كان انسباء هذا وذووه يسخرون من عيشته قائلين","اين رجاؤك الذي لاجله كنت تبذل الصدقات وتدفن الموتى","فيزجرهم طوبيا قائلا لا تتكلموا كذا","فانما نحن بنو القديسين وانما ننتظر تلك الحياة التي يهبها الله للذين لا يصرفون ايمانهم عنه ابدا","و كانت حنة امراته تذهب كل يوم الى الحاكة وتاتي من تعب يديها بما يتاتى لها تحصيله من الميرة","و اتفق انها اخذت جديا وحملته الى البيت","فلما سمع بعلها صوت ثغاء الجدي قال انظروا لعله يكون مسروقا فردوه على اربابه اذ لا يحل لنا ان ناكل ولا نلمس شيئا مسروقا","فاجابته امراته وهي مغضبة قد وضح بطلان رجائك وصدقاتك الان قد عرفت وبهذا الكلام ومثله كانت تعيره"],["حينئذ ان طوبيا وطفق يصلي بدموع","و قال عادل انت ايها الرب وجميع احكامك مستقيمة وطرقك كلها رحمة وحق وحكم","فالان اذكرني يا رب ولا تنتقم عن خطاياي ولا تذكر ذنوبي ولا ذنوب ابائي","لانا لم نطع اوامرك فلاجل ذلك اسلمنا الى النهب والجلاء والموت واصبحنا احدوثة وعارا في جميع الامم التي بددتنا بينها","فالان يا رب عظيمة احكامك لانا لم نعمل بحسب وصاياك ولا سلكنا بخلوص امامك","و الان يارب بحسب مشيئتك اصنع بي ومر ان تقبض روحي بسلام لان الموت لي خير من الحياة","و اتفق في ذلك اليوم عينه ان سارة بنة رعوئيل في راجيس مدينة الماديين سمعت هي ايضا تعييرا من احدى جواري ابيها","لانه كان قد عقد لها على سبعة رجال وكان شيطان اسمه ازموداوس يقتلهم على اثر دخولهم عليها في الحال","و اذ كانت تنتهر الجارية لذنب اجابتها قائلة لا راينا لك ابنا ولا ابنة على الارض يا قاتلة ازواجها","اتريدين ان تقتليني كما قتلت سبعة رجال فلما سمعت هذا الكلام صعدت الى علية بيتها فاقامت ثلاثة ايام وثلاث ليال لا تاكل ولا تشرب","بل استمرت تصلي وتتضرع الى الله بدموع ان يكشف عنها هذا العار","و لما اتمت صلاتها في اليوم الثالث وباركت الرب","قالت تبارك اسمك يا اله ابائنا الذي بعد غضبه يصنع الرحمة وفي زمان البؤس يغفر الخطايا للذين يدعونه","اليك يا رب اقبل بوجهي واليك اصرف ناظري","اتوسل اليك يارب ان تحلني من وثاق هذا العار او تاخذني عن الارض","انك يارب عالم باني لم اشته رجلا قط واني قد صنت نفسي منزهة عن كل شهوة","و لم اكن قط امازج ارباب الملاهي ولا اعاشر السالكين بالطيش","و انما رضيت بان اتخذ رجلا لخوفك لا لشهوتي","و لعلي لم اكن مستاهلة لهم او لم يكونوا مستحقين لي فلعلك ابقيتني لبعل اخر","لان مشورتك لا يدركها انسان","على ان من يعبدك يوقن ان حياته ان انقضت بالمحن فستفوز باكليلها وان حلت به شدة فسينقذ وان عرض على التاديب فله ان يرجع الىرحمتك","لانك لا تسر بهلاكنا فتلقي السكينة بعد العاصفة وبعد البكاء والنحيب تفيض التهلل","فليكن اسمك يا اله اسرائيل مباركا مدى الدهور","في ذلك الحين استجيبت صلوات الاثنين امام مجد الله العلي","فارسل الرب ملاكه القديس رافائيل ليشفي كلا الاثنين اللذين رفعت صلواتهما في وقت واحد الى حضرة الرب"],["و اذ خال طوبيا ان قد استجيبت صلاته وتهيا له ان يموت استدعى اليه طوبيا ابنه","و قال له اسمع يا بني كلمات في واجعلها في قلبك مثل الاساس","اذا قبض الله نفسي فادفن جسدي واكرم والدتك جميع ايام حياتها","و اذكر ما المشقات التي عانتها لاجلك في جوفها وما كان اشدها","و متى استوفت هي ايضا زمان حياتها فادفنها الى جانبي","و انت فليكن الله في قلبك جميع ايام حياتك واحذر ان ترضى بالخطيئة وتتعدى وصايا الرب الهنا","تصدق من مالك ولا تحول وجهك عن فقير وحينئذ فوجه الرب لا يحول عنك","كن رحيما على قدر طاقتك","ان كان لك كثير فابذل كثيرا وان كان لك قليل فاجتهد ان تبذل القليل عن نفس طيبة","فانك تدخر لك ثوابا جميلا الى يوم الضرورة","لان الصدقة تنجي من كل خطيئة ومن الموت ولا تدع النفس تصير الى الظلمة","ان الصدقة هي رجاء عظيم عند الله العلي لجميع صانعيها","احذر لنفسك يا بني من كل زنى ولا تتجاوز امراتك مستبيحا معرفة الاثم ابدا","و لا تدع الكبر يستولي على افكارك واقوالك لان الكبر مبدا كل هلاك","و كل من خدمك بشيء فاوفه اجرته لساعته واجرة اجيرك لا تبق عندك ابدا","كل ما تكره ان يفعله غيرك بك فاياك ان تفعله انت بغيرك","كل خبزك مع الجياع والمساكين واكس العراة من ثيابك","ضع خبزك وخمرك على مدفن البار ولا تاكل ولا تشرب منهما مع الخطاة","التمس مشورة الحكيم دائما","و بارك الله في كل حين واسترشده لتقويم سبلك واقرار كل مشوراتك فيه","ثم اعلم يا بني اني قد اعطيت وانت صغير عشرة قناطير من الفضة لغابيلوس في راجيس مدينة الماديين ومعي بها صك","و حيث ذلك فانظر كيف تتوصل اليه فتقبض منه الزنة المذكورة من الفضة وترد عليه صكه","و لا تخف يا ولدي فانا نعيش عيشة الفقراء ولكن سيكون لنا خير كثير اذا اتقينا الله وابتعدنا عن كل خطيئة وفعلنا خيرا"],["فاجاب طوبيا اباه وقال يا ابت كل ما امرتني به افعله","و اما هذا المال فما ادري كيف احصله فان الرجل لا يعرفني وانا لا اعرفه فما العلامة التي اعطيها له بل الطريق التي تؤدي الى هناك لا اعرفها ايضا","فاجابه ابوه وقال ان عندي صكه فاذا عرضته عليه فانه يؤدي عاجلا","و الان هلم فالتمس لك رجلا ثقة يصحبك باجرته حتى تستوفي المال وانا حي","فبينما خرج طوبيا اذا بفتى بهي قد وقف مشمرا كانه متاهب للمسير","فسلم عليه وهو يجهل انه ملاك الله وقال من اين اقبلت يا فتى الخير","قال انا من بني اسرائيل فقال له طوبيا هل تعرف الطريق الاخذة الى بلاد الماديين","قال اعرفها وقد سلكت جميع طرقها مرارا كثيرة وكنت نازلا باخينا غابيلوس المقيم براجيس مدينة الماديين التي في جبل احمتا","فقال له طوبيا انتظرني حتى اخبر ابي بهذا","و دخل طوبيا واخبر اباه بجميع ذلك فتعجب ابوه وطلب ان يدخل عليه","فدخل وسلم عليه وقال ليكن لك فرح دائم","فاجاب طوبيا واي فرح يكون لي انا المقيم في الظلام لا ابصر ضوء السماء","فقال له الفتى كن طيب القلب فانك عن قليل تنال البرء من لدن الله","فقال له طوبيا هل لك ان تبلغ ابني الى غابيلوس في راجيس مدينة الماديين وانا اوفيك اجرتك متى رجعت","فقال له الملاك اخذه واعود به اليك","فقال له طوبيا اخبرني من اي عشيرة ومن اي سبط انت","فقال له رافائيل الملاك افي نسب الاجير حاجتك ام في الاجير الذي يذهب مع ابنك","و لكن لكي لا اقلق بالك انا عزريا بن حننيا العظيم","فقال له طوبيا انك من نسب كريم غير اني ارجو ان لا يسوءك كوني طلبت معرفة نسبك","فقال له الملاك هاءنذا اخذ ابنك سالما وساعود به اليك سالما","قال طوبيا انطلقا بسلام وليكن الله في طريقكما وملاكه يرافقكما","حينئذ اخذا كل ما ارادا اخذه من اهبة الطريق وودع طوبيا اباه وامه وسارا كلاهما معا","فلما فصلا جعلت امه تبكي وتقول قد اخذت عكازة شيخوختنا وابعدتها عنا","لا كان هذا المال الذي ارسلته لاجله","لقد كان في رزقنا القليل ما يكفي لان نعد النظر الى ولدنا غنى عظيما","فقال لها طوبيا لا تبكي ان ولدنا سيصل سالما ويعود الينا سالما وعيناك تبصرانه","فاني واثق بان ملاك الله الصالح يصحبه ويدبره في جميع احواله حتى يرجع الينا بفرح","فكفت امه عن البكاء عند هذا الكلام وسكتت"],["و سافر طوبيا والكلب يتبعه فبات اول منزلة بجانب نهر دجلة","و خرج ليغسل رجليه فاذا بحوت عظيم قد خرج ليفترسه","فارتاع طوبيا وصرخ بصوت عظيم قائلا يا مولاي قد اقتحمني","فقال له الملاك امسك بخيشومه واجتذبه اليك ففعل كذلك واجتذبه الى اليبس فاخذ يختبط عند رجليه","فقال له الملاك شق جوف الحوت واحتفظ بقلبه ومرارته وكبده فان لك بها منفعة لعلاج مفيد","ففعل كذلك ثم شوى من لحمه فاخذا للطريق وملحا سائره حتى يكون لهما ما يكفيهما الى ان يبلغا راجيس مدينة الماديين","ثم ان طوبيا سال الملاك وقال له نشدتك يا اخي عزريا ان تخبرني ما العلاج الذي يؤخذ من هذه الاشياء التي امرتني ان اذخرها من الحوت","فاجابه الملاك قائلا اذا القيت شيئا من قلبه على الجمر فدخانه يطرد كل جنس من الشياطين في رجل كان او امراة بحيث لا يعود يقربهماابدا","و المرارة تنفع لمسح العيون التي عليها غشاء فتبرا","و قال طوبيا اين تريد ان ننزل","فقال الملاك ان هنا رجلا اسمه رعوئيل من ذوي قرابتك من سبطك وله بنت اسمها سارة وليس له من ذكر ولا انثى سواها","فجميع ماله مستحق لك ولا بد لك ان تتخذها زوجة","فاخطبها الى ابيها فانه يزوجها منك","فاجاب طوبيا وقال اني سمعت انه قد عقد لها على سبعة ازواج فماتوا وقد سمعت ايضا ان الشيطان قتلهم","فلاجل هذا اخاف ان يصيبني مثل ذلك وانا وحيد لابوي فانزل شيخوختهما الى الجحيم بالحزن","فقال له الملاك رافائيل استمع فاخبرك من هم الذين يستطيع الشيطان ان يقوى عليهم","ان الذين يتزوجون فينفون الله من قلوبهم ويتفرغون لشهوتهم كالفرس والبغل اللذين لا فهم لهما اولئك للشيطان عليهم سلطان","فانت اذا تزوجتها ودخلت المخدع فامسك عنها ثلاثة ايام ولا تتفرغ معها الا للصلوات","و في تلك الليلة اذا احرقت كبد الحوت ينهزم الشيطان","و في الليلة الثانية تكون مقبولا في شركة الاباء القديسين","و في الليلة الثالثة تنال البركة حتى يولد لكما بنون سالمون","و بعد انقضاء الليلة الثالثة تتخذ البكر بخوف الرب وانت راغب في البنين اكثر من الشهوة لكي تنال بركة ذرية ابراهيم"],["ثم دخلا على رعوئيل فتلقاهما رعوئيل بالمسرة","و اذ نظر رعوئيل الى طوبيا قال لحنة زوجته ما اشبه هذا الرجل بذي قرابتي","و بعد هذا الكلام قال رعوئيل من اين انتما ايها الاخوان الفتيان فقالا له من سبط نفتالي من جلاء نينوى","فقال لهما رعوئيل هل تعرفان طوبيا اخي فقالا نعرفه","فلما اكثر من الثناء عليه قال الملاك لرعوئيل ان طوبيا الذي انت تسال عنه هو ابو هذا","فالقى رعوئيل بنفسه وقبله بدموع وبكى على عنقه","و قال بركة لك يا بني انك ابن رجل صالح فاضل","و بكت حنة امراته وسارة ابنتهما ايضا","و بعد ان تحادثوا امر رعوئيل ان يذبح كبش وتهيا مادبة ودعاهما ان يتكئا للغذاء","فقال طوبيا اني لا اكل اليوم طعاما ههنا ولا اشرب ما لم تجيبني الى ما انا سائله وتعدني ان تعطيني سارة ابنتك","فلما سمع رعوئيل هذا الكلام ارتعد لمعرفته بما اصاب السبعة الرجال الذين دخلوا عليها وخاف ان يصيب هذا ما اصابهم وفيما هو متردد ولم يردد عليه جوابا","قال له الملاك لا تخف ان تعطيها لهذا فان ابنتك له ينبغي ان تكون زوجة لانه يخاف الله ولذلك لم يقدر غيره ان ياخذها","حينئذ قال رعوئيل لا اشك ان الله قد تقبل صلواتي ودموعي امامه","و لعله لاجل ذلك ساقكما الله الى حتى تتزوج هذه بذي قرابتها على حسب شريعة موسى والان لا تشك اني اعطيكها","ثم اخذ بيمين ابنته سارة وسلمها الى يمين طوبيا قائلا اله ابراهيم واله اسحق واله يعقوب يكون معكما وهو يقرنكما ويتم بركته عليكما","ثم اخذوا صحيفة وكتبوا فيها عقد الزواج","و بعد ذلك اكلوا وباركوا الله","و دعا رعوئيل حنة زوجته وامرها ان تهيا مخدعا اخر","و ادخلته سارة ابنتها وهي باكية","و قالت لها تشجعي يا بنية ورب السماء يؤتيك فرحا بدل الغم الذي قاسيته"],["و لما فرغوا من العشاء ادخلوا عليها الفتى","فذكر طوبيا كلام الملاك فاخرج من كيسه فلذة من الكبد والقاها على الجمر المشتعل","حينئذ قبض الملاك رافائيل على الشيطان واوثقه في برية مصر العليا","و وعظ طوبيا البكر وقال لها يا سارة قومي نصلي الى الله اليوم وغدا وبعد غد فانا في هذه الليالي الثلاث نتحد بالله وبعد انقضاء الليلة الثالثة نكون في زواجنا","لانا بنو القديسين فلا ينبغي لنا ان نقترن اقتران الامم الذين لا يعرفون الله","فقاما معا وصليا كلاهما بحرارة حتى يعافيهما","و قال طوبيا ايها الرب اله ابائنا لتباركك السماوات والارض والبحر والينابيع والانهار وجميع خلائقك التي فيها","انت جبلت ادم من تراب الارض واتيته حواء عونا","و الان يارب انت تعلم اني لا لسبب الشهوة اتخذ اختي زوجة وانما رغبة في النسل الذي يبارك فيه اسمك الى دهر الدهور","و قالت سارة ايضا ارحمنا يا رب ارحمنا حتى نشيخ كلانا معا في عافية","و كان نحو وقت صياح الديك ان رعوئيل امر ان يجمع اليه غلمانه فانطلقوا معه واحتفروا قبرا","لانه قال اخشى ان يصيبه ما اصاب غيره من الرجال السبعة الذين دخلوا عليها","فلما اعدوا القبر رجع رعوئيل الى زوجته وقال لها","ابعثي واحدة من جواريك لترى هل مات حتى اواريه قبل ضوء النهار","فانفذت احدى جواريها فدخلت المخدع فاذا هما سالمان معافيان وهما نائمان معا","فعادت واخبرت بهذه البشرى فبارك رعوئيل وحنة زوجته الرب","قائلين نباركك ايها الرب اله اسرائيل من اجل انه لم يصبنا ما كنا نتوقعه","فانك قد اتيتنا رحمتك وحبست عنا العدو الذي يضطهدنا","و رحمت الوحيدين فاجعلهما يارب يباركانك اتم بركة ويقدمان لك قربان تسبيحك وعافيتهما حتى تعلم الامم كافة انك انت الاله الواحد في الارض كلها","و للحال امر رعوئيل غلمانه ان يردموا القبر الذي حفروه قبل ضوء الصباح","ثم اوعز الى زوجته ان تعد وليمة وتصلح ما ينبغي للمسافرين من الزاد","و امر بذبح بقرتين سمينتين واربعة اكبش وان تهيا وليمة لجميع جيرانه واصدقائه","و استحلف رعوئيل طوبيا ان يقيم عنده اسبوعين","و اعطى رعوئيل لطوبيا نصف ماله كله وكتب لطوبيا صكا بالنصف الباقي ان يستولي عليه بعد موتهما"],["ثم ان طوبيا استدعى الملاك الذي كان يحسبه انسانا وقال له يا اخي عزريا اسالك ان تسمع كلامي","اني لو جعلت نفسي عبدا لك لما وفيت بعنايتك حق الوفاء","و لكني مع ذلك اسالك ان تاخذ دواب وغلمانا وتنطلق الى غابيلوس في راجيس مدينة الماديين وترد عليه صكه وتقبض منه الفضة وتدعوه الى عرسي","لانك تعلم ان ابي يحسب الايام فان زدت في ابطائي يوما واحدا حزنت نفسه","و انت ترى ان رعوئيل قد استحلفني ولست استطيع ان استخف بحلفه","حينئذ اخذ رافائيل اربعة من غلمان رعوئيل وجملين وسافر الى راجيس مدينة الماديين ولقي غابيلوس فدفع اليه صكه واستوفى منه المال كله","و عرفه امر طوبيا بن طوبيا وكل ما وقع واتى به معه الى العرس","فلما دخل بيت رعوئيل وجد طوبيا متكئا فنهض قائما وقبلا بعضهما بعضا وبكى غابيلوس وبارك الله","و قال يباركك الرب اله اسرائيل لانك ابن رجل صالح جدا بار متقي الله صانع صدقات","و تحل البركة على زوجتك وعلى والديكما","و تريان بنيكما وبني بنيكما الى الجيل الثالث والرابع ويكون نسلكما مباركا من اله اسرائيل المالك الى دهر الدهور","فقالوا كلهم امين ثم تقدموا الى الوليمة الا انهم اتخذوا وليمة العرس بخوف الله"],["و لما ابطا طوبيا هناك لسبب العرس قلق ابوه طوبيا وقال لماذا ترى ابطا ابني وما الذي عاقه هناك","العل غابيلوس قد مات وليس من يرد له المال","و اخذه حزن شديد هو وحنة امراته وطفق كلاهما يبكيان لتخلف ابنهما عن الرجوع في يوم الميعاد","و كانت امه تبكي بدموع لا تنقطع وهي تقول اه اوه يا بني لماذا ارسلناك في الغربة يا نور ابصارنا وعكازة شيخوختنا وعزاء عيشتنا ورجاء عقبنا","لقد كان لنا فيك وحدك كل شيء فلم يكن ينبغي لنا ان نرسلك عنا","فكان طوبيا يقول لها اسكتي ولا تقلقي ان ابننا سالم والرجل الذي ارسلناه معه ثقة جدا","فلم يكن ذلك يفيدها ادنى تعزية وكانت كل يوم تقوم مسرعة فتتشوف من كل جهة وتنظر في جميع الطرق التي كانت تظن ان ابنها يرجع منها لعلها تراه عن بعد مقبلا","و اما رعوئيل فقال لصهره امكث ههنا وانا انفذ الى طوبيا ابيك من يخبره بسلامتك","فقال له طوبيا اني لاعلم ان ابي وامي يحسبان الايام وارواحهما معذبة قلقا","و بعد ان اكثر رعوئيل من الالحاح على طوبيا فابى ان يسمع بوجه من الوجوه اعطاه سارة ونصف امواله كلها من غلمان وجوار ومواش وابل وبقر وفضة كثيرة وصرفه من عنده بسلام فرحا","قائلا ملاك الرب القدوس يكون في طريقكما ويبلغكما سالمين وتجدان كل شيء عند ابويكما بخير وترى عيناي بنيكما قبل موتي","و اقبل الوالدان على ابنتهما يقبلانها ثم صرفاها","و اوصياها ان تكرم حمويها وتحب بعلها وتدبر عيالها وتسوس بيتها وتحفظ نفسها غير ملومة"],["و فيما هم راجعون وقد بلغوا الى حاران التي في وسط الطريق جهة نينوى في اليوم الحادي عشر","قال الملاك يا اخي طوبيا انك تعلم كيف فارقت اباك","فلنتقدم نحن ان احببت والعيال وزوجتك يلحقوننا على مهل مع المواشي","و اذ توافقا على المضي قال رافائيل لطوبيا خذ معك من مرارة الحوت فان لنا بها حاجة فاخذ طوبيا من المرارة وانطلقا","و اما حنة فكانت كل يوم تجلس عند الطريق على راس الجبل حيث كانت تستطيع ان تنظر على بعد","فلما كانت تتشوف ذات يوم من ذلك الموضع نظرت على بعد وللوقت عرفت انه ابنها قادما فبادرت واخبرت بعلها قائلة هوذا ابنك ات","و قال رافائيل لطوبيا اذا دخلت بيتك فاسجد في الحال للرب الهك واشكر له ثم ادن من ابيك وقبله","و اطل لساعتك عينيه بمرارة الحوت هذه التي معك واعلم انه للحين تنفتح عيناه ويرى ابوك ضوء السماء ويفرح برؤيتك","حينئذ سبق الكلب الذي كان معه في الطريق وكان كانه بشير يبدي مسرته ببصبصة ذنبه","فقام ابوه وهو اعمى وجعل يجري وهو يتعثر برجليه فناول يده لغلام وخرج لملاقاة ابنه","و استقبله وقبله هو وامراته وطفق كلاهما يبكيان من الفرح","ثم سجدوا لله وشكروا له وجلسوا","فاخذ طوبيا من مرارة الحوت وطلى عيني ابيه","و مكث مقدار نصف ساعة فبدا يخرج من عينيه غشاوة كغرقئ البيض","فامسكها طوبيا وسحبها من عينيه وللوقت عاد الى طوبيا بصره","فمجد الله هو وامراته وكل من كان يعرفه","و قال طوبيا اباركك ايها الرب اله اسرائيل لانك ادبتني وشفيتني وهاءنذا ارى طوبيا ولدي","و اما سارة كنته فوصلت بعد سبعة ايام هي وجميع العيال بسلام والغنم والابل ومال كثير مما للمراة مع المال الذي استوفاه من غابيلوس","و اخبر ابويه بجميع احسانات الله التي انعم بها عليه على يد ذلك الرجل الذي ذهب معه","و وفد على طوبيا احيور ونباط وهما ذوا قرابة له فرحين وهناه بجميع ما من الله به عليه من الخير","و عملوا وليمة سبعة ايام وفرحوا كلهم فرحا عظيما"],["حينئذ دعا طوبيا ابنه اليه وقال له ماذا ترى نعطي هذا الرجل القديس الذي ذهب معك","فاجاب طوبيا وقال لابيه يا ابت اي اجرة نعطيه واي شيء يكون موازيا لاحسانه","اخذني ورجع بي سالما والمال هو استوفاه من عند غابيلوس وبه حصلت على زوجتي وهو كف عنها الشيطان وفرح ابويها وخلصني من افتراس الحوت واياك ايضا هو جعلك تبصر نور السماء وبه غمرنا بكل خير فماذا عسى ان نعطيه مما يكون موازيا لهذه","لكني اسالك يا ابت ان نساله هل يرضى ان ياخذ النصف من كل ما جئنا به","فدعاه الوالد وولده واخذاه ناحية وجعلا يسالانه ان يتنازل ويقبل النصف من جميع ما جاءا به","حينئذ خاطبهما سرا وقال باركا اله السماء واعترفا له امام جميع الاحياء لما اتاكما من مراحمه","اما سر الملك فخير ان يكتم واما اعمال الله فاذاعتها والاعتراف بها كرامة","صالحة الصلاة مع الصوم والصدقة خير من ادخار كنوز الذهب","لان الصدقة تنجي من الموت وتمحو الخطايا وتؤهل الانسان لنوال الرحمة والحياة الابدية","و اما الذين يعملون المعصية والاثم فهم اعداء لانفسهم","اما انا فاعلن لكما الحق وما اكتم عنكما امرا مستورا","انك حين كنت تصلي بدموع وتدفن الموتى وتترك طعامك وتخبا الموتى في بيتك نهارا وتدفنهم ليلا كنت انا ارفع صلاتك الى الرب","و اذ كنت مقبولا امام الله كان لا بد ان تمتحن بتجربة","و الان فان الرب قد ارسلني لاشفيك واخلص سارة كنتك من الشيطان","فاني انا رافائيل الملاك احد السبعة الواقفين امام الرب","فلما سمعا مقالته هذه ارتاعا وسقطا على اوجههما على الارض مرتعدين","فقال لهما الملاك سلام لكم لا تخافوا","لاني لما كنت معكم انما كنت بمشيئة الله فباركوه وسبحوه","و كان يظهر لكم اني اكل واشرب معكم وانما انا اتخذ طعاما غير منظور وشرابا لا يبصره بشر","و الان قد حان ان ارجع الى من ارسلني وانتم فباركوا الله وحدثوا بجميع عجائبه","و بعد ان قال هذا ارتفع عن ابصارهم فلم يعودوا يعاينونه بعد ذلك","حينئذ لبثوا ثلاث ساعات منطرحين على وجوههم يباركون الله ثم نهضوا وحدثوا بجميع عجائبه"],["حينئذ فتح طوبيا الشيخ فاه مباركا للرب وقال عظيم انت يارب الى الابد وفي جميع الدهور ملكك","لانك تجرح وتشفي وتحدر الى الجحيم وتصعد منه وليس من يفر من يدك","اعترفوا للرب يا بني اسرائيل وسبحوه امام جميع الامم","فانه فرقكم بين الامم الذين يجهلونه لكي تخبروا بمعجزاته وتعرفوهم ان لا اله قادرا على كل شيء سواه","هو ادبنا لاجل اثامنا وهو يخلصنا لاجل رحمته","انظروا الان ما صنع لنا واعترفوا له بخوف ورعدة ومجدوا ملك الدهور باعمالكم","اما انا ففي ارض جلائي اعترف له لانه اظهر جلاله في امة خاطئة","ارجعوا الان ايها الخطاة واصنعوا امام الله برا واثقين بانه يصنع لكم رحمة","اما انا فنفسي تتهلل به","باركوا الرب يا جميع مختاريه اقيموا ايام فرح واعترفوا له","يا اورشليم مدينة الله ان الرب ادبك باعمال يديك","اشكري لله نعمته عليك وباركي اله الدهور حتى يعود فيشيد مسكنه فيك ويرد اليك جميع اهل الجلاء وتبتهجي الى دهر الدهور","تتلالئين بسنى بهيج وجميع شعوب الارض لك يسجدون","يزورك الامم من الاقاصي بقرابينهم ويسجدون فيك للرب ويعتدون ارضك ارضا مقدسة","لانهم فيك يدعون الاسم العظيم","ملعونين يكونون الذين استهانوا بك والذين جدفوا عليك يدانون ويباركك الذين يبنونك","اما انت فتفرحين ببنيك لانهم يباركون كافة والى الرب يحتشدون","طوبى للذين يحبونك ويفرحون لك بالسلام","باركي يا نفسي الرب لان الرب الهنا خلص اورشليم مدينته من جميع شدائدها","طوبى لي ان بقي من ذريتي من يبصر بهاء اورشليم","ابواب اورشليم من ياقوت وزمرد وكل محيط اسوارها من حجر كريم","و جميع اسواقها مفروشة بحجر ابيض نقي وفي شوارعها ينشد هللويا","مبارك الرب الذي عظمها وليكن ملكه فيها الى دهر الدهور امين"],["و فرغ طوبيا من كلامه وعاش طوبيا بعدما عاد بصيرا اثنتين واربعين سنة وراى بني حفدته","فتمت سنوه مئة واثنتين ودفن بكرامة في نينوى","و كان حين ذهب بصره ابن ست وخمسين سنة وعاد يبصر وهو ابن ستين سنة","و قضى بقية حياته مسرورا واذ بلغ من تقوى الله غاية حسنة انتقل بسلام","و لما حضرته الوفاة دعا ابنه طوبيا وبني ابنه السبعة الفتيان وقال لهم","قد دنا دمار نينوى لان كلام الرب لا يذهب باطلا واخوتنا الذين تفرقوا من ارض اسرائيل يرجعون اليها","و كل ارضها المقفرة ستمتلئ وبيت الله الذي احرق فيها سيستانف بناؤه وسيرجع الى هناك جميع خائفي الله","و ستترك الامم اصنامها وترحل الى اورشليم فتقيم بها","و تفرح فيها ملوك الارض كافة ساجدة لملك اسرائيل","اسمعوا يا بني لابيكم اعبدوا الرب بحق وابتغوا عمل مرضاته","و اوصوا بنيكم بعمل العدل والصدقات وان يذكروا الله ويباركوه كل حين بالحق وبكل طاقاتهم","اسمعوا لي يا بني لا تقيموا ههنا بل اي يوم دفنتم والدتكم معي في قبر واحد ففي ذلك اليوم وجهوا خطواتكم للخروج من هذا الموضع","فاني ارى ان اثمه سيهلكه","فكان ان طوبيا بعد موت امه ارتحل عن نينوى بزوجته وبنيه وبني بنيه ورجع الى حمويه","فوجدهما سالمين بشيخوخة صالحة فاهتم بهما وهو اغمض اعينهما واحرز كل ميراث بيت رعوئيل وراى بني بنيه الى الجيل الخامس","و بعد ان استوفى تسعا وتسعين سنة في مخافة الرب دفن بفرح","و لبث كل ذوي قرابته وجميع اعقابه في عيشة صالحة وسيرة مقدسة وكانوا مرضيين لدى الله والناس وجميع سكان الارض"]]},{"id":902,"code":"Jdt","name":"يهوديت (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["كان ارفكشاد ملك الماديين قد اخضع امما كثيرة لسلطانه وبنى مدينة منيعة جدا سماها احمتا","بناها من حجارة مربعة منحوتة وابتنى اسوارها على ارتفاع سبعين ذراعا في عرض ثلاثين ذراعا وشيد بروجها على ارتفاع مئة ذراع","مساحة كل جانب من مربعها عشرون قدما وجعل ابوابها في علو الابراج","و كان يفتخر بقدرته وسطوة جيشه وعزة مراكبه","و ان نبوكد نصر ملك اشور الذي كان مالكا على نينوى المدينة العظيمة في السنة الثانية عشرة من ملكه حارب ارفشكاد فظفر به","في الصحراء العظيمة التي يقال لها رعاوى عند الفرات ودجلة ويادسون في صحراء اريوك ملك عليم","فعظم اذ ذاك ملك نبوكد نصر وسمت نفسه فراسل جميع سكان قيليقية ودمشق ولبنان","و الامم التي في الكرمل وقيدار وسكان الجليل في صحراء يزرعيل الواسعة","و جميع من في السامرة وعبر الاردن الى اورشليم وفي جميع ارض يسى الى حدود الحبشة","الى جميع اولئك بعث نبوكد نصر ملك اشور رسلا","فابى جميعهم اتفاقا وردوا الرسل خائبين وطردوهم بلا كرامة","فاستشاط حينئذ نبوكد نصر الملك غضبا على تلك الارض باسرها وحلف بعرشه وملكه لينتقمن من جميع تلك البلاد"],["و في السنة الثالثة عشرة لنبوكد نصر وفي اليوم الثاني والعشرين من الشهر الاول تمت الكلمة في بيت نبوكد نصر ملك اشور بالانتقام","فدعا جميع الشيوخ وكل قواده ورجال حربه وواضعهم مشورة سرية","و قال لهم ان في نفسه ان يخضع كل الارض لملكه","و اذ حسن ذلك لدى الجميع استدعى نبوكد نصر الملك اليفانا قائد جيشه","و قال له اخرج على جميع ممالك الغرب وخصوصا الذين استهانوا باوامري","و لا تشفق عينك على مملكة ما واخضع لي جميع المدن المحصنة","فدعا اليفانا القواد وعظماء جيش اشور واحصى عدد رجال الحرب كما امره الملك مئة وعشرين الف راجل مقاتلين واثني عشر الف فارس ارباب قسي","و سير امام جيوشه عددا لا يحصى من الجمال بما يكفي الجيش بكثرة ومن اصورة البقر وقطعان الغنم ما لا يحصى","و امر ان تجمع الحنطة من كل سورية عند عبوره","و اخذ من بيت الملك من الذهب والفضة شيئا كثيرا جدا","ثم ارتحل بجميع جيشه ومراكبه وفرسانه وارباب القسي وكانوا يغطون وجه الارض كالجراد","فلما جاوز تخوم اشور انتهى الى جبال انجة العظيمة التي الى يسار قيليقية وزحف على جميع قلاعهم وتسلم كل الحصون","و فتح مدينة ملوطة المشهورة ونهب جميع بني ترشيش وبني اسماعيل الذين حيال البرية وجهة جنوب ارض كلون","ثم عبر الفرات واتى الى ما بين النهرين وقهر جميع ما هناك من المدن المشيدة من وادي ممرا الى حد البحر","و استولى على حدودها من قيليقية الى تخوم يافث التي الى الجنوب","و اسر جميع بني مدين وغنم كل ثروتهم وكل من قاومهم قتله بحد السيف","و بعد ذلك انحدر الى صحاري دمشق في ايام الحصاد واحرق جميع حقولهم وقطع كل اشجارهم وكرومهم","فوقع رعبه على جميع سكان الارض"],["حينئذ انفذ اليه جميع ملوك ورؤساء المدن والاقاليم رسلهم من سورية التي بين النهرين وسورية صوبال ولوبية وقيليقية فاتوا اليفانا وقالوا له","ليكف غضبك عنا فخير ان نحيا عبيدا لنبوكد نصر الملك العظيم وندين لك من ان نموت ونخرب ونتحمل خسف العبودية","و هذه مدائننا باسرها وجميع ما نملكه وجبالنا وهضابنا وحقولنا ومواشينا من اصورة البقر وقطعان الغنم والمعز والخيل والابل وجميع مقتنانا وعيالنا بين يديك","جميع ما هو لنا تحت امرك","و نحن وبنونا عبيد لك","فكن في قدومك علينا مولى سلام واستخدمنا بما يحسن عندك","حينئذ انحدر من الجبال مع الفرسان بقوة عظيمة واستولى على جميع المدن وكل سكان الارض","و اخذ من جميع المدن انصارا له من ذوي الباس ومختارين للحرب","فحل على جميع تلك البلدان خوف عظيم حتى خرج للقائه سكان جميع المدن الرؤساء والاشراف مع شعوبهم","و استقبلوه بالاكاليل والمصابيح راقصين بالطبول والنايات","و لا بصنعهم هذا امكنهم ان يلينوا قساوة قلبه","فانه دمر مدنهم وقطع غاباتهم","لان نبوكد نصر الملك كان قد امره ان يبيد جميع الهة الارض حتى يدعى هو وحده الها بين جميع تلك الامم التي تدين له بسطوة اليفانا","ثم عبر سورية صوبال وبامية كلها وجميع ما بين النهرين واتى الادوميين في ارض جبع","و اخذ مدائنهم واقام هناك ثلاثين يوما امر فيها ان تجمع كل قوة جيشه"],["و سمع بنو اسرائيل المقيمون بارض يهوذا فخافوا جدا من وجهه","و اخذ الارتعاد بفرائصهم مخافة ان يفعل باورشليم وبهيكل الرب كما فعل بسائر المدن وهياكلها","فارسلوا الى جميع السامرة في كل وجه الى حد اريحا وضبطوا رؤوس الجبال كلها","و سوروا قراهم وجمعوا الحنطة استعدادا للقتال","و كتب الياقيم الكاهن الى جميع الساكنين قبالة يزرعيل التي حيال الصحراء الكبيرة الى جانب دوتان والى جميع الذين يمكن ان يجاز في اراضيهم","ان يضبطوا مراقي الجبال التي يمكن ان تسلك الى اورشليم ويحفظوا المضايق التي يمكن ان يجاز منها بين الجبال","ففعل بنو اسرائيل كما رسم كاهن الرب الياقيم","و صرخ كل الشعب الى الرب بابتهال عظيم وذللوا نفوسهم بالصوم والصلاة هم ونساؤهم","و لبس الكهنة المسوح وطرحوا الاطفال امام هيكل الرب وغطوا مذبح الرب بمسح","و صرخوا جملة الى الرب اله اسرائيل ان لا يجعل اطفالهم غنيمة ونساءهم مقتسما للاعداء ومدنهم خرابا واقداسهم نجاسة واياهم عارا بين الامم","و جال الياقيم كاهن الرب العظيم في جميع اسرائيل وكلمهم قائلا","اعلموا ان الرب يستجيب لصلواتكم ان واظبتم على الصوم والصلوات امام الرب","اذكروا موسى عبد الرب كيف قهر العمالقة الذين كانوا متكلين على باسهم وقدرتهم وجيشهم وتروسهم ومراكبهم وفرسانهم فقهرهم مقاتلا لا بالسيف بل بالصلوات الطاهرة","هكذا يكون جميع اعداء اسرائيل اذا واظبتم على العمل الذي بداتم به","و اذ خاطبهم بهذا الكلام تضرعوا الى الرب وكانوا لا يبرحون من امام الرب","و كان الذين يقدمون المحرقات الى الرب لابسين المسوح يقربون ذبائح للرب والرماد على رؤوسهم","و كانوا بجملتهم يصلون الى الله من كل قلوبهم ان يفتقد شعب اسرائيل"],["و اخبر اليفانا رئيس جيش الاشوريين ان بني اسرائيل قد تاهبوا للمدافعة وانهم قد سدوا طرق الجبال","فاستشاط اليفانا غضبا في شدة حنقه ودعا جميع رؤساء مواب وقواد عمون","و قال لهم قولوا لي من اولئك الشعب الذين ضبطوا الجبال وما مدنهم وكيف هي وما قوتها وما قدرتهم وكثرتهم ومن قائد جيشهم","و كيف استخفوا بنا دون جميع سكان المشرق ولم يخرجوا لاستقبالنا ليتلقونا بالسلم","فاجابه احيور قائد جميع بني عمون قائلا ان تنازلت فسمعت لي يا سيدي اقول الحق بين يديك في امر اولئك الشعب المقيمين بالجبال ولا تخرج لفظة كاذبة من فمي","ان اولئك الشعب هم من نسل الكلدانيين","و كان اول مقامهم فيما بين النهرين لانهم ابوا اتباع الهة ابائهم المقيمين بارض الكلدانيين","فتركوا سنن ابائهم التي كانت لالهة كثيرة","و سجدوا لاله السماء الواحد وهو امرهم ان يخرجوا من هناك ويسكنوا في حاران فلما عم الجوع الارض كلها هبطوا الى مصر وتكاثروا هناك مدة اربع مئة سنة حتى كان جيشهم لا يحصى","و اذ كان ملك مصر يعنتهم بالاثقال ويستعبدهم في بناء مدنه بالطين واللبن صرخوا الى ربهم فضرب جميع ارض مصر ضربات مختلفة","و بعد ان طردهم المصريون من ارضهم وكفت الضربة عنهم ارادوا امساكهم ليردوهم الى عبوديتهم","و فيما هم هاربون فلق لهم اله السماء البحر وجمدت المياه من الجانبين فعبروا على حضيض البحر على اليبس","و تعقبهم هناك جيش المصريين بلا عدد فغمرتهم المياه حتى لم يبق منهم احد يخبر اعقابهم","فخرجوا من البحر الاحمر ونزلوا برية جبل سيناء حيث لم يكن يقدر ان يسكن انسان ولا يستريح ابن بشر","و هناك حولت لهم ينابيع المياه المرة عذبة ليشربوا ورزقوا طعاما من السماء مدة اربعين سنة","و حيثما دخلوا بلا قوس ولا سهم ولا ترس ولا سيف قاتل الههم عنهم وظفر","و لم يكن من يستهين بهؤلاء الشعب الا اذا تركوا عبادة الرب الههم","فكانوا كلما عبدوا غير الههم اسلموا للغنيمة والسيف والعار","و كلما تابوا عن تركهم عبادة الههم اتاهم اله السماء قوة للمدافعة","فكسروا امامهم ملوك الكنعانيين واليبوسيين والفرزيين والحثيين والحويين والاموريين وجميع الجبابرة الذين في حشبون واستحوذوا على اراضيهم ومدائنهم","و كانوا ما داموا لا يخطاون امام الههم يصيبهم خير لان الههم يبغض الاثم","فلما ان حادوا قبل هذه السنين عن الطريق التي امرهم الله ان يسلكوها انكسروا في الحروب امام شعوب كثيرة وجلي كثيرون منهم الى ارض غير ارضهم","غير انهم من عهد قريب قد تابوا الى الرب الههم واجتمعوا من شتاتهم حيث تبددوا وصعدوا الى هذه الجبال كلها وعادوا فتملكوا في اورشليم حيث اقداسهم","و الان يا سيدي انظر فان كان لاولئك الشعب اثم امام الههم فلنصعد اليهم لان الههم يسلمهم اليك ويستعبدون تحت نير سلطانك","و ان لم يكن لاولئك الشعب اثم امام الههم فلا طاقة لنا بهم لان الههم يدافع عنهم فنكون عارا على جميع وجه الارض","فلما فرغ احيور من هذا الكلام غضب جميع عظماء اليفانا وهموا بقتله قائلين بعضهم لبعض","من يقول ان لبني اسرائيل طاقة بمقاومة الملك نبوكد نصر وجيوشه وهم قوم لا سلاح لهم ولا قوة ولا لهم خبرة في امر الحرب","فلكي يعلم احيور انه انما يخادعنا نصعد الان الى الجبال واذا اخذ جبابرتهم فحينئذ نجعله موردا للسيف ايضا معهم","حتى تعلم كل امة ان نبوكد نصر هو اله الارض ولا اله غيره"],["فلما فرغوا من كلامهم اشتد غضب اليفانا جدا وقال لاحيور","بما انك تنبات لنا قائلا ان شعب اسرائيل يدافع عنه الهه فلكي اريك ان لا اله الا نبوكد نصر","فانا اذا ضربناهم كلهم كرجل واحد فحينئذ انت ايضا تهلك بسيف الاشوريين وجميع اسرائيل يهلكون معك","فتعلم عن خبرة ان نبوكد نصر هو رب الارض كلها وحينئذ سيف جيشي يخترق جنبيك فتسقط طعينا بين جرحى اسرائيل ولا يبقى فيك نسمة الا ريثما تستاصل معهم","و ان كنت تخال ان نبوتك صادقة فلا يسقط وجهك وليفارقك الاصفرار الذي علا وجهك ان كنت تظن ان كلامي هذا لا يمكن ان يتم","و لكي تعلم انك تختبر هذا معهم فها انك من هذه الساعة تنضم الى شعبهم واذا نالهم من سيفي عقوبة ما استحقوه فانك تكون معهم تحت طائلة الانتقام","ثم امر اليفانا عبيده ان يقبضوا على احيور وياخذوه الى بيت فلوى ويسلموه الى ايدي بني اسرائيل","فاخذه عبيد اليفانا وساروا في الصحراء ولما دنوا من الجبال خرج عليهم الرماة بالمقاليع","فانحازوا الى جانب الجبل وربطوا احيور الى شجرة بيديه ورجليه وبعد ان ربطوه هكذا بالحبال تركوه ورجعوا الى سيدهم","فنزل بنو اسرائيل من بيت فلوى واتوه فحلوه واخذوه الى بيت فلوى واقاموه في وسط الشعب وسالوه لم تركه الاشوريون مربوطا","و كان في تلك عزيا بن ميخا من سبط شمعون وكرمي الذي هو عتنيئيل اميرين هناك","فتكلم احيور بين ايدي الشيوخ وبحضرة الجميع بكل ما ذكره عن سؤال اليفانا وكيف هم قوم اليفانا ان يقتلوه بسبب هذا الكلام","و كيف امرهم اليفانا وهو مغضب ان يدفعوه الى ايدي الاسرائيليين وفي قصده انه انه متى ظفر ببني اسرائيل يامر بقتل احيور بضروب مختلفة من العذاب لاجل انه قال ان اله السماء هو المدافع عنهم","فلما قص عليهم احيور جميع ذلك خر الشعب كلهم على وجوههم ساجدين للرب ورفعوا صلواتهم الى الرب بالبكاء والعويل عامة بقلب واحد","قائلين ايها الرب اله السماء والارض انظر الى عتوهم والتفت الى تذللنا ولا تغفل وجوه قديسيك واعلن انك لم تترك المتوكلين عليك وانك تذل المتوكلين على انفسهم والمفتخرين بقوتهم","و بعد هذا البكاء وانقضاء صلاة الشعب ذلك اليوم كله عزوا احيور","قائلين اله ابائنا الذي انذرت بقوته يمن عليك بهذه المنية ان تنظر انت هلاكهم","و اذا اتى الرب الهنا عبيده هذا الخلاص فليكن هو الها لك فيما بيننا ان احببت ان تكون معنا باهلك كلهم","و لما انتهت المشورة اخذوا عزيا الى بيته وصنع له عشاء عظيما","و دعا الشيوخ كلهم فاكلوا بعد انقضاء الصوم","ثم دعوا كل الشعب وباتوا في موضع الاجتماع يصلون ويستغيثون باله اسرائيل ذلك الليل كله"],["و في اليوم الثاني امر اليفانا جميع عسكره ان يزحفوا على بيت فلوى","و كان رجالة الحرب مئة وعشرين الفا والفرسان اثنين وعشرين الفا ما خلا الرجال المجلوين وجميع الفتيان الذين استصحبهم من الاقاليم والمدن","فتاهب جميعهم لمقاتلة بني اسرائيل وجاءوا من جانب الجبل الى القمة التي تنظر الى دوتان من الموضع الذي يقال له بلما الى قليمون التي قبالة يزرعيل","فلما راى بنو اسرائيل كثرتهم خروا على الارض وحثوا الرماد على رؤوسهم وصلوا بقلب واحد الى اله اسرائيل ليظهر رحمته على شعبه","ثم اخذ كل رجل سلاحه واقاموا في الاماكن المفضية الى المضيق بين الجبال ولم يزالوا حارسين كل النهار والليل","و لما كان اليفانا يطوف في الارض وجد العين التي كانت تجري الى داخل المدينة من ناحية الجنوب لها قناة خارج المدينة فامر ان يقطعوا القناة","و كانت عيون اخر على قرب من السور كانوا يخرجون فيستقون منها خفية لكي يكسروا حدة عطشهم وان كانوا لا يرتوون","فتقدم بنو عمون ومواب الى اليفانا وقالوا له ان بني اسرائيل لا يتكلون على الرمح والسهم ولكن الجبال تزرهم والتلال التي بين الهوى تحصنهم","فالان حتى تظفر بهم بلا قتال اقم ارصادا على الينابيع لئلا يستقوا منها ماء فتقتلهم بغير سيف او يلجئهم ما يصيرون اليه من الضنك ان يسلموا مدينتهم التي يعدونها منيعة من اجل انها على الجبال","فاعجب اليفانا وسائر عبيده بهذا الكلام فجعل ارصادا على العيون من اصحاب المئة على كل عين من جميع الجهات","فاقاموا على هذه المحافظة عشرين يوما حتى جفت مياه ابار بيت فلوى وحياضها باسرها حتى لم يكن في داخل المدينة ما يرويهم يوما واحدا لان الماء كان يعطى للشعب كل يوم بمقدار","حينئذ اجتمع على عزيا جميع الرجال والنساء والشبان والاطفال وكلهم بصوت واحد","و قالوا يحكم الله بيننا وبينك فانك قد جنيت علينا شرورا اذ ابيت ان تخاطب الاشوريين بالمسالمة ولذلك باعنا الله الى ايديهم","و الان فانه ليس لنا من نصير ولكنا نصرع امام عيونهم من قبل العطش والدمار العظيم","فالان ادعوا جميع من في المدينة ولنستسلم باجمعنا الى اصحاب اليفانا من تلقاء انفسنا","فخير لنا ان نبارك الرب ونحن احياء في الجلاء من ان نموت ونكون عارا عند جميع البشر بعد ان نكون عاينا نساءنا واطفالنا يموتون امامنا","و نستحلفكم اليوم بالسماء والارض وباله ابائنا الذي ينتقم منا بحسب خطايانا ان تسلموا المدينة الى ايدي جيش اليفانا فيقضى اجلنا سريعا بحد السيف ولا يتمادى في اوار العطش","فلما قالوا هذا حدث بكاء وعويل عظيم في الجماعة كلها وصرخوا الى الله بصوت واحد ساعات كثيرة قائلين","قد خطئنا نحن واباؤنا وصنعنا الظلم والاثم","ارحمنا لانك رحيم او فانتقم عن اثامنا بان تعاقبنا انت ولا تسلم المعترفين بك الى شعب لا يعرفك","لئلا يقال في الامم اين الههم","ثم انهم كلوا من الصراخ وخاروا من البكاء فسكتوا","فقام عزيا ودموعه سائلة وقال لهم كونوا طيبي القلوب يا اخوتي ولننتظر رحمة من لدن الرب هذه الخمسة الايام","فلعله يكف غضبه ويقيم مجدا لاسمه","فاذا انقضت خمسة ايام ولم تاتنا معونة فعلنا ما تقولون"],["و لما سمعت هذا الكلام يهوديت الارملة وهي بنت مراري بن ايدوس ابن يوسف بن عزيا بن الاي ابن يمنور بن جدعون بن رفائيم بن احيطوب بن ملكيا ابن عانان بن نتنيا بن شالتيئيل بن شمعون بن راوبين","و كان بعلها منسى وقد مات في ايام حصاد الشعير","لانه كان يحث رابطي الحزم في الحقل فصخد الحر راسه فمات في بيت فلوى مدينته وقبر هناك مع ابائه","و كانت يهوديت قد بقيت ارملة منذ ثلاث سنين وستة اشهر","و كانت قد هيات لها في اعلى بيتها غرفة سرية وكانت تقيم فيها مع جواريها وتغلقها","و كان على حقويها مسح وكانت تصوم جميع ايام حياتها ما خلا السبوت ورؤوس الشهور واعياد ال اسرائيل","و كانت جميلة المنظر جدا وقد ترك لها بعلها ثروة واسعة وحشما كثيرين واملاكا مملوءة باصورة البقر وقطعان الغنم","و كانت لها شهرة بين جميع الناس من اجل انها كانت تتقي الرب جدا ولم يكن احد يقول عليها كلمة سوء","فهذه لما سمعت ان عزيا وعد بان يسلم المدينة بعد خمسة ايام انفذت الى الشيخين كبري وكرمي","فوافياها فقالت لهما ما هذا الامر الذي وافق عليه عزيا ان يسلم المدينة الى الاشوريين اذا لم تاتنا معونة الى خمسة ايام","من انتم حتى تجربوا الرب","ليس هذا بكلام يستعطف الرحمة ولكنه بالاحرى يهيج الغضب ويضرم السخط","فانكم قد ضربتم اجلا لرحمة الرب وعينتم له يوما كما شئتم","و لكن بما ان الرب طويل الاناة فلنندم على هذا ونلتمس غفرانه بالدموع المسكوبة","انه ليس وعيد الله كوعيد الانسان ولا هو يستشيط حنقا كابن البشر","لذلك فلنذلل له انفسنا ونعبده بروح متواضع","و لنسال الرب باكين ان يؤتينا رحمته بحسب مشيئته لنفتخر بتواضعنا مثلما اضطربت قلوبنا بتكبرهم","فانا لم نجر على خطايا ابائنا الذين تركوا الههم وعبدوا الهة غريبة","فاسلموا من اجل ذلك الاثم الى السيف والنهب والخزي بين اعدائهم لكنا نحن لا نعرف الها غيره","فنترجى بالتواضع تعزيته وهو ينتقم لدمنا عن اعنات اعدائنا لنا ويذل جميع الامم الواثبين علينا ويخزيهم الرب الهنا","و الان يا اخوتي بما انكم انتم شيوخ في شعب الله وبكم نفوسهم منوطة فانهضوا قلوبهم بكلامكم حتى يذكروا ان اباءنا انما ورد عليهم البلاء ليمتحنوا هل يعبدون الههم بالحق","فينبغي لهم ان يذكروا كيف امتحن ابونا ابراهيم وبعد ان جرب بشدائد كثيرة صار خليلا لله","و هكذا اسحق وهكذا يعقوب وهكذا موسى وجميع الذين رضي الله منهم جازوا في شدائد كثيرة وبقوا على امانتهم","فاما الذين لم يقبلوا البلايا بخشية الرب بل ابدوا جزعهم وعاد تذمرهم على الرب","فاستاصلهم المستاصل وهلكوا بالحيات","و اما نحن الان فلا نجزع لما نقاسيه","بل لنحسب ان هذه العقوبات هي دون خطايانا ونعتقد ان ضربات الرب التي نؤدب بها كالعبيد انما هي للاصلاح لا للاهلاك","فقال لها عزيا والشيوخ جميع مقالك حق ولا عيب في كلماتك","فالان صلي عنا لانك امراة قديسة متقية لله","فقالت لهم يهوديت كما انكم عرفتم ان ما تكلمت به هو من قبل الله","فاعلموا عن خبرة ان ما عزمت عليه هو من قبل الله وصلوا حتى يؤيد الله مشورتي","ففي هذه الليلة تقفون انتم على الباب وانا اخرج مع وصيفتي وصلوا ان ينظر الرب الى شعبه اسرائيل خمسة ايام كما قلتم","و انا لا احب ان تفحصوا عن قصدي ومن الان حتى اعلمكم به لا تصنعوا شيئا غير الصلاة عني الى الرب الهنا","فقال لها عزيا امير يهوذا اذهبي بسلام وليكن الرب معك في الانتقام من اعدائنا وانصرفوا راجعين"],["و بينما هم ذاهبون دخلت يهوديت معبدها ولبست مسحا والقت رمادا على راسها وخرت امام الرب وصرخت الى الرب قائلة","ايها الرب اله ابي شمعون الذي اعطاه سيفا لينتقم من الغرباء الذين بنجاستهم فضحوا وكشفوا عذراء للخزي","فجعلت نساءهم غنيمة وبناتهم سبيا وكل سلبهم مقتسما بين عبيدك الذين غاروا غيرتك اتوسل اليك ايها الرب الهي ان تعينني انا الارملة","فان لك الافعال الاولى وانت قدرت بعضها في عقب بعض وما اردته كان","فان طرائقك جميعها مهياة وقد اقمت احكامك بعنايتك","فانظر الان الى معسكر الاشوريين كما تنازلت فنظرت الى معسكر المصريين حين كانوا يسعون في اثر عبيدك بسلاحهم متوكلين على مراكبهم وفرسانهم وعلى كثرة رجال حربهم","حينئذ نظرت الى معسكرهم فزعجتهم الظلمة","التزقت اقدامهم بالعمق وغطتهم المياه","يا رب فليكن مثلهم هؤلاء المتوكلون على كثرة عددهم ومراكبهم وحرابهم وتروسهم وسهامهم المفتخرون برماحهم","و هم لا يعلمون انك انت الهنا الذي يمحق الحروب منذ البدء وان اسمك الرب","فارفع ذراعك كما فعلت من البدء واحطم قوتهم بقوتك ولتسقط بغضبك قوة الذين يطمعون انفسهم في ابتذال اقداسك وتنجيس مسكن اسمك وهدم قرن مذبحك بسيفهم","اجعل يا رب كبرياءه تقطع بنفس سيفه","ليصد بفخ نظره الي واضربه بعذوبة الكلام الخارج من شفتي","و هبني ثباتا في قلبي حتى ازدريه وقوة حتى اهلكه","فيكون هذا ذكرا لاسمك اذا اهلكته يد امراة","لانها ليست قوتك بالكثرة يا رب ولا مرضاتك بقدرة الخيل ومنذ البدء لا ترضى من المتكبرين بل يسرك دائما تضرع المتواضعين الودعاء","يا اله السماوات خالق المياه ورب كل خليقة استجبني انا المسكينة المتضرعة والمتوكلة على رحمتك","و اذكر يا رب ميثاقك واجعل الكلام في في وثبت مشورة قلبي ليثبت بيتك في قدسك","فيعرف جميع الامم انك انت الاله وليس اخر سواك"],["و كان لما فرغت من صراخها الى الرب انها قامت من المكان الذي كانت فيه منطرحة امام الرب","و دعت وصيفتها ونزلت الى بيتها والقت عنها المسح ونزعت عنها ثياب ارمالها","و استحمت وادهنت باطياب نفيسة وفرقت شعرها وجعلت تاجا على راسها ولبست ثياب فرحها واحتذت بحذاء ولبست الدمالج والسواسن والقرطة والخواتم وتزينت بكل زينتها","و زادها الرب ايضا بهاء من اجل ان تزينها هذا لم يكن عن شهوة بل عن فضيلة ولذلك زاد الرب في جمالها حتى ظهرت في عيون الجميع ببهاء لا يمثل","و حملت وصيفتها زق خمر واناء زيت ودقيقا وتينا يابسا وخبزا وجبنا وانطلقت","فلما بلغتا باب المدينة وجدتا عزيا وشيوخ المدينة منتظرين","فلما راوها اندهشوا وتعجبوا جدا من جمالها","غير انهم لم يسالوها عن شيء بل تركوها تجوز قائلين اله ابائنا يمنحك نعمة ويؤيد كل مشورة قلبك بقوته حتى تفتخر بك اورشليم ويكون اسمك محصى في عداد القديسين والابرار","فقال كل من هناك بصوت واحد امين امين","فخرجت يهوديت من الباب هي وامتها وكانت تصلي الى الرب","و كان انها لما نزلت من الجبل عند تبلج النهار لقيتها طلائع الاشوريين فامسكوها قائلين من اين جئت والى اين تذهبين","فاجابت اني بنت للعبرانيين وقد هربت من بينهم لاني ايقنت انهم سيكونون غنيمة لكم لانهم استخفوا بكم وابوا ان يستسلموا لكم طوعا حتى يظفروا منكم برحمة","فلاجل هذا فكرت في نفسي وقلت انطلق الى امام الامير اليفانا لاخبره باسرارهم واعلمه من اي مدخل يستطيع ان يظفر بهم ولا يقتل رجلا من جيشه","فلما سمع اولئك الرجال كلامها وهم ينظرون الى وجهها اندهشت ابصارهم لشدة تعجبهم من حسنها","فقالوا لها قد وقيت نفسك باتخاذك هذه المشورة ان تنزلي الى سيدنا","فاعلمي انك اذا وقفت بحضرته يحسن اليك وتقعين من قلبه احسن موقع ثم اخذوها الى خيمة اليفانا واخبروه بها","فلما دخلت عليه اصطيد اليفانا لساعته بعينيها","فقال له اشراطه من يزدري بشعب العبرانيين ولهم نسوة مثل هذه جميلات السن اهلا لان نقاتلهم لاجلهن","و اذ رات يهوديت اليفانا جالسا في الخيمة المنسوجة من ارجوان وذهب وزمرد وجواهر","و نظرت الى وجهه خرت له ساجدة على الارض فانهضها عبيد اليفانا بامر سيدهم"],["حينئذ قال لها اليفانا لتطب نفسك ولا يكن في قلبك روع لاني لم اضر قط برجل اثر الخضوع لنبوكد نصر الملك","و اما شعبك فلو لم يزدروا بي لما اشرعت رمحي عليهم","و الان فقولي لي لاي سبب فارقتهم واثرت المجيء الينا","فقالت له يهوديت اسمع كلام امتك فانك اذا اتبعت قول امتك يتم الرب الامر لك","ليحي نبوكد نصر ملك الارض ولتحي قوته التي فيك لتاديب جميع الانفس الغاوية لانه لا الناس فقط يخضعون له بك بل وحوش البر ايضا تنقاد له","لان ذكاء عقلك قد شاع في جميع الامم واهل العصر كلهم يعلمون انك انت وحدك صالح وجبار في جميع مملكته وحسن سياستك مشهور في جميع الاقاليم","و ليس بخاف ما تكلم به احيور ولم يجهل ما امرت ان يصيبه","و من المحقق ان الهنا قد بلغ من غضبه من الخطايا انه ارسل انبياءه الى شعبه بانه سيسلمهم لاجل خطاياهم","و لعلم بني اسرائيل بانهم قد اهانوا الههم قد حل رعبك عليهم","و فضلا عن ذلك فان الجوع قد اخذ منهم وهم معدودون في الموتى من عوز الماء","حتى عزموا ان يذبحوا بهائمهم ليشربوا دماءها","و اقداس الرب الههم التي امر الله ان لا تلمس من الحنطة والخمر والزيت قد هموا ان ينفقوها وهم يريدون ان ياكلوا ما لا يحل حتى لمسه بالايدي فحيث انهم يفعلون هذا فقد ثبت انهم سيسلمون للهلاك","و بما ان امتك قد علمت بهذا هربت من عندهم وقد بعثني الرب لاخبرك بهذا","و انا امتك اعبد الله حتى الان عندك ايضا وامتك تخرج وتصلي الى الله","فيقول لي متى يرد عليهم خطيئتهم فاجيء واخبرك بذلك حتى اخذك الى وسط اورشليم ويكون لك جميع شعب اسرائيل مثل الغنم التي لا راعيلها ولا ينبح عليك كلب","و هذه كلها قد لقنتها من عناية الله","و حيث ان الله قد غضب عليهم فانا مرسلة لاخبرك بهذه الامور","فحسن هذا الكلام كله لدى اليفانا وعبيده وكانوا يتعجبون من حكمتها ويقولون بعضهم لبعض","ليس مثل هذه المراة على الارض في المنظر والجمال والحكمة في الكلام","فقال لها اليفانا قد احسن الله اليك اذ ارسلك امام الشعب لتسلميه انت الى ايدينا","و بما ان وعدك حسن ان فعل الهك لي ذلك فهو يكون الها لي وانت تكونين عظيمة في بيت نبوكد نصر وينوه باسمك في كل الارض"],["حينئذ امرهم ان يدخلوها موضع خزائنه وامر ان تمكث هناك واوصى بما يعطى لها من مائدته","فاجابته يهوديت وقالت اني لا استطيع ان اكل مما امرت ان يعطى لي لئلا تكون علي خطيئة ولكني اكل مما اتيت به","فقال لها اليفانا اذا فرغ هذا الذي اتيت به فما نصنع بك","فقالت يهوديت تحيا نفسك يا سيدي ان امتك لا تنفق هذه جميعها حتى يصنع الله بيدي ما في خاطري فادخلها عبيده الخيمة التي امر بها","فلما صارت في داخلها سالت ان يرخص لها ان تخرج في الليل قبل الصباح لتصلي وتتضرع الى الرب","فاوصى اصحاب مخدعه ان ياذنوا لها كما تحب في ان تخرج وتدخل لتعبد الهها ثلاثة ايام","فكانت تخرج ليلا الى وادي بيت فلوى وتغتسل في عين الماء","و بعد صعودها كانت تتضرع الى اله اسرائيل ان يرشد طريقها لتخلص شعبها","ثم تدخل وتقيم في خيمتها طاهرة الى ان تاخذ طعامها في المساء","و كان في اليوم الرابع ان اليفانا صنع عشاء لعبيده وقال لبوغا خصيه انطلق الان واقنع تلك العبرانية ان ترضى بالاقامة معي طوعا","فانه عار عند الاشوريين ان تسخر المراة من الرجل وتمضي عنه نقية","فدخل حينئذ بوغا على يهوديت وقال لا تحتشمي ايتها الفتاة الصالحة ان تدخلي على سيدي وتكرمي امام وجهه وتاكلي معه وتشربي خمرا بفرح","فاجابته يهوديت من انا حتى اخالف سيدي","كل ما حسن وجاد في عينيه فانا اصنعه وكل ما يرضى به فهو عندي حسن جدا كل ايام حياتي","ثم قامت وتزينت بملابسها ودخلت فوقفت امامه","فاضطرب قلب اليفانا لانه كان قد اشتدت شهوته","و قال لها اليفانا اشربي الان واتكئي بفرح فانك قد ظفرت امامي بحظوة","فقالت يهوديت اشرب يا سيدي من اجل انها قد عظمت نفسي اليوم اكثر من جميع ايام حياتي","ثم اخذت واكلت وشربت بحضرته مما كانت قد هياته لها جاريتها","ففرح اليفانا بازائها وشرب من الخمر شيئا كثيرا جدا اكثر مما شرب في جميع حياته"],["و لما امسوا اسرع عبيده الى منازلهم واغلق بوغا ابواب المخدع ومضى","و كانوا جميعهم قد ثقلوا من الخمر","و كانت يهوديت وحدها في المخدع","و اليفانا مضطجع على السرير نائما لشدة سكره","فامرت يهوديت جاريتها ان تقف خارجا امام المخدع وتترصد","و وقفت يهوديت امام السرير وكانت تصلي بالدموع وتحرك شفتيها وهي ساكتة","و تقول ايدني ايها الرب اله اسرائيل وانظر في هذه الساعة الى عمل يدي حتى تنهض اورشليم مدينتك كما وعدت وانا اتم ما عزمت عليه واثقة باني اقدر عليه بمعونتك","و بعد ان قالت هذا دنت من العمود الذي في راس سريره فحلت خنجره المعلق به مربوطا","و استلته ثم اخذت بشعر راسه وقالت ايدني ايها الرب الاله في هذه الساعة","ثم ضربت مرتين على عنقه فقطعت راسه ونزعت خيمة سريره عن العمد ودحرجت جثته عن السرير","و بعد هنيهة خرجت وناولت وصيفتها راس اليفانا وامرتها ان تضعه في مزودها","و خرجتا كلتاهما على عادتهما كانهما خارجتان للصلاة واجتازتا المعسكر ودارتا في الوادي حتى انتهتا الى باب المدينة","فنادت يهوديت من بعد حراس السور افتحوا الابواب فان الله معنا وقد اجرى قوة في اسرائيل","فكان انه لما سمع الرجال صوتها دعوا شيوخ المدينة","و بادروا اليها جميعهم من اصغرهم الى اكبرهم لانه لم يكن في امالهم انها ترجع بعد","ثم اوقدوا مصابيح واجتمعوا حولها باسرهم فصعدت الى اعلى موضع وامرت بالسكوت فلما سكتوا كلهم","قالت يهوديت سبحوا الرب الهنا الذي لم يخذل المتوكلين عليه","و بي انا امته اتم رحمته التي وعد بها ال اسرائيل وقتل بيدي عدو شعبه هذه الليلة","ثم اخرجت راس اليفانا من المزود وارتهم اياه قائلة ها هوذا راس اليفانا رئيس جيش الاشوريين وهذه خيمة سريره التي كان مضطجعا فيها في سكره حيث ضربه الرب الهنا بيد امراة","حي الرب انه حفظني ملاكه في مسيري من ههنا وفي اقامتي هناك وفي ايابي الى هنا ولم ياذن الرب ان تتدنس امته ولكن ارجعني اليكم بغير نجاسة خطيئة فرحة بغلبته وخلاصي وخلاصكم","فاشكروا له كلكم لانه صالح لان رحمته الى الابد","فسجدوا باجمعهم للرب وقالوا لها قد باركك الرب بقوته لانه بك افنى اعداءنا","و قال لها عزيا رئيس شعب اسرائيل مباركة انت يا بنية من الرب الاله العلي فوق جميع نساء الارض","تبارك الرب الذي خلق السماء والارض الذي سدد يدك لضرب راس قائد اعدائنا","فانه عظم اليوم اسمك هكذا حتى لا يبرح مدحك من افواه الناس الذين يذكرون قوة الرب الى الابد الذين لاجلهم لم تشفقي على نفسك لاجل ضيقة وشدة جنسك بل رددت الهلاك امام الهنا","فقال كل الشعب امين امين","ثم دعوا احيور فجاء فقالت له يهوديت ان اله اسرائيل الذي شهدت له بانه ينتقم من اعدائه هو قطع في هذه الليلة بيدي راس جميع الكفار","و حتى تعلم ان الامر هكذا فهوذا راس اليفانا الذي اهان اله اسرائيل باستخفاف كبريائه وتهددك بالموت اذ قال لك اذا اسرشعب اسرائيل امر ان يخترقوا جنبيك بالسيف","فلما راى احيور راس اليفانا ارتاع خوفا وسقط بوجهه على الارض وهلعت نفسه","و بعدما ثابت اليه روحه وانتعش خر قدامها ساجدا لها وقال","مباركة انت من الهك في كل خيام يعقوب وفي كل امة يسمع فيها باسمك يعظم لاجلك اله اسرائيل"],["و قالت يهوديت لجميع الشعب اسمعوا لي يا اخوتي علقوا هذا الراس على اسوارنا","و متى طلعت الشمس فلياخذ كل واحد سلاحه واخرجوا بهجمة لا لتنحدروا الى اسفل ولكن كانكم تقصدون المهاجمة","فعند ذلك يضطر الجواسيس ان يهربوا الى رئيسهم لينبهوه للقتال","فاذا جرى قوادهم الى خيمة اليفانا يجدونه بلا راس متمرغا في دمه فيقع عليهم الذعر","فاذا علمتم انهم هاربون فاسعوا على اعقابهم امنين فان الرب يسحقهم تحت ارجلكم","و لما راى احيور القوة التي اجراها اله اسرائيل ترك سنة الامم وامن بالله وختن لحم قلفته وضم الى شعب اسرائيل هو وكل ذريته الى اليوم","و عندما تبلج النهار علقوا راس اليفانا على الاسوار واخذ كل رجل سلاحه ثم خرجوا بجلبة عظيمة وصراخ","فلما راى الجواسيس ذلك بادروا الى خيمة اليفانا","فجاء من في الخيمة وضجوا امام مدخل المخدع لينبهوه واحدثوا ضوضاء حتى يستيقظ اليفانا بضوضائهم من غير ان يوقظه احد","و لم يكن احد يجسر ان يقرع او يدخل باب مخدع قائد الاشوريين","فلما جاء قواده ورؤساء الالوف وجميع عظماء جيش ملك اشور قالوا للحجاب","ادخلوا وايقظوه لان الفئران قد خرجت من حجرتها واجترات على مهايجتنا للقتال","فحينئذ دخل بوغا مخدعه فوقف عند السجف ثم صفق بكفيه لانه كان يظن انه نائم مع يهوديت","فلما لم يشعر بحركة يسمعها دنا من السجف ورفعه فلما راى جثة اليفانا بلا راس وهي مضرجة بدمه مطروحة على الارض اعول بصوت عظيم ومزق ثيابه","ثم دخل خيمة يهوديت فلم يجدها فخرج الى الشعب خارجا","و قال امراة عبرانية بلبلت بيت الملك نبوكد نصر هوذا اليفانا مطروح على الارض بلا راس","فلما سمع رؤساء جيش الاشوريين مزقوا ثيابهم جميعا ووقع عليهم من الخوف والرعب ما لا يطاق واضطربت قلوبهم جدا","و حدث بين معسكرهم عويل لا نظير له"],["و لما سمع كل الجيش ان اليفانا قد قطع راسه طارت عقولهم ومشورتهم ولم يعودوا يبالون الا بالخوف والرعب فاستنجدوا بالهزيمة","و لم يكلم احد صاحبه بل طاطا كل منهم راسه وتركوا كل شيء وكانوا يسارعون لينجوا من العبرانيين الذين سمعوهم اتين عليهم بسلاحهم فهربوا في طرق الصحراء وشعاب التلال","فلما راهم بنو اسرائيل هاربين سعوا على اعقابهم ونزلوا وهم يهتفون بالابواق مجلبين وراءهم","و كان الاشوريون متبددين وهم مندفعون في هزيمتهم وبنو اسرائيل صبة واحدة في اثارهم فاهلكوا كل من ادركوه","و ارسل عزيا رسلا الى جميع مدن ونواحي اسرائيل","فكل بلدة ومدينة ارسلت في اثرهم شبانا منتخبين مدججين في السلاح فطردوهم بحد السيف الى ان بلغوا الى اخر تخمهم","و دخل بقية سكان بيت فلوى محلة اشور فاخذوا كل ما تركه الاشوريون عندما هربوا وكان شيئا كثيرا","و الذين رجعوا الى بيت فلوى منصورين جاءوا بجميع اموالهم حتى كانت المواشي والبهائم وجميع اثاثهم بلا عدد فاثروا جميعهم من صغيرهم الى كبيرهم من غنيمتهم","و اتى يوياقيم الكاهن العظيم من اورشليم الى بيت فلوى مع جميع شيوخه ليرى يهوديت","فلما خرجت اليه باركوها كلهم بصوت واحد قائلين انت مجد اورشليم وفرح اسرائيل وفخر شعبنا","فانك قد صنعت بباس وثبت قلبك فاحببت العفاف ولم تعرفي رجلا بعد رجلك فلهذا ايدتك يد الرب فكوني مباركة الى الابد","فقال جميع الشعب امين امين","و لم يكد شعب اسرائيل في ثلاثين يوما يجمعون غنيمة الاشوريين","و كل ما تبين انه كان من خواص اليفانا دفعوه الى يهوديت من ذهب وفضة وثياب وجواهر وامتعة كل هذه اعطاها لها الشعب","و كان جميع الشعب يفرحون مع النساء والعذارى والشبان بالاعواد والقياثير"],["حينئذ انشدت يهوديت هذا النشيد للرب فقالت","سبحوا الرب بالدفوف رنموا للرب على الصنوج انشدوا له انشادا جديدا عظموه وادعوا باسمه","الرب يمحق الحروب الرب اسمه","جعل معسكره في وسط شعبه لينقذنا من ايدي جميع اعدائنا","اتى اشور من الجبال الشمالية اتى في كثرة قوته فسدت كثرته الاودية وخيوله غطت الوهاد","قال انه سيحرق تخومي ويقتل فتياني بالسيف ويجعل اطفالي غنيمة وابكاري سبيا","الرب القدير ضربه واسلمه الى يد امراة فطعنته","ان جبارهم لم يسقط بايدي الشبان ولم يبطش به بنو طيطان ولا جبابرة طوال تعرضوا له بل يهوديت ابنة مراري بجمال وجهها اهلكته","نزعت ثياب ارمالها وتردت بثياب فرحها لابتهاج بني اسرائيل","دهنت وجهها بالطيب وضمت ضفائرها بالتاج ولبست حللها الفاخرة لتفتنه","بهاء حذائها خطف ابصاره وجمالها اسر نفسه فقطعت بالخنجر عنقه","ارتاعت فارس من ثباتها والماديون من جراتها","حينئذ اعولت محلة الاشوريين عندما ظهر متواضعي ملتهبين من العطش","بنو الجواري اثخنوهم وقتلوهم كانهم صبية منهزمون فهلكوا في القتال بين يدي الرب الهي","فلنسبح الرب تسبيحا ونرنم نشيدا جديدا لالهنا","ايها الرب ادوناي انك عظيم شهير بجبروتك ولا يقوى عليك احد","اياك فلتعبد خليقتك باسرها لانك انت قلت فكانوا ارسلت روحك فخلقوا وليس من يقاوم كلمتك","تهتز الجبال من اساسها مع المياه والصخور كالشمع تذوب امام وجهك","و الذين يتقونك يكونون اعزة عندك في كل شيء","الويل للامة القائمة على شعبي الرب القدير ينتقم منهم وفي يوم الدينونة يفتقدهم","يجعل لحومهم للنار والدود لكي يحترقوا ويتالموا الى الابد","و كان بعد هذا ان جميع الشعب بعد غلبتهم جاءوا الى اورشليم ليسجدوا للرب ولما تطهروا قدموا جميعهم محرقاتهم ونذورهم واوعادهم","و يهوديت ايضا قدمت جميع ادوات حرب اليفانا التي اعطاها لها الشعب والخيمة التي اخذتها من سريره ابسال نسيان","و كان الشعب مسرورين بمشاهدة المقدسات وعيدوا لفرح هذه الغلبة مع يهوديت ثلاثة اشهر","و بعد تلك الايام رجع كل واحد الى بيته وعظمت يهوديت في بيت فلوى جدا وكانت اجل من في جميع ارض اسرائيل","و كان فيها العفاف مقرونا بالشجاعة ولم تعد تعرف رجلا كل ايام حياتها منذ وفاة منسى بعلها","و كانت في الاعياد تظهر بمجد عظيم","و بقيت في بيت بعلها مئة وخمس سنين واعتقت وصيفتها وتوفيت ودفنت مع بعلها في بيت فلوى","فناح عليها جميع الشعب سبعة ايام","و لم يكن مدة حياتها كلها من يقلق اسرائيل ولا بعد موتها سنين كثيرة","و احصي يوم هذه الغلبة عند العبرانيين في عداد الايام المقدسة واليهود يعيدونه منذ ذلك الوقت الى يومنا هذا"]]},{"id":903,"code":"EstG","name":"تتمة أستير (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["و قال مردكاي ان هذا كله انما كان من قبل الله","و قد ذكرت حلما رايته يشير الى ذلك فلم يسقط منه شيء","ينبوع صغير ازداد فصار نهرا ثم انقلب فصار نورا وشمسا وفاض بمياه كثيرة فهذا هو استير التي اتخذها الملك زوجة وشاء ان تكون ملكة","و التنينان انا وهامان","و الامم المجتمعون هم الذين طلبوا ان يمحوا اسم اليهود","و شعبي هو اسرائيل الذي صرخ الى الرب فانقذ الرب شعبه وخلصنا من جميع الشرور وصنع ايات عظيمة ومعجزات في الامم","و امر ان يكون سهمان احدهما لشعب الله والاخر لجميع الامم","فبرز السهمان امام الله في اليوم المسمى منذ ذلك الزمان لجميع الامم","و ذكر الرب شعبه ورحم ميراثه","لذلك يحفظ هذان اليومان من شهر اذار اليوم الرابع عشر والخامس عشر من هذا الشهر بكل غيرة وفرح فيجتمع الشعب جماعة واحدة في كل اجيال شعب اسرائيل فيما بعد"],["كان في السنة الرابعة من ملك تلماي وكلوبطرا ان دوسيتاوس الذي كان يقول عن نفسه انه كاهن ومن نسل لاوي وابنه تلماي اتيا برسالة فوريم هذه قائلين انها قد ترجمت في اورشليم بيد لوسيماكوس بن تلماي","و كان في السنة الثانية من ملك ارتحششتا الاكبر في اليوم الاول من شهر نيسان ان مردكاي بن يائير بن شمعي بن قيش من سبط بنيامين راى حلما","و هو رجل يهودي مقيم بمدينة شوشن رجل عظيم من عظماء بلاط الملك","و كان من جملة اهل الجلاء الذين اخذهم نبوكد نصر ملك بابل من اورشليم مع يكنيا ملك يهوذا","و هذا حلمه راى كان اصواتا وضوضاء ورعودا وزلازل واضطرابا في الارض","ثم اذا بتنينين عظيمين متهيئان للاقتتال","و قد تهيجت كل الامم باصواتهما لتقاتل شعب الابرار","و كان ذلك اليوم يوم ظلمة وهول وشدة وضنك ورعب عظيم على الارض","فاضطرب شعب الابرار خوفا من شرورهم متوقعين الموت","و صرخوا الى الله وفيما هم يصرخون اذا بينبوع صغير قد تكاثر حتى صار نهرا عظيما وفاض بمياه كثيرة","ثم اشرق النور والشمس فارتفع المتواضعون وافترسوا المتجبرين","فلما راى مردكاي ذلك ونهض من مضجعه كان يفكر في ماذا يريد الله ان يفعل وكان ذلك لا يبرح من نفسه وهو يرغب ان يعرف ما معنى الحلم"],["و كان حينئذ يقف بباب الملك مع بجتان وتارش خصيي الملك وهما حاجبا البلاط","فبعد ان وقف على نواياهما وتقصى مدققا علم انهما يحاولان ان يلقيا ايديهما على الملك ارتحششتا فاطلع الملك على ذلك","فالقاهما تحت العذاب فاقرا فامر بان يساقا الى الموت","و كتب الملك ما وقع في سفر اخبار الايام وكذلك مردكاي كتب ذكر الامر","ثم امره الملك ان يقيم ببيت الملك وامر له بهبات لانه اطلعه على ذلك","و كان هامان بن همداتا الاجاجي له عند الملك كرامة عظيمة فاراد ان يؤذي مردكاي وشعبه بسبب خصيي الملك المقتولين"],["من ارتحششتا الاكبر المالك من الهند الى الحبشة على المئة والسبعة والعشرين اقليما الى الرؤساء والقواد الذين في طاعته سلام","اني مع كوني متسلطا على شعوب كثيرين وقد اخضعت المسكونة باسرها تحت يدي لم احب ان اسيء انفاذ مقدرتي العظيمة ولكني حكمت بالرحمة والحلم حتى يقضوا حياتهم بلا خوف وبسكينة ويتمتعوا بالسلام الذي يصبو اليه كل بشر","فسالت اصحاب مشورتي كيف يتم ذلك فكان ان واحدا منهم يفوق من سواه في الحكمة والامانة وهو ثنيان الملك اسمه هامان","قال لي ان في المسكونة شعبا متشتتا له شرائع جديدة يتصرف بخلاف عادة جميع الامم ويحتقر اوامر الملوك ويفسد نظام جميع الامم بفتنته","فلما وقفنا على هذا وراينا ان شعبا واحدا متمرد على الناس طائفة تتبع شرائع فاسدة وتخالف اوامرنا وتقلق سلام واتفاق جميع الاقاليم الخاضعة لنا","امرنا ان كل من يشير اليهم هامان المولى على جميع الاقاليم وثنيان الملك الذي نكرمه بمنزلة اب يبادون بايدي اعدائهم هم ونساؤهم واولادهم ولا يرحمهم احد في اليوم الرابع عشر من الشهر الثاني عشر شهر اذار من هذه السنة","حتى اذا هبط اولئك الناس الخبثاء الى الجحيم في يوم واحد يرد الى مملكتنا السلام الذي اقلقوه","فاما مردكاي فتضرع الى الرب متذكرا جميع اعماله","و قال اللهم ايها الرب الملك القادر على الكل اذ كل شيء في طاعتك وليس من يقاوم مشيئتك اذا هممت بنجاة اسرائيل","انت صنعت السماء والارض وكل ما تحت السماوات","انت رب الجميع وليس من يقاوم عزتك","انك تعرف كل شيء وتعلم اني لا تكبرا ولا احتقارا ولا رغبة في شيء من الكرامة فعلت هذا اني لم اسجد لهامان العاتي","فاني مستعد ان اقبل حتى اثار قدميه عن طيب نفس لاجل نجاة اسرائيل","و لكن خفت ان احول كرامة الهي الى انسان واعبد احدا سوى الهي","فالان ايها الرب الملك اله ابراهيم ارحم شعبك لان اعداءنا يطلبون ان يهلكونا ويستاصلوا ميراثك","لا تهمل نصيبك الذي افتديته لك من مصر","و استجب لتضرعي واعطف على نصيبك وميراثك وحول حزننا فرحا لنحيا ونسبح اسمك ايها الرب ولا تسدد افواه المرنمين لك","و كذلك جميع اسرائيل بروح واحد وتضرع واحد صرخوا الى الرب من اجل ان الموت اشرف عليهم يقينا"],["و ان استير الملكة ايضا التجئت الى الرب خوفا من الخطر المشرف","فخلعت ثياب الملك ولبست ثيابا للحزن والبكاء وعوض الاطياب المختلفة القت على راسها رمادا وزبلا وذللت جسدها بالصوم وجميع المواضع التي كانت تفرح فيها من قبل ملاتها من نتاف شعر راسها","و كانت تتضرع الى الرب اله اسرائيل قائلة ايها الرب الذي هو وحده ملكنا اعني انا المنقطعة التي ليس لها معين سواك","فان خطري بين يدي","لقد سمعت من ابي انك ايها الرب اتخذت اسرائيل من جميع الامم واباءنا من جميع اسلافهم الاقدمين لتحوزهم ميراثا ابديا وصنعت معهم كما قلت","انا قد خطئنا امامك ولذلك اسلمتنا الى ايدي اعدائنا","لانا عبدنا الهتهم وانت عادل ايها الرب","و الان لم يكفهم انهم استعبدونا عبودية شاقة جدا بل بما انهم يعزون قوة ايديهم الى اوثانهم","يحاولون ان ينقضوا مواعيدك ويمحوا ميراثك ويسدوا افواه المسبحين لك ويطفئوا مجد هيكلك ومذبحك","ليفتحوا افواه الامم فيسبحوا لقوة الاوثان ويمجدوا ملكا بشريا الى الابد","لا تسلم ايها الرب صولجانك الى من ليسوا بشيء لئلا يضحكوا من هلاكنا ولكن اردد مشورتهم عليهم واهلك الذي ابتدا يشدد علينا","اذكرنا يا رب واستعلن لنا في وقت ضنكنا وهبني ثقة ايها الرب ملك الالهة وملك كل قدرة","الق في فمي كلاما مرصفا بحضرة ذاك الاسد وحول قلبه الى بغض عدونا لكي يهلك هو وسائر المتواطئين معه","و ايانا فانقذنا بيدك واعني انا التي لا معونة لها سواك ايها الرب العالم بكل شيء","انك تعلم اني ابغض مجد الظالمين واكره مضجع القلف وجميع الغرباء","و انت عالم بضرورتي واني اكره سمة ابهتي ومجدي التي احملها على راسي ايام بروزي وامقتها كفرصة الطامث ولا احملها في ايام قراري","و اني لم اكل على مائدة هامان ولا لذذت بوليمة الملك ولم اشرب خمر السكب","و لم افرح انا امتك منذ نقلت الى ههنا الى اليوم الا بك ايها الرب اله ابراهيم","الاله القدير على الجميع فاستجب لاصوات الذين ليس لهم رجاء غيرك ونجنا من ايدي الاثماء وانقذني من مخافتي"],["و امرها ان تدخل على الملك وتتوسل اليه لاجل شعبها وارضها","و قال اذكري ايام مذلتك حيث نشات على يدي فان هامان ثنيان الملك قد تكلم في اهلاكنا","فادعي الرب وكلمي الملك في امرنا وخلصينا من الموت","ثم انها في اليوم الثالث نزعت ثياب حدادها ولبست ملابس مجدها","و لما تبرجت ببزة الملك ودعت مدبر ومخلص الجميع الله اتخذت لها جاريتين","فكانت تستند الى احداهما كانها لم تكن تستطيع ان تستقل لكثرة ترفها ورخوصتها","و الجارية الاخرى كانت تتبع مولاتها رافعا اذيالها المنسحبة على الارض","و كان احمرار وجهها وجمال عينيها ولمعانهما يخفي كابة نفسها المنقبضة بشدة خوفها","فدخلت كل الابواب بابا بابا ثم وقفت قبالة الملك حيث كان جالسا على عرش ملكه بلباس الملك مزينا بالذهب والجواهر ومنظره رهيب","فلما رفع وجهه ولاح من اتقاد عينيه غضب صدره سقطت الملكة واستحال لون وجهها الى صفرة واتكات راسها على الجارية استرخاء","فحول الله روح الملك الى الحلم فاسرع ونهض عن العرش مشفقا وضمها بذراعيه حتى ثابت الى نفسها وكان يلاطفها بهذاالكلام","ما لك يا استر انا اخوك لا تخافي","انك لا تموتين انما الشريعة ليست عليك ولكن على العامة","هلمي والمسي الصولجان","و اذ لم تزل ساكتة اخذ صولجان الذهب وجعله على عنقها وقبلها وقال لماذا لا تكلمينني","فاجابت وقالت اني رايتك يا سيدي كانك ملاك الله فاضطرب قلبي هيبة من مجدك","لانك عجيب جدا يا سيدي ووجهك مملوء نعمة","و فيما هي تتكلم سقطت ثانية وكاد يغشى عليها","فاضطرب الملك وكان جميع اعوانه يلاطفونها"],["من ارتحششتا العظيم المالك من الهند الى الحبشة الى القواد والرؤساء في المئة والسبعة والعشرين اقليما التي في طاعتنا سلام","ان كثيرين يسيئون اتخاذ المجد الممنوح لهم فيتكبرون","و يجتهدون لا ان يظلموا رعية الملوك فقط ولكن اذ لا يحسنون تحمل المجد الممنوح لهم يتامرون على الذين منحوه لهم","و لا يكتفون بان لا يشكروا على الانعام وان ينابذوا الحقوق الانسانية بل يتوهمون انهم يستطيعون ان يفروا من قضاء الله المطلع على كل شيء","و قد بلغ من حماقتهم انهم يحاولون بمكايد اكاذيبهم ان يسقطوا الذين سلمت اليهم المناصب وهم يجرونها بالتحري ويفعلون كل مايستاهلون به شكر الجميع","و يخدعوا باحتيال مكرهم مسامع الرؤساء السليمة الذين يقيسون طباع غيرهم على طباعهم","و هذا امر مختبر من التواريخ القديمة ومما يحدث كل يوم ان دسائس البعض تفسد خواطر الملوك الصالحة","فلذلك ينبغي ان ينظر في سلم جميع الاقاليم","فلا ينبغي ان يظن اننا نامر باشياء متباينة عن خفة عقل بل ذلك ناشئ عن اختلاف الازمنة وضروراتها التي حملتنا على ابراز الحكم بحسب مقتضى نفع الجميع","و لكي تفهموا كلامنا باوضح بيانا فان هامان بن همداتا الذي هو مكدوني جنسا ومشربا وهو غريب عن دم الفرس وقد فضح رحمتنا بقساوته بعد ان اويناه غريبا","و بعدما احسنا اليه حتى كان يدعى ابا لنا وكان الجميع يسجدون له سجودهم لثنيان الملك","قد بلغ من شدة عتوه انه اجتهد ان يسلبنا الملك والحياة","لانه سعى بدسائس جديدة لم تسمع باهلاك مردكاي الذي انما نحن في الحياة من امانته واحسانه وباهلاك قرينة ملكنا استير وسائر شعبها","و كان في نفسه انه بعد قتلهم يترصد لنا في خلوتنا ويحول مملكة الفرس الى المكدونيين","و نحن لم نجد قط ذنبا في اليهود المقضي عليهم بالموت بقضاء اخبث البشر بل بعكس ذلك وجدنا ان لهم سننا عادلة","و هم بنو الله العلي العظيم الحي الى الابد الذي باحسانه سلم الملك الى ابائنا والينا وما برح محفوظا الى اليوم","و حيث ذلك فاعلموا ان الرسائل التي وجهها باسمنا هي باطلة","و بسبب تلك الجريمة قد علق امام ابواب هذه المدينة شوشن هو صاحب تلك المؤامرة وجميع انسبائه على خشبات فنال بذلك جزاء ما استحق من قبل الله لا من قبلنا","فليعلن هذا الامر الذي نحن منفذوه الان في جميع المدن ليباح لليهود ان يعملوا بسننهم","و ينبغي لكم ان تعضدوهم حتى يستمكنوا من قتل الذين كانوا متاهبين لقتلهم في اليوم الثالث عشر من الشهر الثاني عشر الذي يدعى اذار","فان ذلك اليوم الذي كان لهم يوم حزن ونحيب قد حوله لهم الله القدير الى فرح","و انتم ايضا فانظموا هذا اليوم بين سائر ايام الاعياد الاخرى وعيدوه بكل فرح حتى يعلم فيما بعد","ان كل من يطيع الفرس بامانة يثاب على امانته ثوابا وافيا ومن يرصد لملكهم يهلك بجنايته","و كل اقليم او مدينة يابى ان يشترك في هذا العيد فليهلك بالسيف والنار لا الناس فقط بل البهائم ايضا ليكون الى الابد عبرة للاستخفاف والعصيان"]]},{"id":904,"code":"Ps151","name":"مزمور 151 (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["المزمور المائة والحادي والخمسون","1- انا صغيرا كنت في اخوتي، وحدثا في بيت ابي، كنت راعيا غنم ابي .","2- يداي صنعتا الارغن، واصابعي الفت المزمار . هلليلويا","3- من هو الذي يخبر سيدي، هو الرب الذي يستجيب للذين يصرخون اليه .","4- هو ارسل ملاكه، وحملني ( واخذني ) من غنم ابي ومسحني بدهن مسحته . هلليلويا","5- اخوتي حسان وهم اكبر مني والرب لم يسر بهم .","6- خرجت للقاء الفلسطيني فلعنني باوثانه .","7- و لكن انا سللت سيفه الذي كان بيده، وقطعت راسه .","8- ونزعت العار عن بني اسرائيل . هلليلويا"]]},{"id":905,"code":"Wis","name":"حكمة سليمان (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["احبوا العدل يا قضاة الارض واعتقدوا في الرب خيرا والتمسوه بقلب سليم","فانما يجده الذين لا يجربونه ويتجلى للذين لا يكفرون به","لان الافكار الزائغة تقصي من الله واختبار قدرته يثقف الجهال","ان الحكمة لا تلج النفس الساعية بالمكر ولا تحل في الجسد المسترق للخطية","لان روح التاديب القدوس يهرب من الغش ويتحول عن الافكار السفيهة وينهزم اذا حضر الاثم","ان روح الحكمة محب للانسان فلا يبرئ المجدف مما نطق لان الله ناظر لكليتيه ورقيب لقلبه لا يغفل وسامع لفمه","لان روح الرب ملا المسكونة وواسع الكل عنده علم كل كلمة","فلذلك لا يخفى عليه ناطق بسوء ولا ينجو من القضاء المفحم","لكن سيفحص عن افكار المنافق وكل ما سمع من اقواله يبلغ الى الرب فيحكم على اثامه","لان الاذن الغيرى تسمع كل شيء وصياح المتذمرين لا يخفى عليها","فاحترزوا من التذمر الذي لا خير فيه وكفوا السنتكم عن الثلب فان المنطوق به في الخفية لا يذهب سدى والفم الكاذب يقتل النفس","لا تغاروا على الموت في ضلال حياتكم ولا تجلبوا عليكم الهلاك باعمال ايديكم","اذ ليس الموت من صنع الله ولا هلاك الاحياء يسره","لانه انما خلق الجميع للبقاء فمواليد العالم انما كونت معافاة وليس فيها سم مهلك ولا ولاية للجحيم على الارض","لان البر خالد","لكن المنافقين هم استدعوا الموت بايديهم واقوالهم ظنوه حليفا لهم فاضمحلوا وانما عاهدوه لانهم اهل ان يكونوا من حزبه"],["فانهم بزيغ افكارهم قالوا في انفسهم ان حياتنا قصيرة شقية وليس لممات الانسان من دواء ولم يعلم قط ان احدا رجع من الجحيم","انا ولدنا اتفاقا وسنكون من بعد كانا لم نكن قط لان النسمة في انافنا دخان والنطق شرارة من حركة قلوبنا","فاذا انطفات عاد الجسم رمادا وانحل الروح كنسيم رقيق وزالت حياتنا كاثر غمامة واضمحلت مثل ضباب يسوقه شعاع الشمس ويسقط بحرها","و بعد حين ينسى اسمنا ولا يذكر احد اعمالنا","انما حياتنا ظل يمضي ولا مرجع لنا بعد الموت لانه يختم علينا فلا يعود احد","فتعالوا نتمتع بالطيبات الحاضرة ونبتدر منافع الوجود ما دمنا في الشبيبة","و نترو من الخمر الفاخرة ونتضمخ بالادهان ولا تفتنا زهرة الاوان","و نتكلل بالورد قبل ذبوله ولا يكن مرج الا تمر لنا فيه لذة","و لا يكن فينا من لا يشترك في لذاتنا ولنترك في كل مكان اثار الفرح فان هذا حظنا ونصيبنا","لنجر على الفقير الصديق ولا نشفق على الارملة ولا نهب شيبة الشيخ الكثير الايام","و لتكن قوتنا هي شريعة العدل فانه من الثابت ان الضعف لا يغني شيئا","و لنكمن للصديق فانه ثقيل علينا يقاوم اعمالنا ويقرعنا على مخالفتنا للناموس ويفضح ذنوب سيرتنا","يزعم ان عنده علم الله ويسمي نفسه ابن الرب","و قد صار لنا عذولا حتى على افكارنا","بل منظره ثقيل علينا لان سيرته تخالف سيرة الناس وسبله تباين سبلهم","قد حسبنا كزيوف فهو يجانب طرقنا مجانبة الرجس ويغبط موت الصديقين ويتباهى بان الله ابوه","فلننظر هل اقواله حق ولنختبر كيف تكون عاقبته","فانه ان كان الصديق ابن الله فهو ينصره وينقذه من ايدي مقاوميه","فلنمتحنه بالشتم والعذاب حتى نعلم حلمه ونختبر صبره","و لنقض عليه باقبح ميتة فانه سيفتقد كما يزعم","هذا ما ارتاوه فضلوا لان شرهم اعماهم","فلم يدركوا اسرار الله ولم يرجوا جزاء القداسة ولم يعتبروا ثواب النفوس الطاهرة","فان الله خلق الانسان خالدا وصنعه على صورة ذاته","لكن بحسد ابليس دخل الموت الى العالم","فيذوقه الذين هم من حزبه"],["اما نفوس الصديقين فهي بيد الله فلا يمسها العذاب","و في ظن الجهال انهم ماتوا وقد حسب خروجهم شقاء","و ذهابهم عنا عطبا اما هم ففي السلام","و مع انهم قد عوقبوا في عيون الناس فرجاؤهم مملوء خلودا","و بعد تاديب يسير لهم ثواب عظيم لان الله امتحنهم فوجدهم اهلا له","محصهم كالذهب في البودقة وقبلهم كذبيحة محرقة","فهم في وقت افتقادهم يتلالاون ويسعون سعي الشرار بين القصب","و يدينون الامم ويتسلطون على الشعوب ويملك ربهم الى الابد","المتوكلون عليه سيفهمون الحق والامناء في المحبة سيلازمونه لان النعمة والرحمة لمختاريه","اما المنافقون فسينالهم العقاب الخليق بمشوراتهم اذ استهانوا بالصديق وارتدوا عن الرب","لان مزدري الحكمة والتاديب شقي انما رجاؤهم باطل واتعابهم بلا ثمرة واعمالهم لا فائدة فيها","نساوهم سفيهات واولادهم اشرار","و نسلهم ملعون اما العاقر الطاهرة التي لم تعرف المضجع الفاحش فطوبى لها انها ستحوز ثمرتها في افتقاد النفوس","و طوبى للخصي الذي لم تباشر يده ماثما ولا افتكر قلبه بشر على الرب فانه سيعطى نعمة سامية لامانته وحظا شهيا في هيكل الرب","لان ثمرة الاتعاب الصالحة فاخرة وجرثومة الفطنة راسخة","اما اولاد الزناة فلا يبلغون اشدهم وذرية المضجع الاثيم تنقرض","ان طالت حياتهم فانهم يحسبون كلا شيء وفي اواخرهم تكون شيخوختهم بلا كرامة","و ان ماتوا سريعا فلا يكون لهم رجاء ولا عزاء في يوم الحساب","لان عاقبة الجيل الاثيم هائلة"],["ان البتولية مع الفضيلة اجمل فان معها ذكرا خالدا لانها تبقى معلومة عند الله والناس","اذا حضرت يقتدى بها واذا غابت يشتاق اليها ومدى الدهور تفتخر باكليل الظفر بعد انتصارها في ساحة المعارك الطاهرة","اما لفيف المنافقين الكثير التوالد فلا ينجح وفراخهم النغلة لا تتعمق اصولها ولا تقوم على ساق راسخة","و ان اخرجت فروعا الى حين فانها لعدم رسوخها تزعزعها الريح وتقتلعها الزوبعة","فتنقصف فروعها قبل اناها وتكون ثمرتها خبيثة غير ناضجة للاكل ولا تصلح لشيء","و المولودون من المضجع الاثيم يشهدون بفاحشة والديهم عند استنطاق حالهم","اما الصديق فانه وان تعجله الموت يستقر في الراحة","لان الشيخوخة المكرمة ليست هي القديمة الايام ولا هي تقدر بعدد السنين","و لكن شيب الانسان هو الفطنة وسن الشيخوخة هي الحياة المنزهة عن العيب","انه كان مرضيا لله فاحبه وكان يعيش بين الخطاة فنقله","خطفه لكي لا يغير الشر عقله ولا يطغي الغش نفسه","لان سحر الاباطيل يغشي الخير ودوار الشهوة يطيش العقل السليم","قد بلغ الكمال في ايام قليلة فكان مستوفيا سنين كثيرة","و اذ كانت نفسه مرضية للرب فقد اخرج سريعا من بين الشرور اما الشعوب فابصروا ولم يفقهوا ولم يجعلوا هذا فيقلوبهم","ان نعمته ورحمته لمختاريه وافتقاده لقديسيه","لكن الصديق الذي قد مات يحكم على المنافقين الباقين بعده الشبيبة السريعة الكمال تحكم على شيخوخة الاثيم الكثيرة السنين","فانهم يبصرون موت الحكيم ولا يفقهون ماذا اراد الرب به ولماذا نقله الى عصمته","يبصرون ويزدرون والرب يستهزئ بهم","سيسقطون من بعد سقوطا مهينا ويكونون عارا بين الاموات مدى الدهور فانه يحطمهم وهم مبلسون مطرقون ويقتلعهم من الاسس ويتم خرابهم فيكونون في العذاب وذكرهم يهلك","يتقدمون فزعين من تذكر خطاياهم واثامهم تحجهم في وجوههم"],["حينئذ يقوم الصديق بجراة عظيمة في وجوه الذين ضايقوه وجعلوا اتعابه باطلة","فاذا راوه يضطربون من شدة الجزع وينذهلون من خلاص لم يكونوا يظنونه","و يقولون في انفسهم نادمين وهم ينوحون من ضيق صدرهم هذا الذي كنا حينا نتخذه سخرة ومثلا للعار","و كنا نحن الجهال نحسب حياته جنونا وموته هوانا","فكيف اصبح معدودا في بني الله وحظه بين القديسين","لقد ضللنا عن طريق الحق ولم يضئ لنا نور البر ولم تشرق علينا الشمس","اعيينا في سبل الاثم والهلاك وهمنا في متايه لا طريق فيها ولم نعلم طريق الرب","فماذا نفعتنا الكبرياء وماذا افادنا افتخارنا بالاموال","قد مضى ذلك كله كالظل وكالخبر السائر","او كالسفينة الجارية على الماء المتموج التي بعد مرورها لا تجد اثرها ولا خط حيزومها في الامواج","او كطائر يطير في الجو فلا يبقى دليل على مسيره يضرب الريح الخفيفة بقوادمه ويشق الهواء بشدة سرعته وبرفرفة جناحيه يعبر ثم لا تجد لمروره من علامة","او كسهم يرمى الى الهدف فيخرق به الهواء ولوقته يعود الى حاله حتى لا يعرف ممر السهم","كذلك نحن ولدنا ثم اضمحللنا ولم يكن لنا ان نبدي علامة فضيلة بل فنينا في رذيلتنا","كذا قال الخطاة في الجحيم","لان رجاء المنافق كغبار تذهب به الريح وكزبد رقيق تطارده الزوبعة وكدخان تبدده الريح وكذكر ضيف نزل يوما ثم ارتحل","اما الصديقون فسيحيون الى الابد وعند الرب ثوابهم ولهم عناية من لدن العلي","فلذلك سينالون ملك الكرامة وتاج الجمال من يد الرب لانه يسترهم بيمينه وبذراعه يقيهم","يتسلح بغيرته ويسلح الخلق للانتقام من الاعداء","يلبس البر درعا وحكم الحق خوذة","و يتخذ القداسة ترسا لا يقهر","و يحدد غضبه سيفا ماضيا والعالم يحارب معه الجهال","فتنطلق صواعق البروق انطلاقا لا يخطئ وعن قوس الغيوم المحكمة التوتير تطير الى الهدف","و سخطه يرجمهم ببرد ضخم ومياه البحار تستشيط عليهم والانهار تلتقي بطغيان شديد","و تثور عليهم ريح شديدة زوبعة تذريهم والاثم يدمر جميع الارض والفجور يقلب عروش المقتدرين"],["الحكمة خير من القوة والحكيم افضل من الجبار","و انتم ايها الملوك فاسمعوا وتعقلوا ويا قضاة اقاصي الارض اتعظوا","اصغوا ايها المتسلطون على الجماهير المفتخرون بجموع الامم","فان سلطانكم من الرب وقدرتكم من العلي الذي سيفحص اعمالكم ويستقصي نياتكم","فانكم انتم الخادمين لملكه لم تحكموا حكم الحق ولم تحفظوا الشريعة ولم تسيروا بحسب مشيئة الله","فسيطلع عليكم بغتة مطلعا مخيفا لانه سيمضى على الحكام قضاء شديد","فان الصغير اهل للرحمة اما ارباب القوة فبقوة يفحصون","ورب الجميع لا يستثني احد ولا يهاب العظمة لان الصغير والعظيم كليهما صنعه على السواء وعنايته تعم الجميع","لكن على الاشداء امتحانا شديدا","اليكم ايها الملوك توجيه كلامي لكي تتعلموا الحكمة ولا تسقطوا","فان الذين يحفظون بقداسة ما هو مقدس يقدسون والذين يتعلمون هذه يجدون ما يحتجون به","فابتغوا كلامي واحرصوا عليه فتتادبوا","فان الحكمة ذات بهاء ونضرة لا تذبل ومشاهدتها متيسرة للذين يحبونها ووجدانها سهل على الذين يلتمسونها","فهي تسبق فتتجلى للذين يبتغونها","ومن ابتكر في طلبها لا يتعب لانه يجدها جالسة عند ابوابه","فالتامل فيها كمال الفطنة ومن سهر لاجلها فلا يلبث له هم","لانها تجول في طلب الذين هم اهل لها وتتمثل لهم في الطرق باسمة وتتلقاهم كلما تاملوا فيها","فاولها الخلوص في ابتغاء التاديب","وتطلب التاديب هو المحبة والمحبة حفظ الشرائع ومراعاة الشرائع ثبات الطهارة","والطهارة تقرب الى الله","فابتغاء الحكمة يبلغ الى الملكوت","فان كنتم تلتذون بالعرش والصولجان يا ملوك الشعوب فاكرموا الحكمة لكي تملكوا الى الابد","واحبوا نور الحكمة يا حكام الشعوب","وانا اخبركم ما الحكمة وكيف صدرت ولا اكتم عنكم الاسرار لكن ابحث عنها من اول كونها واجعل معرفتها بينه ولا اتجاوز من الحق شيئا","ولا اسير مع من يذوب حسدا لان مثل هذا لا حظ له في الحكمة","ان كثرة الحكماء خلاص العالم والملك الفطن ثبات الشعب","فتادبوا باقوالي واستفيدوا بها"],["انما انا انسان يموت مشاكل لسائر الناس من جنس اول من جبل وقد صورت جسدا في جوف امي","و في مدة عشرة اشهر صنعت من الدم بزرع الرجل واللذة التي تصاحب النوم","و لما ولدت انتشيت هذا الهواء الشائع وسقطت على هذه الارض المشتركة واول ما استهللت بالبكاء على حد الجميع","و ربيت في القمط وباهتمام كثير","فانه ليس لملك بدء مولد غير هذا","بل دخول الجميع الى الحياة واحد وخروجهم سواء","حينئذ تمنيت فاوتيت الفطنة ودعوت فحل علي روح الحكمة","ففضلتها على الصوالجة والعروش ولم احسب الغنى شيئا بالقياس اليها","و لم اعدل بها الحجر الكريم لان جميع الذهب بازائها قليل من الرمل والفضة عندها تحسب طينا","و احببتها فوق العافية والجمال واتخذتها لي نورا لان ضوءها لا يغرب","فاوتيت معها كل صنف من الخير ونلت من يديها غنى لا يحصى","فتمتعت بهذه كلها لان الحكمة قائدة لها ولم اعلم انها ام جميعها","تعلمتها بغير مكر واشرك فيها بغير حسد وغناها لا استره","فانه كنز للناس لا ينقص والذين استفادوا منه اشركوا في محبة الله لان مواهب التاديب قربتهم اليه","و قد وهبني الله ان ابدي عما في نفسي وان اجري في خاطري ما يليق بمواهبه فانه هو المرشد الى الحكمة ومثقف الحكماء","و في يده نحن واقوالنا والفطنة كلها ومعرفة ما يصنع","و وهبني علما يقينا بالاكوان حتى اعرف نظام العالم وقوات العناصر","و مبدا الازمنة ومنتهاها وما بينهما وتغير الاحوال وتحول الاوقات","و مداور السنين ومراكز النجوم","و طبائع الحيوان واخلاق الوحوش وعصوف الرياح وخواطر الناس وتباين الانبتة وقوى العقاقير","فعلمت جميع المكنونات والظواهر لان الحكمة مهندسة كل شيء هي علمتني","فان فيها الروح الفهم القدوس المولود الوحيد ذا المزايا الكثيرة اللطيف السريع الحركة الفصيح الطاهر النير السليم المحب للخير الحديد الحر المحسن","المحب للبشر الثابت الراسخ المطمئن القدير الرقيب الذي ينفذ جميع الارواح الفهمة الطاهرة اللطيفة","لان الحكمة اسرع حركة من كل متحرك فهي لطهارتها تلج وتنفذ في كل شيء","فانها بخار قوة الله وصدور مجد القدير الخالص فلذلك لا يشوبها شيء نجس","لانها ضياء النور الازلي ومراة عمل الله النقية وصورة جودته","تقدر على كل شيء وهي واحدة وتجدد كل شيء وهي ثابتة في ذاتها وفي كل جيل تحل في النفوس القديسة فتنشئ احباء لله وانبياء","لان الله لا يحب احدا الا من يساكن الحكمة","انها ابهى من الشمس واسمى من كل مركز للنجوم واذا قيست بالنور تقدمت عليه","لان النور يعقبه الليل اما الحكمة فلا يغلبها الشر"],["انها تبلغ من غاية الى غاية بالقوة وتدبر كل شيء بالرفق","لقد احببتها والتمستها منذ صبائي وابتغيت ان اتخذها لي عروسا وصرت لجمالها عاشقا","فان في نسبها مجدا لانها تحيا عند الله ورب الجميع قد احبها","فهي صاحبة اسرار علم الله والمتخيرة لاعماله","اذا كان الغنى ملكا نفيسا في الحياة فاي شيء اغنى من الحكمة صانعة الجميع","و ان كانت الفطنة هي التي تعمل فمن احكم منها في هندسة الاكوان","و اذا كان احد يحب البر فالفضائل هي اتعابها لانها تعلم العفة والفطنة والعدل والقوة التي لا شيء للناس في الحياة انفع منها","و اذا كان احد يؤثر انواع العلم فهي تعرف القديم وتتمثل المستقبل وتفقه فنون الكلام وحل الاحاجي وتعلم الايات والعجائب قبل ان تكون وحوادث الاوقات والازمنة","لذلك عزمت ان اتخذها قرينة لحياتي علما بانها تكون لي مشيرة بالصالحات ومفرجة لهمومي وكربي","فيكون لي بها مجد عند الجموع وكرامة لدى الشيوخ على ما انا فيه من الفتاء","و اعد حاذقا في القضاء وعجيبا امام المقتدرين","اذا صمت ينتظرون واذا نطقت يصغون واذا افضت في الكلام يضعون ايديهم على افواههم","و انال بها الخلود واخلف عند الذين بعدي ذكرا مؤبدا","ادبر الشعوب وتخضع لي الامم","يسمع الملوك المرهوبون فيخافونني ويظهر في الجمع صلاحي وفي الحرب باسي","و اذا دخلت بيتي سكنت اليها لانه ليس في معاشرتها مرارة ولا في الحياة معها غمة بل سرور وفرح","فلما تفكرت في نفسي بهذه وتاملت في قلبي ان في قربى الحكمة خلودا","و في مصافاتها لذة صالحة وفي اتعاب يديها غنى لا ينقص وفي الترشح لمؤانستها فطنة وفي الاشتراك في حديثها فخرا طفقت اطوف طالبا ان اتخذها لنفسي","و قد كنت صبيا حسن الطباع ورزقت نفسا صالحة","ثم بازديادي صلاحا حصلت على جسد غير مدنس","و لما علمت باني لا اكون عفيفا ما لم يهبني الله العفة وقد كان من الفطنة ان اعلم ممن هذه الموهبة توجهت الى الرب وسالته من كل قلبي قائلا"],["يا اله الاباء يا رب الرحمة يا صانع الجميع بكلمتك","و فاطر الانسان بحكمتك لكي يسود على الخلائق التي كونتها","و يسوس العالم بالقداسة والبر ويجري الحكم باستقامة النفس","هب لي الحكمة الجالسة الى عرشك ولا ترذلني من بين بنيك","فاني انا عبدك وابن امتك انسان ضعيف قليل البقاء وناقص الفهم في القضاء والشرائع","على انه ان كان في بني البشر احد كامل فما لم تكن معه الحكمة التي منك لا يحسب شيئا","انك قد اخترتني لشعبك ملكا ولبنيك وبناتك قاضيا","و امرتني ان ابني هيكلا في جبل قدسك ومذبحا في مدينة سكناك على مثال المسكن المقدس الذي هياته منذ البدء","ان معك الحكمة العليمة باعمالك والتي كانت حاضرة اذ صنعت العالم وهي عارفة ما المرضي في عينيك والمستقيم في وصاياك","فارسلها من السماوات المقدسة وابعثها من عرش مجدك حتى اذا حضرت تجد معي واعلم ما المرضي لديك","فانها تعلم وتفهم كل شيء فتكون لي في افعالي مرشدا فطينا وبعزها تحفظني","فتغدو اعمالي مقبولة واحكم لشعبك بالعدل واكون اهلا لعرش ابي","فاي انسان يعلم مشورة الله او يفطن لما يريد الرب","ان افكار البشر ذات احجام وبصائرنا غير راسخة","اذ الجسد الفاسد يثقل النفس والمسكن الارضي يخفض العقل الكثير الهموم","و نحن بالجهد نتمثل ما على الارض وبالكد ندرك ما بين ايدينا فما في السماوات من اطلع عليه","و من علم مشورتك لو لم تؤت الحكمة وتبعث روحك القدوس من الاعالي","فانه كذلك قومت سبل الذين على الارض وتعلم الناس مرضاتك","و الحكمة هي التي خلصت كل من ارضاك يا رب منذ البدء"],["هي التي حفظت اول من جبل ابا للعالم لما خلق وحده","و انقذته من زلته واتته قوة ليتسلط على الجميع","و لما ارتد عنها الظالم في غضبه هلك في حنقه الذي كان به قاتل اخيه","و لما غمر الطوفان الارض بسببه عادت الحكمة فخلصتها بهدايتها للصديق في الة خشب حقيرة","و هي التي عند اتفاق لفيف الامم على الشر لقيت الصديق وصانته لله بغير وصمة وحفظت احشائه صماء عن ولده","و هي التي انقذت الصديق من المنافقين الهالكين فهرب من النار الهابطة على المدن الخمس","و الى الان يشهد بشرهم قفر يسطع منه الدخان ونبات يثمر ثمرا لا ينضج وعمود من ملح قائم تذكارا لنفس لم تؤمن","و الذين اهملوا الحكمة لم ينحصر ظلمهم لانفسهم بجهلهم الصلاح ولكنهم خلفوا للناس ذكر حماقتهم بحيث لم يستطيعوا كتمانما زلوا فيه","و اما الذين خدموا الحكمة فانقذتهم من كل نصب","و هي التي قادت الصديق الهارب من غضب اخيه في سبل مستقيمة وارته ملكوت الله واتته علم القديسين وانجحته في اتعابه واكثرت ثمرات اعماله","و عند طماعة المستطيلين عليه انتصبت لمعونته واغنته","و وقته من اعدائه وحمته من الكامنين له واظفرته في القتال الشديد لكي يعلم ان التقوى اقدر من كل شيء","و هي التي لم تخذل الصديق المبيع بل صانته من الخطيئة ونزلت معه في الجب","و في القيود لم تفارقه حتى ناولته صوالجة الملك وسلطانا على الذين قسروه وكذبت الذين عابوه واتته مجدا ابديا","و هي التي انقذت شعبا مقدسا وزرية لا وصمة فيها من امة مضايقيهم","و حلت نفس عبد للرب وقاومت ملوكا مرهوبين بعجائب وايات","و جزت القديسين ثواب اتعابهم وقادتهم في طريق عجيب وكانت لهم ظلا في النهار وضياء نجوم في الليل","و عبرت بهم البحر الاحمر واجازتهم المياه الغزيرة","اما اعداؤهم فاغرقتهم ثم قذفتهم من عمق الغمار على الشاطئ فسلب الصديقون المنافقين","و رنموا لاسمك القدوس ايها الرب وحمدوا بقلب واحد يدك الناصرة","لان الحكمة فتحت افواه البكم وجعلت السنة الاطفال تفصح"],["ثم سددت مساعيهم بارشاد نبي قديس","فساروا في برية لا ساكن بها وضربوا اخبيتهم في ارض قفرة","و قاوموا محاربيهم ودافعوا اعداءهم","و في عطشهم دعوا اليك فاعطوا ماء من صخرة الصوان وشفاء لغليلهم من الحجر الجلمود","فكان الذي عذب به اعداؤهم اذ اعوزهم ما يشربون وبنو اسرائيل متهللون بكثرته","هو الذي احسن به اليهم في عوزهم","فانك بلبلت اولئك اذ بدلتهم بمعين النهر الدائم دما صديدا","عقابا لهم على قضائهم بقتل الاطفال وهؤلاء اعطيتهم ماء غزيرا عند الياس منه","لكي تريهم بعطشهم هذا كيف عاقبت اضدادهم","فانهم بامتحانك لهم وان كان تاديب رحمة فهموا كيف كان عذاب المنافقين المقضي عليهم بالغضب","لانك جربت هؤلاء كاب انذارا لهم واولئك ابتليتهم كملك قاس قضاء عليهم","و قد مسهم في الغيب من الضر ما مسهم في المشهد","اذ اخذهم ضعفان من الحزن والنحيب بتذكر الضربات السالفة","لانهم لما سمعوا ان ما كان لهم عقابا صار لاعدائهم احسانا شعروا بيد الرب","و الذي قضوا من قبل بطرحه في النهر واستخفوا به ورذلوه استعظموه في اخر الامر اذا كان عطش الصديقين على خلاف عطشهم","و اذ كانوا قد سفهوا في افكارهم الاثيمة وضلوا حتى عبدوا زحافات حقيرة ووحوشا لا نطق لها انتقمت منهم بان ارسلت عليهم جما من الحيوانات التي لا نطق لها","لكي يعلموا ان ما خطئ به احد به يعاقب","و لم يكن صعبا على يدك القادرة على كل شيء التي صنعت العالم من مادة غير مصورة ان تبعث عليهم جما من الادباب او الاسود الباسلة","او من اصناف جديدة لم تعرف من الوحوش الضارية التي تنفخ نارا او تبعث دخانا قاتما او ترسل من عيونها شرارا مخيفا","اذا لكانت تهلكهم خوفا من منظرها فضلا عن ان تهشمهم باصابتها","بل قد كان نفس كافيا لاسقاطهم فيتعقبهم القضاء وروح قدرتك يذريهم لكنك رتبت كل شيء بمقدار وعدد ووزن","و عندك قدرة عظيمة في كل حين فمن يقاوم قوة ذراعك","ان العالم كله امامك مثل ما ترجح به كفة الميزان وكنقطة ندى تسقط على الارض عند السحر","لكنك ترحم الجميع لانك قادر على كل شيء وتتغاضى عن خطايا الناس لكي يتوبوا","لانك تحب جميع الاكوان ولا تمقت شيئا مما صنعت فانك لو ابغضت شيئا لم تكونه","و كيف يبقى شيء لم ترده ام كيف يحفظ ما لست انت داعيا له","انك تشفق على جميع الاكوان لانها لك ايها الرب المحب النفوس"],["ان في كل شيء روحك الذي لا فساد فيه","فبه توبخ الخطاة شيئا فشيئا وفيما يخطاون به تذكرهم وتنذرهم لكي يقلعوا عن الشر ويؤمنوا بك ايها الرب","فانك ابغضت الذين كانوا قديما سكان ارضك المقدسة","لاجل اعمالهم الممقوتة لديك من السحر وذبائح الفجور","اذ كانوا يقتلون اولادهم بغير رحمة وياكلون احشاء الناس ويشربون دماءهم في شعائر عبادتك","فاثرت ان تهلك بايدي ابائنا اولئك الوالدين قتلة النفوس التي لا نصرة لها","لكي تكون الارض التي هي اكرم عندك من كل ارض عامرة بابناء الله كما يليق بها","على انك اشفقت على اولئك ايضا لانهم بشر فبعثت بالزنابير تتقدم عسكرك وتبيدهم شيئا بعد شيء","لا لانك عجزت عن اخضاع المنافقين للصديقين بالقتال او تدميرهم بمرة بالوحوش الضارية او بامر جازم من عندك","لكن بعقابهم شيئا فشيئا منحتهم مهلة للتوبة وان لم يخف عليك ان جيلهم شرير وان خبثهم غريزي وافكارهم لا تتغير الى الابد","لانهم كانوا ذرية ملعونة منذ البدء ولم يكن عفوك عن خطاياهم خوفا من احد","فانه من يقول ماذا صنعت او يعترض قضاءك ومن يشكوك بهلاك الامم التي خلقتها او يقف بين يديك مخاصما عن اناس مجرمين","اذ ليس اله الا انت المعتني بالجميع حتى تري انك لا تقضي قضاء الظلم","و ليس لملك او سلطان ان يطالبك بالذين اهلكتهم","و اذ انت عادل تدبر الجميع بالعدل وتحسب القضاء على من لا يستوجب العقاب منافيا لقدرتك","لان قوتك هي مبدا عدلك وبما انك رب الجميع فانت تشفق على الجميع","و انما تبدي قوتك للذين لا يؤمنون انك على كمال القدرة وتعاقب العلماء على جسارتهم","لكنك ايها السلطان القدير تحكم بالرفق وتدبرنا باشفاق كثير لان في يدك ان تعمل بقدرة متى شئت","فعلمت شعبك باعمالك هذه ان الصديق ينبغي ان يكون محبا للناس وجعلت لبنيك رجاء حسنا لانك تمنحهم في خطاياهم مهلة للتوبة","لانك ان كنت عاقبت اعداء بنيك المستوجبين للموت بمثل هذا التحرز والترفق وجعلت لهم زمانا ومكانا للاقلاع عن الشر","فباي اعتناء دبرت بنيك الذين واثقت اباءهم بالاقسام والعهود على مواعيدك الصالحة","فتؤدبنا نحن وتجلد اعداءنا جلدا كثيرا لكي نتذكر حلمك اذا حكمنا وننتظر رحمتك اذا حكم علينا","لاجل ذلك فالمنافقون الذين عاشوا بالسفه عذبتهم بارجاسهم عينها","فانهم في ضلالهم تجاوزوا طرق الضلال اذ اتخذوا ما يستحقره اعداؤهم من الحيوان الهة مغترين كاطفال لا يفقهون","لذلك بعثت عليهم عقاب اولاد لا عقل لهم للسخرية","و لما لم يتعظوا بتاديب السخرية ذاقوا العقاب اللائق بالله","و فيما تحملوه بغيظهم وقد راوا ان ما اتخذوه الها كانوا به يعذبون عرفوا الاله الحق الذي كانوا يكفرون به ولذلك حلت بهم خاتمة العقاب"],["ان جميع الذين لم يعرفوا الله هم حمقى من طبعهم لم يقدروا ان يعلموا الكائن من الخيرات المنظورة ولم يتاملوا المصنوعات حتى يعرفوا صانعها","لكنهم حسبوا النار او الريح او الهواء اللطيف او مدار النجوم او لجة المياه او نيري السماء الهة تسود العالم","فان كانوا انما اعتقدوا هذه الهة لانهم خلبوا بجمالها فليتعرفوا كم ربها احسن منها اذ الذي خلقها هو مبدا كل جمال","او لانهم دهشوا من قوتها وفعلها فليتفهموا بها كم منشئها اقوى منها","فانه بعظم جمال المبروءات يبصر فاطرها على طريق المقايسة","غير ان لهؤلاء وجها من العذر لعلهم ضلوا في طلبهم لله ورغبتهم في وجدانهم","اذ هم يبحثون عنه مترددين بين مصنوعاته فيغرهم منظرها لان المنظورات ذات جمال","مع ذلك ليس لهم من مغفرة","لانهم ان كانوا قد بلغوا من العلم ان استطاعوا ادراك كنه الدهر فكيف لم يكونوا اسرع ادراكا لرب الدهر","اما الذين سموا اعمال ايدي الناس الهة الذهب والفضة وما اخترعته الصناعة وتماثيل الحيوان والحجر الحقير مما صنعته يد قديمة فهم اشقياء ورجاؤهم في الاموات","يقطع نجار شجرة من الغابة طوع العمل ويجردها بحذقه من قشرها كله ثم بحسن صناعته يصنعها الة تصلح لخدمة العيش","و يستعمل نفايتها وقودا لاعداد طعامه","ثم ياخذ قطعة من نفايتها لا تصلح لشيء خشبة ذات اعوجاج وعقد ويعتني بنقشها في اوان فراغه ويصورها بخبرة صناعته على شكل انسان","او يمثل بها حيوان خسيسا ويدهنها بالاسفيداج ويحمر لونها بالزنجفر ويطلي كل لطخة بها","و يجعل لها مقاما يليق بها ويضعها في الحائط ويوثقها بالحديد","و يتحفظ عليها ان لا تسقط لعلمه بانها لا تقوم بمعونة نفسها اذ هي تمثال يفتقر الى من يعينه","ثم يتضرع اليها عن امواله وازواجه وبنيه ولا يخجل ان يخاطب من لا روح له","فيطلب العافية من السقيم ويسال الميت الحياة ويستغيث بمن هو اعجز شيء عن الاغاثة","و يتوسل من اجل السفر الى من لا يستطيع المشي ويلتمس النصرة في الكسب والتجارة ونجح المساعي ممن هو اقصر موجود باعا"],["و اخر قبل ان يركب البحر ويسير على الامواج المعربدة يستغيث بخشب هو اقصف من المركب الذي يحمله","لان المركب اخترعه حب الكسب وصنعته الحكمة المهندسة","لكن عنايتك ايها الاب هي التي تدبره لانك انت الذي فتحت في البحر طريقا وفي الامواج مسلكا امنا","و بينت انك قادر ان تخلص من كل خطر ولو ركب البحر من يجهل صناعته","و انت تحب ان لا تكون اعمال حكمتك باطلة فلذلك يودع الناس انفسهم خشبا صغيرا ويقطعون اللجة في سفينة ويخلصون","و في البدء ايضا حين هلك الجبابرة المتكبرون التجا رجاء العالم الى سفينة وارشدته يديك فابقى للدهر ذرية تتوالد","فالخشب الذي به يحصل البر هو مبارك","اما الخشب المصنوع صنما فملعون هو وصانعه اما هذا فلانه عمله واما ذاك فلانه مع كونه فاسدا سمي الها","فان الله يبغض المنافق ونفاقه على السواء","فيصيب العقاب المصنوع والصانع","لذلك ستفتقد اصنام الامم ايضا لانها صارت في خلق الله رجسا ومعثرة لنفوس الناس وفخا لاقدام الجهال","لان اختراع الاصنام هو اصل الفسق ووجدانها فساد الحياة","و هي لم تكن في البدء وليست تدوم الى الابد","لانها انما دخلت العالم بحب الناس للمجد الفارغ ولذلك قد عزم على الغائها عن قريب","و ذلك ان والدا قد فجع بثكل معجل فصنع تمثالا لابنه الذي خطف سريعا وجعل يعبد ذلك الانسان الميت بمنزلة اله ورسم للذين تحت يده شعائر وذبائح","ثم على ممر الزمان تاصلت تلك العادة الكفرية فحفظت كشريعة وباوامر الملوك عبدت المنحوتات","و الذين لم يستطع الناس اكرامهم بمحضرهم لبعد مقامهم صوروا هيئاتهم الغائبة وجعلوا صورة الملك المكرم نصب العيون حرصا على تملقه في الغيبة كانه حاضر","ثم ان حب الصناع للمباهاة كان داعية للجاهلين الى المبالغة في هذه العبادة","فانهم رغبة في ارضاء الامر قد افرغوا وسعهم في الصناعة لاخراج الصورة على غاية الكمال","فاستميل الجمهور ببهجة ذلك المصنوع حتى ان الذي كانوا قبل قليل يكرمونه كانسان عدوه الها","و بهذا كان اقتناص الخلق فان رزيئة بعض الناس او اقتسار الملوك استعبدهم حتى جعلوا على الحجر والخشب الاسم الذي لا يشرك فيه احد","ثم لم يكتفوا بضلالهم في معرفة الله لكنهم غاصوا في حرب الجهل الشديدة وهم يسمون مثل هذه الشرور سلاما","فانهم يمارسون ذبائح من بنيهم وشعائر خفية ومادب جنون على اساليب اخر","لا يرعون حسن السيرة ولا طهارة الزواج فيقتل الرجل صاحبه بالاغتيال ويمضه بالفاحشة","شر متفاقم في كل موضع الدم والقتل والسرقة والمكر والفساد والخيانة والفتنة والحنث وقلق الابرار","و كفران النعمة وتدنس النفوس والتباس المواليد وتشوش الزواج والفسق والعهر","لان عبادة الاصنام المكروهة هي علة كل شر وابتداؤه وغايته","فانهم اذا فرحوا جنوا او تنباوا كذبوا او عاملوا ظلموا او حالفوا اسرعوا الى الحنث","و لتوكلهم على اصنام لا ارواح له لا يتوقعون اذا اقسموا بالزور ان ينالهم الخسران","فهناك امران يستحقون بهما حلول اعقاب سوء اعتقادهم في الله اذ اتبعوا الاصنام وقسمهم بالظلم والمكر اذا ستخفوا بالقداسة","لان معصية الظالمين انما يتعقبها القضاء على الخطاة لا قدرة المقسم بهم"],["و انت يا الهنا ذو صلاح وصدق طويل الاناة ومدبر الجميع بالرحمة","فاذا خطئنا فنحن في يدك وقد علمنا قدرتك لكنا لا نختار الخطا لعلمنا بانا من خاصتك","فان معرفتك هي البر الكامل والعلم بقدرتك هو اصل الحياة الدائمة","لذلك لم يغونا ما اخترعته صناعة الناس الممقوتة ولا عمل المصورين العقيم من الصور الملطخة بالالوان","التي في النظر اليها فضيحة للسفهاء بعشقهم صورة تمثال ميت لا روح فيه","لا جرم ان الذين يصنعونها والذين يعشقونها والذين يعبدونها هم كلفون بالمنكرات وهم اهل لان تكون امالهم في امثال هذه","ان الخزاف يعني بعجن الطين اللين ويصنع منه كل اناء مما نستخدمه فيصنع من الطين الواحد الانية المستخدمة في الاعمال الطاهرة والمستخدمة في عكس ذلك واما تخصيص كل اناء بواحدة من الخدمتين فانما يرجع الى حكم صانع الطين","و بعنائه الممقوت يصنع من هذا الطين الها باطلا وهو انما ولد من الطين من حين يسير وعن قليل سيعود الى ما اخذ منه حين يطالب بدين نفسه","غير ان همه ليس بانه يتعب ولا بانه قريب الاجل لكنه يباري صاغة الذهب والفضة ويعارض النحاسين ويعتد ما يصنعه من الخسائس فخرا","فقلبه رماد ورجاؤه اخس من التراب وحياته احقر من الطين","لانه جهل من جبله ونفخ فيه نفسا عاملة وروحا محييا","بل حسب حياتنا عبثا وعمرنا موسما للاكتساب وزعم انه لا بد من الربح بكل حيلة ولو بالظلم","فانه عالم بانه اعظم جرما من الجميع لانه يصنع من طين الارض انية قصمة ومنحوتات","ان جميع اعداء شعبك المتسلطين عليهم هم اجهل الناس واشقى من نفوس الاطفال","لانهم حسبوا جميع اصنام الامم الهة تلك التي لا تبصر بعيونها ولا تنشق الهواء بانوفها ولا تسمع باذانها ولا تلمس باصابع ايديها وارجلها عاجزة عن الخطو","لانها انما عملها انسان والذي اعير روحا صنعها وليس في طاقة انسان ان يصنع الها مثله","و انما هو فان فيصنع بيديه الاثيمتين ما لا حياة فيه فهو افضل من معبوداته اذ هو قد كان حيا واما هي فلم تكن حية البتة","و هم يعبدون اعدى الحيوان مما هو اشد البهائم عجمة","و ليس فيه ما في منظر الحيوانات الاخر من الحسن الشائق اذ فاته مدح الله وبركته"],["لذلك كانوا احقاء بان يعاقبوا بامثال هذه ويعذبوا بجم من الحشرات","اما شعبك فبدلا من ذلك العقاب احسنت اليهم باعداد السلوى ماكلا غريب الطعم اشبعت به شهوتهم","حتى انه بينما كان اولئك مع جوعهم فاقدي كل شهوة للطعام من كراهة ما بعثت عليهم كان هؤلاء بعد عوز يسير يتناولون ماكلا غريب الطعم","فانه كان ينبغي لاولئك المقتسرين ان تنزل بهم فاقة لا مناص منها ولهؤلاء ان يروا كيف يعذب اعداؤهم لا غير","و لما اقتحم هؤلاء حنق الوحوش الهائل واهلكهم لدغ الحيات الخبيثة","لم يستمر غضبك الى المنتهى بل انما اقلقوا الى حين انذارا لهم ونصبت لهم علامة للخلاص تذكرهم وصية شريعتك","فكان الملتفت اليها يخلص لا بذلك المنظور بل بك يا مخلص الجميع","و بذلك اثبت لاعدائنا انك انت المنقذ من كل سوء","لان اولئك قتلهم لسع الجراد والذباب ولم يوجد لنفوسهم شفاء اذ هم اهل لان يعاقبوا بمثل ذلك","اما بنوك فلم تقو عليهم انياب التنانين السامة لان رحمتك اقبلت وشفتهم","و انما نخسوا ليتذكروا اقوالك ثم خلصوا سريعا لئلا يسقطوا في نسيان عميق فيحرموا احسانك","و ما شفاهم نبت ولا مرهم بل كلمتك يارب التي تشفي الجميع","لان لك سلطان الحياة والموت فتحدر الى ابواب الجحيم وتصعد","اما الانسان فيقتل بخبثه لكنه لا يعيد الروح الذي قد خرج ولا يسترجع النفس المقبوضة","انه ليس احد يستطيع ان يهرب من يدك","فانك قد جلدت بقوة ذراعك المنافقين الذين جحدوا معرفتك واطلقت في اثرهم سيولا وبردا وامطارا غريبة ونارا اكلة","و اغرب شيء ان النار كانت في الماء الذي يطفئ كل شيء تزداد حدة لان عناصر العالم تقاتل عن الصديقين","و كان اللهيب تارة يسكن لئلا يحرق ما ارسل على المنافقين من الحيوان ولكي يبصروا فيعلموا ان قضاء الله على اعقابهم","و تارة يخرج عن طبع النار فيتاجج في الماء لكي يستاصل انبتة الارض الاثيمة","اما شعبك فبدلا من ذلك اطعمتهم طعام الملائكة وارسلت لهم من السماء خبزا معدا لا تعب فيه يتضمن كل لذة ويلائم كل ذوق","لان جوهرك ابدى عذوبتك لبنيك فكان يخدم شهوة المتناول ويتحول الى ما شاء كل واحد","و كان الثلج والجليد يثبتان في النار ولا يذوبان لكي يعلم كيف اكلت ثمار الاعداء نار تلتهب في البرد وتبرق في المطر","اما عند هؤلاء فقد تناست القوة التي لها لكي يغتذي القديسون","اذ الخليقة الخادمة لك انت صانعها تتشدد لتعاقب المجرمين وتتراخى لتحسن الى المتوكلين عليك","لذلك كانت حينئذ تتحول الى كل شيء لتخدم نعمتك الغاذية الجميع على ما يشاء كل محتاج","لكي يعلم بنوك الذين احببتهم ايها الرب ان ليس ما تخرج الارض من الثمار هو يغذو الانسان لكن كلمتك هي التي تحفظ المؤمنين بك","اذ ما لم تكن النار تحله كانت شعاعة يسيرة من الشمس تحميه فيذوب","حتى يعلم انه يجب ان نسبق الشمس الى شكرك ونحضر امامك عند شروق النور","لان رجاء من لا شكر له يذوب كجليد شتوي ويذهب كماء لا منفعة فيه"],["ان احكامك عظيمة لا يعبر عنها ولذلك ضلت النفوس التي لا تاديب لها","فانه لما توهم المجرمون انهم يتسلطون على الامة القديسة اذا هم ملقون في اسر الظلمة وقيود الليل الطويل محبوسون تحت سقوفهم منفيون عن العناية الابدية","و اذ حسبوا انهم مستترون في خطاياهم الخفية فرق بينهم ستر النسيان المظلم وهم في رعب شديد تقلقهم الاخيلة","و لم تكن الاكنة التي لبثوا فيها لتقيهم من الذعر فقد كانت اصوات قاصفة تدوي من حولهم واشباح مكفهرة تتراى امام وجوههم الكاسفة","و لم يكن في قوة النار مهما اشتدت ان تاتي بضياء ولا في بريق النجوم ان ينير ذلك الليل المدلهم","و انما كانت تلمع لهم بغتة نيران مخيفة فيرتعدون من ذلك المنظر المبهم ويتوهمون ما يظهر لهم اهول مما هو","حينئذ بطلت صناعة السحر وشعوذته وبرز على افتخارهم بالحكمة حجة مخزية","اذ الذين وعدوا بنفي الجزع والبلبال عن النفس الدنفة هؤلاء ادنفهم خوف مضحك","فانهم وان لم يصبهم شيء هائل كان مرور الوحوش وفحيح الافاعي يدحرهم فيهلكون من الخوف ويتوقون حتى الهواء الذي لا محيد عنه","لان الخبث ملازم للجبن فهو يقضي على نفسه بشهادته ولقلق الضمير لا يزال متخيلا الضربات","فان الخوف انما هو ترك المدد الذي من العقل","و انتظار المدد من الداخل اضعف ولذلك تحسب مجلبة العذاب المجهولة اشد","فالذين ناموا تلك النومة في ذلك الليل الذي لا يطاق الوارد من اخادير الجحيم الفظيعة","كانوا تارة تقتحمهم الاخيلة وتارة تنحل قواهم من انخلاع قلوبهم لما غشيهم من مفاجاة الخوف الغير المتوقع","ثم حيثما سقط احد بقى محبوسا في سجن لا حديد فيه","فان كان فلاحا او راعيا او صاحب عمل من اعمال الصحراء اخذ بغتة فوقع في قسر لا انفكاك عنه","اذ جميعهم كانوا مقيدين بسلسلة واحدة من الظلام فدوي الريح واغاريد الطيور على الاغصان الملتفة وصوت المياه المندفعة بقوة","و قعقعة الحجارة المتدحرجة وركض الحيوانات الذي لا يرى وزئير الوحوش الضارية والصدى المتردد في بطون الجبال كل ذلك كان يذيبهم من الخوف","و بينما كان سائر العالم يضيئه نور ساطع ويتعاطى اعماله بغير مانع","كان اولئك منفردين في ظل ليل مدلهم مشاكل لما سيغشاهم من الظلمة لكنهم كانوا على انفسهم اثقل من الظلمة"],["اما قديسوك فكان عندهم نور عظيم وكان اولئك يسمعون اصواتهم بغير ان يبصروا اشخاصهم ويغبطونهم على انهم لا يقاسون مثل حالهم","و يشكرونهم على انهم لا يؤذون الذين قد ظلموهم ويستغفرونهم من معاداتهم لهم","و بازاء ذلك جعلت لهؤلاء عمود نار دليلا في طريق لم يعرفوه شمسا لتلك الضيافة الكريمة لا اذى بها","اما اولئك فكان جديرا بهم ان يفقدوا النور ويحبسوا في الظلمة لانهم حبسوا بنيك الذين بهم سيمنح الدهر نور شريعتك الغير الفاني","و لما ائتمروا ان يقتلوا اطفال القديسين وعرض واحد منهم لذلك ثم خلص عاقبتهم انت باهلاك جمهور اولادهم ثم دمرتهم جميعا في الماء الغامر","و تلك الليلة قد اخبر بها اباؤنا من قبل لكي تطيب نفوسهم لعلمهم اليقين ما الاقسام التي يثقون بها","ففاز شعبك بخلاص الصديقين وهلاك الاعداء","فان الذي عاقبت به المقاومين هو الذي جذبتنا به اليك ومجدتنا","فان القديسين بني الصالحين كانوا يذبحون خفية ويوجبون على انفسهم شريعة الله هذه ان يشترك القديسون في السراء والضراء على السواء وكانوا يرنمون بتسابيح الاباء","و قد رفع الاعداء جلبة اصواتهم بالبكاء والنحيب على اطفالهم","و كان قضاء واحد على العبد والمولى وضربة واحدة نالت الشعب والملك","و كان لكلهم اجمعين اموات لا يحصون قد ماتوا ميتة واحدة حتى ان الاحياء لم يكفوا لدفن الموتى اذ في لحظة ابيد نسلهم الاعز","و بعد ان ابوا بسبب السحر ان يؤمنوا بشيء اعترفوا عند هلاك الابكار بان الشعب هو ابن لله","و حين شمل كل شيء هدوء السكوت وانتصف مسير الليل","هجمت كلمتك القديرة من السماء من العروش الملكية على ارض الخراب بمنزلة مبارز عنيف","و سيف صارم يمضي قضاءك المحتوم فوقف وملا كل مكان قتلى وكان راسه في السماء وقدماه على الارض","حينئذ بلبلتهم بغتة اخيلة الاحلام بلبلة شديدة وغشيتهم اهوال مفاجئة","و كان كل واحد عند صرعه بين حي وميت يعلن لاي سبب يموت","لان الاحلام التي اقلقتهم انباتهم بذلك لئلا يهلكوا وهم يجهلون مجلبة هلاكهم","و الصديقون ايضا مستهم محنة الموت ووقعت الضربة على جم منهم في البرية لكن الغضب لم يلبث طويلا","لان رجلا لا عيب فيه بادر لحمايتهم فبرز بسلاح خدمته الذي هو الصلاة والتكفير بالبخور وقاوم الغضب وازال النازلة فتبين انه خادمك","فانتصر على الجمع لا بقوة الجسد ولا باعمال السلاح ولكنه بالكلام كف المعاقب مذكرا الاقسام والعهود للاباء","فانه اذ كان القتلى يتساقطون جماعات وقف في الوسط فحسم السخط وقطع المسلك الى الاحياء","لانه كان على ثوبه السابغ العالم كله واسماء الاباء المجيدة منقوشة في اربعة اسطر من الحجارة الكريمة وعظمتك على تاج راسه","فهذه خضع المهلك لها وهابها وكان مجرد اختبار الغضب قد كفى"],["اما المنافقون فاستمر عليهم الى الانقضاء غضب لا رحمة معه لانه كان يعلم من قبل ماذا سيكون من امرهم","وانهم بعد ترخيصهم لهم في الذهاب ومبادرتهم لاطلاقهم يندمون فيجدون في اثرهم","فانهم قبل ان تنقضي مناحتهم وهم منتحبون على قبور امواتهم عادوا فاتخذوا مشورة جهل اخرى وسعوا في اثار الذين حثوهم على الرحيل سعيهم وراء قوم فارين","و انما ساقهم الى هذا الاجل امر لا بد منه انساهم ما سبق من الحوادث لكي يستتموا ما بقي من الام عقابهم","و يعبر شعبك اعجب عبور ويموت اولئك اغرب ميتة","و كانت جميع الخلائق كل واحدة في جنسها تستبدل طبعها وتخدمك بحسب ما رسم لها لكي يحفظ بنوك بغير ضر","فالغمام ظلل المحلة ومما كان قبلا يغمر بالمياه برزت ارض يابسة طريق ممهد في البحر الاحمر ومرج اخضر في قعر لجة عظيمة","هناك عبرت الامة كلها وهم في ستر يدك يرون عجائب الايات","و رتعوا كالخيل ووثبوا كالحملان مسبحين لك ايها الرب مخلصهم","متذكرين ما وقع في غربتهم كيف اخرجت الارض الذباب بدلا من نتاج الحيوان وفاض النهر بجم من الضفادع عوض الاسماك","و اخيرا راوا صنفا جديدا من الطير حين حثتهم شهوتهم ان يتطلبوا طعاما لذيذا","فصعدت السلوى من البحر تسلية لهم اما الخطاة فنزل عليهم الانتقام مع ما له من العلائم القديمة التي هي شدة الصواعق وانما اصابهم ما استحقت فواحشهم","اذ كانت معاملتهم للاضياف اشد كراهية فان اولئك ابوا ان يقبلوا غرباء لم يعرفوهم اما هؤلاء فاستعبدوا اضيافا قد احسنوا اليهم","و فضلا عن ذلك فان عليهم افتقادا اخر اذ ان اولئك انما قبلوا قوما اجنبيين كرها","اما هؤلاء فانهم قبلوا اضيافا باحتفال وفرح واشركوهم في حقوقهم ثم اساءوا اليهم بصنوف العذاب الشديد","فضربوا بالعمى مثل اولئك الواقفين على باب الصديق الذين شملتهم ظلمة هائلة فجعل كل منهم يتلمس طالبا مدخل بابه","اذ تغيرت نسب العناصر بعضها الى بعض كما يتغير في العود اسم صوت من اللحن والصوت باق وذلك بين لمن تامل تلك الحوادث","فالارضيات تحولت الى مائيات والسابحات سعت على الارض","و النار كانت لها قوة في الماء اشد من قوتها الغريزية والماء نسي قوته المطفئة","و بالعكس اللهيب لم يؤذ جسم السريع الفاسد من الحيوان اذ كان يمشي فيه ولم يذب الطعام السماوي السريع الذوبان كالجليد لانك يا رب عظمت شعبك في كل شيء ومجدته ولم تهمله بل كنت مؤازرا له في كل زمان ومكان"]]},{"id":906,"code":"Sir","name":"يشوع بن سيراخ (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["كل حكمة فهي من الرب ولا تزال معه الى الابد","من يحصي رمل البحار وقطار المطر وايام الدهر ومن يمسح سمك السماء ورحب الارض والغمر","و من يستقصي الحكمة التي هي سابقة كل شيء","قبل كل شيء حيزت الحكمة ومنذ الازل فهم الفطنة","ينبوع الحكمة كلمة الله في العلى ومسالكها الوصايا الازلية","لمن انكشف اصل الحكمة ومن علم دهائها","لمن تجلب معرفة الحكمة ومن ادرك كثرة خبرتها","واحد هو حكيم عظيم المهابة جالس على عرشه","الرب هو حازها وراها واحصاها","و افاضها على جميع مصنوعاته فهي مع كل ذي جسد على حسب عطيته وقد منحها لمحبيه","مخافة الرب مجد وفخر وسرور واكليل ابتهاج","مخافة الرب تلذ للقلب وتعطي السرور والفرح وطول الايام","المتقي للرب يطيب نفسا في اواخره وينال حظوة يوم موته","محبة الرب هي الحكمة المجيدة","و الذين تتراءى لهم يحبونها عند رؤيتهم لها وتاملهم لعظائمها","راس الحكمة مخافة الله انها تولدت في الرحم مع المؤمنين وجعلت عشها بين الناس مدى الدهر وستسلم نفسها الى ذريتهم","مخافة الرب هي عبادته عن معرفة","العبادة تحفظ القلب وتبرره وتمنح السرور والفرح","المتقي للرب يطيب نفسا وينال حظوة في يوم وفاته","كمال الحكمة مخافة الرب انها تسكر بثمارها","تملا كل بيتها رغائب ومخازنها غلالا","اكليل الحكمة مخافة الرب انها تنشئ السلام والشفاء والعافية","و قد رات الحكمة واحصتها وكلتاهما عطية من الله","الحكمة تسكب المعرفة وعلم الفطنة وتعلي مجد الذين يملكونها","اصل الحكمة مخافة الرب وفروعها طول الايام","في زخائر الحكمة العقل والعبادة عن معرفة اما عند الخطاة فالحكمة رجس","مخافة الرب تنفي الخطيئة","غضب الاثيم لا يمكن ان يبرر لان وقر غضبه يسقطه","الطويل الاناة يصبر الى حين ثم يعاوده السرور","العاقل يكتم كلامه الى حين وشفاه المؤمنين تثني على عقله","في زخائر الحكمة امثال المعرفة","اما عند الخاطئ فعبادة الله رجس","يا بني ان رغبت في الحكمة فاحفظ الوصايا فيهبها لك الرب","فان الحكمة والتاديب هما مخافة الرب والذي يرضيه","هو الايمان والوداعة فيغمر صاحبهما بالكنوز","لا تعاص مخافة الرب ولا تتقدم اليه بقلب وقلب","لا تكن مرائيا في وجوه الناس وكن محترسا لشفتيك","لا تترفع لئلا تسقط فتجلب على نفسك الهوان","و يكشف الرب خفاياك ويصرعك في المجمع","لانك لم تتوجه الى مخافة الرب لكن قلبك مملوء مكرا"],["يا بني ان اقبلت لخدمة الرب الاله فاثبت على البر والتقوى واعدد نفسك للتجربة","ارشد قلبك واحتمل امل اذنك واقبل اقوال العقل ولا تعجل وقت النوائب","انتظر بصبر ما تنتظره من الله لازمه ولا ترتدد لكي تزداد حياة في اواخرك","مهما نابك فاقبله وكن صابرا على صروف اتضاعك","فان الذهب يمحص في النار والمرضيين من الناس يمحصون في اتون الاتضاع","امن به فينصرك قوم طرقك وامله احفظ مخافته وابق عليها في شيخوختك","ايها المتقون للرب انتظروا رحمته ولا تحيدوا لئلا تسقطوا","ايها المتقون للرب امنوا به فلا يضيع اجركم","ايها المتقون للرب املوا الخيرات والسرور الابدي والرحمة","ايها المتقون للرب احبوه فتستنير قلوبكم","انظروا الى الاجيال القديمة وتاملوا هل توكل احد على الرب فخزي","او ثبت على مخافته فخذل او دعاه فاهمل","فان الرب راوف رحيم يغفر الخطايا ويخلص في يوم الضيق","ويل للقلوب الهيابة وللايدي المتراخية وللخاطئ الذي يمشي في طريقين","ويل للقلب المتواني انه لا يؤمن ولذلك لا حماية له","ويل لكم ايها الذين فقدوا الصبر وتركوا الطرق المستقيمة ومالوا الى طرق السوء","فماذا تصنعون يوم افتقاد الرب","ان المتقين للرب لا يعاصون اقواله والمحبين له يحفظون طرقه","ان المتقين للرب يبتغون مرضاته والمحبين له يمتلئون من الشريعة","ان المتقين للرب يهيئون قلوبهم ويخضعون امامه نفوسهم","ان المتقين للرب يحفظون وصاياه ويصبرون الى يوم افتقاده","قائلين ان لم نتب نقع في يدي الرب لا في ايدي الناس","لان رحمته على قدر عظمته"],["بنو الحكمة جماعة الصديقين وذريتهم اهل الطاعة والمحبة","يا بني اسمعوا اقوال ابيكم واعملوا بها لكي تخلصوا","فان الرب قد اكرم الاب في الاولاد واثبت حكم الام في البنين","من اكرم اباه فانه يكفر خطاياه ويمتنع عنها ويستجاب له في صلاة كل يوم","و من احترم امه فهو كمدخر الكنوز","من اكرم اباه سر باولاده وفي يوم صلاته يستجاب له","من احترم اباه طالت ايامه ومن اطاع اباه اراح امه","الذي يتقي الرب يكرم ابويه ويخدم والديه بمنزلة سيدين له","اكرم اباك بفعالك ومقالك بكل اناة","لكي تحل عليك البركة منه وتبقى بركته الى المنتهى","فان بركة الاب توطد بيوت البنين ولعنة الام تقلع اسسها","لا تفتخر بهوان ابيك فان هوان ابيك ليس فخرا لك","بل فخر الانسان بكرامة ابيه ومذلة الام عار للبنين","يا بني اعن اباك في شيخوخته ولا تحزنه في حياته","و ان ضعف عقله فاعذر ولا تهنه وانت في وفور قوتك فان الرحمة للوالد لا تنسى","و باحتمالك هفوات امك تجزى خيرا","و على برك يبنى لك بيت وتذكر يوم ضيقك وكالجليد في الصحو تحل خطاياك","من خذل اباه فهو بمنزلة المجدف ومن غاظ امه فهو ملعون من الرب","يا بني اقض اعمالك بالوداعة فيحبك الانسان الصالح","ازدد تواضعا ما ازددت عظمة فتنال حظوة لدى الرب","لان قدرة الرب عظيمة وبالمتواضعين يمجد","لا تطلب ما يعييك نيله ولا تبحث عما يتجاوز قدرتك لكن ما امرك الله به فيه تامل ولا ترغب في استقصاء اعماله الكثيرة","فانه لا حاجة لك ان ترى المغيبات بعينيك","و ما جاوز اعمالك فلا تكثر الاهتمام به","فانك قد اطلعت على اشياء كثيرة تفوق ادراك الانسان","و ان كثيرين قد اضلهم زعمهم وازل عقولهم وهمهم الفاسد","القلب القاسي عاقبته السوء والذي يحب الخطر يسقط فيه","القلب الساعي في طريقين لا ينجح والفاسد القلب يعثر فيهما","القلب القاسي يثقل بالمشقات والخاطئ يزيد خطيئة على خطيئة","داء المتكبر لا دواء له لان جرثومة الشر قد تاصلت فيه","قلب العاقل يتامل في المثل ومنية الحكيم اذن سامعة","القلب الحكيم العاقل يمتنع من الخطايا وينجح في اعمال البر","الماء يطفئ النار الملتهبة والصدقة تكفر الخطايا","من صنع جميلا ذكر في اواخره وصادف سندا في يوم سقوطه"],["يا بني لا تحرم المسكين ما يعيش به ولا تماطل عيني المعوز","لا تحزن النفس الجائعة ولا تغظ الرجل في فاقته","لا تزد القلب المغيظ قلقا ولا تماطل المعوز بعطيتك","لا تاب اعطاء البائس سؤله ولا تحول وجهك عن المسكين","لا تصرف طرفك عن المعوز ولا تصنع شيئا يجلب عليك لعنة الانسان","فان من يلعنك بمرارة نفسه يستجيب صانعه دعاءه","كن متوددا الى الجماعة واخفض راسك لذي الوجاهة","امل اذنك الى المسكين واجبه برفق ووداعة","انقذ المظلوم من يد الظالم ولا تكن صغير النفس في القضاء","كن ابا لليتامى وبمنزلة رجل لامهم","فتكون كابن العلي وهو يحبك اكثر من امك","الحكمة تنشئ لها بنين والذين يلتمسونها تضمهم اليها","من احبها احب الحياة والذين يبتكرون اليها يمتلئون سرورا","من ملكها يرث مجدا وحيثما دخلت فهناك بركة الرب","الذين يعبدونها يخدمون القدوس والذين يحبونها يحبهم الرب","من سمع لها يحكم على الامم ومن اقبل اليها يسكن مطمئنا","اذا استسلم لها يرثها واعقابه يبقون على امتلاكها","فانها في اول الامر تسلك معه بعوج","فتلقي عليه الخوف والرعب وتمتحنه بتاديبها الى ان تثق بنفسه وتختبره في احكامها","ثم تعود فتعامله باستقامة وتسره","و تكشف له اسرارها وتجمع فيه كنوزا من العلم وفهم البر","و اما اذا ذهب في الضلال فهي تخذله وتسلمه الى مصرعه","يا بني احرص على الزمان واحتفظ من الشر","و لا تستحي في امر نفسك","فان من الحياء ما يجلب الخطيئة ومنه ما هو مجد ونعمة","لا تحاب الوجوه فذلك ضرر لنفسك","و لا تستحي حياء به هلاكك","لا تمتنع من الكلام في وقت الخلاص ولا تكتم حكمتك اذا جمل ابداؤها","فانما تعرف الحكمة بالكلام والتاديب بنطق اللسان","لا تخالف الحق بل استحي من جهالتك","لا تستحي ان تعترف بخطاياك ولا تغالب مجرى النهر","و لا تتذلل للرجل الاحمق ولا تحاب وجه المقتدر","جاهد عن الحق الى الموت والرب الاله يقاتل عنك","لا تكن جافيا في لسانك ولا كسلا متوانيا في اعمالك","لا تكن كاسد في بيتك وكمجنون بين اهلك","لا تكن يدك مبسوطة للاخذ مقبوضة عن العطاء"],["لا تعتد باموالك ولا تقل لي بها كفاية","لا تتبع هواك ولا قوتك لتسير في شهوات قلبك","و لا تقل من يتسلط على فان الرب ينتقم منك انتقاما","لا تقل قد خطئت فاي سوء اصابني فان الرب طويل الاناة","لا تكن بلا خوف من قبل الخطيئة المغفورة لتزيد خطيئة على خطيئة","و لا تقل رحمته عظيمة فيغفر كثرة خطاياي","فان عنده الرحمة والغضب وسخطه يحل على الخطاة","لا تؤخر التوبة الى الرب ولا تتباطا من يوم الى يوم","فان غضب الرب ينزل بغتة ويستاصل في يوم الانتقام","لا تعتد باموال الظلم فانها لا تنفعك شيئا في يوم الانتقام","لا تنقلب مع كل ريح ولا تسر في كل طريق فانه كذلك يفعل الخاطئ ذو اللسانين","بل كن ثابتا في فهمك وليكن كلامك واحدا","كن سريعا في الاستماع وكثير التاني في احارة الجواب","ان كان لك فهم فجاوب قريبك والا فاجعل يدك على فمك","في الكلام كرامة وهوان ولسان الانسان تهلكته","لا تدع نماما ولا تختل بلسانك","فان للسارق الخزي ولذي اللسانين المذمة الشديدة","لا تكن جاهلا في كبيرة ولا في صغيرة"],["و لا تصر عدوا بعد ان كنت صديقا فان القبيح السمعة يرث الخزي والعار وكذلك الخاطئ ذو اللسانين","لا تكن كثور مستكبرا بافكار قلبك لئلا تسلب نفسك","فتاكل اوراقك وتتلف اثمارك وتترك نفسك كالخشب اليابس","النفس الشريرة تهلك صاحبها وتجعله شماتة لاعدائه","الفم العذب يكثر الاصدقاء واللسان اللطيف يكثر المؤانسات","ليكن المسالمون لك كثيرين واصحاب سرك من الالف واحدا","اذا اتخذت صديقا فاتخذه عن خبرة ولا تثق به سريعا","فان لك صديقا في يومه ولكنه لا يثبت في يوم ضيقك","و صديقا يصير عدوا فيكشف عار مخاصمتك","و صديقا يشترك في مائدتك ولكنه لا يثبت في يوم ضيقك","يكون نظيرك في اموالك ويتخذ دالة بين اهل بيتك","لكنه اذا انحططت يكون ضدك ويتوارى عن وجهك","تباعد عن اعدائك واحذر من اصدقائك","الصديق الامين معقل حصين ومن وجده فقد وجد كنزا","الصديق الامين لا يعادله شيء وصلاحه لا موازن له","الصديق الامين دواء الحياة والذين يتقون الرب يجدونه","من يتقي الرب يحصل على صداقة صالحة لان صديقه يكون نظيره","يا بني اتخذ التاديب منذ شبابك فتجد الحكمة الى مشيبك","مثل الحارث والزارع اقبل اليها وانتظر ثمارها الصالحة","فانك تتعب في حراثتها قليلا وتاكل من غلاتها سريعا","ما اصعبها على الغير المتادبين ان فاقد اللب لا يستمر عليها","فانها له كحجر الامتحان الثقيل فلا يلبث ان يتركها","لان الحكمة هي كاسمها ولا تستبين لكثيرين والذين يعرفونها تثبت فيهم الى مشاهدة الله","اسمع يا بني واقبل رايي ولا تنبذ مشورتي","و ادخل رجليك في قيودها وعنقك في غلها","احن عاتقك واحملها ولا تغتظ من سلاسلها","اقبل اليها بكل نفسك واحفظ طرقها بكل قوتك","ابحث واطلب فتتعرف لك واذا فزت بها فلا تهملها","فانك في اواخرك تجد راحتها وتتحول لك مسرة","فتكون لك قيودها حماية قوة واغلالها حلة مجد","لان عليها حليا من ذهب وسلاسلها سلك سمنجوني","فتلبسها حلة مجد لك وتعقدها اكليل ابتهاج","ان شئت يا بني فانك تتادب وان استسلمت تستفيد دهاء","ان احببت ان تسمع فانك تعي وان املت اذنك تصير حكيما","قف في جماعة الشيوخ ومن كان حكيما فلازمه ارغب ان تسمع كل حديث الهي ولا تهمل امثال التعقل","و ان رايت عاقلا فابتكر اليه ولتطا قدمك درج بابه","تروا في اوامر الرب وفي وصاياه تامل كل حين فهو يثبت قلبك وينيلك ما تتمناه من الحكمة"],["لا تعمل الشر فلا يلحقك الشر","تباعد عن الاثيم فيميل الاثيم عنك","يا بني لا تزرع في خطوط الاثم لئلا تحصد ما زرعت سبعة اضعاف","لا تلتمس من الرب رئاسة ولا من الملك كرسي مجد","لا تدع البر امام الرب ولا الحكمة لدى الملك","لا تبتغ ان تصير قاضيا لعلك لا تستطيع ان تستاصل الظلم فربما هبت وجه المقتدر فتضع في طريق استقامتك حجر عثار","لا تخطا الى جماعة المدينة ولا تطرح نفسك بين الجمهور","لا تعد الى الخطيئة ثانية فانك لا تكون مزكى من الاولى","لا تكن صغير النفس في صلاتك","و لا تهمل الصدقة","لا تقل ان الله ينظر الى كثرة تقادمي واذا قربتها للعلي فهو يقبلها","لا تستهزئ باحد في مرارة نفسه فانه يوجد من يخفض ويرفع","لا تفتر الكذب على اخيك ولا تختلقه على صديقك","لا تبتغ ان تكذب بشيء فان تعود الكذب ليس للخير","لا تكثر الكلام في جماعة الشيوخ ولا تكرر الالفاظ في صلاتك","لا تكره الشغل المتعب ولا الحراثة التي سنها العلي","لا تنظم نفسك في عداد الخاطئين","اذكر ان الغضب لا يبطئ","ضع نفسك جدا لان عقاب المنافق نار ودود","لا تبدل صديقا بشيء زمني ولا اخا خالصا بذهب اوفير","لا تفارق امراتك اذا كانت حكيمة صالحة فان نعمتها فوق الذهب","لا تعنت عبدا يجد في عمله ولا اجيرا يبذل نفسه","لتحبب نفسك العبد العاقل ولا تمنعه العتق","ان كانت لك دواب فتعهدها وان كان لك منها نفع فابقها عندك","ان كان لك بنون فادبهم واخضع رقابهم من صبائهم","ان كانت لك بنات فصن اجسامهن ولا يكن وجهك اليهن كثير الطلاقة","زوج بنتك تقض امرا عظيما وسلمها الى رجل عاقل","ان كانت لك امراة على وفق قلبك فلا ترفضها اما المكروهة فلا تسلم اليها نفسك","اكرم اباك بكل قلبك ولا تنس مخاض امك","اذكر انك بهما كونت فماذا تجزيهما مكافاة عما جعلا لك","اخش الرب بكل نفسك واحترم كهنته","احبب صانعك بكل قوتك ولا تهمل خدامه","اتق الرب واكرم الكاهن","و اعطه حصته بحسب ما امرت به والباكورة لاجل الخطاء","و عطية الاكتاف وذبيحة التقديس وباكورة الاقداس","و ابسط يدك للفقير لكي تكمل بركتك","كن عارفا للجميل من كل حي ولا تنكر على الميت جميله","لا تتوار عن الباكين ونح مع النائحين","لا تتقاعد عن عيادة المرضى فانك بمثل ذلك تكون محبوبا","في جميع اعمالك اذكر اواخرك فلن تخطا الى الابد"],["لا تخاصم المقتدر لئلا تقع في يديه","لا تنازع الغني لئلا يجعل عليك ثقلا","فان الذهب اهلك كثيرين وازاغ قلوب الملوك","لا تخاصم الفتيق اللسان ولا تجمع على ناره حطبا","لا تمازح الناقص الادب لئلا يهين اسلافك","لا تعير المرتد عن الخطيئة اذكر انا باجمعنا نستوجب المؤاخذة","لا تهن احدا في شيخوخته فان الذين يشيخون هم منا","لا تشمت بموت احد اذكر انا باجمعنا نموت","لا تستخف بكلام الحكماء بل كن لهجا بامثالهم","فانك منهم تتعلم التاديب والخدمة للعظماء","لا تهمل كلام الشيوخ فانهم تعلموا من ابائهم","و منهم تتعلم الحكمة وان ترد الجواب في وقت الحاجة","لا توقد جمر الخاطئ لئلا تحترق بنار لهيبه","لا تنتصب في وجه الشاتم لئلا يترصد لفمك في الكمين","لا تقرض من هو اقوى منك فان اقرضته شيئا فاحسب انك قد اضعته","لا تكفل ما هو فوق طاقتك فان كفلت فاهتم اهتمام من يفي","لا تحاكم القاضي لانه يحكم له بحسب رايه","لا تسر في الطريق مع المتقحم لئلا يجلب عليك وبالا فانه يسعى في هوى نفسه فتهلك انت بجهله","لا تشاجر الغضوب ولا تسر معه في الخلاء فان الدم عنده كلا شيء فيصرعك حيث لا ناصر لك","لا تشاور الاحمق فانه لا يستطيع كتمان الكلام","لا تباشر امرا سريا امام الاجنبي فانك لا تعلم ما سيبدو منه","لا تكشف ما في قلبك لكل انسان فعساه لا يجزيك شكرا"],["لا تغر على المراة التي في حجرك ولا تعلم عليك تعليما سيئا","لا تسلم نفسك الى المراة لئلا تتسلط على قدرتك","لا تلق المراة البغي لئلا تقع في اشراكها","لا تالف المغنية لئلا تصطاد بفنونها","لا تتفرس في العذراء لئلا تعثرك محاسنها","لا تسلم نفسك الى الزواني لئلا تتلف ميراثك","لا تسرح بصرك في ازقة المدينة ولا تتجول في اخليتها","اصرف طرفك عن المراة الجميلة ولا تتفرس في حسن الغريبة","فان حسن المراة اغوى كثيرين وبه يتلهب العشق كالنار","كل امراة زانية تداس كالزبل في الطريق","كثيرون افتتنوا بجمال المراة الغريبة فكان حظهم الرذل لان محادثتها تتلهب كالنار","لا تجالس ذات البعل البتة ولا تتكئ معها على المرفق","و لا تكن لها منادما على الخمر لئلا تميل نفسك اليها وتزل بقلبك الى الهلاك","لا تقاطع صديقك القديم فان الحديث لا يماثله","الصديق الحديث خمر جديدة اذا عتقت لذ لك شربها","لا تغر من مجد الخاطئ فانك لا تعلم كيف يكون انقلابه","لا ترتض بمرضاة المنافقين اذكر انهم الى الجحيم لا يتزكون","تباعد عمن له سلطان على القتل فلا تجري في خاطرك مخافة الموت","و ان دنوت منه فلا تجرم لئلا يذهب بحياتك","اعلم انك تتخطى بين الفخاخ وتتمشى على متارس المدن","اختبر الناس ما استطعت وشاور الحكماء منهم","ليكن مؤاكلوك من الابرار وافتخارك بمخافة الرب","اجعل عشرتك مع العقلاء وكل حديثك في شريعة العلي","يثنى على عمل الصناع لاجل ايديهم اما رئيس الشعب فانه حكيم لاجل كلامه","الفتيق اللسان يخاف منه في مدينته والهاذر في كلامه يمقت"],["القاضي الحكيم يؤدب شعبه وتدبير العاقل يكون مرتبا","كما يكون قاضي الشعب يكون الخادمون له وكما يكون رئيس المدينة يكون جميع سكانها","الملك الفاقد التاديب يدمر شعبه والمدينة تعمر بعقل ولاتها","ملك الارض في يد الرب فهو يقيم عليها في الاوان اللائق من به نفعها","فوز الرجل في يد الرب وعلى وجه الكاتب يجعل مجده","اذا ظلمك القريب في شيء فلا تحنق عليه ولا تات شيئا من امور الشتم","الكبرياء ممقوتة عند الرب والناس وشانها ارتكاب الاثم امام الفريقين","انما ينقل الملك من امة الى امة لاجل المظالم والشتائم والاموال","لا احد اقبح جرما من البخيل لماذا يتكبر التراب والرماد","لا احد اكبر اثما ممن يحب المال لان ذاك يجعل نفسه ايضا سلعة وقد اطرح احشاءه مدة حياته","كل سلطان قصير البقاء ان المرض الطويل يثقل على الطبيب","فيحسم الطبيب المرض قبل ان يطول هكذا الملك يتسلط اليوم وفي غد يموت","و الانسان عند مماته يرث الافاعي والوحوش والدود","اول كبرياء الانسان ارتداده عن الرب","اذ يرجع قلبه عن صانعه فالكبرياء اول الخطاء ومن رسخت فيه فاض ارجاسا","و لذلك انزل الرب باصحابها نوازل غريبة ودمرهم عن اخرهم","نقض الرب عروش السلاطين واجلس الودعاء مكانهم","قلع الرب اصول الامم وغرس المتواضعين مكانهم","قلب الرب بلدان الامم وابادها الى اسس الارض","اقحل بعضها واباد سكانها وازال من الارض ذكرهم","محا الرب ذكر المتكبرين وابقى ذكر المتواضعين بالروح","لم تخلق الكبرياء مع الناس ولا الغضب مع مواليد النساء","اي نسل هو الكريم نسل الانسان اي نسل هو الكريم المتقون للرب اي نسل هو اللئيم نسل الانسان اي نسل هو اللئيم المتعدون الوصايا","فيما بين الاخوة يكون رئيسهم مكرما هكذا في عيني الرب الذين يتقونه","الغني والمجيد والفقير فخرهم مخافة الرب","ليس من الحق ان يهان الفقير العاقل ولا من اللائق ان يكرم الرجل الخاطئ","العظيم والقاضي والمقتدر يكرمون وليس احد منهم اعظم ممن يتقي الرب","العبد الحكيم يخدمه الاحرار والرجل العاقل لا يتذمر","لا تعتل عن الاشتغال بالاعمال ولا تنتفخ في وقت الاعسار","فان الذي يشتغل بكل عمل خير ممن يتمشى او ينتفخ وهو في فاقة الى الخبز","يا بني مجد نفسك بالوداعة واعط لها من الكرامة ما تستحق","من خطئ الى نفسه فمن يزكيه ومن يكرم الذي يهين حياته","الفقير يكرم من اجل عمله والغني يكرم لاجل غناه","من اكرم مع الفقر فكيف مع الغنى ومن اهين مع الغنى فكيف مع الفقر"],["حكمة الوضيع ترفع راسه وتجلسه في جماعة العظماء","لا تمدح الرجل لجماله ولا تذم الانسان لمنظره","النحل صغير في الطيور وجناه راس كل حلاوة","لا تفتخر بتردي الثياب ولا تترفع في يوم الكرامة فان اعمال الرب عجيبة وافعاله خفية عن البشر","كثيرون من المتسلطين جلسوا على التراب والخامل الذكر لبس التاج","كثيرون من المقتدرين لحقهم اشد الهوان والمكرمون سلموا الى ايدي الاخرين","لا تذم قبل ان تفحص تفهم اولا ثم وبخ","لا تجاوب قبل ان تسمع ولا تعترض حديث احد قبل تمامه","لا تجادل في امر لا يعنيك ولا تجلس للقضاء مع الخطاة","يا بني لا تتشاغل باعمال كثيرة فانك ان اكثرت منها لم تخل من ملام ان تتبعتها لم تحشها وان سبقتها لم تنج","رب انسان ينصب ويتعب ويجد ولا يزداد الا فاقة","و رب انسان بليد فاقد المدد قليل القوة كثير الفقر","نظرت اليه عينا الرب بالخير فنعشه من ضعته ورفع راسه فتعجب منه كثيرون","الخير والشر الحياة والموت الفقر والغنى من عند الرب","الحكمة والعلم ومعرفة الشريعة من عند الرب المحبة وطرق الاعمال الصالحة من عنده","الضلال والظلمة خلقا مع الخطاة والذين يرتاحون الى الشر في الشر يشيخون","عطية الرب تدوم للاتقياء ومرضاته تفوز الى الابد","رب غني استغنى باهتمامه وامساكه وانما حظه من اجرته","ان يقول قد بلغت الراحة وانا الان اكل من خيراتي","و هو لا يعلم كم يمضي من الزمان حتى يترك ذلك لغيره ويموت","اقم على عهدك وثابر عليه وشخ في عملك","لا تعجب من اعمال الخطاة امن بالرب وابق على جهدك","فانه هين في عيني الرب ان يغني المسكين في الحال بغتة","بركة الرب في اجرة التقي وهو في لحظة يجعل بركته مزهرة","لا تقل اي حاجة لي واي خير يحصل لي منذ الان","لا تقل لي ما يكفيني فلم اتعنى منذ الان","ان البؤوس تنسى في يوم النعم والنعم لا تذكر في يوم البؤوس","فانه هين عند الرب ان يجازي الانسان بحسب طرقه يوم الموت","شر ساعة ينسي اللذات وفي وفاة الانسان انكشاف اعماله","لا تغبط احدا قبل موته ان الرجل يعرف ببنيه","لا تدخل كل انسان الى بيتك فان مكايد الغشاش كثيرة","كصفة الحجل الصياد في القفص صفة قلب المتكبر وهو كراصد يرقب السقوط","فانه يكمن محولا الخير الى الشر ويصم المختارين بالنقائص","من شرارة واحدة يكثر الحريق والرجل الخاطئ يكمن للدم","احذر من الخبيث الذي يخترع المساوئ لئلا يجلب عليك عارا الى الابد","ادخل الاجنبي الى بيتك فيقلب احوالك بالمشاغب ويطردك عن خاصتك"],["اذا احسنت فاعلم الى من تحسن فيكون معروفك مرضيا","احسن الى التقي فتنال جزاء ان لم يكن من عنده فمن عند العلي","لا خير لمن يواظب على الشر ولا يتصدق لان العلي يمقت الخطاة ويرحم التائبين","اعط التقي ولا تمد الخاطئ فانه سينتقم من المنافقين والخطاة لكنه يحفظهم ليوم الانتقام","اعط الصالح ولا تؤاس الخاطئ","احسن الى المتواضع ولا تعط المنافق امنع خبزك ولا تعطه له لئلا يتقوى به عليك","فتصادف من الشر اضعاف كل ما كنت تصنع اليه من المعروف ان العلي يمقت الخطاة ويكافئ المنافقين بالانتقام","لا يعرف الصديق في السراء ولا يخفى العدو في الضراء","في سراء الرجل اعداؤه محزونون وفي ضرائه الصديق ايضا ينصرف","لا تثق بعدوك ابدا فان خبثه كصدا النحاس","و ان كان متواضعا يمشي مطرقا فتنبه لنفسك وتحرز منه فانك تكون معه كمن جلا مراة وستعلم ان نقاءها من الصدا لا يدوم","لا تجعله قريبا منك لئلا يقلبك ويقيم في مكانك لا تجلسه عن يمينك لئلا يطمع في كرسيك واخيرا تفهم كلامي وتنخس باقوالي","من يرحم راقيا قد لدغته الحية او يشفق على الذين يدنون من الوحوش هكذا الذي يساير الرجل الخاطئ يمتزج بخطاياه","انه يلبث معك ساعة وان ملت لا يثبت","العدو يظهر حلاوة من شفتيه وفي قلبه ياتمر ان يسقطك في الحفرة","العدو تدمع عيناه وان صادف فرصة يشبع من الدم","ان صادفك شر وجدته هناك قد سبقك","و فيما يوهمك انه معين لك يعقل رجلك","يهز راسه ويصفق بيديه ويهمس باشياء كثيرة ويغير وجهه"],["من لمس القير توسخ ومن قارن المتكبر اشبهه","لا ترفع ثقلا يفوق طاقتك ولا تقارن من هو اقوى واغنى منك","كيف يقرن بين قدر الخزف والمرجل انها اذا صدمت تنكسر","الغني يظلم ويصخب والفقير يظلم ويتضرع","ان كنت نافعا استغلك وان كنت عقيما خذلك","ان كان لك مال عاشرك واستنفذ مالك وهو لا يتعب","ان كان له بك حاجة غرك وتبسم اليك ووعدك وكلمك بالخير وقال ما حاجتك","و قدم لك من الاطعمة ما يخجلك حتى يستنفذ ما لك في مرتين او ثلاث واخيرا يستهزئ بك ويراك بعد ذلك فيخذلك وينغض راسه عليك","اخشع لله وانتظر يده","احذر ان تغتر وتتذلل في جهالتك","لا تكن ذليلا في حكمتك لئلا يستدرجك الذل الى الجهالة","اذا دعاك مقتدر فتوار فبذلك يزيد في دعوته لك","لا تقتحم لئلا تطرد ولا تقف بعيدا لئلا تنسى","لا تقدم على محادثته ولا تثق بكلامه الكثير فانه بكثرة مخاطبته يختبرك وبتبسمه اليك يفحصك","انه بلا رحمة لا ينجز ما وعد ولا يمسك عن الاساءة والقيود","احترز وتنبه جدا فانك على شفا السقوط","و ان سمعت بهذه في منامك فتيقظ","في حياتك كلها احبب الرب وادعه لخلاصك","كل حيوان يحب نظيره وكل انسان يحب قريبه","كل ذي جسد يصاحب نوعه والرجل يلازم نظيره","ايقارن الذئب الحمل كذلك شان الخاطئ مع التقي","اي سلام بين الضبع والكلب واي سلام بين الغني والفقير","الفراء في البرية صيد الاسود وكذلك الفقراء هم مراعي الاغنياء","التواضع رجس عند المتكبر وهكذا الفقير رجس عند الغني","الغني اذا تزعزع يثبته اصدقاؤه والمتواضع اذا سقط فاصدقاؤه يطردونه","يزل الغني فيعينه كثيرون يتكلم بالمنكرات فيبرئونه","يزل المتواضع فيوبخونه ينطق بعقل فلا يجعلون لكلامه موضعا","يتكلم الغني فينصت الجميع ويرفعون مقالته الى السحاب","يتكلم الفقير فيقولون من هذا وان عثر يصرعونه","الغنىش يحسن بمن لا خطية له والفقر مستقبح في فم المنافق","قلب الانسان يغير وجهه اما الى الخير واما الى الشر","طلاقة الوجه من طيب القلب والبحث عن الامثال يجهد الافكار"],["طوبى للرجل الذي لم يزل بفيه ولم ينخسه الندم على الخطيئة","طوبى لمن لم يقض عليه ضميره ولم يسقط من رجائه","الغنى لا يجمل بالرجل الشحيح وما منفعة الاموال مع الانسان الحسود","من اختزن بخسران نفسه فانما يختزن للاخرين ويتنعم بخيراته غيره","من اساء الى نفسه فالى من يحسن الم تره لا يتمتع من امواله","لا اسوا ممن يحسد نفسه ان ذلك جزاء خبثه","و ان هو احسن فعن سهو وفي الاخر يبدي خبثه","لا اخبث ممن يحسد بعينه ويحول وجهه ويحتقر النفوس","عين البخيل لا تشبع من حظه وظلم الشرير يضني نفسه","العين الشريرة تحسد على الخبز وعلى مائدتها تكون في عوز","يا بني انفق على نفسك بحسب ما تملك وقرب للرب تقادم تليق به","اذكر ان الموت لا يبطئ الم يبلغك عهد الجحيم","قبل ان تموت احسن الى صديقك وعلى قدر طاقتك ابسط يدك واعطه","لا تخسر يوما صالحا ولا يفتك حظ خير شهي","الست مخلفا اتعابك لاخر وما جهدت فيه للاقتسام بالقرعة","اعط وخذ وزك نفسك","قبل وفاتك اصنع البر فانه لا سبيل الى التماس الطعام في الجحيم","كل جسد يبلى مثل الثوب لان العهد من البدء انه يموت موتا فكما ان اوراق شجرة كثيفة","بعضها يسقط وبعضها ينبت كذلك جيل اللحم والدم بعضهم يموت وبعضهم يولد","كل عمل فاسد يزول وعامله يذهب معه","و كل عمل منتقى يبرر وعامله يكرم لاجله","طوبى للرجل الذي يتامل في الحكمة ويتحدث بها في عقله","و يتفكر في طرقها بقلبه ويتبصر في اسرارها ينطلق في اثرها كالباحث ويترقب عند مداخلها","و يتطلع من كواتها ويتسمع عند ابوابها","و يحل بقرب بيتها ويضرب وتدا في حائطها وينصب خيمته بجانبها وينزل بمنزل الخيرات","يجعل بنيه في كنفها ويسكن تحت اغصانها","يستتر بظلها من الحر وفي مجدها يجد راحة"],["الذي يتقي الرب يعمل ذلك والذي يتمسك بالشريعة ينال الحكمة","تبادر اليه كام وتتخذه كامراة بكر","تطعمه خبز العقل وتسقيه ماء الحكمة فيها يترسخ فلا يتزعزع","و عليها يعتمد فلا يخزى فترفع مقامه عند اصحابه","و تفتح فاه في الجماعة وتملاه من روح الحكمة والعقل وتلبسه حلة المجد","فيرث السرور واكليل الابتهاج واسما ابديا","الجهال من الناس لا يدركونها اما العقلاء فيبادرون اليها والخطاة لا يرونها لانها بعيدة عن الكبرياء والمكر","الكذابون من الناس لا يذكرونها اما الصادقون فيوجدون فيها ويفلحون الى ان يشاهدوا الله","لا يجمل الحمد في فم الخاطئ","لان الخاطئ لم يرسله الرب انما ينطق بالحمد ذو الحكمة والرب ينجحه","لا تقل انما ابتعادي عنها من الرب بل امتنع عن عمل ما يبغضه","لا تقل هو اضلني فانه لا حاجة له في الرجل الخاطئ","كل رجس مبغض عند الرب وليس بمحبوب عند الذين يتقونه","هو صنع الانسان في البدء وتركه في يد اختياره","و اضاف الى ذلك وصاياه واوامره","فان شئت حفظت الوصايا ووفيت مرضاته","و عرض لك النار والماء فتمد يدك الى ما شئت","الحياة والموت امام الانسان فما اعجبه يعطى له","ان حكمة الرب عظيمة هو شديد القدرة ويرى كل شيء","و عيناه الى الذين يتقونه ويعلم كل اعمال الانسان","لم يوص احدا ان ينافق ولا اذن لاحد ان يخطئ","لانه لا يحب كثرة البنين الكفرة الذين لا خير فيهم"],["لا تشته كثرة اولاد لا خير فيهم ولا تفرح بالبنين المنافقين ولا تسر بكثرتهم اذا لم تكن فيهم مخافة الرب","لا تثق بحياتهم وتلتفت الى مكانهم","ولد واحد يتقي الرب خير من الف منافقين","و الموت بلا ولد خير من الاولاد المنافقين","لانه بعاقل واحد تعمر المدينة وقبيلة من الاثماء تخرب","كثير من امثال هذه رايته بعيني واعظم منها سمعت به اذني","في مجمع الخطاة تتقد النار وفي الامة الكافرة يضطرم الغضب","لم يعف عن الجبابرة الاولين الذين تمردوا بقوتهم","و لم يشفق على جيل لوط الذين مقتهم لكبريائهم","و لم يرحم امة الهلاك المتعظمين بخطاياهم","و كذلك الست مئة الف من الرجالة الذين تعصبوا بقساوة قلوبهم بل لو وجد واحد قاسي الرقبة لكان من العجب ان يصفح عنه","لان الرحمة والغضب من عنده هو رب العفو وساكب الغضب","كما انه كثير الرحمة هكذا هو شديد العقاب فيقضي على الرجل بحسب اعماله","لا يفلت الخاطئ بغنائمه ولا يضيع الرب صبر التقي","لكل رحمة يجعل موضعا وكل واحد يلقى ما تستحق اعماله","لا تقل ساتوارى عن الرب العل احدا من العلى يذكرني","اني في شعب كثير لا اذكر فماذا تعتبر نفسي في خلق لا يقدر","ها ان السماء وسماء سماء الله والغمر والارض تتزعزع عند افتقاده","و الجبال واسس الارض ترتعد رعبا عندما ينظر اليها","و في ذلك لا يتامل القلب","و ليس من يفهم طرقه رب زوبعة لا يبصرها الانسان","فان اكثر اعمال الرب في الخفاء اعمال العدل من يخبر بها او من يحتملها ان العهد بعيد والفحص عن الجميع يكون عند الانقضاء","المتواضع القلب يتامل في ذلك اما الرجل الجاهل الضال فيتامل في الحماقات","اسمع لي يا بني وتعلم العلم ووجه قلبك الى كلامي","اني اعبر عن التاديب بوزن وابدي العلم بتدقيق","جميع اعمال الرب من البدء قدرها بحكمة ومنذ انشائها ميز اجزاءها","زين اعماله الى الدهر ومبادئها الى احقابها فلم تجع ولم تتعب ولم تزل تعمل","و لم يضايق بعضها بعضا","و هي لا تعاصي كلمته مدى الدهر","و بعد ذلك نظر الرب الى الارض وملاها من خيراته","و نفوس ذوي الحياة تغطي وجهها واليها تعود"],["خلق الرب الانسان من الارض","و اليها اعاده","جعل لهم وقتا واياما معدودة واتاهم سلطانا على كل ما فيها والبسهم قوة بحسب طبيعتهم وصنعهم على صورته","القى رعبه على كل ذي جسد وسلطه على الوحش والطير","خلق منه عونا بازائه واعطاهم اختيارا ولسانا وعينين واذنين وقلبا يتفكر","و ملاهم من معرفة الحكمة واراهم الخير والشر","و جعل عينه على قلوبهم ليظهر لهم عظائم اعماله","ليحمدوا اسمه القدوس ويخبروا بعظائم اعماله","و زادهم العلم واورثهم شريعة الحياة","و عاهدهم عهد الدهر واراهم احكامه","فرات عيونهم عظائم المجد وسمعت اذانهم مجد صوته وقال لهم احترزوا من كل ظلم","و اوصاهم كل واحد في حق القريب","طرقهم امامه في كل حين فهي لا تخفى عن عينيه","لكل امة اقام رئيسا","اما اسرائيل فهو نصيب الرب","جميع اعمالهم كالشمس امامه وعيناه على الدوام تنظران الى طرقهم","لم تخف عنه اثامهم بل جميع خطاياهم امام الرب","صدقة الرجل كخاتم عنده فيحفظ احسان الانسان كحدقة عينه","و بعد ذلك يقوم ويجازيهم يجازيهم جزاءهم على رؤوسهم ويهبطهم الى بطون الارض","لكنه جعل للتائبين مرجعا وعزى ضعفاء الصبر ورسم لهم نصيب الحق","فتب الى الرب واقلع عن الخطايا","تضرع امام وجهه واقلل من العثرات","ارجع الى العلي واعرض عن الاثم وابغض الرجس اشد بغض فهل من حامد للعلي في الجحيم","تعلم اوامر الله واحكامه وكن ثابتا على حظ التقدمة والصلاة للعلي","ادخل في ميراث الدهر المقدس مع الاحياء المعترفين للرب","لا تلبث في ضلال المنافقين اعترف قبل الموت فان الاعتراف يعدم من الميت اذ يعود كلا شيء","انك ما دمت حيا معافى تحمد الرب وتفتخر بمراحمه","ما اعظم رحمة الرب وعفوه للذين يتوبون اليه","لا يستطيع الناس ان يحوزوا كل شيء لان ابن الانسان ليس بخالد","اي شيء اضوا من الشمس وهذه ايضا تكسف والشرير يفكر في اللحم والدم","الرب يستعرض جنود السماء العليا اما البشر فجميعهم تراب ورماد"],["الحي الدائم خلق جميع الاشياء عامة الرب وحده يتزكى","لم يسمح لاحد ان يخبر باعماله","و من استقصى عظائمه","من يعدد قوة عظمته ومن يقدم على تبيان مراحمه","ليس للانسان ان يسقط من عجائب الرب ولا ان يزيد عليها ولا ان يسبرها","اذا اتم الانسان فحينئذ يبتدئ واذا استراح فحينئذ يتحير","ما الانسان وما منفعته ما خيره وما شره","عدة ايام الانسان على الاكثر مئة سنة كنقطة ماء من البحر وكذرة من الرمل هكذا سنون قليلة في يوم الابدية","فلذلك طالت عليهم اناة الرب وافاض عليهم رحمته","راى وعلم ان منقلبهم هائل","فلذلك اكثر من العفو","رحمة الانسان لقريبه اما رحمة الرب فلكل ذي جسد","يوبخ ويؤدب ويعلم ويرد كالراعي رعيته","يرحم الذين يقبلون تاديبه ويبادرون الى العمل باحكامه","يا بني لا تقرن الصنيعة بالملام ولا العطية بكلام التنغيص","اليس الندى يبرد الحر هكذا الكلام افضل من العطية","اما ترى ان الكلام افضل من العطية وكلاهما عند الرجل المنعم عليه","تعيير الاحمق مكروه وعطية الحاسد تكل العيون","قبل القضاء كن على يقين من الحق وقبل الكلام تعلم","قبل المرض استطب وقبل القضاء افحص نفسك فتنال العفو ساعة الافتقاد","قبل المرض كن متواضعا وعند ارتكاب الخطايا ار توبتك","لا يحبسك شيء عن قضاء نذرك في وقته ولا تحجم عن اعمال البر حتى الموت فان ثواب الرب يبقى الى الابد","قبل الصلاة اهب نفسك ولا تكن كانسان يجرب الرب","اذكر الغضب في ايام الانقضاء ووقت الانتقام عند تحول الوجه","في وقت الشبع اذكر وقت الجوع وفي ايام الغنى اذكر الفقر والعوز","بين الغداة الى العشي يتغير الزمان وكل شيء سريع التحول امام الرب","الحكيم يتحذر في كل شيء وفي ايام الخطايا يحترز من الهفوات","كل عاقل يعرف الحكمة ويعترف لمن يجدها","العقلاء في الكلام يتممون اعمالهم بالحكمة ويفيضون الامثال السديدة","لا تكن تابعا لشهواتك بل عاص اهواءك","فانك ان ابحت لنفسك الرضى بالشهوة جعلتك شماتة لاعدائك","لا تتلذذ بكثرة المادب ولا تلزم نفسك الانفاق عليها","لا تفقر نفسك بالمادب تنفق عليها من الدين وليس في كيسك شيء فانك بذلك تكمن لحياتك"],["العامل الشريب لا يستغني والذي يحتقر اليسير يسقط شيئا فشيئا","الخمر والنساء تجعلان العقلاء اهل ردة","و الذي يخالط الزواني يزداد وقاحة السوس والدود يرثانه والنفس الوقحة تستاصل","من اسرع الى التصديق فهو خفيف العقل ومن خطئ فهو مجرم على نفسه","الذي يتلذذ بالاثم يلحقه الوصم والذي يكره التكلم يقلل الذنوب","الذي يخطا الى نفسه يندم والذي يتلذذ بالشر يلحقه الوصم","لا تنقل كلام السوء فلست بخاسر شيئا","لا تطلع على سرك صديقك ولا عدوك ولا تكشف ما في نفسك لاحد وان لم تكن فيك خطيئة","فانه يسمعك ثم يرصدك ويصير يوما عدوا لك","ان سمعت كلاما فليمت عندك ثق فانه لا يشقك","الاحمق يمخض بالكلمة مخاض الوالدة بالجنين","الكلمة في جوف الاحمق كنبل مغروز في فخذ لحيمة","عاتب صديقك فلعله لم يفعل وان كان قد فعل فلا يعود يفعل","عاتب صديقك فلعله لم يقل وان كان قد قال فلا يكرر القول","عاتب صديقك فان النميمة كثيرة","و لا تصدق كل كلام فرب زال ليست زلته من قلبه","و من الذي لم يخطا بلسانه عاتب قريبك قبل ان تهدده","و ابق مكانا لشريعة العلي كل الحكمة مخافة الرب وفي كل حكمة العمل بالشريعة","ليست الحكمة علم الشر وحيث تكون مشورة الخطاة فليست هناك الفطنة","فان من الشر ما هو رجس ومن الجهال من نقص حظه من الحكمة","ناقص العقل وهو تقي خير من وافر الفطنة وهو يتعدى الشريعة","رب دهاء يكون محكما وهو جائر","و رب رجل يهدم المحبة ليبدي العدل رب شرير يمشي مكبا في الحداد وبواطنه مملوءة مكرا","يكب بوجهه ويصم احدى اذنيه وحين لا تشعر يفاجئك","و ان منعه العجز من الاساءة فاذا صادف فرصة فعل","من منظره يعرف الرجل ومن استقبال الوجه يعرف العاقل","لبسة الرجل وضحكة الاسنان ومشية الانسان تخبر بما هو عليه","رب عتاب لا يجمل ورب صامت عن فطنة"],["العتاب خير من الحقد والمقر يكفي الخسران","الخصي المتشهي يفسد البكر","و هكذا فعل من يقضي قضاء الجور","ما احسن ابداءك الندامة اذا وبخت فانك بذلك تجتنب الخطيئة الاختيارية","رب ساكت يعد حكيما ورب متكلم يكره لطول حديثه","من الساكتين من يسكت لانه لا يجد جوابا ومن يسكت لانه يعرف الاوقات","الانسان الحكيم يسكت الى حين اما العاتي والجاهل فلا يبالي بالاوقات","الكثير الكلام يمقت والمتسلط جورا يبغض","رب نجاح يكون لاذى صاحبه ورب وجدان يكون لخسرانه","رب عطية لا تنفعك ورب عطية تكون مضاعفة الجزاء","رب انحطاط سببه المجد ورب تواضع يرفع به الراس","رب مشتر كثيرا بقليل يدفع ثمنه سبعة اضعاف","الحكيم يحبب نفسه بالكلام ونعم الحمقى تفاض سدى","عطية الجاهل لا تنفعك لان له عوض العينين عيونا","يعطي يسيرا ويمتن كثيرا ويفتح فاه مثل المنادي","يقرض اليوم ويطالب غدا ان انسان مثل هذا لبغيض","يقول الاحمق لا صديق لي وصنائعي غير مشكورة","ان الذين ياكلون خبزي خبثاء اللسان ما اكثر المستهزئين به واكثر استهزاءاتهم","فانه لا يدركك حق الادراك ماذا يستبقي ولا يبالي بما لا يستبقي","الزلة عن السطح ولا الزلة من اللسان فان سقوط الاشرار يفاجئ سريعا","الانسان السمج كحديث في غير وقته لا يزال في افواه فاقدي الادب","يرذل المثل من فم الاحمق لانه لا يقوله في وقته","رب انسان يمنعه اقلاله عن الخطيئة وفي راحته لا ينخسه ضميره","من الناس من يهلك نفسه من الحياء وانما يهلكها لاجل شخص الجاهل","و من يعد صديقه من الحياء فيصيره عدوا له بغير سبب","الكذب عار قبيح في الانسان وهو لا يزال في افواه فاقدي الادب","السارق خير ممن يالف الكذب لكن كليهما يرثان الهلاك","شان الانسان الكذوب الهوان وخزيه معه على الدوام","الحكيم في الكلام يشتهر والانسان الفطن يرضي العظماء","الذي يفلح الارض يعلي كدسه والذي يرضي العظماء يكفر الذنب","الهدايا والرشى تعمي اعين الحكماء وكلجام في الفم تحجز توبيخاتهم","الحكمة المكتومة والكنز المدفون اي منفعة فيهما","الانسان الذي يكتم حماقته خير من الانسان الذي يكتم حكمته"],["يا بني ان خطئت فلا تزد بل استغفر عما سلف من الخطاء","اهرب من الخطيئة هربك من الحية فانها ان دنوت منها لدغتك","انيابها انياب اسد تقتل نفوس الناس","كل اثم كسيف ذي حدين ليس من جرحه شفاء","التقريع والشتم يسلبان الغنى وبمثل ذلك يسلب بيت المتكبر","تضرع الفقير يبلغ الى اذني الرب فيجرى له القضاء سريعا","من مقت التوبيخ فهو في اثر الخاطئ ومن اتقى الرب يتوب بقلبه","السليط اللسان بعيد السمعة لكن العاقل يعلم متى يسقط","من بنى بيتا باموال غيره فهو كمن يجمع حجارته في الشتاء","جماعة الاثماء مشاقة مجموعة وغايتها لهيب نار","طريق الخطاة مفروش بالبلاط وفي منتهاه حفرة الجحيم","من حفظ الشريعة فطن لروحها","و غاية مخافة الرب الحكمة","من لم يكن ذا دهاء لم يؤدب","و رب دهاء يكثر المرارة","علم الحكيم يفيض كالعباب ومشورته كينبوع حياة","باطن الاحمق كاناء مكسور لا يضبط شيئا من العلم","العالم اذا سمع كلام حكمة مدحه وزاد عليه اما الخليع فاذا سمعه كرهه ونبذه وراء ظهره","حديث الاحمق كحمل في الطريق وانما اللطف على شفتي العاقل","فم الفطن يبتغى في الجماعة وكلامه يتامل به في القلب","الحكمة للاحمق كبيت مخرب وعلم الجاهل كلام لا يفهم","التاديب للجهال كالقيود في الرجلين وكالوثاق في اليد اليمنى","الاحمق يرفع صوته عند الضحك اما ذو الدهاء فيبتسم قليلا بسكون","التاديب للفطن كحلية من ذهب وكسوار في ذراعه اليمنى","قدم الاحمق تسرع الى داخل البيت اما الانسان الواسع الخبرة فيستحيي","الجاهل يتطلع من الباب الى داخل البيت اما الرجل المتادب فيقف خارجا","من قلة الادب التسمع على الباب والفطن يستثقل ذلك الهوان","شفاه الجهال تحدث بالخزعبلات وكلام الفطنين يوزن بالميزان","قلوب الحمقى في افواههم وافواه الحكماء في قلوبهم","اذا لعن المنافق الشيطان فقد لعن نفسه","النمام ينجس نفسه ومعاشرته مكروهة"],["الكسلان اشبه بحجر قذر كل احد يصفر لهوانه","الكسلان اشبه بزبل الدمن كل من قبضه ينفض يده","الابن الفاقد الادب عار لابيه والبنت انما تعقب الخسران","البنت الفطينة ميراث لرجلها والبنت المخزية غم لوالدها","الوقحة تخزي اباها ورجلها وكلاهما يهينانها","الكلام في غير وقته كالغناء في النوح اما السياط والتاديب فهما في كل وقت حكمة","الذي يعلم الاحمق يجبر اناء من خزف","و ينبه مستغرقا في نومه","من كلم الاحمق فانما يكلم متناعسا فاذا انتهى قال ماذا","ابك على الميت لانه فقد النور وابك على الاحمق لانه فقد العقل","اقلل من البكاء على الميت فانه في راحة","اما الاحمق فحياته اشقى من موته","النوح على الميت سبعة ايام والنوح على الاحمق والمنافق جميع ايام حياته","لا تكثر الكلام مع الجاهل ولا تخالط الغبي","تحفظ منه لئلا يعنتك وينجسك برجسه","اعرض عنه فتجد راحة ولا يغمك سفهه","اي شيء اثقل من الرصاص وماذا يسمى الا احمق","الرمل والملح والحديد اخف حملا من الانسان الجاهل","عرق الخشب المربوطة في البناء لا تتفكك في الزلزلة كذلك القلب المعتمد على مشورة سديدة لا يخاف اصلا","القلب المستند على راي عاقل كزينة من رمل على حائط مصقول","كما ان الاوتاد الموضوعة في مكان عال لا تثبت امام الريح","كذلك قلب الاحمق الخائف الافكار لا يثبت امام هول من الاهوال","قلب الاحمق يخاف في افكاره اما الذي يستمر على وصايا الله في كل حين فلا يخاف ابدا","من نخس العين اسال الدموع ومن نخس القلب ابرز الحس","من رمى الطيور بالحجر نفرها ومن عير صديقه قطع الصداقة","ان جردت السيف على صديقك فلا تياس فانه يرجع","ان فتحت فمك على صديقك فلا تخف فانه يصالح الا في التعيير والتكبر وافشاء السر والجرح بالمكر فانه في هذه يفر كل صديق","ابق امينا للقريب في فقره لكي تشبع معه من خيراته","اثبت معه في وقت ضيقه لكي تشترك في ميراثه","قبل النار بخار الاتون والدخان وكذلك قبل الدماء التقريعات","لا استحيي ان ادفع عن صديقي ولا اتوارى عن وجهه ثم ان اصابني منه شر","فكل من يسمع بذلك يتحفظ منه","من يجعل حارسا لفمي وخاتما وثيقا على شفتي لئلا اسقط بسببهما ويهلكني لساني"],["ايها الرب الاب يا سيد حياتي لا تتركني ومشورة شفتي ولا تدعني اسقط بهما","من ياخذ افكاري بالسياط وقلبي بتاديب الحكمة بحيث لا يشفق على جهالاتي ولا تهمل خطاياي","لكي لا تتكاثر جهالاتي وتتوافر خطاياي فاسقط تجاه اضدادي ويشمت عدوي بي","ايها الرب الاب يا اله حياتي لا تتركني ومشورة شفتاي","لا تدعني اطمح بعيني والهوى اصرفه عني","لا تملكني شهوة البطن ولا الزنى ولا تسلمني الى نفس وقحة","ايها البنون دونكم ادب الفم فان من يحفظه لا يؤخذ بشفتيه","انه بهما يصطاد الخاطئ وبهما يعثر القاذف والمتكبر","لا تعود فاك الحلف","و لا تالف تسمية القدوس","فانه كما ان العبد الذي لا يزال يفحص لا يخلو من الحبط كذلك من لم يبرح يحلف ويسمي لا يتزكى","الرجل الحلاف يمتلئ اثما ولا يبرح السوط من بيته","و هو ان لم يف فعليه خطيئة وان استخف فخطيئته مضاعفة","و ان حلف باطلا لا يبرر وبيته يملا نوائب","و من الكلام كلام اخر يلابسه الموت لا كان في ميراث يعقوب","ان هذه كلها تبعد عن الاتقياء فلا يتمرغون في الخطايا","لا تعود فاك فحش الكلام فان ذلك لا يخلو من خطيئة","تذكر اباك وامك اذا جلست بين العظماء","لئلا تنساهما امامهم ويسفهك تعود معاشرتهم فتود لو لم تولد منهما وتلعن يوم ولادتك","من تعود كلام الشتيمة لا يتادب طول ايامه","من الناس صنفان يكثران من الخطايا وصنف ثالث يجلب الغضب","النفس المتوهجة كنار ملتهبة فلا تنطفئ الى ان تفنى","و الانسان الزاني بنجاسة لحمه فلا يكف الى ان يوقد النار","لان الانسان الزاني كل خبز يحلو له فلا يكل الى ان يفرغ","و الانسان الذي يتعدى على فراشه قائلا في نفسه من يراني","حولي الظلمة والحيطان تسترني ولا احد يراني فماذا اخشى ان العلي لا يذكر خطاياي","و هو انما يخاف من عيون البشر","و لا يعلم ان عيني الرب اضوا من الشمس عشرة الاف ضعف فتبصران جميع طرق البشر وتطلعان على الخفايا","هو عالم بكل شيء قبل ان يخلق فكذلك بعد ان انقضى","فهذا يعاقب في شوارع المدينة وحيث لا يظن يقبض عليه","و يهان من الجميع لانه لم يفهم مخافة الرب","هكذا ايضا المراة التي تترك بعلها وتجعل له وارثا من الغريب","لانها اولا عصت شريعة العلي وثانيا خانت رجلها وثالثا تنجست بالزنى واقامت نسلا من رجل غريب","فهذه يؤتى بها الى الجماعة وتبحث احوال اولادها","ان اولادها لا يتاصلون واغصانها لا تثمر","و هى تخلف ذكرا ملعونا وفضيحتها لا تمحى","فيعرف المتخلفون ان لا شيء افضل من مخافة الرب ولا شيء اعذب من رعاية وصايا الرب","ان اتباع الله مجد عظيم وفي قبوله لك طول ايام"],["الحكمة تمدح نفسها وتفتخر بين شعبها","تفتح فاها في جماعة العلي وتفتخر امام جنوده","و تعظم في شعبها وتمجد في ملا القديسين","و تحمد في جميع المختارين وتبارك بين المباركين وتقول","اني خرجت من فم العلي بكرا قبل كل خليقة","و جعلت النور يشرق في السماوات على الدوام وغشيت الارض كلها بمثل الضباب","و سكنت في الاعالي وجعلت عرشي في عمود الغمام","انا وحدي جلت في دائرة السماء وسلكت في عمق الغمار ومشيت على امواج البحر","و داست قدمي كل الارض وعلى كل شعب","و كل امة تسلطت","و وطئت بقدرتي قلوب الكبار والصغار في هذه كلها التمست الراحة وباي ميراث احل","حينئذ اوصاني خالق الجميع والذي حازني عين مقر مسكني","و قال اسكني في يعقوب ورثي في اسرائيل","قبل الدهر من الاول حازني والى الدهر لا ازول وقد خدمت امامه في المسكن المقدس","و هكذا في صهيون ترسخت وجعل لي مقرا في المدينة المحبوبة وسلطنتي هي في اورشليم","فتاصلت في شعب مجيد وفي نصيب الرب نصيب ميراثه وفي ملا القديسين مقامي","ارتفعت كالارز في لبنان وكالسرو في جبال حرمون","كالنخل في السواحل وكغراس الورد في اريحا","كالزيتون النضير في السهل وكالدلب على مجارى المياه في الشوارع","فاح عرفي كالدارصيني والقندول العطر وانتشرت رائحتي كالمر المنتقى","كالقنة والجزع والميعة ومثل بخور اللبان في المسكن","اني مددت اغصاني كالبطمة واغصاني اغصان مجد ونعمة","انا كالكرمة المنبتة النعمة وازهاري ثمار مجد وغنى","انا ام المحبة البهية والمخافة والعلم والرجاء الطاهر","في كل نعمة الطريق والحق وكل رجاء الحياة والفضيلة","تعالوا الي ايها الراغبون في واشبعوا من ثماري","فان روحي احلى من العسل وميراثي الذ من شهد العسل","و ذكري يبقى في اجيال الدهور","من اكلني عاد الي جائعا ومن شربني عاد ظامئا","من سمع لي فلا يخزى ومن عمل بارشادي فلا يخطا","من شرحني فله الحياة الابدية","هذه كلها هي سفر الحياة وعهد العلي وعلم الحق","ان موسى امر بالشريعة واحكام العدل ميراث ال يعقوب ومواعيد اسرائيل","ان الرب وعد داود عبده ان يقيم منه الملك القدير الجالس على عرش المجد الى الابد","هو يفيض الحكمة كفيشون ومثل دجلة في ايام الغلال","و يملا فهما كالفرات ومثل الاردن في ايام الحصاد","و يبدي التاديب كالنور ومثل جيحون في ايام القطاف","الحكمة لا يستوفي معرفتها الاول ولا يستقصيها الاخر","لان فكرها اوسع من البحر ومشورتها اعمق من الغمر العظيم","انا الحكمة مفيضة الانهار","انا كساقية من النهر وكقناة خرجت الى الفردوس","قلت اسقي جنتي واروي روضتي","فاذا بساقيتي قد صارت نهرا وبنهري قد صار بحرا","فاني اضيء بالتاديب مثل الفجر واذيع الى الاقاصي","انفذ الى جميع اعماق الارض وانظر الى جميع الراقدين وانير لجميع الذين يرجون الرب","اني افيض التعليم مثل نبوة واخلفه لاجيال الدهور","فانظروا كيف لم يكن عنائي لي وحدي بل ايضا لجميع الذين يلتمسون الحكمة"],["ثلاث هن زينة لي وبهن قمت جميلة امام الرب والناس","اتفاق الاخوة وحب القريب والمصافاة بين المراة ورجلها","ثلاثة تبغضهم نفسي وتمقت حياتهم","الفقير المتكبر والغني الكذاب والشيخ الزاني الفاقد الفهم","ان لم تدخر في شبابك فكيف تجد في شيخوختك","ما اجمل القضاء للشيب وحسن المشورة للشيوخ","ما اجمل الحكمة للشيوخ والراي والمشورة لارباب المجد","كثرة الخبرة اكليل الشيوخ ومخافة الرب فخرهم","تسع خصال غبطتها في قلبي والعاشرة ينطق بها لساني","مغبوط الانسان الذي يفرح بالاولاد والذي يرى في حياته سقوط اعدائه","مغبوط من يساكن امراة عاقلة ومن لم يزلل بلسانه ومن لم يخدم من لا يستاهله","مغبوط من وجد الفطنة ومن يجعل حديثه في اذن واعية","ما اعظم من وجد الحكمة لكنه ليس افضل ممن يتقي الرب","مخافة الرب اعلى من كل شيء","الذي يحوزها بمن يشبه","مخافة الرب اول محبته والايمان اول الاتصال به","غاية الالم الم القلب وغاية الخبث خبث المراة","كل الم ولا الم القلب","و كل خبث ولا خبث المراة","و كل نائبة ولا النائبة من المبغضين","و كل انتقام ولا انتقام الاعداء","لا راس شر من راس الحية","و لا غضب شر من غضب المراة مساكنة الاسد والتنين خير عندي من مساكنة المراة الخبيثة","خبث المراة يغير منظرها ويرد وجهها اسود كالمسح","رجلها يكمد بين اصحابه واذا سمع تاوه بمرارة","كل سوء بازاء سوء المراة خفيف لتقع قرعة الخاطئ عليها","مثل العقبة الكثيرة الرمل لقدمي الشيخ مثل المراة الخبيثة اللسان للرجل الهادئ","لا يعثرك جمال امراة ولا تشته امراة لحسنها","غضب ووقاحة وفضيحة عظيمة","المراة التي تتسلط على رجلها","المراة الشريرة ذلة للقلب وتقطيب للوجه والم للفؤاد","التي لا تنشئ سعادة رجلها انما هي تراخ لليدين وتخلع للركبتين","من المراة ابتدات الخطيئة وبسببها نموت نحن اجمعون","لا تجعل للماء مخرجا ولا للمراة الشريرة سلطانا","ان لم تسلك طوع يدك تخزيك امام اعدائك","فاقطعها عن جسدك لئلا تؤذيك على الدوام"],["رجل المراة الصالحة مغبوط وعدد ايامه مضاعف","المراة الفاضلة تسر رجلها وتجعله يقضي سنيه بالسلام","المراة الصالحة نصيب صالح تمنح حظا لمن يتقي الرب","فيكون قلبه جذلا ووجهه بهجا كل حين غنيا كان ام فقيرا","ثلاث خاف منهن قلبي وعلى الرابعة ابتهلت بوجهي","شكاية المدينة وتالب الجمع","و البهتان كل ذلك اثقل من الموت","لكن المراة الغائرة من المراة وجع قلب ونوح","و لسانها سوط يصيب الجميع","المراة الشريرة نير قلق ومثل متخذها مثل من يمسك عقربا","المراة السكيرة سخط عظيم وفضيحتها لا تستر","زنى المراة في طموح البصر ويعرف من جفنيها","واظب على مراقبة البنت القليلة الحياء لئلا تجد فرصة فتبذل نفسها","تنبه لطرفها الوقح ولا تعجب اذا عقتك","تفتح فمها كالمسافر العطشان وتشرب من كل ماء صادفته وتجلس عند كل جذع وتفتح الكنانة تجاه كل سهم","لطف المراة ينعم رجلها","و ادبها يسمن عظامه","المراة المحبة للصمت عطية من الرب والنفس المتادبة لا يستبدل بها","المراة الحيية نعمة على نعمة","و النفس العفيفة لا قيمة توازنها","الشمس تشرق في على الرب وجمال المراة الصالحة في عالم بيتها","السراج يضيء على المنارة المقدسة وحسن الوجه على القامة الرزينة","العمد من الذهب تقوم على قواعد من الفضة والساقان الجميلتان على اخمصي ذات الوقار","الاسس على الصخر تثبت الى الابد ووصايا الرب في قلب المراة الطاهرة","اثنان يحزن لهما قلبي والثالث ياخذني عليه الغضب","رجل الحرب اذا اعجزته الفاقة والرجال العقلاء اذا اهينوا","اما من ارتد عن البر الى الخطيئة فالرب يستبقيه للسيف","قلما يتخلص التاجر من الاثم والخمار لا يتزكى من الخطيئة"],["كثيرون خطئوا لاجل عرض الدنيا والذي يطلب الغنى يغضي طرفه","بين الحجارة المتضامة يغرز الوتد وبين البيع والشراء تنشب الخطيئة","و سيسحق الاثم مع الاثيم","من لم يحرص على الثبات في مخافة الرب يهدم بيته سريعا","عند هز الغربال يبقى الزبل كذلك كساحة الانسان عند تفكره","انية الخزاف تختبر بالاتون والانسان يمتحن بحديثه","حراثة الشجر تظهر من ثمرها كذلك تفكر قلب الانسان يظهر من كلامه","لا تمدح رجلا قبل ان يتكلم فانه بهذا يمتحن الناس","اذا تعقبت العدل فانك تدركه وتلبسه حلة مجد وتسكن معه فيصونك الى الابد وفي يوم الافتقاد تجد سندا","الطيور تاوى الى اشكالها والحق يعود الى العاملين به","الاسد يكمن للفريسة كذلك الخطايا تكمن لفاعلي الاثم","حديث التقي في كل حين حكمة اما الجاهل فيتغير كالقمر","بين السفهاء ترقب الفرصة وبين العقلاء كن مواظبا","حديث الحمقى مكروه وضحكهم في ملذات الخطيئة","محادثة الحلاف تقف الشعر ومخاصمته سد الاذان","مخاصمة المتكبرين سفك الدماء ومشاتمتهم سماع ثقيل","الذي يفشي الاسرار يهدم الثقة ولا يجد صديقا لنفسه","احبب الصديق وكن معه امينا","لكن ان افشيت اسراره فلا تطلبه من بعد","فان من اتلف صداقة القريب كان بمنزلة من اتلف عدوه","و مثل تسريحك للقريب مثل اطلاقك طائرا من يدك فلا تعود تصطاده","لا تطلبه فانه قد ابتعد وفر كالظبي من الفخ","ان الجرح له ضماد والمشاتمة بعدها صلح","اما الذي يفشي الاسرار فشانه الياس","الغامز بالعين يختلق الشرور وليس من يتجنبه","امام عينيك يحلو بفمه ويستحسن كلامك ثم يقلب منطقه ومن كلامك يلقي امامك معثرة","قد ابغضت امورا كثيرة ولكن لا كبغضي له والرب سيبغضه","من رمى حجرا الى فوق فقد رماه على راسه والضربة بالمكر تجرح الماكر","من حفر حفرة سقط فيها ومن نصب شركا اصطيد به","من صنع المساوئ فعليه تنقلب ولا يشعر من اين تقع عليه","الاستهزاء والتعيير شان المتكبرين والانتقام يكمن لهم مثل الاسد","الشامتون بسقوط الاتقياء يصطادون بالشرك والوجع يفنيهم قبل موتهم","الحقد والغضب كلاهما رجس والرجل الخاطئ متمسك بهما"],["من انتقم يدركه الانتقام من لدن الرب ويترقب الرب خطاياه","اغفر لقريبك ظلمه لك فاذا تضرعت تمحى خطاياك","ايحقد انسان على انسان ثم يلتمس من الرب الشفاء","ام لا يرحم انسانا مثله ثم يستغفر عن خطاياه","ان امسك الحقد وهو بشر فمن يكفر خطاياه","اذكر اواخرك واكفف عن العدواة","اذكر الفساد والموت واثبت على الوصايا","اذكر الوصايا ولا تحقد على القريب","اذكر ميثاق العلي واغض عن الجهالة","امسك عن النزاع فتقلل الخطايا","فان الانسان الغضوب يضرم النزاع والرجل الخاطئ يبلبل الاصدقاء ويلقي الشقاق بين المسالمين","بحسب الحطب تضطرم النار وبحسب قوة الانسان يكون غيظه وبحسب غناه يثير غضبه وبحسب شدة النزاع يستشيط","الخصومة عن عجلة تضرم النار والنزاع عن عجلة يسفك الدم","اذا نفخت في شرارة اضطرمت واذا تفلت عليها انطفات وكلاهما من فمك","النمام وذو اللسانين اهل للعنة لاهلاكهما كثيرين من اهل المسالمة","اللسان الثالث اقلق كثيرين وبددهم من امة الى امة","و هدم مدنا محصنة وخرب بيوت العظماء","و كسر جيوش الشعوب وافنى امما ذات اقتدار","اللسان الثالث طرد نساء فاضلات وسلبهن اتعابهن","من اصغى اليه لا يجد راحة ولا يسكن مطمئنا","ضربة السوط تبقي حبطا وضربة اللسان تحطم العظام","كثيرون سقطوا بحد السيف لكنهم ليسوا كالساقطين بحد اللسان","طوبى لمن وقي شره ولم يعرض على غضبه ولم يحمل نيره ولم يوثق بقيوده","فان نيره نير من حديد وقيوده قيود من نحاس","الموت به موت قاس والجحيم انفع منه","لكنه لا يتسلط على الاتقياء ولا هم يحترقون بلهيبه","بل الذين يتركون الرب يقعون تحت سلطانه فيشتعل فيهم ولا ينطفئ يطلق عليهم كالاسد ويفترسهم كالنمر","سيج ملكك بالشوك","احبس فضتك وذهبك واجعل لكلامك ميزانا ومعيارا ولفمك بابا ومزلاجا","و احذر ان تزل به فتسقط امام الكامن لك"],["الذي يصنع رحمة يقرض القريب والسخي اليد يحفظ الوصايا","اقرض القريب في وقت حاجته واقضه ما له عليك في اجله","حقق ما نطقت به وكن امينا معه فتنال في كل حين بغيتك","كثيرون حسبوا القرض لقطة فعنوا الذين امدوهم","قبل ان يقبض يقبل اليد ويخشع بصوته حتى ينال مال القريب","فاذا ان الرد ماطل ونطق بكلام مضجر وشكا صرف الدهر","ان كان الرد في طاقته لم يكد يرد النصف ويحسب ما رده لقطة","و الا فيسلبه امواله ويتخذه عدوا بلا سبب","يجزيه اللعنة والشتيمة وبدل الاكرام يكافئه الاهانة","كثيرون امسكوا لاجل خبث الناس مخافة ان يسلبوا بغير سبب","مع ذلك كن طويل الاناة على البائس ولا تماطله في الصدقة","لاجل الوصية اعن المسكين وفي عوزه لا تردده فارغا","اتلف فضتك على اخيك وصديقك ولا تدعها تصدا تحت الحجر وتتلف","انفق ذخيرتك بحسب وصايا العلي فتنفعك اكثر من الذهب","اغلق على الصدقة في اخاديرك فهي تنقذك من كل شر","تقاتل عنك عدوك اكثر من ترس الباس ورمح الحماسة","الرجل الصالح يكفل القريب والذي فقد كل حياء يخذله","لا تنس نعم الكافل فانه بذل نفسه لاجلك","الخاطئ يهرب من كافله واللئيم الروح يخذله","الخاطئ يدمر خيرات الكافل وجاحد الجميل يخذل مخلصه","من الناس من يكفل قريبه لكنه يفقد كل حياء فيخذله","كثيرون كانوا في نجح فاهلكتهم الكفالة واقلقتهم كامواج البحر","الجات رجالا مقتدرين الى المهاجرة فتاهوا بين امم غريبة","الخاطئ الذي يتهافت على الكفالة ويصبوا الى المعاملات يقع تحت الاقضية","امدد قريبك بقدر طاقتك واحذر على نفسك ان تسقط","راس المعيشة الماء والخبز واللباس والبيت الساتر للسوءة","عيش الفقير تحت سقف من الواح خير من الاطعمة الفاخرة في دار الغربة","ارض بالقليل والكثير فلا تسمع تعييرا في امر البيت","بئس حياة الانسان من بيت الى بيت وحيثما ضاف لم يفتح فاه","تطعم وتسقي جاحدين لجميلك وانت ضيفهم ووراء ذلك تسمع اقوالا مرة","ان قم يا ضيف جهز المائدة وان كان بيدك شيء فاطعمني","انصرف يا ضيف من امام شخص كريم ان اخا لي يتضيفني فانا محتاج الى البيت","امران يستثقلهما الانسان الفطن الانتهار في امر البيت وتعيير المقرض"],["من احب ابنه اكثر من ضربه لكي يسر في اخرته","من ادب ابنه يجتني ثمر تاديبه ويفتخر به بين الوجهاء","من علم ابنه يغير عدوه ويبتهج به امام اصدقائه","اذا توفى ابوه فكانه لم يمت لانه خلف من هو نظيره","في حياته راى وفرح وعند وفاته لم يحزن","خلف منتقما من الاعداء ومكافئا للاصدقاء بالجميل","من دلل ابنه فسيضمد جراحه وعند كل صراخ تضطرب احشاءه","الفرس الذي لم يرض يصير جموحا والابن الذي لم يضبط يصير سفيها","ان دللت ابنك روعك وان لاعبته حزنك","لا تضاحكه لئلا يغمك وفي اواخرك ياخذك صريف الاسنان","لا تجعل له سلطانا في صبائه ولا تهمل جهالاته","احن رقبته في صبائه وارضض اضلاعه ما دام صغيرا لئلا يتصلب فيعصيك فياخذك وجع القلب","ادب ابنك واجتهد في تهذيبه لئلا يسقط فيما يخجلك","فقير ذو عافية وصحيح البنية خير من غني منهوك بالاسقام","العافية وصحة البنية خير من كل الذهب وقوة الجسم افضل من نشب لا يحصى","لا غنى خير من عافية الجسم ولا سرور يفوق فرح القلب","الموت افضل من الحياة المرة او السقم الملازم","الخيرات المسكوبة على فم مغلق كالاطعمة الموضوعة على قبر","اي منفعة للصنم بالقربان فانه لا ياكل ولا يشم","هكذا من يرهقه الرب ويجازيه على اثامه","يرى بعينيه ويتنهد كالخصي الذي يعانق عذراء ثم يتنهد","لا تغم نفسك ولا تضيق صدرك بافكارك","سرور القلب حياة الانسان وابتهاج الرجل طول الايام","احبب نفسك وفرج عن قلبك وانف الحزن عنك بعيدا","فان الحزن قتل كثيرين وليس فيه ثمرة","الغيرة والغضب يقللان الايام والغمة تاتي بالشيخوخة قبل الاوان","القلب البهج الصالح لا يزال في الولائم ومادبة معدة باهتمام"],["السهر لاجل الغنى يذيب الجسم والاهتمام به ينفي النوم","سهر الاهتمام يحرم الوسن والمرض الشديد يذهبه النوم","يجد الغني في جمع الاموال وفي راحته يشبع من اللذات","يجد الفقير في حاجة العيش وفي راحته يمسي معوزا","من احب الذهب لا يزكى ومن اتبع الفساد يشبع منه","كثيرون سقطوا لاجل الذهب فاضحى هلاكهم امام وجوههم","الذهب عود عثار للذين يذبحون له وكل جاهل يصطاد به","طوبى للغني الذي وجد بغير عيب ولم يسع وراء الذهب","من هو فنغبطه لانه صنع عجائب في شعبه","من الذي امتحن به فوجد كاملا به فليفتخر من الذي قدر ان يتعدى فلم يتعد وان يصنع الشر ولم يصنع","ستكون خيراته ثابتة وتخبر الجماعة بصدقاته","اذا جلست على مائدة حافلة فلا تفتح لها حنجرتك","و لا تقل ما اكثر ما عليها","اذكر ان العين الشريرة سوء عظيم","اي شيء خلق اسوا من العين فلذلك هي تدمع من كل شخص","حيثما لحظت فلا تمدد اليه يدك","و لا تزاحمها في الصحفة","افهم ما عند القريب مما عندك وتامل في كل امر","كل مما وضع امامك كما ياكل الانسان ولا تكن لهما لئلا تكره","و كن اول من امسك مراعاة للادب ولا تتضلع لئلا ينكر عليك","و اذا اتكات بين كثيرين فلا تمدد يدك قبلهم","ما اقل ما يكتفي به الانسان المتادب ومثل هذا لا تاخذه الكظة على فراشه","السهاد والهيضة والمغص للرجل الشره","رقاد الصحة لقنوع الجوف يقوم باكرا وهو مالك نفسه","و اذا اكرهت على الاكل فاعتزل من بين الجماعة فتستريح","اسمع لي يا بني ولا تستخف بي واخيرا تختبر اقوالي","في جميع اعمالك كن نشيطا فلا يلحق بك سقم","من سخا بالطعام تباركه الشفاه ويشهد بكرمه شهادة صدق","من شح بالطعام تتذمر عليه المدينة ويشهد بلؤمه شهادة يقين","لا تكن ذا باس تجاه الخمر فان الخمر اهلكت كثيرين","الاتون يمتحن الحديد الممهى والخمر تمتحن قلوب المتجبرين في القتال","الخمر حياة للانسان اذا اقتصدت في شربها","اي عيش لمن ليس له خمر","اي شيء يعدم الحياة الموت","الخمر من البدء خلقت للانبساط لا للسكر","الخمر ابتهاج القلب وسرور النفس لمن شرب منها في وقتها ما كفى","الشرب بالرفق صحة للنفس والجسد","الافراط من شرب الخمر خصومة ونزاع","الافراط من شرب الخمر مرارة للنفس","السكر يهيج غضب الجاهل لمصرعه ويقلل القوة ويكثر الجراح","في مجلس الخمر لا توبخ القريب ولا تحتقره في سروره","لا تخاطبه بكلام تعيير ولا تضايقه في المطالبة"],["اذا جعلوك رئيسا فلا تتكبر بل كن بينهم كواحد منهم","اهتم بهم ثم اجلس وبعد قضائك ما عليك اتكئ","لكي تفرح بهم وتاخذ الاكليل زينة وتكرم بهداياهم","تكلم يا شيخ فانك اهل ذلك","لكن عن دقة علم ولا تمنع الغناء","لا تطلق كلامك عند السماع ولا تات بالحكمة في غير وقتها","الحان المغنين في مجلس الخمر كفص من ياقوت في حلي من ذهب","انغام المغنين على خمر لذيذة كفص من زمرد في مصوغ من ذهب","اسمع وانت ساكت فباحتشامك تنال الحظوة","تكلم يا شاب لكن نادرا متى دعتك الحاجة","ان سئلت مرتين فجاوب بالايجاز","معبرا عن الكثير بالقليل وكن كمن يعلم ويصمت","في جماعة العظماء لا تساو نفسك بهم وبين الشيوخ لا تكن كثير الهذر","قدام الرعد ينطلق البرق وقدام المحتشم تسبق الحظوة","اذا ان الوقت فقم لا تتاخر اسرع الى بيتك لا تتهاون هناك تنزه","و اصنع ما بدا لك ولا تخطا بكلام الكبرياء","و على هذه كلها بارك صانعك الذي يسكرك من طيباته","من اتقى الرب يقبل تاديبه والمبتكرون اليه يجدون مرضاته","من ابتغى الشريعة يمتلئ منها والمراءي يعثر فيها","الذين يتقون الرب يجدون العدل ويوقدون من الاحكام مصباحا لهم","الانسان الخاطئ يجانب التوبيخ ويجد حججا توافق مبتغاه","صاحب المشورة لا يهمل التامل اما المتكبر ممن ليس كذلك فلا ياخذه الخوف","و لا بعدما عمل بهواه عن غير مشورة","لا تعمل شيئا عن غير مشورة فلا تندم على عملك","لا تسر في طريق الهلكة فلا تعثر بالحجارة لا ترم نفسك في طريق لم تختبره فلا تجعل لنفسك معثرة","احترز حتى من بنيك وتحفظ من اهل بيتك","في جميع اعمالك اقتد بضميرك فان ذلك هو حفظ الوصايا","الذي يقتدي بالشريعة يرعى الوصايا والذي يتكل على الرب لا يخسر"],["من اتقى الرب لا يلقى ضرا بل عند التجربة يحفظه الرب وينجيه من الشرور","الرجل الحكيم لا يبغض الشريعة اما الذي يراءي فيها فهو كسفينة في الزوبعة","الانسان العاقل يؤمن بالشريعة والشريعة امينة له","هيئ كلامك كما يفعل الصديقون في مسائلهم فتسمع انظم معاني علمك وجاوب","احشاء الاحمق كمحالة العجلة وفكره مثل المحور الخفيف الدوران","الصديق المتهزئ كفحل الخيل الذي يصهل تحت كل راكب","لماذا يفضل يوم على يوم ونور كل يوم في السنة من الشمس","علم الرب ميز بينها اذ صنعت الشمس التي تحفظ الرسم","و خالف بين الازمنة فعيدت الاعياد في الساعة المعينة","فمنها ما اعلاه وقدسه ومنها ما جعله في عداد الايام وكذا البشر كلهم من التراب وادم صنع من الارض","لكن الرب ميز بينهم بسعة علمه وخالف بين طرقهم","فمنهم من باركه واعلاه ومنهم من قدسه وقربه اليه ومنهم من لعنه وخفضه ونكسه من مقامه","كما يكون الطين في يد الخزاف وتجري جميع احواله بحسب مرضاته","كذلك الناس في يد صانعهم وهو يجازيهم بحسب قضائه","بازاء الشر الخير وبازاء الموت الحياة كذلك بازاء التقي الخاطئ وهكذا تامل في جميع اعمال العلي تجدها اثنين اثنين الواحد بازاء الاخر","اني انا الاخير قد استيقظت وورثت هذه كما كانت منذ البدء","كمن يلتقط وراء القطافين اقبلت ببركة الرب فملات المعصرة كالذي قطف","فانظروا كيف لم يكن اجتهادي لي وحدي بل ايضا لجميع الذين يلتمسون التاديب","اسمعوني يا عظماء الشعب واصغوا الي يا رؤساء الجماعة","لا تول على نفسك في حياتك ابنك او امراتك او اخاك او صديقك ولا تعط لاخر اموالك لئلا تندم فتتضرع اليه بها","ما حييت وما دام فيك نفس لا تسلم نفسك الى احد من البشر","لانه خير ان يطلب بنوك منك من ان تنظر انت الى ايدي بنيك","في جميع امورك احفظ لنفسك مزيتها","و لا تجعل عيبا في كرامتك قسم ميراثك عند انقضاء ايام حياتك حين يحضر الموت","العلف والعصا والحمل للحمار والخبز والتاديب والعمل للعبد","اشغل الغلام بالعمل فتستريح ارخ يديك عنه فيلتمس العتق","النير والسيور تحني الرقاب ومواظبة العمل تخضع العبد","للعبد الشرير التنكيل والعذاب اقسره على العمل لئلا يتفرغ","فان الفراغ يعلم ضروب الخبث","الزمه الاعمال كما يليق به فان لم يطع فثقل عليه القيود لكن لا تفرط في عقاب ذي جسد ولا تصنع شيئا بغير تمييز","ان كان لك عبد فليكن عندك كنفسك فانك اكتسبته بالدم ان كان لك عبد فعامله كنفسك فانك تحتاج اليه احتياجك الى نفسك","ان اذيته ابق","و اذا فر ذاهبا ففي اي طريق تطلبه"],["الامال الفارغة الكاذبة لذي السفه والاحلام يطير بها الجهال","مثل الملتفت الى الاحلام مثل القابض على الظل والمتطلب للريح","رؤيا الاحلام هي هذا بازاء هذا شبه الشخص امام الشخص","بالنجس ماذا يطهر وبالكذب ماذا يصدق","العرافة والتطير والاحلام باطلة","كخيالات قلب الماخض ان لم ترسل هذه من عند العلي في افتقاد منه فلا توجه اليها قلبك","فان كثيرين اضلتهم الاحلام فسقطوا لاعتمادهم عليها","الشريعة تتمم بغير تلك الاكاذيب والحكمة في الفم الصادق كمال","الرجل المتادب يعلم كثيرا والكثير الخبرة يحدث بعقل","الذي لم يختبر يعلم قليلا اما الذي جال فهو كثير الحيلة","الذي لم يمتحن ماذا يعلم اما الذي ضل فهو كثير الدهاء","اني رايت في مطافي امورا كثيرة واكثر اقوالي مما اختبرت","و قد طالما خاطرت بنفسي في هذا الطلب حتى الى الموت ثم نجوت","روح المتقين للرب يحيا","لان رجاءهم في مخلصهم","من اتقى الرب فلا يخاف ولا يفزع لانه هو رجاؤه","من اتقى الرب فطوبى لنفسه","الى من يتوجه ومن عمدته","ان عيني الرب الى محبيه هو مجير قدير وعمدة قوية ستر من الحر وظل من الهجير","صيانة من العثار ومعونة عند السقوط هو يعلي النفس وينير العينين يمنح الشفاء والحياة والبركة","الذابح من كسب الظلم يستهزا بتقدمته واستهزاءات الاثماء ليست بمرضية","الرب وحده للذين ينتظرونه في طريق الحق والعدل","ليست مرضاة العلي بتقادم المنافقين ولا بكثرة ذبائحهم يغفر خطاياهم","من قدم ذبيحة من مال المساكين فهو كمن يذبح الابن امام ابيه","خبز المعوزين حياتهم فمن امسكه عليهم فانما هو سافك دماء","من يخطف معاش القريب يقتله","من يمسك اجرة الاجير يسفك دمه","واحد بنى واخر هدم فماذا انتفعا سوى التعب","واحد صلى واخر لعن فايهما يستجيب الرب لدعائه","من اغتسل من لمس الميت ثم لمسه فماذا نفعه غسله","كذلك الانسان الذي يصوم عن خطاياه ثم يعود يفعلها من يستجيب لصلاته وماذا نفعه اتضاعه"],["من حفظ الشريعة فقد قدم ذبائح كثيرة","من رعى الوصايا فقد ذبح ذبيحة الخلاص","و من اقلع عن الاثم فقد ذبح ذبيحة الخطيئة وكفر ذنوبه","من قدم السميذ فقد وفى بالشكر ومن تصدق فقد ذبح ذبيحة الحمد","مرضاة الرب الاقلاع عن الشر وتكفير الذنوب الرجوع عن الاثم","لا تحضر امام الرب فارغا","فان هذه كلها تجرى طاعة للوصية","تقدمة الصديق تدسم المذبح ورائحتها طيبة امام العلي","ذبيحة الرجل الصديق مرضية وذكرها لا ينسى","مجد الرب عن قرة عين ولا تنقص من بواكير يديك","كن متهلل الوجه في كل عطية وقدس العشور بفرح","اعط العلي على حسب عطيته وقدم كسب يدك عن قرة عين","فان الرب مكافئ فيكافئك سبعة اضعاف","لا تقدم هدايا بها عيب فان الرب لا يقبلها","و لا تعتمد على ذبيحة اثيمة فان الرب ديان ولا يلتفت الى كرامة الوجوه","لا يحابي الوجوه في حكم الفقير بل يستجيب صلاة المظلوم","لا يهمل اليتيم المتضرع اليه ولا الارملة اذا سكبت شكواها","اليست دموع الارملة تسيل على خديها اما هي صراخ على الذي اسالها","انها من خديها تصعد الى السماء والرب المستجيب لا يتلذذ بها","ان المتعبد يقبل بمرضاة وصلاته تبلغ الى الغيوم","صلاة المتواضع تنفذ الغيوم ولا تستقر حتى تصل ولا تنصرف حتى يفتقد العلي ويحكم بعدل ويجري القضاء","فالرب لا يبطئ ولا يطيل اناته عليهم حتى يحطم صلب الذين لا رحمة فيهم","و ينتقم من الامم حتى يمحو قوم المتجبرين ويحطم صوالجة الظالمين","حتى يكافئ الانسان على حسب افعاله ويجزي البشر باعمالهم على حسب نياتهم","حتى يجري الحكم لشعبه ويفرج عنهم برحمته","الرحمة تجمل في اوان الضيق كسحاب المطر في اوان القحط"],["ايها الرب اله الجميع ارحمنا وانظر الينا وارنا نور مراحمك","و الق رعبك على جميع الامم الذين لم يلتمسوك ليعلموا انه لا اله الا انت ويخبروا بعظائمك","ارفع يدك على الامم الغريبة وليعرفوا عزتك","كما قد ظهرت فينا قداستك امامهم هكذا فلتظهر عظمتك فيهم امامنا","و ليعرفوك كما عرفنا نحن ان لا اله الا انت يا رب","استانف الايات واحدث العجائب","مجد يدك وذراعك اليمنى","اثر غضبك وصب سخطك","دمر المقاوم واحطم العدو","عجل الزمان واذكر الميثاق وليخبر بعظائمك","لتاكل نار الغضب الناجي وليلق مضايقو شعبك الهلاك","اهشم رؤوس قادة الاعداء القائلين ليس غيرنا","اجمع كل اسباط يعقوب واتخذها ميراثا لك كما كانت في البدء","ايها الرب ارحم الشعب الذي دعي باسمك واسرائيل الذي انزلته منزلة بكرك","اشفق على مدينة قدسك اورشليم مدينة راحتك","املا صهيون لكي تنادي باقوالك املا شعبك من مجدك","اشهد للذين هم خلقك منذ البدء وايقظ النبوءات التي باسمك","اعط الذين ينتظرونك الثواب وليتبين صدق انبيائك استجب ايها الرب لصلاة المتضرعين اليك","على حسب بركة هرون على شعبك فيعلم جميع سكان الارض انك انت الرب اله الدهور","الجوف يتناول كل طعام لكن من الطعام ما هو اطيب من غيره","الحلق يميز اطعمة الصيد والقلب الفهم يميز الاقوال الكاذبة","القلب الخبيث يورث الغم والرجل الكثير الخبرة يكافئه","المراة تتزوج اي رجل كان لكن في البنات من تفضل على غيرها","جمال المراة يبهج الوجه ويفوق جميع منى الانسان","و ان كان في لسانها رحمة ووداعة فليس رجلها كسائر بني البشر","من حاز امراة فهي له راس الغنى وعون بازائه وعمود يستريح اليه","حيث لا سياج ينتهب الملك وحيث لا امراة ينوح التائه","من ذا يامن اللص المشدود الازر الهائم من مدينة الى مدينة هكذا حال الرجل الذي لا وكر له فياوي حيثما امسى"],["كل صديق يقول لي مع فلان صداقة لكن رب صديق انما هو صديق بالاسم الا يورث الغم حتى الموت","كل صاحب وصديق يتحول الى العداوة","ايها الاختراع الموبق من اين هبطت فغطيت اليبس خيانة","رب صاحب يتنعم مع صديقه في السراء وعند الضراء يضحي له عدوا","رب صاحب لاجل بطنه يجد مع صديقه ويحمل الترس في الحرب","لا تنس صديقك في قلبك ولا تتغاض عنه وانت موسر","لا تستشر من يرصدك واكتم مشورتك عمن يحسدك","كل مشير يبدي مشورة لكن رب مشير انما يشير لنفسه","الحذر لنفسك من المشير واستخبر اولا عن حاجته فانه يشير بما ينفعه","لئلا يلقي القرعة عليك ويقول لك","سبيلك حسن ثم يقف تجاهك ينظر ماذا يحل بك","لا تستشر المنافق في التقوى ولا الظالم في العدل ولا المراة في ضرتها ولا الجبان في الحرب ولا التاجر في التجارة ولا المبتاع في البيع ولا الحاسد في شكر المعروف","و لا الجافي في الرقة ولا الكسلان في شيء من الشغل","و لا الاجير المساكن في انجاز الشغل ولا البطال في كثرة العمل لا تلتفت الى هؤلاء لشيء من المشورة","لكن ائلف الرجل التقي ممن علمته يحفظ الوصايا","و نفسه كنفسك واذا سقطت يتوجع لك","و اعقد المشورة مع القلب فانه ليس لك مشير انصح منه","لان نفس الرجل قد تخبر بالحق اكثر من سبعة رقباء يرقبون من موضع عال","و في كل هذه تضرع الى العلي ليهديك بالحق في الطريق المستقيم","الكلام مبدا كل عمل والمشورة قبل الفعل","الوجه يدل على تغير القلب اربعة تصدر من القلب الخير والشر والحياة والموت والمتسلط على هذه في كل حين هو اللسان","من الناس من هو ذو دهاء مؤدب لكثيرين لكنه لا ينفع نفسه شيئا","و منهم من يدعي الحكمة وكلامه مكروه فمثل هذا يحرم كل قوت","لانه لم يؤت الحظوة من عند الرب اذ ليس من الحكمة على شيء","و منهم من حكمته لنفسه وثمار عقله صالحة في الفم","الرجل الحكيم يعلم شعبه وثمار عقله صالحة","الرجل الحكيم يمتلئ بركة ويغبطه كل من يراه","حياة الرجل ايام معدودة اما ايام اسرائيل فلا عدد لها","الحكيم يرث ثقة شعبه واسمه يحيا الى الابد","يا بني جرب نفسك في حياتك وانظر ماذا يضرها وامنعها عنه","فانه ليس كل شيء ينفع كل احد ولا كل نفس ترضى بكل امر","لا تشره الى كل لذة ولا تنصب على الاطعمة","فان كثرة الاكل تهيض الاكل والشره يبلغ الى المغص","كثيرون هلكوا من الشره اما القنوع فيزداد حياة"],["اعط الطبيب كرامته لاجل فوائده فان الرب خلقه","لان الطب ات من عند العلي وقد افرغت عليه جوائز الملوك","علم الطبيب يعلي راسه فيعجب به عند العظماء","الرب خلق الادوية من الارض والرجل الفطن لا يكرهها","اليس بعود تحول الماء عذبا حتى تعرف قوته","ان العلي الهم الناس العلم لكي يمجد في عجائبه","بتلك يشفي ويزيل الاوجاع ومنها يصنع العطار امزجة وصنعته لا نهاية لها","فيحل السلام من الرب على وجه الارض","يا بني اذا مرضت فلا تتهاون بل صل الى الرب فهو يشفيك","اقلع عن ذنوبك وقوم اعمالك ونق قلبك من كل خطيئة","قرب رائحة مرضية وتذكار السميذ واستسمن التقدمة كانك لست بكائن","ثم اجعل موضعا للطبيب فان الرب خلقه ولا يفارقك فانك تحتاج اليه","ان للاطباء وقتا فيه النجح على ايديهم","لانهم يتضرعون الى الرب ان ينجح عنايتهم بالراحة والشفاء لاسترجاع العافية","من خطئ امام صانعه فليقع في يدي الطبيب","يا بني اذرف الدموع على الميت واشرع في النياحة على ما يليق بذي مصيبة شديدة وكفن جسده كما يحق ولا تتهاون بدفنه","ليكن بكاؤك مرا وتوهج في النحيب","اقم المناحة بحسب منزلته يوما او يومين دفعا للغيبة ثم تعز عن الحزن","فان الحزن يجلب الموت وغمة القلب تحني القوة","في الانفراد الحزن يتشدد وحياة البائس هي على حسب قلبه","لا تسلم قلبك الى الحزن بل اصرفه ذاكرا الاواخر","لا تنس فانه لا رجوع من هناك ولست تنفعه ولكنك تضر نفسك","اذكر ان ما قضي عليه يقضى عليك لي امس ولك اليوم","اذا استراح الميت فاسترح من تذكره وتعز عنه عند خروج روحه","الكاتب يكتسب الحكمة في اوان الفراغ والقليل الاشتغال يحصل عليها","كيف يحصل على الحكمة الذي يمسك المحراث ويفتخر بالمنخس ويسوق البقر ويتردد في اعمالها وحديثه في اولاد الثيران","قلبه في خطوط المحراث وسهره في تسمين العجال","كذلك كل صانع ومهندس ممن يقضي الليل كانهار والحافرون نقوش الخواتم الجاهدون في تنويع الاشكال الذين قلوبهم في تمثيل الصورة باصلها وسهرهم في استكمال صنعتهم","و كذلك الحداد الجالس عند السندان المكب على صوغ حديدة ضخمة يصلب وهج النار لحمه وهو يكافح حر الكير","صوت المطرقة يتتابع على اذنيه وعيناه الى مثال المصنوع","قلبه في اتمام المصنوعات وسهره في تزيينها الى التمام","و هكذا الخزاف الجالس على عمله المدير دولابه برجليه فانه لا يزال مهتما بعمله ويحصي جميع مصنوعاته","بذراعه يعرك الطين وامام قدميه يحني قوته","قلبه في اتقان الدهان وسهره في تنظيف الاتون","هؤلاء كلهم يتوكلون على ايديهم وكل منهم حكيم في صناعته","بدونهم لا تعمر مدينة","لا ياوون المدن ولا يتمشون ولا يدخلون الجماعة","و لا يجلسون على منبر القاضي ولا يفقهون فنون الدعاوي ولا يشرحون الحكم والقضاء ولا يضربون الامثال","لكنهم يصلحون الاشياء الدهرية ودعاؤهم لاجل عمل صناعتهم خلافا لمن يسلم نفسه الى التامل في شريعة العلي"],["فانه يبحث عن حكمة جميع المتقدمين ويتفرغ للنبوءات","يحفظ احاديث الرجال المشهورين ويدخل في افانين الامثال","يبحث عن خفايا الاقوال السائرة ويتبحر في الغاز الاحاجي","يخدم بين ايدي العظماء ويقف امام الرئيس","يجول في ارض الامم الغريبة فيختبر في الناس الخير والشر","يوجه قلبه الى الابتكار امام الرب صانعه ويتضرع الى العلي","و يفتح فاه بالصلاة ويستغفر لخطاياه","فان شاء الرب العظيم يملاه من روح الفهم","فيمطر باقوال حكمته وفي الصلاة يعترف للرب","يستهدي بمشورته وعلمه ويتامل في خفاياه","يبين تاديب ارشاده ويفتخر بشريعة عهد الرب","كثيرون يمدحون حكمته وهي لا تمحى الى الابد","ذكره لا يزول واسمه يحيا الى جيل الاجيال","تحدث الامم بحكمته وتشيد الجماعة بحمده","ان بقي خلف اسما اكثر من الف وان دخل الى الراحة افاد نفسه","اني استمر على بيان افكاري لاني امتلات كبدر تم","اسمعوني ايها البنون الاصفياء انبتوا كورد مغروس على نهر الصحراء","و افيحوا عرفكم كاللبان","و ازهروا كالزنبق انشروا عرفكم وسبحوا بترنيمكم باركوا الرب على جميع اعماله","و عظموا اسمه اعترفوا له بالتسبيح بترانيم الشفاه وبالكنارة وقولوا هكذا بالاعتراف","اعمال الرب كلها حسنة جدا وجميع اوامره تجرى في اوقاتها وكلها تطلب في اونتها","بكلمته وقف الماء كربوة وقفت حياض المياه بقول فمه","في امره كل مرضاة وليس احد يمنع تمام خلاصه","اعمال كل ذي جسد امامه ولا شيء يخفى عن عينيه","ينظر من دهر الى دهر وليس شيء عجيبا امامه","ليس لقائل ان يقول ما هذا او لم هذا لان كل شيء خلق لفوائد تختص به","فاضت بركته كنهر","و روت اليبس كطوفان كذلك يورث الامم غضبه","كما حول المياه الى يبس طرقه مستقيمة للقديسين كذلك هي معاثر للاثماء","الصالحات خلقت للصالحين منذ البدء كذلك الشرور للاشرار","راس ما تحتاج اليه حياة الانسان الماء والنار والحديد والملح وسميذ الحنطة والعسل واللبن ودم العنب والزيت واللباس","كل هذه خيرات للاتقياء وكذلك هي تتحول للخطاة شرورا","من الارواح ارواح خلقت للانتقام وهذه في غضبها تشدد سياطها","و في وقت الانقضاء تصب قوتها وتسكن غضب صانعها","النار والبرد والجوع والموت كل هذه خلقت للانتقام","انياب السباع والعقارب والافاعي والسيف تنتقم من المنافقين باهلاكهم","هذه تفرح بوصيته وعلى الارض تستعد لوقت الحاجة وفي ازمنتها لا تتعدى كلمته","فلذلك ترسخت منذ البدء وتاملت ورسمت في كتابي","ان جميع اعمال الرب صالحة فتؤتي كل فائدة في ساعتها","و ليس لقائل ان يقول ان هذا شر من هذا فان كل امر يستحسن في وقته","فالان سبحوا بكل قلوبكم وافواهكم وباركوا اسم الرب"],["جهد عظيم خلق لكل انسان ونير ثقيل وضع على بني ادم من يوم خروجهم من اجواف امهاتهم الى يوم دفنهم في الارض ام الجميع","فان عندهم انزعاج الافكار وروع القلب وقلق الانتظار ويوم الانقضاء","من الجالس على العرش في المجد الى المتضع على التراب والرماد","من اللابس السمنجوني والتاج الى الملتف بالكتان الخشن وزد على ذلك الغضب والغيرة والاضطراب والجزع وخوف الموت والحقد والخصومة","وفي وقت الراحة على الفراش نوم الليل الذي يكدر خاطر الانسان","فهو في راحة قليلة كلا شيء وبعد ذلك في الاحلام كما في يوم المراقبة","يرتعد من رؤيا قلبه كالمنهزم من وجه الحرب وعند نجاته يهب ويتعجب من زوال خوفه","هذا حال كل ذي جسد من الانسان الى البهيمة وللخطاة من ذلك سبعة اضعاف","الموت والدم والخصومة والسيف والنوائب والجوع والسحق والسوط","كل ذلك خلق للاثماء ولاجلهم اتى الطوفان","كل ما هو من الارض فالى الارض يعود وكل ما هو من المياه فالى البحر ينثني","كل رشوة ومظلمة تمحى والامانة تبقى الى الابد","اموال الظالمين تجف كالسيل وتدوي كالرعد الشديد عند المطر","يفرح الظالم عند بسط يديه لكن المعتدين يضمحلون في الانقضاء","اعقاب المنافقين لا ياتون بفروع كثيرة ولا الاصول النجسة التي على الصخر الصلب","الخضر الذي على كل ماء وشط نهر يقلع قبل كل عشب","النعمة كجنة بركات والرحمة تستمر الى الابد","حياة العامل القنوع تحلو لكن الذي يجد كنزا هو فوق كليهما","النسل وابتناء مدينة يخلدان الاسم لكن المراة التي لا عيب فيها تحسب فوق كليهما","الخمر والغناء يسران القلب لكن حب الحكمة فوق كليهما","المزمار والعود يطيبان اللحن لكن اللسان العذب فوق كليهما","البهاء والجمال تشتهيهما عينك لكن خضر المزرعة فوق كليهما","الصديق والصاحب لهما لقاء وفاق لكن المراة مع رجلها فوق كليهما","الاخوة والعون لساعة الضيق لكن نصرة الرحمة فوق كليهما","الذهب والفضة يثبتان القدم لكن المشورة تفضل على كليهما","الغنى والقوة يعزان القلب لكن مخافة الرب فوق كليهما","ليس في مخافة الرب افتقار ولا يحتاج صاحبها الى نصرة","مخافة الرب كجنة بركة وقد البست مجدا يفوق كل مجد","يا بني لا تعش عيش الاستعطاء فان الموت خير من التكفف","الرجل الذي يترصد مائدة الغريب عيشه لا يعد عيشا ونفسه تتنجس باطعمة غريبة","الرجل الاريب المتادب يتحفظ من ذلك","يحلو الاستعطاء في فم الوقح وفي جوفه تتقد النار"],["ايها الموت ما اشد مرارة ذكرك على الانسان المتقلب في السلام فيما بين امواله","على الرجل الذي لا تتجاذبه الهموم الموفق في كل امر القادر على التلذذ بالطعام","ايها الموت حسن قضاؤك للانسان المعوز الضعيف القوة","الهرم الذي يتجاذبه كل هم القنط الفاقد الصبر","لا تخش قضاء الموت اذكر اوائلك واواخرك هذا هو قضاء الرب على كل ذي جسد","و ماذا ترفض مما هو مرضاة العلي عشر سنين كانت مرضاته ام مئة ام الفا","انه ليس في الجحيم حساب على العمر","بنو الخطاة بنو رجس وكذلك الذين يترددون الى بيوت المنافقين","بنو الخطاة يهلك ميراثهم ويلازم ذريتهم العار","الاب المنافق يتشكى منه بنوه لانهم بسببه يلحقهم العار","ويل لكم ايها الرجال المنافقون النابذون لشريعة الاله العلي","فانكم اذ ولدتم انما ولدتم للعنة ومتى متم فاللعنة هي نصيبكم","كل ما هو من الارض يذهب الى الارض كذلك المنافقون يذهبون من اللعنة الى الهلاك","الناس ينوحون على اجسادهم لكن اسم الخطاة يمحى","ليكن اهتمامك بالاسم فانه ادوم لك من الف كنز عظيم من الذهب","الحياة الصالحة ايام معدودات اما الاسم الصالح فيدوم الى الابد","احفظوا التاديب في السلام ايها البنون اما الحكمة المكتومة والكنز المدفون فاية منفعة فيهما","الانسان الذي يكتم حماقته خير من الانسان الذي يكتم حكمته","استحيوا مما اقول لكم","فانه ليس بحسن الخجل من كل شيء ولا امر مما يصنع برشد يعجب كل انسان","اخجلوا امام الاب والام من الزنى وامام الرئيس والمقتدر من الكذب","و امام القاضي والامير من الزلة وامام المجمع والشعب من الاثم","و امام الشريك والصديق من الظلم وامام بلد سكناك من السرقة","و من مخالفة حق الله وعهده ومن اتكاء المرفق على الخبز ومن الخيانة في الاخذ والعطاء","و من السكوت امام الذين يسلمون عليك ومن النظر الى المراة البغي","و من اعراض وجهك عن نسيبك ومن سلب النصيب والعطاء","و من التفرس في امراة ذات بعل ومن مراودة جاريتها وعلى سريرها لا تقف","و من كلام التعيير امام الاصدقاء ومن الامتنان بعد العطاء ومن نقل الكلام المسموع وافشاء ما قيل في السر"],["حينئذ يكون خجلك في محله وتنال حظوة امام كل انسان اما هذه فلا تخجل فيها ولا تحاب الوجوه لتخطا فيها","شريعة العلي والميثاق والقضاء بحيث لا يبرا المنافق","و دعوى صاحبك مع المتغربين واقتسام الميراث بين الاصدقاء","و عدل الميزان والمعيار والمكسب كثر ام قل","و الاعتدال في البيع بين المشترين والمبالغة في تاديب البنين وضرب العبد الشرير حتى تدمي جنبه","و الختم على المراة الشريرة اليق بها","و حيث تكون الايدي الكثيرة اقفل ومتى قسمت فبالعدد والوزن والعطاء والاخذ كل شيء ليكن في دفتر","و لا تخجل في تاديب الجاهل والاحمق والهرم المتحاكم الى الشبان حينئذ تكون متادبا في الحقيقة وممدوحا امام كل حي","البنت سهاد خفي لابيها وهم يسلبه النوم مخافة من العنوس اذا شبت والصلف اذا تزوجت","و في عذرتها من التدنس والعلوق في بيت ابيها وفي الزواج من التعدي على رجلها او العقم","واظب على مراقبة البنت القليلة الحياء لئلا تجعلك شماتة لاعدائك وحديثا في المدينة ومذمة لدى الشعب فتخزيك في الملا الكثير","لا تتفرس في جمال احد ولا تجلس بين النساء","فانه من الثياب يتولد السوس ومن المراة الخبث","رجل يسيء خير من امراة تحسن ثم تجلب الخزي والفضيحة","اني اذكر اعمال الرب واخبر بما رايت ان في اقوال الرب اعماله","عين الشمس المنيرة تبصر كل شيء وعمل الرب مملوء من مجده","الم ينطق الرب القديسين بجميع عجائبه التي اثبتها الرب القدير لكي يثبت كل الخلق في مجده","انه بحث الغمر والقلب وفطن لكل دهاء","علم الرب كل علم واطلع على علامة الدهر مخبرا بالماضي والمستقبل وكاشفا عن اثار الخفايا","لا يفوته فكر ولا يخفى عليه كلام","و قد زين عظائم حكمته وهو الدائم منذ الدهر والى الدهر ولم يزد شيئا","و لم ينقص ولا يحتاج الى مشورة","ما اشهى جميع اعماله والذي يرى منها مثل شرارة","كل هذه تحيا وتبقى الى الابد لكل فائدة وجميعها تطيعه","كل شيء اثنان واحد بازاء الاخر ولم يصنع شيئا ناقصا","بل الواحد يؤيد مزايا الاخر فمن الذي يشبع من النظر الى مجده"],["الجلد الطاهر فخر العلاء ومنظر السماء مراى مجده","الشمس عند خروجها تبشر بمراها هي الة عجيبة صنع العلي","عند هاجرتها تيبس البقعة فمن يقوم امام حرها الشمس كنافخ في الاتون لما يصنع في النار","تحرق الجبال ثلاثة اضعاف وتبعث ابخرة نارية وتلمع باشعة تجهر العيون","عظيم الرب صانعها الذي بامره تسرع في سيرها","و القمر بجميع احواله الموقتة هو نبا الازمنة وعلامة الدهر","من القمر علامة العيد هو نير ينقص عند التمام","باسمه سمي الشهر وفي تغيره يزداد زيادة عجيبة","ان في العلاء محلة عسكر تتلالا في جلد السماء","هناك بهاء السماء ومجد النجوم وعالم متالق والرب في الاعالي","عند كلام القدوس تقوم لاجراء احكامه ولا ياخذها في محارسها فتور","انظر الى قوس الغمام وبارك صانعها ان رونقها في غاية الجمال","تنطق السماء منطقة مجد ويد العلي تمدانها","بامره عجل الثلج ورشق بروق قضائه","و به انفتحت الكنوز وطارت الغيوم كذوات الاجنحة","بعظمته شدد الغيوم فانقضت حجارة البرد","بلحظاته تتزلزل الجبال وبارادته تهب الجنوب","عند صوت رعده تتمخض الارض عند عاصفة الشمال وزوبعة الريح","يذري الثلج كما يتطاير ذوات الاجنحة وانحداره كنزول الجراد","تعجب العين من حسن بياضه وينذهل القلب من مطره","و يسكب الصقيع كالملح على الارض واذا جمد صار كاطراف الاوتاد","تهب ريح الشمال الباردة فيجمد الماء يستقر الجليد على كل مجتمع المياه ويلبس المياه درعا","تاكل الجبال وتحرق الصحراء وتتلف الخضر كالنار","يسرع الغمام فيشفي كل شيء والندى الناشئ من الحر يعيد البهجة","بكلامه طامن الغمر وانبت فيه الجزائر","الذين يركبون البحر يحدثون بهوله نسمع باذاننا فنتعجب","هناك المصنوعات العجيبة الغريبة انواع الحيوانات خلائق الحيتان","به ينتهي الى النجاح وبكلمته يقوم الجميع","انا نكثر الكلام ولا نستقصي وغاية ما يقال انه هو الكل","ماذا نستطيع من تمجيده وهو العظيم فوق جميع مصنوعاته","مرهوب الرب وعظيم جدا وقدرته عجيبة","ارفعوا الرب في تمجيده ما استطعتم فلا يزال ارفع","باركوا الرب وارفعوه ما قدرتم فانه اعظم من كل مدح","بالغوا في رفعه قدر طاقتكم لا تكلوا فانكم لن تدركوه","من راه فيخبر ومن يكبره كما هو","و هناك خفايا كثيرة اعظم من هذه فان الذي رايناه من اعماله هو القليل","ان الرب صنع كل شيء واتى الاتقياء الحكمة"],["لنمدح الرجال النجباء اباءنا الذين ولدنا منهم","فيهم انشا الرب مجدا كثيرا وابدى عظمته منذ الدهر","و قد كانوا ذوي سلطان في ممالكهم رجال اسم وباس مؤتمرين بفطنتهم ناطقين بالنبوءات","ائمة الشعب بمشوراتهم وبفهم كتب امتهم","قد ضمنوا تاديبهم اقوال الحكمة وبحثوا في الحان الغناء وانشدوا قصائد الكتاب","رجال غنى واقتدار فاعلي سلامة في بيوتهم","اولئك كلهم نالوا مجدا في اجيالهم وكانت ايامهم ايام فخر","فمنهم من خلفوا اسما يخبر بمدائحهم","و منهم من لا ذكر لهم وقد هلكوا كانهم لم يكونوا قط وولدوا كانهم لم يولدوا هم وبنوهم بعدهم","اما اولئك فهم رجال رحمة وبرهم لا ينسى","الميراث الصالح يدوم مع ذريتهم واعقابهم يبقون على المواعيد","تثبت ذريتهم وبنوهم لاجلهم","الى الابد تدوم ذريتهم ولا يمحى مجدهم","اجسامهم دفنت بالسلام واسماؤهم تحيا مدى الاجيال","الشعوب يحدثون بحكمتهم والجماعة تخبر بمدحتهم","اخنوخ ارضى الرب فنقل وسينادي الاجيال الى التوبة","نوح وجد برا كاملا وبه كانت المصالحة في زمان الغضب","فلذلك ابقيت بقية على الارض حين كان الطوفان","و اقيمت معه عهود لكي لا يهلك بالطوفان كل ذي جسد","ابراهيم كان ابا عظيما لامم كثيرة ولم يوجد نظيره في المجد وقد حفظ شريعة العلي فعاهده عهدا","و جعل العهد في جسده وعند الامتحان وجد امينا","فلذلك حلف له ان الامم سيباركون في نسله وانه يكثر نسله كتراب الارض","و يعلي ذريته كنجوم ويورثهم من البحر الى البحر ومن النهر الى اقصى الارض","و كذلك جعل في اسحق لاجل ابراهيم ابيه","بركة جميع الناس والعهد ثم اقرهما على راس يعقوب","اثره ببركاته وورثه الميراث ميز حظوظه وقسمها على الاسباط الاثني عشر","و اقام منه رجل رحمة قد نال حظوة امام كل بشر"],["موسى كان محبوبا عند الله والناس مبارك الذكر","فاتاه مجدا كمجد القديسين وجعله عظيما مرهوبا عند الاعداء بكلامه ازال الايات","و مجده امام الملوك اوصاه بشعبه واراه مجده","قدسه بايمانه ووداعته واصطفاه من بين جميع البشر","اسمعه صوته وادخله في الغمام","اعطاه الوصايا مواجهة شريعة الحياة والعلم ليعلم يعقوب العهد واسرائيل احكامه","اعلى هرون القديس نظيره اخاه من سبط لاوي","جعل له عهد الدهر واعطاه كهنوت الشعب اسعده في البهاء","و نطقه حلة مجد البسه كمال الفخر وايده بادوات العزة","السراويل والثوب السابغ والافود وجعل حوله الرمانات من ذهب مع جلاجل كثيرة من حوله","ليرن صوتها عند خطوه ليسمع الصليل في الهيكل ذكرا لبني شعبه","واعطاه الحلة المقدسة من ذهب وسمنجوني وارجوان صنعة نساج حاذق صدرة القضاء التي فيها النور والحق","نسيجها من قرمز مشزور صنعة عامل حاذق وعليها حجارة كريمة كنقش الخاتم مرصعة في الذهب صنعة نقاش الجوهر منقوش عليها اسماء اسباط اسرائيل ذكرا","وكان على العمامة اكليل من ذهب منقوش عليه عنوان القداسة وكان زينة كرامة صنعة براعة تعشقها العيون لحسنها","كل هذه كانت في غاية الجمال ولم يكن لها مثيل في الدهر","لم يلبسها الا من هو من عشيرته بنوه واعقابه في كل عهد","ذبائحه تحرق بالنار كل يوم مرتين بلا انقطاع","كرس موسى يديه ومسحه بالدهن المقدس","فصار ذلك عهدا ابديا له ولذريته ما دامت السماء ليخدم للرب ويمارس الكهنوت ويبارك شعبه باسمه","اصطفاه من بين جميع الاحياء ليقرب التقدمة للرب البخور والرائحة الطيبة ذكرا وتكفيرا عن شعبه","اقامه على وصاياه واعطاه سلطانا على عهود الاحكام ليعلم يعقوب الشهادات وينير اسرائيل بشريعته","اجتمع عليه الغرباء وحسدوه في البرية رجال داتان وابيرام وجماعة قورح بالحدة والغضب","نظر الرب فلم يرض فابادهم بحدة غضبه","اجرى بهم عجائب وافناهم بنار لهيبه","و زاد هرون مجدا واعطاه ميراثا جعل لهم بواكير ثمار الارض","و هيا لهم قبل غيرهم شبعهم من الخبز فهم ياكلون من ذبائح الرب التي اعطاها له ولذريته","الا انه لم يرث في ارض الشعب ولم يكن له نصيب فيما بينهم لانه هو نصيبه وميراثه","و فنحاس ابن العازار هو الثالث في المجد لاجل غيرته في مخافة الرب","و لانه قام عند ارتداد الشعب بصلاح نشاط نفسه وكفر عن اسرائيل","لذلك اعطاه الرب عهد سلامه لكي يكون امام شعبه في الاقداس وتبقى له ولنسله عظمة الكهنوت مدى الدهور","و عاهد داود بن يسى من سبط يهوذا على ميراث الملك من ابن الى ابن في ذريته كالميراث لهرون ونسله ليعطكم الحكمة فيقلوبكم لكي تحكموا بالعدل في شعبه فلا تزول خيراتهم ومجدهم مدى اجيالهم"],["كان يشوع بن نون رجل باس في الحروب خليفة موسى في النبوءات","و كان كاسمه عظيما في خلاص مختاريه شديد الانتقام على الاعداء المقاومين لكي يورث اسرائيل","ما اعظم مجده عند رفع يديه وتسديد حربته على المدن","من قام نظيره من قبله ان الرب نفسه دفع اليه الاعداء","الم ترجع الشمس الى الوراء على يده وصار اليوم نحوا من يومين","دعا العلي القدير اذ كان يهزم الاعداء من كل جهة فاستجاب له الرب العظيم بحجارة برد عظيمة الثقل","اغار على الامة بالقتال وفي المنهبط اهلك المقاومين","لكي تعرف الامم كمال عدتهم وان حربه امام الرب لانه منقاد للقدير","و في ايام موسى صنع رحمة هو وكالب بن يفنا اذ قاما على العدو وردا الشعب عن الخطيئة وسكنا تذمر السوء","و هما وحدهما ابقيا من الست مئة الف راجل ليدخلاهم الى الميراث الى ارض تدر لبنا وعسلا","و اتى الرب كالب قوة وبقيت معه الى شيخوخته فصعد الى ذلك الموضع المرتفع من الارض الذي نالته ذريته ميراثا","لكي يعلم جميع بني اسرائيل ان الانقياد للرب حسن","و القضاة كل منهم باسمه الذين لم تزن قلوبهم على الرب ولم يرتدوا عنه","ليكن ذكرهم مباركا ولتزهر عظامهم من مواضعها","و ليتجدد اسمهم وليمجدهم بنوهم","صموئيل المحبوب عند الرب نبي الرب سن الملك ومسح رؤساء شعبه","قضى للجماعة بحسب شريعة الرب وافتقد الرب يعقوب","بايمانه اختبر انه نبي وبايمانه علم انه صادق الرؤيا","دعا الرب القدير عندما كان اعداؤه يضيقون من كل جهة واصعد حملا رضيعا","فارعد الرب من السماء وبقصيف عظيم اسمع صوته","و حطم رؤساء الصوريين وجميع اقطاب فلسطين","و قبل رقاده عن الدهر شهد امام الرب ومسيحه اني لم اخذ من احد من البشر مالا بل ولا حذاء ولم يشكه انسان","و من بعد رقاده تنبا واخبر الملك بوفاته ورفع من الارض صوته بالنبوءة لمحو اثم الشعب"],["و بعد ذلك قام ناتان وتنبا في ايام داود","كما يفصل الشحم من ذبيحة الخلاص هكذا فصل داود من بين بني اسرائيل","لاعب الاسود ملاعبته الجداء والادباب كانها حملان الضان","الم يقتل الجبار وهو شاب الم يرفع العار عن شعبه","اذ رفع يده بحجر المقلاع وحط صلف جليات","لانه دعا الرب العلي فاعطى يمينه قوة ليقتل رجلا شديد القتال ويعلي قرن شعبه","فاعطاه الرب مجد قاتل ربوات ومدحه ببركاته اذ نقل اليه تاج المجد","فانه حطم الاعداء من كل جهة وافنى الفلسطينيين المناصبين وحطم قرنهم الى يومنا هذا","في جميع اعماله اعترف للقدوس العلي بكلام مجد","بكل قلبه سبح واحب صانعه","اقام المغنين امام المذبح ولقنهم الحانا لذيذة السماع","جعل للاعياد رونقا وللمواسم زينة الى الانقضاء لكي يسبح اسمه القدوس ويرنم في قدسه منذ الصباح","الرب غفر خطاياه واعلى قرنه الى الابد عاهده على الملك وعرش المجد في اسرائيل","بعده قام ابن حكيم وعلى يده استراح في الرحب","ملك سليمان ايام سلام واراحه الله من كل جهة لكي يشيد بيتا لاسمه ويهيئ قدسا الى الابد","ما اعظم حكمتك في صبائك وفطنتك التي طفحت بها مثل النهر فان قريحتك عمت الارض","فملاتها من امثال الاحاجي بلغ اسمك الى الجزائر البعيدة واحببت لاجل سلامك","اعجبت الافاق بما لك من الاغاني والامثال والالغاز والتفاسير","باسم الرب الاله الموصوف باله اسرائيل","جمعت الذهب كالقصدير والفضة كالرصاص","املت فخذيك الى النساء فاستولين على جسدك","جعلت عيبا في مجدك ونجست نسلك فجلبت الغضب على بنيك لقد صدعت قلبي جهالتك","حتى قسم السلطان الى قسمين ونشا من افرائيم ملك متمرد","لكن الرب لا يترك رحمته ولا يفسد من اعماله شيئا لا يدمر اعقاب مصطفاه ولا يهلك ذرية محبه","فابقى ليعقوب بقية ولداود جرثومة منه","و استراح سليمان مع ابائه","و خلف بعده ذا سفه عند الشعب من نسله","رحبعام السخيف الراي الذي بعث بمشورته الشعب على التمرد","و ياربعام بن ناباط الذي اثم اسرائيل وسن لافرائيم طريق الخطيئة فكثرت خطاياهم","جدا حتى اجلتهم عن ارضهم","و التمسوا كل شر حتى حل بهم الانتقام"],["و قام ايليا النبي كالنار وتوقد كلامه كالمشعل","بعث عليهم الجوع وبغيرته ردهم نفرا قليلا","اغلق السماء بكلام الرب وانزل منها نارا ثلاث مرات","ما اعظم مجدك يا ايليا بعجائبك ومن له فخر كفخرك","انت الذي اقمت ميتا من الموت ومن الجحيم بكلام العلي","و اهبطت الملوك الى الهلاك والمفتخرين من اسرتهم","و سمعت في سيناء القضاء وفي حوريب احكام الانتقام","و مسحت ملوكا للنقمة وانبياء خلائف لك","و خطفت في عاصفة من النار في مركبة خيل نارية","و قد اكتتبك الرب لاقضية تجرى في اوقاتها ولتسكين الغضب قبل حدته ورد قلب الاب الى الابن واصلاح اسباط يعقوب","طوبى لمن عاينك ولمن حاز فخر مصافاتك","انا نحيا هذه الحياة وبعد الموت لا يكون لنا مثل هذا الاسم","و توارى ايليا في العاصفة فامتلا اليشاع من روحه وفي ايامه لم يتزعزع مخافة من ذي سلطان ولم يستول عليه احد","لم يغلبه كلام وفي رقاد الموت جسده تنبا","صنع في حياته الايات وبعد موته الاعمال العجيبة","و مع هذه كلها لم يتب الشعب ولم يقلعوا عن الخطايا الى ان طردوا من ارضهم وتبددوا في كل الارض","و ابقى شعب قليل ورؤساء لبيت داود","بعضهم صنعوا المرضي وبعضهم اكثروا من الخطايا","حزقيا حصن مدينته وادخل اليها ماء جيحون حفر الصخر بالحديد وبنى ابارا للماء","في ايامه صعد سنحاريب وبعث ربشاقا فاقبل ورفع يده على صهيون وتنفخ بكبريائه","حينئذ ارتجفت قلوبهم وايديهم وتمخضوا كالوالدات","فدعوا الرب الرحيم باسطين اليه ايديهم فالقدوس من السماء استجاب لهم سريعا","و افتداهم على يد اشعيا","ضرب محلة اشور وملاكه حطمهم","لان حزقيا صنع المرضي امام الرب وجد في السلوك في طرق داود ابيه التي اوصاه بها اشعيا النبي العظيم الصادق في رؤياه","في ايامه رجعت الشمس الى الوراء وهو زاد على عمر الملك","بروح عظيم راى العواقب وعزى النائحين في صهيون","كشف عما سيكون على مدى الدهور وعن الخفايا قبل حدوثها"],["ذكر يوشيا مزاج طيب قد عبئ بصناعة العطار","في كل فم يحلو كالعسل وهو كالغناء في مجلس الخمر","اقيم ليتوب الشعب على يده فرفع ارجاس الاثم","وجه قلبه الى الرب وفي ايام الاثماء وطد التقوى","كلهم اجرموا ما خلا داود وحزقيا ويوشيا","تركوا شريعة العلي ارتد ملوك يهوذا","دفعوا قرنهم الى غيرهم ومجدهم الى امة غريبة","احرقوا بالنار مدينة القدس المختارة وخربوا طرقها على يد ارميا","فانهم اساءوا اليه وهو قد قدس في جوف امه نبيا ليستاصل ويسيء ويهلك وايضا ليبني ويغرس","و راى حزقيال رؤيا المجد التي اراه اياها بمركبة الكروبين","انذر الاعداء بالمطر ووعد المستقيمين في طرقهم بالاحسان","لتزهر عظام الانبياء الاثني عشر من مكانها فانهم عزوا يعقوب وافتدوهم بايمان الرجاء","كيف نعظم زربابل انه كخاتم في اليد اليمنى","كذلك يشوع بن يوصاداق فانهما في ايامهما بنيا البيت ورفعا شان الشعب المقدس للرب المهيا لمجد ابدي","و نحميا يكون ذكره طول الايام فانه اقام لنا السور المنهدم ونصب الابواب والمزاليج ورم منازلنا","لم يخلق على الارض احد مثل اخنوخ الذي نقل عن الارض","و لم يولد رجل مثل يوسف رئيس اخوته وعمدة الشعب","عظامه افتقدت وبعد موته تنبات","سام وشيث ممجدان بين الناس وفوق كل نفس في الخلق ادم"],["سمعان بن اونيا الكاهن العظيم رم البيت في حياته ووثق الهيكل في ايامه","و اسس سمكا مضاعفا تحصينا شامخا حول الهيكل","في ايامه استنبطت ابار المياه وكالبحر تناهت في الفيضان","هو الذي اهتم بشعبه لئلا يهلك وحصن المدينة لئلا تفتح","ما امجده في تصرفه بين الشعب وفي خروجه من وراء حجاب البيت","مثله مثل كوكب الصبح بين الغمام او البدر ايام تمامه","او الشمس المشرقة على هيكل العلي","او القوس المتلالئة بين سحب البهاء او زهر الورد في ايام الربيع او الزنبق على مجاري المياه او نبات لبنان في ايام الصيف","او النار او اللبان على المجمرة","او اناء الذهب المصمت المزين بكل حجر كريم","او الزيتون المثمر او السرو المرتفع الى السحب اذ كان ياخذ حلة مجده ويلبس كمال زينته","و يصعد الى المذبح المقدس كان يزيد لباس القدس بهاء","و اذ كان يتناول اعضاء الذبيحة من ايدي الكهنة وهو واقف على موقد المذبح كان يحيط به اكليل من الاخوة احاطة الفروع بارزلبنان","و الشطب بالنخل وكان جميع بني هرون في مجدهم","و تقدمة الرب في ايديهم امام كل جماعة اسرائيل وكان هو عند اتمام خدمته على المذبح لتزيين تقدمة العلي القدير","يمد يده على المسكب ويسكب من دم العنب","يصبه على اسس المذبح رائحة مرضية امام العلي ملك الجميع","حينئذ كان بنو هرون يهتفون بالابواق المطروقة ويسمعون صوتا عظيما ذكرا امام العلي","و كان عند ذلك كل الشعب يبادرون معا ويخرون على وجوههم الى الارض ساجدين لربهم القدير لله العلي","و كان المغنون يسبحون باصواتهم ويسمعون في البيت المعظم الحانهم اللذيذة","و كان الشعب يتضرعون الى الرب العلي بصلاتهم امام الرحيم الى ان يفرغ من اكرام الرب وتتم خدمته","ثم كان ينزل ويرفع يديه على كل جماعة بني اسرائيل مباركا الرب بشفتيه ومفتخرا باسمه","و يكرر سجوده ليظهر ان البركة من لدن العلي","فالان يا جميع الناس باركوا الله الذي يصنع العظائم في كل مكان ويزيد ايامنا منذ الرحم ويعاملنا على حسب رحمته","ليمنحنا سرور القلب والسلام في اسرائيل في ايامنا وعلى مدى الدهور","مقرا علينا رحمته ومفتديا لنا في ايامه","امتان مقتتهما نفسي والثالثة ليست بامة","الساكنون في جبل السامرة والفلسطينيون والشعب الاحمق الساكن في شكيم","قد رسم تاديب العقل والعلم في هذا الكتاب يشوع بن سيراخ الاورشليمي الذي افاض الحكمة من قلبه","طوبى لمن يواظب على هذه فان الذي يجعلها في قلبه يكون حكيما","و اذا عمل بها يقدر على كل شيء لان نور الرب دليله"],["صلاة يشوع بن سيراخ اعترف لك ايها الرب الملك واسبح الله مخلصي","اعترف لاسمك لانك كنت لي مجيرا ونصيرا","و افتديت جسدي من الهلاك ومن شرك سعاية اللسان ومن شفاه مختلقي الزور وكنت لي ناصرا تجاه المقاومين","و افتديتني برحمتك الغزيرة واسمك من زئير المستعدين للافتراس","من ايدي طالبي نفسي ومن مضايقي الكثيرة","من الاختناق باللهيب المحيط بي ومن وسط النار حتى لا اصلى","من عمق جوف الجحيم ومن اللسان الدنس وكلام الزور وسعاية اللسان الجائر عند الملك","دنت نفسي من الموت","و اقتربت حياتي من عمق الجحيم","احيط بي من كل جهة ولا نصير التفت لاغاثة الناس فلم تكن","فتذكرت رحمتك ايها الرب وصنيعك الذي منذ الدهر","كيف تنقذ الذين ينتظرونك وتخلصهم من ايدي الامم","فرفعت من الارض صلاتي وتضرعت لانقذ من الموت","دعوت الرب ابا ربي لئلا يخذلني في ايام الضيق في عهد المتكبرين الخاذلين لي","اني اسبح اسمك في كل حين وارنم له بالاعتراف لان صلاتي قد استجيبت","فانك قد خلصتني من الهلكة وانقذتني من زمان السوء","فلذلك اعترف لك واسبحك وابارك اسم الرب","في صبائي قبل ان اتيه التمست الحكمة علانية في صلاتي","امام الهيكل ابتهلت لاجلها والى اواخري التمسها فازهرت كباكورة العنب","ابتهج بها قلبي ودرجت قدمي في الاستقامة ومنذ صبائي جددت في اثرها","املت اذني قليلا ووعيت","فوجدت لنفسي تاديبا كثيرا وكان لي فيها نجح عظيم","ان الذي اتاني حكمة اوتيه تمجيدا","فاني عزمت ان اعمل بها وقد حرصت على الخير ولست اخزى","جاهدت نفسي لاجلها وفي اعمالي لم ابرح متنطسا","مددت يدي الى العلاء وبكيت على جهالاتي","وجهت نفسي اليها وبالطهارة وجدتها","بها ملكت قلبي من البدء فلذلك لا اخذل","و جوفي اضطرب في طلبها فلذلك اقتنيت قنية صالحة","اعطاني الرب اللسان جزاء فبه اسبحه","ادنوا مني ايها الغير المتادبين وامكثوا في منزل التاديب","لماذا تتقاعدون عن هذه ونفوسكم ظامئة جدا","اني فتحت فمي وتكلمت دونكم كسبا بلا فضة","اخضعوا رقابكم تحت النير ولتتخذ نفوسكم التاديب فان وجدانه قريب","انظروا باعينكم كيف تعبت قليلا فوجدت لنفسي راحة كثيرة","نالوا التاديب كمقدار كثير من الفضة واكتسبوا به ذهبا كثيرا","تبتهج نفوسكم برحمته ولا تخزوا بمدحته","اعملوا عملكم قبل الاوان فيؤتيكم ثوابكم في اوانه"]]},{"id":907,"code":"Bar","name":"باروخ (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["هذا كلام الكتاب الذي كتبه باروك بن نيريا بن معسيا بن صدقيا بن حسديا ابن حلقيا في بابل","في السنة الخامسة في السابع من الشهر حين اخذ الكلدانيون اورشليم واحرقوها بالنار","و تلا باروك كلام هذا الكتاب على مسمعي يكنيا بن يوياقيم ملك يهوذا وعلى مسامع جميع الشعب الذين جاءوا لاستماع الكتاب","و على مسامع المقتدرين وبني الملوك ومسامع الشيوخ ومسامع جميع الشعب من الصغار الى الكبار جميع الساكنين في بابل على نهر سود","فبكوا وصاموا وصلوا امام الرب","و جمعوا من الفضة قدر ما استطاعت يد كل واحد","و بعثوا الى اورشليم الى يوياقيم بن حلقيا بن شلوم الكاهن والى الكهنة والى جميع الشعب الذين معه في اورشليم","عندما اخذ انية بيت الرب المسلوبة من الهيكل ليردها الى ارض يهوذا في العاشر من سيوان وهي انية الفضة التي صنعها صدقيا ابن يوشيا ملك يهوذا","بعدما اجلى نبوكد نصر ملك بابل يكنيا والرؤساء والمحصنين والمقتدرين وشعب الارض من اورشليم وذهب بهم الى بابل","و قالوا انا قد ارسلنا اليكم فضة فابتاعوا بالفضة محرقات وذبائح للخطية ولبانا واصنعوا تقادم وقدموها علىمذبح الرب الهنا","و صلوا من اجل حياة نبوكد نصر ملك بابل وحياة بلشصر ابنه لكي تكون ايامهما كايام السماء على الارض","فيؤتينا الرب قوة وينير عيوننا ونحيا تحت ظل نبوكد نصر ملك بابل وظل بلشصر ابنه ونتعبد لهما اياما كثيرة ونحننائلون لديهما حظوة","و صلوا من اجلنا الى الرب الهنا فانا قد خطئنا الى الرب الهنا ولم يرتد سخط الرب وغضبه عنا الى هذا اليوم","و اتلوا هذا الكتاب الذي ارسلناه اليكم لينادى به في بيت الرب في يوم العيد وفي ايام المحفل","و قولوا للرب الهنا العدل ولنا خزي الوجوه كما في هذا اليوم لرجال يهوذا وسكان اورشليم","و لملوكنا ورؤسائنا وكهنتنا وانبيائنا وابائنا","لانا خطئنا امام الرب وعصيناه","و لم نسمع لصوت الرب الهنا لنسلك في اوامر الرب التي جعلها امام وجوهنا","من يوم اخرج الرب اباءنا من ارض مصر الى هذا اليوم ما زلنا نعاصي الرب الهنا ونعرض عن استماع صوته","فلحق بنا الشر واللعنة اللذان امر الرب موسى عبده ان يوعد بهما يوم اخرج اباءنا من ارض مصر ليعطينا ارضا تدر لبنا وعسلا كما في هذا اليوم","فلم نسمع لصوت الرب الهنا ولا لجميع كلام الانبياء الذين ارسلهم الينا","و مضينا كل واحد على اصرار قلبه الشرير عابدين الهة اخر صانعين الشر امام عيني الرب الهنا"],["فاقام الرب كلامه الذي تكلم به علينا وعلى قضاتنا الذين يقضون في اسرائيل وعلى ملوكنا ورؤسائنا وعلى رجال اسرائيل ويهوذا","جالبا علينا شرا عظيما بحيث لم يحدث تحت السماء باسرها مثل ما احدثه في اورشليم على حسب ما كتب في شريعة موسى","حتى اكل بعضنا لحم ابنه والاخر لحم بنته","و اخضعهم تحت ايدي جميع الممالك التي حولنا وجعلهم عارا ودهشا في جميع الشعوب الذين شتتهم الرب بينهم","فاذا هم في الانحطاط بدل الرفعة لانا خطئنا الى الرب الهنا غير سامعين لصوته","للرب الهنا العدل ولنا ولابائنا خزي الوجوه كما في هذا اليوم","لان الرب تكلم علينا بجميع هذا الشر الذي حل بنا","و نحن لم نستعطف وجه الرب تائبين كل واحد عن افكار قلبه الشرير","فسهر الرب على الشر وجلبه الرب علينا لان الرب عادل في جميع اعماله التي اوصانا بها","فلم نسمع لصوته لنسلك في اوامر الرب التي جعلها امام وجوهنا","فالان ايها الرب اله اسرائيل الذي اخرج شعبه من ارض مصر بيد قديرة وبايات ومعجزات وقوة عظيمة وذراع مبسوطة واقام له اسما كما في هذا اليوم","انا خطئنا ونافقنا واثمنا ايها الرب الهنا في جميع رسومك","لينصرف غضبك عنا فقد بقينا نفرا قليلا في الامم الذين شتتنا بينهم","اسمع يا رب صلاتنا وتضرعنا وانقذنا لاجلك وانلنا حظوة امام وجوه الذين اجلونا","لكي تعرف الارض باسرها انك انت الرب الهنا وانه باسمك دعي اسرائيل وعشائره","ايها الرب التفت من بيت قدسك وانظر الينا وامل ايها الرب اذنك واستجب","افتح عينيك وانظر فانه ليس الاموات في الجحيم الذين اخذت ارواحهم عن احشائهم يعترفون للرب بالمجد والعدل","لكن الروح الكئيب من الشدة والذي يمشي منحنيا ضعيفا والعيون الكليلة والنفس الجائعة هم يعترفون لك بالمجد والعدل يا رب","فانا لا لاجل بر ابائنا وملوكنا نلقي تضرعنا امامك ايها الرب الهنا","بل لانك ارسلت سخطك وغضبك علينا كما تكلمت على السنة عبيدك الانبياء","هكذا قال الرب احنوا مناكبكم وتعبدوا لملك بابل فتسكنوا في الارض التي اعطيتها لابائكم","و ان لم تسمعوا لصوت الرب بان تتعبدوا لملك بابل","فاني ابطل من مدن يهوذا ومن شوارع اورشليم صوت الطرب وصوت الفرح صوت العروس وصوت العروسة وتكون كل الارض مستوحشة لا ساكن فيها","فلم نسمع لصوتك بان نتعبد لملك بابل فاقمت كلامك الذي تكلمت به على السنة عبيدك الانبياء ان تخرج عظام ملوكنا وعظام ابائنا من مواضعها","و ها انها مطروحة لحر النهار وقرس الليل وقد ماتوا في اوجاع اليمة بالجوع والسيف والطرد","و جعلت البيت الذي دعي باسمك كما في هذا اليوم لاجل شر ال اسرائيل وال يهوذا","و قد عاملتنا ايها الرب الهنا بكل رافتك وكل رحمتك العظيمة","كما تكلمت على لسان عبدك موسى يوم امرته ان يكتب شريعتك امام بني اسرائيل قائلا","ان لم تسمعوا لصوتي فان هذا الجمع العظيم الكثير ليصيرن نفرا قليلا في الامم الذين اشتتهم بينهم","فاني عالم بانهم لا يسمعون لي لانهم شعب قساة الرقاب لكنهم سيرجعون الى قلوبهم في ارض جلائهم","و يعلمون اني انا الرب الههم واعطيهم قلوبا واذانا سامعة","فيسبحونني في ارض جلائهم ويذكرون اسمي","و يتوبون عن صلابة رقابهم وعن شر اعمالهم لانهم يتذكرون طريق ابائهم الذين خطئوا امام الرب","و اعيدهم الى الارض التي حلفت عليها لابائهم ابراهيم واسحق ويعقوب فيتسلطون عليها واكثرهم فلا يقلون","و اقيم لهم عهدا ابديا فاكون لهم الها ويكونون لي شعبا ولا اعود ازعزع شعبي اسرائيل من الارض التي اعطيتها لهم"],["ايها الرب القدير اله اسرائيل قد صرخت اليك النفس في المضايق والروح في الكروب","فاسمع يا رب وارحم فانك اله رحيم ارحم فانا قد خطئنا اليك","فانك انت تدوم الى الابد اما نحن فنهلك الى الابد","ايها الرب القدير اله اسرائيل اسمع صلاة قوم اسرائيل وبني الذين خطئوا اليك الذين لم يسمعوا لصوت الههم وقد لحق الشر بنا","لا تذكر اثام ابائنا بل اذكر يدك واسمك في هذا الزمان","فانك انت الرب الهنا واياك نسبح يا رب","لانك لذلك جعلت مخافتك في قلوبنا ولندعو باسمك انا نسبحك في جلائنا لانا قد نبذنا عن قلوبنا كل اثم ابائنا الذين خطئوا امامك","و ها انا اليوم في الجلاء حيث شتتنا للتعيير واللعنة والعقاب لاجل جميع اثام ابائنا الذين ارتدوا عن الرب الهنا","اسمع يا اسرائيل وصايا الحياة اصغوا وتعلموا الفطنة","لماذا يا اسرائيل لماذا انت في ارض الاعداء","قد ذبلت في ارض الغربة وتنجست بالاموات وحسبت مع الذين هم في الجحيم","انك قد تركت ينبوع الحكمة","و لو انك سلكت في طريق الله لسكنت في السلام مدى الدهر","تعلم اين الفطنة واين القوة واين التعقل لكي تعلم ايضا اين طول الايام والحياة واين نور العيون والسلام","من وجد موضعها ومن بلغ الى كنوزها","اين رؤساء الامم والذين يتسلطون على وحوش الارض","و الذين يلاعبون طيور السماء","و يكنزون الفضة والذهب مما يتوكل عليه البشر ولا حد لكسبهم ويصوغون الفضة ويهتمون ولا استقصاء لمساعيهم","انهم قد اضمحلوا والى الجحيم هبطوا واخرون قاموا من مكانهم","احداث راوا النور وسكنوا الارض لكنهم لم يعرفوا طريق التادب","و لم يفهموا سبله وبنوهم لم يدركوه وابتعدوا عن طريقه","لم يسمع به في كنعان ولا تراءى في تيمان","و بنو هاجر ايضا المبتغون للتعقل على الارض وتجار مران وتيمان وقائلو الامثال ومبتغو التعقل لم يعرفوا طريق الحكمة ولم يتذكروا سبلها","يا اسرائيل ما اعظم بيت الله وما اوسع موضع ملكه","عظيم هو بغير حد وعال بغير قياس","هناك ولد الجبابرة المذكورون الذين كانوا في البدء الطوال القامات الحاذقون بالقتال","اولئك لم يخترهم الرب ولم يجعل لهم طريق التادب","فهلكوا لعدم الفطنة هلكوا لغباوتهم","من صعد الى السماء فتناولها ونزل بها من الغيوم","من اجتاز الى عبر البحر ووجدها واثرها على الذهب الابريز","ليس احد يعرف طريقها ويطلع على سبيلها","لكن العالم بكل شيء هو يعلمها وبعقله وجدها الذي ثبت الارض الى الابد وملاها حيوانا ذا اربع","الذي يرسل النور فينطلق يدعوه فيطيعه برعدة","ان النجوم اشرقت في محارسها وتهللت","دعاها فقالت نحن لديك واشرقت متهللة للذي صنعها","هذا هو الهنا ولا يعتبر حذاءه اخر","هو وجد طريق التادب بكماله وجعله ليعقوب عبده ولاسرائيل حبيبه","و بعد ذلك تراءى على الارض وتردد بين البشر"],["هذا كتاب اوامر الله والشريعة التي الى الابد كل من تمسك بها فله الحياة والذين يهملونها يموتون","تب يا يعقوب واتخذها وسر في الضياء تجاه نورها","لا تعط مجدك لاخر ومزيتك لامة غريبة","طوبى لنا يا اسرائيل لان ما يرضي عند الله معروف لدينا","ثقوا يا شعبي يا تذكار اسرائيل","فانكم لم تباعوا للامم لهلاككم ولكن بما انكم اسخطتم الله قد اسلمتم الى اعدائكم","لانكم اغضبتم صانعكم اذ ذبحتم للشياطين لا لله","و نسيتم رازقكم الاله الازلي وحزنتم مربيتكم اورشليم","انها رات الغضب الذي حل بكم من قبل الله فقالت اسمعن يا جارات صهيون ان الله قد جلب علي نوحا عظيما","فاني رايت سبي بني وبناتي الذي جلبه عليهم الازلي","اني ربيتهم بفرح ثم ودعتهم ببكاء ونوح","لا يشمتن احد بي انا الارملة التي ثكلت كثيرين فاني قد اوحشت لاجل خطايا بني لانهم زاغوا عن شريعة الله","و لم يعرفوا رسومه ولم يسلكوا في طرق وصايا الله ولم يسيروا في سبل التادب ببره","هلم يا جارات صهيون فاذكرن سبي بني وبناتي الذي جلبه عليهم الازلي","فانه جلب عليهم امة من بعيد امة وقحة اعجمية اللسان","لم تهب شيخا ولم تشفق على طفل فذهبوا باحباء الارملة واثكلوا المتوحدة بناتها","باي شيء استطيع ان اغيثكم","الذي جلب عليكم الشر هو ينقذكم من ايدي اعدائكم","سيروا يا بني سيروا اني بقيت مستوحشة","قد خلعت حلة السلام ولبست مسح التضرع اصرخ الى الازلي مدى ايامي","ثقوا يا بني واستغيثوا بالله فينقذكم من ايدي الاعداء المتسلطين عليكم","فاني قد رجوت بالازلي خلاصكم وحلت بي مسرة من لدن القدوس بالرحمة التي تؤتونها عما قليل من عند الازلي مخلصكم","قد ودعتكم ببكاء ونوح ولكن الله سيردكم لي بفرح ومسرة الى الابد","فكما ترى الان جارات صهيون سبيكم هكذا عما قليل سيرين خلاصكم من عند الله تؤتونه بمجد عظيم وببهاء الازلي","يا بني احتملوا بالصبر الغضب الذي حل بكم من الله قد اضطهدك العدو لكنك سترى هلاكه عن قليل وتطا رقابهم","ان مترفي سلكوا طرقا وعرة وسيقوا كغنم نهبتها الاعداء","ثقوا يا بني واستغيثوا بالله فان الذي جلب عليكم هذه سيتذكركم","و كما كنتم تهوون ان تشردوا عن الله فبقدر ذلك عشر مرات تلتمسونه تائبين","و الذي جلب عليكم الشر يجلب لكم المسرة الابدية مع خلاصكم","ثقي يا اورشليم فان الذي سماك باسمه يعزيك","ويل للذين جاروا عليك وشمتوا بسقوطك","ويل للمدن التي استعبدت بنيك ويل للتي اخذت اولادك","فانها كما شمتت بسقوطك وفرحت بخرابك كذلك ستكتئب عند دمارها","و ابطل مفاخرتها بكثرة سكانها واحول مرحها الى نوح","لان نار تنزل عليها من عند الازلي الى ايام كثيرة وتسكنها الشياطين طول الزمان","تطلعي يا اورشليم من حولك نحو المشرق وانظري المسرة الوافدة عليك من عند الله","ها ان بنيك الذين ودعتهم قادمون يقدمون مجتمعين من المشرق الى المغرب بكلمة القدوس مبتهجين بمجد الله"],["اخلعي يا اورشليم حلة النوح والمذلة والبسي بهاء المجد من عند الله الى الابد","تسربلي ثوب البر الذي من الله واجعلي على راسك تاج مجد الازلي","فان الله يظهر سناك لكل ما تحت السماء","و يكون اسمك من قبل الله الى الابد سلام البر ومجد عبادة الله","انهضي يا اورشليم وقفي في الاعالي وتطلعي من حولك نحو المشرق وانظري بنيك مجتمعين من مغرب الشمس الى مشرقها بكلمة القدوس مبتهجين بذكر الله"],["نسخة الرسالة التي ارسل بها ارميا الى الذين كان ملك بابل مزمعا ان يسوقهم في الجلاء الى بابل يخبرهم بما امره الله به","انه لاجل الخطايا التي خطئتم امام الله يسوقكم نبوكد نصر ملك بابل في الجلاء الى بابل","فاذا دخلتم بابل فستكونون هناك سنين كثيرة وزمانا طويلا الى سبعة اجيال وبعد ذلك اخرجكم من هناك بسلام","و الان فانكم سترون في بابل الهة من الفضة والذهب والخشب تحمل على المناكب وتلقي الرهبة على الامم","فاحترزوا ان تتشبهوا بالغرباء وتاخذكم منها رهبة","و اذا رايتم الجموع امامها ووراءها يسجدون لها فقولوا في قلوبكم لك يا رب ينبغي السجود","فان ملاكي معكم وهو يطالب بانفسكم","اما تلك فان لها السنة قد نحتها النجار وهي مغشاة بالذهب والفضة لكنها الهة زور لا تستطيع نطقا","ياخذ الناس لها ذهبا كما يؤخذ لعذراء تحب الزينة","فيصوغون اكاليل يجعلونها على رؤوس الهتهم وربما سرق الكهنة من الهتهم الذهب والفضة لمنفعة انفسهم","و قد يبذلون منهما بالزواني اللاتي في البيت يزينون الالهة بالملابس كالبشر وهي من الفضة والذهب والخشب","فهي لا تسلم من الصدا والسوس وان كانت تلبس الارجوان","و يمسحون وجوهها من غبار البيت المتراكم عليها","و في يد كل منها صولجان كالحاكم على بلد لكنه لا يقتل من يجرم اليه","و في يمينه سيف وفاس لكنه لا ينجي نفسه من الحرب واللصوص فحق بذلك انها ليست الهة","فلا تخافوها فانه كما ان الاناء المكسور لا ينفع صاحبه كذلك الهتهم","اذا نصبت في البيوت فعيونها تمتلئ غبارا من اقدام الداخلين","يحظر عليها في الديار كما يحظر على من اجرم الى الملك وكهنتها يحصنون بيوتها بابواب واقفال ومزاليج كما يفعل بمن حكم عليه بالموت لئلا تسلبها اللصوص","يوقدون لها من السرج اكثر مما يوقدون لانفسهم وهي لا تستطيع ان ترى منها شيئا","انما هي كجوائز البيت وقد ذكر ان حشرات الارض تنهش قلوبها فتؤكل هي وثيابها ولا تشعر","تسود وجوهها من الدخان الذي في البيت","على ابدانها ورؤوسها تثب البوم والخطاف وسائر الطيور والسنانير","فاعلموا من ذلك انها ليست الهة فلا تخافوها","و الذهب الذي يغشيها للزينة ان لم يمسح صداه لم يكن لها رونق كما انها اذ صيغ عليها لم تشعر","تبتاع بكل ثمن وان لم يكن فيها روح","ليس لها ارجل فتحمل على المناكب وبذلك تبدي للناس هوانها والذين يعبدونها هم ايضا يخزون","لانها اذا سقطت على الارض لا تقوم من نفسها ولا اذا نصبها احد تتحرك من نفسها ولا اذا اميلت تستقيم بل تقدم اليها الهدايا كما تقدم الى اموات","و كهنتها يبيعون ذبائحها لمنفعة انفسهم وكذلك نساؤهم يملحن ما بقي منها ولا يجعلن فيها حظا لمسكين ولا سقيم","الطامث والنفساء تلمسان ذبائحها فاذ قد علمتم من ذلك انها ليست الهة فلا تخافوها","لماذا تسمى الهة لان النساء يقدمن الهدايا لهذه الالهة التي هي من الفضة والذهب والخشب","و لان الكهنة يجلسون في بيوتها باقمصة ممزقة وهم محلوقو الرؤوس واللحى ورؤوسهم مكشوفة","و يعجون صائحين امام الهتهم كالجالسين على مادبة الميت","الكهنة ينزعون من ثيابها ما يكسون نساؤهم واولادهم","و اذا اساء اليها احد او احسن فلا تستطيع المكافاة ولا في وسعها ان تقيم ملكا او تخلعه","و لا تقدر ان تهب عرضا ولا نقدا واذا نذر احد نذرا ولم يقضه فلا تطالب","لا تنحي احدا من الموت ولا تنقذ الضعيف من يد القوي","لا ترد البصر لاعمى ولا تفرج عن ذي شدة","لا ترحم ارملة ولا تحسن الى يتيم","فهذه الالهة التي هي من الخشب مغشاة بالذهب والفضة تماثل حجارة من الجبل والذين يعبدونها يخزون","فكيف يسوغ ان تحسب او تسمى الهة","بل الكلدانيون انفسهم يزدرونها فانهم اذا راوا ابكم لا ينطق يقدمونه الى بال ويطلبون منه النطق كانه يشعر","و مع اختبارهم لها لا يتركون عبادتها لانهم لا يشعرون","و النساء يقعدن على الطرق متحزمات بالحبال يبخرن بالنخالة","فاذا اجتذب مجتاز واحدة منهن وضاجعها عيرت صاحبتها بانها لم تحظ مثلها ولم يقطع حبلها","و كل ما يصنع لهذه الالهة انما هو زور فكيف يسوغ ان تحسب او تسمى الهة","هي صنعة النجار والصايغ فلا تكون الا ما يريد صانعها","و الذين صنعوها قصيرو بقاء فكيف يكون ما صنعوه","انهم تركوا لمن يليهم زورا وعارا","و اذا اتى عليها حرب وشر ياتمر الكهنة فيما بينهم اين يختبئون بها","فكيف لا يشعر انها ليست بالهة وهي لا تخلص انفسها من الحرب والشر","و بما انها من الخشب مغشاة بالذهب والفضة فسيعلم فيما بعد انها زور ويتبين لجميع الامم والملوك انها ليست الهة بل صنعة ايدي الناس ولا شيء فيها من صنعة الله","فهل من حاجة الى التنبيه على انها ليست الهة","فانها لا تقيم ملكا على بلد ولا تعطي الناس مطرا","و لا تخاصم حتى لخصومة انفسها ولا تنقذ احدا من مظلمة اذ لا تستطيع شيئا وانما هي كالغربان التي بين السماء والارض","و اذا وقعت نار في بيت هذه الالهة المصنوعة من الخشب المغشاة بالذهب او الفضة فكهنتها يفرون وينجون اما هي فتحترق كجوائز البيت","انها لا تقاوم ملكا ولا عدوا فكيف يسوغ ان تحسب او تعد الهة","و هذه الالهة المصنوعة من الخشب المغشاة بالفضة والذهب لا تنجي انفسها من السراق او اللصوص","و الذين يستولون عليها ينزعون عنها الذهب والفضة والثياب التي عليها ويذهبون بها وهي لا تدافع عن انفسها","لا جرم ان ملكا من ذوي الباس او اناء نافعا في البيت يستخدمه مالكه خير من الهة الزور وبابا في البيت يحفظ ما فيه خير من الهة الزور وعمود من الخشب في قصر خير من الهة الزور","ان الشمس والقمر والنجوم تضيء وترسل لمنفعة الخلق وتطيع مرسلها","و كذلك البرق اذا لمع يروق العين والريح تهب في كل ناحية","و السحب يامرها الله ان تمر على كل المسكونة فتقضي ما امرت به","و النار المرسلة من فوق لتفني الجبال والغاب تفعل ما اوصيت به اما تلك فلا تعدل بهذه منظرا ولا قوة","فلا يسوغ ان تحسب او تسمى الهة اذ لا تستطيع ان تجري حكما او تصنع احسانا","فاذ قد علمتم انها ليست بالهة فلا تخافوها","فانها لا تلعن الملوك ولا تباركهم","و لا تبدي ايات في الامم ولا في السماء ولا تنير كالشمس ولا تضيء كالقمر","الوحوش خير منها لان في طاقتها ان تهرب الى ملجا وتنفع انفسها","و بالجملة فلا يتبين لنا بوجه من الوجوه انها الهة فلا تخافوها","مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل شخص منصوب في مقثاة لا يحرس شيئا","و ايضا مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل عوسج في بستان يقع عليه كل طير او مثل ميت مطروح فيالظلمة","و من الارجوان والقرمز اللذين ياكلهما العث عليها يعلم انها ليست الهة وفي اخر الامر هي ايضا تؤكل وتصير عارا فيالافاق","ان الرجل الصديق الذي لا صنم له افضل لانه بمعزل عن العار"]]},{"id":908,"code":"1Mac","name":"المكابيين الأول (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["ان الاسكندر بن فيلبس المكدوني بعد خروجه من ارض كتيم وايقاعه بداريوس ملك فارس وماداي ملك مكانه وهو اول من ملك على اليونان","ثم اثار حروبا كثيرة وفتح حصونا متعددة وقتل ملوك الارض","و اجتاز الى اقاصي الارض وسلب غنائم جمهور من الامم فسكتت الارض بين يديه فترفع في قلبه وتشامخ","و حشد جيشا قويا جدا","و استولى على البلاد والامم والسلاطين فكانوا يحملون اليه الجزية","و بعد ذلك انطرح على فراشه واحس من نفسه بالموت","فدعا عبيده الكبراء الذين نشاوا معه منذ الصباء فقسم مملكته بينهم في حياته","و كان ملك الاسكندر اثنتي عشرة سنة ومات","فتملك عبيده كل واحد في مكانه","و لبس كل منهم التاج بعد وفاته وكذلك بنوهم من بعدهم سنين كثيرة فكثرت الشرور في الارض","و خرجت منهم جرثومة اثيمة هي انطيوكس الشهير ابن انطيوكس الملك وكان رهينة في رومية وملك في السنة المئة والسابعة والثلاثين من دولة اليونان","و في تلك الايام خرج من اسرائيل ابناء منافقون فاغروا كثيرين قائلين هلم نعقد عهدا مع الامم حولنا فانا منذ انفصلنا عنهم لحقتنا شرور كثيرة","فحسن الكلام في عيونهم","و بادر نفر من الشعب وذهبوا الى الملك فاطلق لهم ان يصنعوا بحسب احكام الامم","فابتنوا مدرسة في اورشليم على حسب سنن الامم","و عملوا لهم غلفا وارتدوا عن العهد المقدس ومازجوا الامم وباعوا انفسهم لصنيع الشر","و لما استتب الملك لانطيوكس ازمع على امتلاك مصر ليكون مالكا على كلتا المملكتين","فدخل مصر بجيش كثيف وعجلات وفيلة وفرسان واسطول عظيم","و اثار الحرب على بطلماوس ملك مصر فارتاع بطلماوس من وجهه وهرب وسقط قتلى كثيرون","فاستحوذوا على المدن الحصينة بارض مصر وسلبوا غنائم ارض مصر","و رجع انطيوكس بعدما اوقع بمصر وذلك في السنة المئة والثالثة والاربعين ونهض نحو اسرائيل","فصعد الى اورشليم بجيش كثيف","و دخل المقدس بتجبر واخذ مذبح الذهب ومنارة النور مع جميع ادواتها ومائدة التنضيد والمساكب والجامات ومجامر الذهبو الحجاب والاكاليل والحلية الذهبية التي كانت على وجه الهيكل وحطمها جميعا","و اخذ الفضة والذهب والانية النفيسة واخذ ما وجد من الكنوز المكنونة اخذ الجميع وانصرف الى ارضه","و اكثر من القتل وتكلم بتجبر عظيم","فكانت مناحة عظيمة في اسرائيل في كل ارضهم","و انتحب الرؤساء والشيوخ وخارت العذارى والفتيان وتغير جمال النساء","و كل عروس اتخذ مرثاة والجالسة في الحجلة عقدت مناحة","فارتجت الارض على سكانها وجميع ال يعقوب لبسوا الخزي","و بعد سنتين من الايام ارسل الملك رئيس الجزية الى مدن يهوذا فوفد على اورشليم في جيش كثيف","و خاطبهم خطاب سلام مكرا فوثقوا به","ثم هجم على المدينة فجاة وضربها ضربة عظيمة واهلك شعبا كثيرا من اسرائيل","و سلب غنائم المدينة واحرقها بالنار وهدم بيوتها واسوارها من حولها","و سبوا النساء والاولاد واستولوا على المواشي","و بنوا على مدينة داود سورا عظيما متينا وبروجا حصينة فصارت قلعة لهم","و جعلوا هناك امة اثيمة رجالا منافقين فتحصنوا فيها ووضعوا فيها السلاح والطعام وجمعوا غنائم اورشليم","و وضعوها هناك فصاروا لهم شركا مهلكا","و كان ذلك مكمنا للمقدس وشيطانا خبيثا لاسرائيل على الدوام","فسفكوا الدم الزكي حول المقدس ونجسوا المقدس","فهرب اهل اورشليم بسببهم فامست مسكن غرباء وصارت غريبة للمولودين فيها وابناؤها هجروها","و رد مقدسها خرابا كالقفر وحولت اعيادها مناحة وسبوتها عارا وعزها اضمحلالا","و على قدر مجدها اكثر هوانها ورفعتها الت الى مناحة","و كتب الملك انطيوكس الى مملكته كلها بان يكونوا جميعهم شعبا واحدا ويتركوا كل واحد سننه","فاذعنت الامم باسرها لكلام الملك","و كثيرون من اسرائيل ارتضوا دينه وذبحوا للاصنام ودنسوا السبت","و انفذ الملك كتبا على ايدي رسل الى اورشليم ومدن يهوذا ان يتبعوا سنن الاجانب في الارض","و يمتنعوا عن المحرقات والذبيحة والسكيب في المقدس","و يدنسوا السبوت والاعياد","و ينجسوا المقادس والقديسين","و يبتنوا مذابح وهياكل ومعابد للاصنام ويذبحوا الخنازير والحيوانات النجسة","و يتركوا بنيهم قلفا ويقذروا نفوسهم بكل نجاسة ورجس حتى ينسوا الشريعة ويغيروا جميع الاحكام","و من لا يعمل بمقتضى كلام الملك يقتل","و كتب بمثل هذا الكلام كله الى مملكته باسرها واقام رقباء على جميع الشعب","و امر مدائن يهوذا بان يذبحوا في كل مدينة","فانضم اليهم كثيرون من الشعب كل من نبذ الشريعة فصنعوا الشر في الارض","و الجاوا اسرائيل الى المختبات في كل موضع فروا اليه","و في اليوم الخامس عشر من كسلو في السنة المئة والخامسة والاربعين بنوا رجاسة الخراب على المذبح وبنوا مذابح في مدن يهوذا من كل ناحية","و كانوا يقترون على ابواب البيوت وفي الساحات","و ما وجدوه من اسفار الشريعة مزقوه واحرقوه بالنار","و كل من وجد عنده سفر من العهد او اتبع الشريعة فانه مقتول بامر الملك","هكذا كانوا يفعلون بسطوتهم في اسرائيل بالذين يصادفونهم في المدن شهرا فشهرا","و في اليوم الخامس والعشرين من الشهر ذبحوا على مذبح الاصنام الذي فوق المذبح","و النساء اللواتي ختن اولادهن قتلوهن بمقتضى الامر","و علقوا الاطفال في اعناقهن ونهبوا بيوتهن وقتلوا الذين ختنوهم","و ان كثيرين في اسرائيل عزموا وصمموا في انفسهم على ان لا ياكلوا نجسا واختاروا الموت لئلا يتنجسوا بالاطعمة","و لا يدنسوا العهد المقدس فماتوا","و كان على اسرائيل غضب شديد جدا"],["في تلك الايام خرج من اورشليم متتيا بن يوحنا بن سمعان كاهن من بني يوياريب وسكن في مودين","و كان له خمسة بنين يوحنا الملقب بكديس","و سمعان المسمى بطسي","و يهوذا الملقب بالمكابي","و العازار الملقب باواران ويوناتان الملقب بافوس","و لما راى ما يصنع من المنكرات في يهوذا واورشليم","قال ويل لي لم ولدت فانظر حطم شعبي وحطم المدينة المقدسة وامكث ههنا اراها مسلمة الى ايدي الاعداء","و ارى المقدس في ايدي الاجانب وهيكلها كرجل ذليل","و قد اخذت انية مجدها في السبي وقتل اطفالها في الساحات وفتيانها بسيف العدو","اية امة لم ترث ملكها ولم تسلب غنائمها","جميع حلاها قد نزعت والتي كانت حرة صارت امة","ها ان اقداسنا وبهاءنا ومجدنا قد دمرت ودنستها الامم","فلم حياتنا بعد","و مزق متتيا وبنوه ثيابهم وتحزموا بالمسوح وناحوا مناحة شديدة","و ان الذين ارسلهم الملك ليجبروا الناس على الارتداد قدموا الى مدينة مودين ليذبحوا","فاقبل عليهم كثيرين من اسرائيل واجتمع متتيا وبنوه","فاجاب رسل الملك وكلموا متتيا قائلين انت رئيس في هذه المدينة شريف عظيم معزز بالبنين والاخوة","فالان ابدا انت وتقدم لامضاء امر الملك كما فعلت الامم كلها ورجال يهوذا ومن بقي في اورشليم فتكون انت واهل بيتك من اصدقاء الملك وتكرم انت وبنوك بالذهب والفضة والهدايا الكثيرة","فاجاب متتيا بصوت عظيم وقال انه وان طاعت للملك كل الامم التي في دار ملكه وارتد كل احد عن دين ابائه ورضي باوامره","فانا وبني واخوتي نسلك في عهد ابائنا","فحاشا لنا ان نترك الشريعة والاحكام","انا لن نسمع لكلام الملك فنحيد عن ديننا يمنة او يسرة","و لما فرغ من هذا الكلام اقبل رجل يهودي على عيون الجميع ليذبح على المذبح الذي في مودين على مقتضى امر الملك","فلما راى متتيا ذلك غار وارتعش حقواه واستشاط غضبا وفاقا للشريعة فوثب عليه وقتله على المذبح","و في ذلك الوقت قتل ايضا رجل الملك الذي كان يجبر على الذبح وهدم المذبح","و غار للشريعة كما فعل فنحاس بزمري بن سالو","و صاح متتيا في المدينة بصوت عظيم قائلا كل من غار للشريعة وحافظ على العهد فليخرج ورائي","و هرب هو وبنوه الى الجبال وتركوا كل ما لهم في المدينة","حينئذ نزل كثيرون الى البرية ممن يبتغون العدل والحكم","ليسكنوا هناك هم وبنوهم ونساؤهم ومواشيهم لان الشرور كثرت عليهم","فاخبر رجال الملك والجند الذين كانوا في اورشليم في مدينة داود بان رجالا من الناقضين لامر الملك قد نزلوا واختباوا في البرية فجرى كثيرون في اعقابهم","فادركوهم وجيشوا حولهم وناصبوهم القتال في يوم السبت","و قالوا لهم حسبكم ما فعلتم فاخرجوا وافعلوا كما امر الملك فتحيوا","فقالوا لا نخرج ولا نفعل كما امر الملك لئلا ندنس يوم السبت","فاثاروا عليهم القتال","فلم يردوا عليهم ولا رموهم بحجر ولا سدوا مختباتهم","قائلين لنمت جميعا في استقامتنا والسماء والارض شاهدتان لنا بانكم تهلكوننا ظلما","فهجموا عليهم وقاتلوهم في السبت فهلكوا هم ونساؤهم وبنوهم ومواشيهم وكانوا الف نفس من الناس","و اخبر متتيا واصحابه فناحوا عليهم نوحا شديدا","و قال بعضهم لبعض ان فعلنا كلنا كما فعل اخوتنا ولم نقاتل الامم عن نفوسنا واحكامنا لم يلبثوا ان يبيدونا عن الارض","و اتمروا في ذلك اليوم قائلين كل رجل اتانا مقاتلا يوم السبت نقاتله ولا نموت جميعا كما مات اخوتنا في المختبات","حينئذ اجتمعت اليهم جماعة الحسيديين ذوي الباس في اسرائيل وكل من انتدب للشريعة","و انضم اليهم جميع الذين فروا من الشر فازدادوا بهم تعزيزا","و الفوا جيشا واوقعوا بالخطاة في غضبهم وبرجال النفاق في حنقهم وفر الباقون الى الامم طالبين النجاة","ثم جال متتيا واصحابه وهدموا المذابح","و ختنوا كل من وجدوه في تخوم اسرائيل من الاولاد الغلف وتشددوا","و تتبعوا ذوي التجبر ونجحوا في عمل ايديهم","و انقذوا الشريعة من ايدي الامم وايدي الملوك ولم يجعلوا للخاطئ قرنا","و قاربت ايام متتيا ان يموت فقال لبنيه لقد اشتد التجبر والعقاب وزمان الانقلاب ووغر الحنق","فالان ايها البنون غاروا للشريعة وابذلوا نفوسكم دون عهد ابائنا","اذكروا اعمال ابائنا التي صنعوها في اجيالهم فتنالوا مجدا عظيما واسما مخلدا","الم يكن ابرهيم في التجربة وجد مؤمنا فحسب له ذلك برا","و يوسف في اوان ضيقه حفظ الوصية فصار سيدا على مصر","و فنحاس ابونا غار غيرة فاخذ عهد كهنوت ابدي","و يشوع اذ اتم ما امر به صار قاضيا في اسرائيل","و كالب بشهادته في الجماعة نال ميراثا في الارض","و داود برحمته ورث عرش الملك الى ابد الاباد","و ايليا بغيرته للشريعة رفع الى السماء","و حننيا وعزريا وميشائيل بايمانهم خلصوا من اللهيب","و دانيال باستقامته انقذ من افواه الاسود","و هكذا اعتبروا في جيل فجيل ان جميع المتوكلين عليه لا يزلون","و لا تخشوا من كلام الرجل الخاطئ لان مجده ياول الى قذر ودود","اليوم يرتفع وغدا لا وجود له لانه يعود الى ترابه وتضمحل افكاره","فانتم ايها البنون تشددوا وكونوا رجالا في الشريعة فانكم بها ستمجدون","و هوذا سمعان اخوكم اني اعلم انه رجل مشورة فاسمعوا منه كل الايام وليكن لكم ابا","و يهوذا المكابي الشديد الباس منذ صباه هو يكون لكم رئيس الجيش ويتولى قتال الشعوب","و اجمعوا اليكم جميع العاملين بالشريعة وانتقموا لشعبكم انتقاما","كافئوا الامم مكافاة وواظبوا على وصايا الشريعة","ثم باركهم وانضم الى ابائه","و كانت وفاته في السنة المئة والسادسة والاربعين فدفنه بنوه في قبور ابائهم بمودين وبكى عليه جميع اسرائيل بكاء شديدا"],["فقام مكانه يهوذا ابنه المسمى بالمكابي","و كان كل اخوته وجميع الذين انضموا الى ابيه انصارا له يحاربون حرب اسرائيل بفرح","فزاد شعبه بسطة في العز ولبس لامته كجبار وتقلد سلاحه للقتال وباشر الحروب وبسيفه حمى الجيش","و كان كالاسد في حركاته وكالشبل الزائر على الفريسة","فتعقب اهل النفاق مستقصيا اثارهم واحرق الذين يفتنون شعبه بالنار","فنكص المنافقون خوفا منه واضطرب جميع فاعلي الاثم ونجح الخلاص على يده","و احنق ملوكا كثيرين وفرح يعقوب باعماله فصار ذكره مباركا مدى الدهر","و جال في مدن يهوذا واهلك الكفرة منها وصرف الغضب عن اسرائيل","فاشتهر الى اقاصي الارض وجمع المشرفين على الهلاك","و حشد ابلونيوس الامم وجاء بجيش عظيم من السامرة ليحارب اسرائيل","فلما علم يهوذا خرج للقائه فاوقع به وقتله وسقط قتلى كثيرون وانهزم الباقون","فسلب غنائمهم واخذ يهوذا سيف ابلونيوس فكان يقاتل به كل الايام","و سمع سارون قائد جيش سورية ان يهوذا قد عصب عصابة وجماعة من المؤمنين يسيرون معه الى القتال","فقال اقيم لنفسي اسما واتمجد في المملكة واقاتل يهوذا والذين معه من المستهينين بامر الملك","ثم تجهز للخروج وخرج معه جيش قوي من الكفرة يظاهرونه وينتقمون من بني اسرائيل","فدنوا الى عقبة بيت حورون فخرج يهوذا للقائهم في نفر يسير","فلما راوا الجيش مقبلا الى لقائهم قالوا ليهوذا كيف نطيق قتال مثل هذا الجمع القوي ونحن نفر يسير وقد استرخينا اليوم من الصوم","فقال يهوذا ما اسهل ان يدفع الكثيرون الى ايدي القليلين وسواء عند اله السماء ان يخلص بالكثيرين وبالقليلين","فانه ليس الظفر في الحرب بكثرة الجنود وانما القوة من السماء","اولئك ياتوننا بجمع من ذوي الشتائم والنفاق ليبيدونا نحن ونساءنا واولادنا ويسلبونا","و اما نحن فنحارب عن نفوسنا وسنننا","و هو يكسرهم امام وجوهنا فلا تخافوهم","و لما فرغ من كلامه هجم عليهم بغتة فانكسر سارون وجيشه امامه","فتتبعه في عقبة بيت حورون الى السهل فسقط منهم ثماني مئة رجل وانهزم الباقون الى ارض فلسطين","فوقع خوف يهوذا واخوته ورعبهم على الامم الذين حولهم","و بلغ ذكره الى الملك وتحدثت الامم كلها بوقائع يهوذا","فلما سمع انطيوكس الملك بهذا الكلام استشاط غضبا وارسل وجمع كل جيوش مملكته عسكرا شديدا جدا","و فتح خزانته ودفع الى جيوشه وظائف سنة وامرهم بان يكونوا متاهبين لكل شيء","ثم راى ان الفضة قد نفدت من الخزائن وقد قل جباة ضرائب البلاد لسبب الفتنة والضربة التي احدثها في الارض لينسخ السنن التي كانت لها منذ ايام القدم","و خشي انه لا يملك ما يقوم بنفقاته وعطاياه التي طال ما كان يجود بها جودا واسعا فاق به الملوك الذين كانوا من قبله","فتحير في نفسه حيرة شديدة وازمع ان يذهب الى بلاد فارس وياخذ جزية البلاد ويجبي مالا جزيلا","فاستخلف ليسياس على امور الملك من نهر الفرات الى حدود مصر وهو رجل شريف من النسل الملكي","و ان يتولى تربية انطيوكوس ابنه الى ان يعود","و فوض اليه شطر الجيش والفيلة وامره بكل ما كان في نفسه وبامر سكان اليهودية واورشليم","ان يوجه اليهم جيشا يكسر ويستاصل شوكة اسرائيل وبقية اورشليم ويمحو ذكرهم من المكان","و ينزل في جميع تخومهم ابناء الاجانب ويقسم الارض بينهم","و اخذ الملك الشطر الباقي من الجيش وسار من انطاكية عاصمة ملكه في السنة المئة والسابعة والاربعين وعبر نهر الفرات وجال في الاقاليم العليا","فاختار ليسياس بطلماوس بن دوريمانس ونكانور وجرجياس رجالا ذوي باس من اصحاب الملك","و وجه منهم اربعين الف راجل وسبعة الاف فارس لياتوا ارض يهوذا ويدمروها على حسب امر الملك","فساروا بالجيش كله حتى بلغوا الى قرب عماوس ونزلوا هناك في ارض السهل","و سمع بخبرهم تجار البلاد فاخذوا من الفضة والذهب شيئا كثيرا وعبيدهم وجاءوا المحلة حتى يشتروا بني اسرائيل عبيدا لهمو انضمت اليهم جيوش سورية وارض الغرباء","و راى يهوذا واخوته تفاقم الشر وان الجيوش حالة في تخومهم وبلغهم كلام الملك انه امر باهلاك الشعب واستئصاله","فقال كل واحد لصاحبه هلم ننهض شعبنا من مذلته ونقاتل عن شعبنا واقداسنا","فاحتشدت الجماعة لتتاهب للقتال وتصلي وتسال الرافة والمراحم","و كانت اورشليم مهجورة كالقفر لا يدخلها ولا يخرج منها احد من بنيها وكان المقدس مدوسا وابناء الاجانب في القلعة التيكانت مسكنا للامم وقد زال الطرب عن يعقوب وبطل المزمار والكنارة","فاجتمعوا وساروا الى المصفاة قبالة اورشليم لان المصفاة كانت من قبل هي موضع الصلاة لاسرائيل","و صاموا في ذلك اليوم وتحزموا بالمسوح وحثوا الرماد على رؤوسهم ومزقوا ثيابهم","و نشروا كتاب الشريعة الذي كانت الامم تبحث فيه عن مثال لاصنامها","و اتوا بثياب الكهنوت وبالبواكير والعشور ثم دعوا النذراء الذين قد استوفوا ايامهم","و رفعوا اصواتهم الى السماء قائلين ما نصنع بهؤلاء والى اين ننطلق بهم","فان اقداسك قد ديست ودنست وكهنتك في النحيب والمذلة","و ها ان الامم قد اجتمعوا علينا ليبيدونا وانت عليم بما ياتمرون علينا","فكيف نستطيع الثبات امامهم ان لم تكن انت في نصرتنا","ثم نفخوا في الابواق وصرخوا بصوت عظيم","و بعد ذلك رتب يهوذا قواد الشعب رؤساء الالف والمئة والخمسين والعشرة","و امر من اخذ في بناء بيت او خطب امراة او غرس كرما او كان خائفا بان يرجع الى بيته بحسب الشريعة","ثم سار الجيش ونزلوا بجنوب عماوس","فقال يهوذا تنطقوا وكونوا ذوي باس وتاهبوا للغد لمقاتلة هذه الامم المجتمعة علينا لتبيدنا نحن واقداسنا","فانه خير لنا ان نموت في القتال ولا نعاين الشر في قومنا واقداسنا","و كما تكون مشيئته في السماء فليصنع بنا"],["و اخذ جرجياس خمسة الاف راجل والف فارس منتخبين وسار الجيش ليلا","ليهجموا على محلة اليهود ويوقعوا بهم بغتة وكان اهل القلعة ادلاء لهم","فسمع يهوذا فسار هو ورجال الباس ليضرب جيش الملك الذي في عماوس","و كان لا يزال متفرقا في خارج المحلة","فلما انتهى جرجياس الى محلة يهوذا ليلا لم يجد احدا فطلبهم في الجبال لانه قال انهم هربوا منا","فلما كان النهار ظهر يهوذا في السهل ومعه ثلاثة الاف رجل الا انهم لم يكن معهم من الجنن والسيوف ما يوافق مرادهم","و راوا ان جيش الامم قوي وعليه الدروع والخيل من حوله وهم مدربون على الحرب","فقال يهوذا لمن معه من الرجال لا تخافوا كثرتهم ولا تخشوا بطشهم","اذكروا كيف نجا اباؤنا في بحر القلزم حين تتبعهم فرعون بجيشه","فالان لنصرخن الى السماء لعله يرحمنا ويتذكر عهد ابائنا ويكسر هذا الجيش امامنا اليوم","فتعلم كل الامم ان لاسرائيل فاديا ومخلصا","و رفع الاجانب ابصارهم فراوهم مقبلين عليهم","فخرجوا من المحلة للقتال ونفخ اصحاب يهوذا في البوق","و اقتتلوا فانكسرت الامم وانهزمت الى السهل","و سقط جميع ساقتهم بالسيف فتعقبوهم الى جازر وسهول ادوم واشدود ويمنيا وكان الساقطون منهم ثلاثة الاف رجل","ثم رجع يهوذا وجيشه عن تعقبهم","و قال للشعب لا تطمعوا في الغنائم لان الحرب لا تزال قائمة علينا","فان جرجياس وجيشه بالقرب منا في الجبل فاثبتوا الان امام اعدائنا وقاتلوهم وبعد ذلك تاخذون الغنائم بامان","و لم يفرغ يهوذا من هذا الكلام حتى ظهرت فرقة تتشوف من الجبل","فرات انهم قد انكسروا وان المحلة قد احرقت كما دلهم على ذلك الدخان المتصاعد","فلما عاينوا ذلك خافوا جدا واذ راوا جيش يهوذا في السهل مستعدا للقتال","فروا جميعا الى ارض الاجانب","فرجع يهوذا الى غنائم المحلة فاخذوا ذهبا كثيرا وفضة وسمنجونيا وارجوانا بحريا واموالا جزيلة","و عادوا وهم يسبحون الرب ويباركونه الى السماء لانه صالح لان الى الابد رحمته","و كان في ذلك اليوم خلاص عظيم في اسرائيل","و وفد كل من نجا من الاجانب على ليسياس واخبروه بجميع ما وقع","فلما سمع ذلك بهت وانكسر عزمه اذ لم ينفذ في اسرائيل ما كان يريده ولم يتم ما امر به الملك","فلما كانت السنة القابلة جمع ليسياس ستة الاف راجل منتخبين وخمسة الاف فارس لمحاربتهم","فاتوا الى ادوم ثم نزلوا ببيت صور فلاقاهم يهوذا في عشرة الاف رجل","فراى جيشا قويا فصلى وقال مبارك انت يا مخلص اسرائيل الذي حطم بطش الجبار على يد عبده داود واسلم محلة الاجانب الى يد يوناتان بن شاول وحامل سلاحه","فالق هذا الجيش في ايدي شعبك اسرائيل وليخزوا مع جنودهم وفرسانهم","احلل عليهم الرعدة واذب تجبر قوتهم وليضطربوا وينسحقوا","اسقطهم بسيف محبيك وليسبحك بالاناشيد جميع الذين يعرفون اسمك","ثم التحم القتال فسقط من جيش ليسياس خمسة الاف رجل وصرعوا امامهم","فلما راى ليسياس انكسار جيشه وبسالة جيش يهوذا وانهم مستعدون بشجاعتهم اما للحياة واما للموت ذهب الى انطاكية وجمع جيشا من الغرباء ولما كثر جيشه الاول هم بالرجوع الى اليهودية","و ان يهوذا واخوته قالوا ها ان اعداءنا قد انسحقوا فلنصعد الان لتطهير المقادس وتدشينها","فاجتمع كل الجيش وصعدوا الى جبل صهيون","فراوا المقدس خاليا والمذبح منجسا والابواب محرقة وقد طلع النبات في الديار كما يطلع في غابة او جبل من الجبال والغرفات مهدومة","فمزقوا ثيابهم وناحوا نوحا عظيما وحثوا على رؤوسهم رمادا","و سقطوا بوجوههم على الارض ونفخوا في ابواق الاشارة وصرخوا الى السماء","حينئذ رتب يهوذا رجالا يصادمون اهل القلعة ريثما يطهر المقادس","و اختار كهنة لا عيب فيهم من ذوي الحرص على الشريعة","فطهروا المقادس ورفعوا الحجارة المدنسة الى موضع نجس","ثم ائتمروا في مذبح المحرقة المدنس ماذا يصنعون به","فخطرت لهم مشورة صالحة ان يهدموه لئلا يكون لهم عارا لتدنيس الامم اياه فهدموا المذبح","و وضعوا الحجارة في جبل البيت في موضع لائق الى ان ياتي نبي ويجيب عنها","ثم اخذوا حجارة غير منحوتة وفاقا للشريعة وبنوا المذبح الجديد على رسم الاول","و بنوا المقادس وداخل البيت وقدسوا الديار","و صنعوا انية مقدسة جديدة وحملوا المنارة ومذبح البخور والمائدة الى الهيكل","و بخروا على المذبح واوقدوا السرج التي على المنارة فكانت تضيء في الهيكل","و جعلوا الخبز على المائدة ونشروا السجوف واتموا جميع الاعمال التي عملوها","و بكروا في اليوم الخامس عشر من الشهر التاسع وهو كسلو في السنة المئة والثامنة والاربعين","و قدموا ذبيحة بحسب الشريعة على مذبح المحرقة الجديد الذي صنعوه","و في مثل الوقت واليوم الذي فيه دنسته الامم في ذلك اليوم دشن بالاناشيد والعيدان والكنارات والصنوج","فخر جميع الشعب على وجوههم وسجدوا للذي انجحهم وباركوه الى السماء","و اتموا تدشين المذبح في ثمانية ايام وقدموا المحرقات بفرح وذبحوا ذبيحة السلامة والحمد","و زينوا وجه الهيكل باكاليل من الذهب وتروس ودشنوا الابواب والغرفات وجعلوا لها مصاريع","فكان عند الشعب سرور عظيم جدا وازيل تعيير الامم","و رسم يهوذا واخوته وجماعة اسرائيل كلها ان يعيد لتدشين المذبح في وقته سنة فسنة مدة ثمانية ايام من اليوم الخامس والعشرين من شهر كسلو بسرور وابتهاج","و في ذلك الزمان بنوا على جبل صهيون من حوله اسوارا عالية وبروجا حصينة لئلا تجيء الامم وتطاه كما فعلت من قبل","و اقام ثم جيشا يحرسونه وحصنوا بيت صور صيانة له حتى يكون للشعب معقلا تلقاء ادوم"],["و لما سمعت الامم التي من حولهم ان قد بني المذبح ودشن المقدس كما كانا من قبل استشاطوا غضبا","و اتمروا ان يبيدوا من بينهم من نسل يعقوب وطفقوا يقتلون ويهلكون من الشعب","و كان يهوذا يحارب بني عيسو في ادوم عند اقربتين لانهم كانوا يضيقون على اسرائيل فضربهم ضربة عظيمة ودفعهم وسلب غنائمهم","و تذكر شر بني بيان الذين كانوا شركا ومعثرة للشعب يكمنون لهم على الطرق","فالجاهم الى البروج وحاصرهم وابسلهم واحرق بروجهم وكل من كان فيها بالنار","ثم عبر الى بني عمون فصادف عسكرا قويا وشعبا كثيرا تحت قيادة تيموتاوس","فواقعهم في حروب كثيرة فانكسروا امامه فاوقع بهم","و فتح يعزير وتوابعها ثم عاد الى اليهودية","و ان الامم الذين في جلعاد اجتمعوا على من كان من اسرائيل في تخومهم ليبيدوهم ففروا الى حصن دياتما","و ارسلوا كتابا الى يهوذا واخوته قائلين ان الامم الذين حولنا قد اجتمعوا علينا يريدون ابادتنا","و في عزمهم ان ياتوا ويستفتحوا الحصن الذي التجانا اليه وجيشهم تحت قيادة تيموتاوس","فالان هلم واستنقذنا من ايديهم فقد سقط منا عدد كثير","و جميع اخوتنا الذين في ارض طوب قد قتلوا وسبيت نساؤهم واولادهم وسلبت امتعتهم وهلك هناك نحو الف رجل","فبينما هم يقراون الكتاب اذا برسل اخرين قد وفدوا من الجليل وثيابهم ممزقة واخبروا بمثل ذلك","قائلين قد اجتمعوا علينا من بطلمايس وصور وصيدا وكل جليل الامم ليبيدونا","فلما سمع يهوذا والشعب هذا الكلام عقدوا مجمعا عظيما وتشاوروا فيما يصنعون باخوتهم الذين في الضيق تحت الحصار","فقال يهوذا لسمعان اخيه اختر لك رجالا وانطلق واستنقذ اخوتك الذين في الجليل وانا ويوناتان اخي ننطلق الى ارض جلعاد","و استخلف يوسف بن زكريا وعزريا قائدي الشعب مع بقية الجيش في اليهودية للمحافظة","و اوصاهما قائلا توليا امر هذا الشعب ولا تقيما على الامم حربا حتى نعود","فانقسمت الرجال ثلاثة الاف مع سمعان ينطلقون الى الجليل وثمانية الاف مع يهوذا الى ارض جلعاد","و انطلق سمعان الى الجليل وناصب الامم حروبا كثيرة فانكسرت الامم من وجهه فتتبعهم الى باب بطلمايس","فسقط من الامم ثلاثة الاف رجل وسلب غنائمهم","و اخذ الذين في الجليل وعربات مع النساء والاولاد وكل ما كان لهم وجاء بهم الى اليهودية بسرور عظيم","و اما يهوذا المكابي ويوناتان اخوه فعبرا الاردن وسارا مسيرة ثلاثة ايام في البرية","فصادفا النباطيين فتلقوهما بسلام وقصوا عليهما كل ما اصاب اخوتهما في ارض جلعاد","و ان كثيرين منهم قد حصروا في بصرة وباصر وعليم وكسفور ومكيد وقرنائيم وكلها مدن حصينة عظيمة","و انهم ايضا محصورون في سائر مدن ارض جلعاد والقوم مستعدون لمحاصرتهم غدا في الحصون والقبض عليهم وابادتهم جميعا في يوم واحد","فعدل يهوذا جيشه بغتة وتوجه جهة البرية الى باصر فاستحوذ على المدينة وقتل كل ذكر بحد السيف وسلب جميع غنائمهم واحرق المدينة بالنار","ثم قام من هناك ليلا وسار الى الحصن","و لما كان الصبح رفعوا ابصارهم فاذا بقوم كثيرين لا عدد لهم حاملين سلالم ومجانيق لفتح الحصن وهم محاصرون لهم","و راى يهوذا ان الحرب قد التحمت وقد علت جلبة المدينة الى السماء بالابواق والصراخ العظيم","فقال لرجال الجيش قاتلوا اليوم عن اخوتكم","و خرج في ثلاث فرق من ورائهم ونفخوا في الابواق وصرخوا في الصلاة","و علم جيش تيموتاوس انه المكابي فهربوا من وجهه فضربهم ضربة عظيمة فسقط منهم في ذلك اليوم ثمانية الاف رجل","ثم انصرف الى المصفاة وحاربها فافتتحها وقتل كل ذكر بها وسلب غنائمها واحرقها بالنار","و مضى من هناك فافتتح كسفور ومكيد وباصر وسائر مدن ارض جلعاد","و بعد هذه الامور جمع تيموتاوس جيشا اخر ونزل قبالة رافون في عبر الوادي","فارسل يهوذا رجالا يكشفون امر الجيش فاخبروه قائلين ان جميع الامم التي حولنا قد انضمت اليهم وهم جيش عظيم جدا","و قد استاجروا العرب يظاهرونهم ونزلوا في عبر الوادي وفي عزمهم ان ياتوك للقتال فخرج يهوذا لملاقاتهم","و قال تيموتاوس لرؤساء جيشه اذا بلغ يهوذا وجيشه الى وادي الماء فان عبر الينا اولا فلا نطيق الثبات امامه بل يتغلب علينا تغلبا","و ان تخوف وحل في عبر النهر جزنا اليه وتغلبنا عليه","فلما بلغ يهوذا الى وادي الماء اقام كتبة الشعب على الوادي وامرهم قائلا لا تدعوا احدا يحل ههنا بل لينطلقوا بجملتهم الى الحرب","و عبر اليهم وهو في المقدمة وكل الشعب وراءه فانكسرت امامه جميع الامم والقوا سلاحهم وفروا الى المعبد الذي في قرنائيم","فاستولى اليهود على المدينة واحرقوا المعبد مع كل من كان فيه بالنار وانكسر اهل قرنائيم ولم يطيقوا الثبات امام يهوذا","و جمع يهوذا كل من كان من اسرائيل في ارض جلعاد صغيرهم وكبيرهم ونساءهم واولادهم مع امتعتهم جيشا عظيما جدا لينصرف بهم الى ارض يهوذا","فبلغوا الى عفرون وهي مدينة عظيمة على المدخل حصينة جدا فلم يكن لهم ان يحيدوا عنها يمنة ولا يسرة الا ان يجوزوا فيوسطها","فاغلق اهل المدينة على انفسهم وردموا الابواب بالحجارة فارسا اليهم يهوذا بكلام السلم","قائلا انا نجوز في ارضك لنذهب الى ارضنا ولا يضركم احد انما نمر باقدامنا فابوا ان يفتحوا له","فامر يهوذا ان ينادى في المحلة بان يهجم كل واحد من المكان الذي هو فيه","فهجم رجال الباس وحاربوا المدينة كل ذلك اليوم وليلته كلها فاسلمت المدينة الى يديه","فاهلك كل ذكر بحد السيف ودمرها وسلب غنائمها واجتاز في المدينة من فوق القتلى","ثم عبروا الاردن الى السهل العظيم قبالة بيت شان","و كان يهوذا يجمع المتخلفين ويشجع الشعب طول الطريق حتى وصلوا الى ارض يهوذا","فصعدوا جبل صهيون بسرور وابتهاج وقدموا المحرقات لاجل انه لم يسقط احد منهم حتى رجعوا بسلام","و في الايام التي كان فيها يهوذا ويوناتان في جلعاد وسمعان اخوه في الجليل قبالة بطلمايس","سمع يوسف بن زكريا وعزريا رئيسا الجيش بما ابدوا من الحماسة والقتال","فقالا لنقم لنا نحن ايضا اسما ولننطلق لمحاربة الامم التي حولنا","ثم امرا الجيش الذي معهما فزحفوا على يمنيا","فخرج جرجياس ورجاله من المدينة الى ملاقاتهم للقتال","فانكسر يوسف وعزريا فتتبعوهما الى حدود اليهودية وسقط في ذلك اليوم من شعب اسرائيل الفا رجل وكانت في شعب اسرائيل حطمة عظيمة","ذلك لانهما لم يسمعا ليهوذا واخوته ظنا منهما بانهما يبديان حماسة","الا انهما لم يكونا من نسب اولئك الرجال الذين اوتوا خلاص اسرائيل على ايديهم","و عظم الرجل يهوذا واخوته جدا في عيون كل اسرائيل وجميع الامم التي سار اليها ذكرهم","و كانوا يجتمعون اليهم باصوات التهنئة","و خرج يهوذا واخوته وحاربوا بني عيسو في ارض الجنوب وضرب حبرون وتوابعها وهدم سورها واحرق البروج التيحولها","و سار قاصدا ارض الاجانب وجال في ارض السامرة","و في ذلك الحين سقط كهنة في الحرب وكانوا يريدون ان يبدوا حماسة فخرجوا الى الحرب عن غير تدبر","ثم توجه يهوذا الى اشدود في ارض الاجانب فهدم مذابحهم واحرق منحوتات الهتهم بالنار وسلب غنائم المدن وعاد الى ارض يهوذا"],["و فيما كان انطيوكس الملك يجول في الاقاليم العليا سمع بذكر المايس وهي مدينة بفارس مشهورة باموالها من الفضة والذهب","و ان بها هيكلا فيه كثير من الاموال وفيه سجوف الذهب والدروع والاسلحة التي تركها ثم الاسكندر بن فيلبس الملك المكدوني الذي كان اول ملك في اليونان","فاتى وحاول ان ياخذ المدينة وينهبها فلم يستطع لان الامر كان قد عرف عند اهل المدينة","فثاروا اليه وقاتلوه فهرب ومضى من هناك بغم شديد راجعا الى بابل","و جاءه في فارس مخبر بان الجيوش التي وجهت الى ارض يهوذا قد انكسرت","و ان ليسياس قد انهزم من وجههم وكان قد خرج عليهم في جيش في غاية القوة فتعززوا بالسلاح والذخائر والغنائم الكثيرة التي اخذوها ممن دمروهم من الجيوش","و هدموا الرجاسة التي كان قد بناها على المذبح في اورشليم وحوطوا المقدس بالاسوار الرفيعة كما كان من قبل وحصنوا بيت صور مدينتهم","فلما سمع الملك هذا الكلام بهت واضطرب جدا وانطرح على الفراش وقد اوقعه الغم في السقم لان الامر وقع على خلاف مشتهاه","فلبث هناك اياما كثيرة لانه تجدد فيه غم شديد وايقن بالموت","فدعا جميع اصحابه وقال لهم لقد شرد النوم عن عيني وسقط قلبي من الكرب","فقلت في نفسي الى اي بلاء صرت وما اعظم اللجة التي انا فيها بعد ان كنت مسرورا ومحبوبا في سلطاني","اني لاتذكر المساوئ التي صنعتها في اورشليم وكيف اخذت كل انية الذهب والفضة التي كانت فيها وارسلت لابادة سكان يهوذا بغير سبب","فانا اعلم باني لاجل ذلك اصابتني هذه البلايا وها انا اهلك بكمد شديد في ارض غريبة","ثم دعا فيلبس احد اصحابه واقامه على جميع مملكته","و دفع اليه تاجه وحلته وخاتمه واوصاه بتدبير انطيوكس ابنه وترشيحه للملك","و مات هناك انطيوكس الملك في السنة المئة والتاسعة والاربعين","و علم ليسياس ان الملك قد توفي وملك موضعه انطيوكس ابنه الذي رباه هو في حداثته وسماه باسم اوباطور","و كان اهل القلعة يصدون اسرائيل عن دخول المقادس ويحاولون الاضرار بهم من كل جانب وتوطيد الامم بينهم","فعزم يهوذا على الايقاع بهم وحشد جميع الشعب لمحاصرتهم","فاجتمعوا معا وحاصروهم سنة مئة وخمسين ونصب عليهم القذافات والمجانيق","فخرج بعض منهم من الحصار فانضم اليهم نفر منافقون من اسرائيل","و انطلقوا الى الملك وقالوا الى متى لا تجري القضاء ولا تنتقم لاخوتنا","انا ارتضينا بخدمة ابيك والعمل باوامره واتباع رسومه","و لذلك ابناء شعبنا يحاصرون القلعة بغضا لنا وكل من صادفوه منا قتلوه ونهبوا املاكنا","و لم يكتفوا بمد ايديهم علينا ولكنهم تجاوزا الى جميع تخومنا","و ها انهم قد زحفوا الى قلعة اورشليم ليستحوذوا عليها وعلى المقدس وحصنوا بيت صور","فالان ان لم تسرع وتبادرهم فسيصنعون شرا من ذلك فلا تقدر ان تكفهم","فلما سمع الملك غضب وجمع جميع اصحابه وقواد جيشه ورؤساء الفرسان","و جاءته من ممالك اخرى ومن جزائر البحار جنود مستاجرة","و كان عدد جيوشه مئة الف راجل وعشرين الف فارس واثنين وثلاثين فيلا مضراة على الحرب","فزحفوا مجتازين في ادوم ونزلوا عند بيت صور وحاربوا اياما كثيرة وصنعوا المجانيق فخرجوا واحرقوها بالنار وقاتلوا بباس","فسار يهوذا عن القلعة ونزل ببيت زكريا تجاه محلة الملك","فبكر الملك ووجه بباس جيشه الى طريق بيت زكريا فتاهبت الجيوش للقتال ونفخوا في الابواق","و اروا الفيلة عصير العنب والتوت حتى يهيجوها للقتال","ثم وزعوها على الفرق فجعلوا عند كل فيل الف رجل لابسين الدروع المسرودة وعلى رؤوسهم خوذ النحاس واقاموا لكل فيل خمسمئة فارس منتخبين","فكان اولئك حيثما وجد الفيل سبقوا اليه وحيثما ذهب ذهبوا معه لا يفارقونه","و كان على كل فيل برج حصين من الخشب يحميه مطوق بالمجانيق وعلى البرج اثنان وثلاثون رجلا من ذوي الباس يقاتلون منه والهندي يدير الفيل","و جعلوا سائر الفرسان من هنا وهناك على جانبي الجيش يحثونه ويكتنفونه في الشعاب","فلما لمعت الشمس على تروس الذهب والنحاس لمعت بها الجبال وتاججت كسرج من نار","و انتشر جيش الملك قسم على الجبال العالية وقسم في البطاح ومشوا بتحفظ وانتظام","فارتعد كل من سمع جلبتهم ودرجان جمهورهم وقعقعة سلاحهم فان الجيش كان عظيما وقويا جدا","فتقدم يهوذا وجيشه للمبارزة فسقط من جيش الملك ست مئة رجل","و راى العازار بن سواران واحدا من الفيلة عليه الدرع الملكية يفوق جميع الفيلة فظن ان عليه الملك","فبذل نفسه ليخلص شعبه ويقيم لنفسه اسما مخلدا","و عدا اليه مقتحما في وسط الفرقة يقتل يمنة ويسرة فتفرقوا عنه من هنا ومن هناك","و دخل بين قوائم الفيل حتى صار تحته وقتله فسقط عليه الى الارض فمات مكانه","و ان اليهود لما راوا سطوة الملك وبطش الجيوش ارتدوا عنهم","فصعد الملك بجيشه نحو اورشليم لملاقاتهم وزحف الى اليهودية وجبل صهيون","و عقد صلحا مع اهل بيت صور فخرجوا من المدينة لنفاد الطعام من عندهم مدة حصرهم فيها اذ كان سبت للارض","فاستولى الملك على بيت صور واقام هناك حرسا يحافظون عليها","و نزل عند المقدس اياما كثيرة ونصب هناك القذافات والمجانيق والات لرشق النار والحجارة وادوات لرمي السهام ومقاليع","و صنع اليهود مجانيق قبالة مجانيقهم وحاربوا اياما كثيرة","و لم يكن في اوعيتهم طعام لانها كانت السنة السابعة وكان الذين لجاوا الى اليهودية من الامم قد اكلوا ما فضل من الذخيرة","فلم يبق في المقادس الا نفر يسير لان الجوع غلب عليهم فتفرقوا كل واحد الى موضعه","و بلغ ليسياس ان فيلبس الذي اقامه انطيوكس في حياته ليرشح انطيوكس ابنه للملك","قد رجع من فارس وماداي ومعه جيوش الملك التي سارت في صحبته وانه يحاول ان يتولى الامور","فبادر وسعى الى الملك والقواد والجيش وقال لهم انا لنضعف يوما بعد يوم وقد قل طعامنا والمكان الذي نحاصره حصين وامور المملكة تستحثنا","و الان فلنعاقد هؤلاء الناس ولنبرم صلحا معهم ومع جميع امتهم","و لنقرر لهم ان يسلكوا في سننهم كما كانوا من قبل فانهم لاجل سننهم التي نقضناها غضبوا وفعلوا كل ذلك","فحسن الكلام في عيون الملك والرؤساء فارسل اليهم في المصالحة فاجابوا","فحلف لهم الملك والرؤساء وعلى ذلك خرجوا من الحصن","فدخل الملك الى جبل صهيون وراى الموضع حصينا فنقض الحلف الذي حلفه وامر بهدم السور الذي حوله","ثم انصرف مسرعا ورجع الى انطاكية فوجد فيلبس قد استولى على المدينة فقاتله واخذ المدينة عنوة"],["و في السنة المئة والحادية والخمسين خرج ديمتريوس بن سلوقس من رومية وصعد في نفر يسير الى مدينة بالساحل وملك هناك","و لما دخل دار ملك ابائه قبضت الجيوش على انطيوكس وليسياس لتاتيه بهما","فلما علم بذلك قال لا تروني اوجههما","فقتلتهما الجيوش وجلس ديمتريوس على عرش ملكه","فاتاه جميع رجال النفاق والكفر من اسرائيل وفي مقدمتهم الكيمس وهو يطمع ان يصير كاهنا اعظم","و وشوا على الشعب عند الملك قائلين ان يهوذا واخوته قد اهلكوا اصحابك وطردونا عن ارضنا","فالان ارسل رجلا تثق به يذهب ويفحص عن جميع ما انزله بنا وببلاد الملك من الدمار ويعاقبهم مع جميع اعوانهم","فاختار الملك بكيديس احد اصحاب الملك امير عبر النهر وكان عظيما في المملكة وامينا للملك وارسله","هو والكيمس الكافر وقد قلده الكهنوت وامره ان ينتقم من بني اسرائيل","فسارا وقدما ارض يهوذا في جيش كثيف وانفذا رسلا الى يهوذا واخوته يخاطبونهم بالسلام مكرا","فلم يلتفتوا الى كلامهما لانهم راوهما قادمين في جيش كثيف","و اجتمعت الى الكيمس وبكيديس جماعة الكتبة يسالون حقوقا","و وافى الحسيديون وهم المقدمون في بني اسرائيل يسالونهما السلم","لانهم قالوا ان مع جيوشه كاهنا من نسل هرون فلا يظلمنا","فخاطبهم خطاب سلام وحلف لهم قائلا انا لا نريد بكم ولا باصحابكم سوءا","فصدقوه فقبض على ستين رجلا منهم وقتلهم في يوم واحد كما هو مكتوب","جعلوا لحوم اصفيائك وسفكوا دماءهم حول اورشليم ولم يكن لهم من دافن","فوقع خوفهم ورعبهم على جميع الشعب لانهم قالوا ليس فيهم شيء من الحق والعدل اذ نكثوا العهد والحلف الذي حلفوه","و ارتحل بكيديس عن اورشليم ونزل ببيت زيت وارسل وقبض على كثيرين من الذين كانوا قد خذلوه وعلى بعض من الشعب وذبحهم علىالجب العظيم","ثم سلم البلاد الى الكيمس وابقى معه جيشا يؤازره وانصرف بكيديس الى الملك","و كان الكيمس يجهد في تولى الكهنوت الاعظم","و اجتمع اليه جميع المفسدين في الشعب واستولوا على ارض يهوذا وضربوا اسرائيل ضربة عظيمة","و راى يهوذا جميع الشر الذي صنعه الكيمس ومن معه في بني اسرائيل وكان فوق ما صنعت الامم","فخرج الى جميع حدود اليهودية مما حولها وانزل نقمته بالقوم الذين خذلوه فكفوا عن مهاجمة البلاد","فلما راى الكيمس ان قد تقوى يهوذا ومن معه وعلم انه لا يستطيع الثبات امامهم رجع الى الملك ووشى عليهم بجرائم","فارسل الملك نكانور احد رؤسائه المشهورين وكان عدوا مبغضا لاسرائيل وامره بابادة الشعب","فوفد نكانور على اورشليم في جيش كثير وارسل الى يهوذا واخوته يخاطبهم بالسلام مكرا","قائلا لا يكن قتال بيني وبينكم فانني قادم في نفر قليل لاواجهكم بسلام","و جاء الى يهوذا وحيا بعضهما بعضا تحية السلم وكان الاعداء مستعدين لاختطاف يهوذا","و علم يهوذا ان مواجهته كانت مكرا فاجفل منه وابي ان يعود الى مواجهته","فلما راى نكانور ان مشورته قد كشفت خرج لملاقاة يهوذا بالقتال عند كفر سلامة","فسقط من جيش نكانور نحو خمسة الاف رجل وفر الباقون الى مدينة داود","و بعد هذه الامور صعد نكانور الى جبل صهيون فخرج بعض الكهنة من المقادس وبعض شيوخ الشعب يحيونه تحية السلم ويرونه المحرقات المقربة عن الملك","فاستهزا بهم وسخر منهم وتقذرهم وكلمهم بتجبر","و اقسم بغضب قائلا ان لم يسلم يهوذا وجيشه الى يدي اليوم فسيكون متى عدت بسلام اني احرق هذا البيت وخرج بحنق شديد","فدخل الكهنة ووقفوا امام المذبح والهيكل وبكوا وقالوا","انك يا رب قد اخترت هذا البيت ليدعى فيه باسمك ويكون بيت صلاة وتضرع لشعبك","فانزل النقمة بهذا الرجل وجيشه وليسقطوا بالسيف واذكر تجاديفهم ولا تبق عليهم","ثم خرج نكانور من اورشليم ونزل ببيت حورون فانحاز اليه جيش سورية","و نزل يهوذا باداسة في ثلاثة الاف رجل وصلى يهوذا وقال","انه لما جدف الذين كانوا مع ملك اشور خرج ملاكك يا رب وضرب مئة الف وخمسة وثمانين الفا منهم","هكذا فاحطم هذا الجيش امامنا اليوم فيعلم الباقون انهم تكلموا على اقداسك سوءا واقض عليه بحسب خبثه","ثم الحم الجيشان القتال في اليوم الثالث عشر من شهر اذار فانكسر جيش نكانور وكان هو اول من سقط في القتال","فلما راى جيش نكانور انه قد سقط القوا اسلحتهم وهربوا","فتعقبوهم مسيرة يوم من اداسة الى مدخل جازر ونفخوا وراءهم في ابواق الاشارة","فخرج الناس من جميع قرى اليهودية من كل جانب وصدموهم فارتدوا الى جهة الذين يتعقبونهم فسقطوا جميعهم بالسيف ولم يبق منهم احد","فاخذوا الغنائم والاسلاب وقطعوا راس نكانور ويمينه التي مدها بتجبر واتوا بهما وعلقوهما قبالة اورشليم","ففرح الشعب جدا وقضوا ذلك النهار بمسرة عظيمة","و رسموا ان يعيد ذلك اليوم الثالث عشر من اذار كل سنة","و هدات ارض يهوذا اياما يسيرة"],["و سمع يهوذا باسم الرومانيين انهم ذوو اقتدار عظيم ويعزون كل من ضوى اليهم وكل من جاءهم اثروه بمودتهم ولهم شوكة شديدة","و قصت عليه وقائعهم وما ابدوا من الحماسة في قتال الغاليين وانهم اخضعوهم وضربوا عليهم الجزية","و ما فعلوا في بلاد اسبانية واستيلاؤهم على معادن الفضة والذهب التي هناك وانهم اخضعوا كل مكان بمشورتهم وطول اناتهم","و ان كان ذلك المكان عنهم بمسافة بعيدة وكسروا الذين اغاروا عليهم من الملوك من اقاصي الارض وضربوهم ضربة عظيمة وانسائر الملوك يحملون اليهم الجزية كل سنة","و قد قهروا فيلبس وفرساوس ملك كتيم في الحرب وكل من قاتلهم واخضعوهم","و كسروا انطيوكس الكبير ملك اسية الذي زحف لقتالهم ومعه مئة وعشرون فيلا وفرسان وعجلات وجيش كثير جدا","و قبضوا عليه حيا وضربوا عليه وعلى الذين يملكون بعده جزية عظيمة ورهائن ووضائع معلومة","و ان يتركوا بلاد الهند وماداي ولود وخيار بلادهم واخذوها منه واعطوها لاومينيس الملك","و لما هم اليونان ان يسيروا لمقاتلتهم بلغهم ذلك","فارسلوا اليهم قائدا واحدا وحاربوهم فسقط منهم قتلى كثيرون وسبوا نساءهم واولادهم ونهبوهم واستولوا على ارضهم وهدموا حصونهم واستعبدوهم الى هذا اليوم","و دمروا سائر الممالك والجزائر التي قاومتهم واستعبدوا سكانها","و انهم حفظوا المودة لاوليائهم والذين اعتمدوا عليهم وتسلطوا على الممالك قريبها وبعيدها وكل من سمع باسمهم خافهم","و من ارادوا مؤازرته وتمليكه ملكوه ومن ارادوا خلعه خلعوه فعلا شانهم جدا","و مع ذلك كله لم يلبس احد منهم التاج ولا تردى الارجوان مباهاة به","و انما وضعوا لهم شورى ياتمر فيها كل يوم ثلاث مئة وعشرون رجلا لاصلاح شؤونهم","و هم يفوضون سلطانهم وسياسة ارضهم بجملتها كل سنة الى رجل واحد وجميعهم يطيعون هذا الواحد وليس فيهم حسد ولا منافسة","فاختار يهوذا اوبولمس بن يوحنا بن اكوس وياسون بن العازار وارسلهما الى رومية ليعقدا معهم عهد الموالاة والمناصرة","و يرفعا عنهم النير لانهم راوا ان دولة اليونان قد استعبدت اسرائيل استعبادا","فانطلقا الى رومية في سفر بعيد جدا ودخلا الشورى وتكلما وقالا","انا مرسلان اليكم من قبل يهوذا المكابي واخوته وجمهور اليهود لنعقد معكم عهد المناصرة والمسالمة وان تثبتونا في جملة مناصريكم واوليائكم","فحسن الكلام لديهم","و هذه نسخة الكتاب الذي دونوه على الواح من نحاس وارسلوه الى اورشليم حتى يكون عندهم تذكار للمسالمة والمناصرة","الفلاح للرومانيين ولامة اليهود في البحر والبر الى الابد وليبعد عنهم السيف والعدو","اذا قامت حرب في رومية اولا او عند اي كان من مناصريهم في جميع سلطانهم","فامة اليهود تناصر بكل عزمها كما تقتضيه الحال","و ليس على الرومانيين ان يؤدوا الى المحاربين معهم او يجهروا لهم طعاما ولا اسلحة ولا فضة ولا سفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر الرومانيين بغير ان ياخذوا شيئا","و كذلك امة اليهود اذا حدثت لها حرب اولا فالرومانيون ينتدبون للمناصرة كما تقتضيه الحال","و ليس على اليهود ان يؤدوا الى المناصرين طعاما ولا اسلحة ولا فضة ولاسفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر اليهود دون غش","على هذا الكلام عاهد الرومانيون شعب اليهود","و اذا شاء هؤلاء او اولئك ان يزيدوا على هذا الكلام او يسقطوا منه فيفعلون برضى الفريقين وكل ما زادوا او اسقطوا يكون مقررا","اما الشرور التي انزلها بهم الملك ديمتريوس فقد كتبنا اليه قائلين لم ثقلت النير على اوليائنا ومناصرينا اليهود","فان عادوا يتظلمون منك فسنجري لهم الحكم ونقاتلك بحرا وبرا"],["و لما سمع ديمتريوس بان نكانور وجيوشه قد سقطوا في الحرب عاد ثانية فارسل الى ارض يهوذا بكيديس والكيمس ومعهما الجناح الايمن","فانطلقا في طريق الجلجال ونزلا عند مشالوت باربيل فاستولى عليها واهلكا نفوسا كثيرة","و في الشهر الاول من السنة المئة والثانية والخمسين نزلا على اورشليم","ثم زحفا وانطلقا الى بئروت في عشرين الف راجل والفي فارس","و كان يهوذا قد نزل بلاشع ومعه ثلاثة الاف رجل منتخبين","فلما راوا كثرة عدد الجيوش خافوا خوفا شديدا فجعل كثيرون ينسابون من المحلة ولم يبق منهم الا ثماني مئة رجل","فلما راى يهوذا ان جيشه قد انساب والحرب تضايقه انكسر قلبه لانه لم يبق له وقت لردهم واسترخت عزائمه","فقال لمن بقي معه لنقم ونهجم على مناصبينا عسى ان نقدر على مدافعتهم","فصرفوه عن عزمه قائلين انه ليس في طاقاتنا اليوم الا ان ننجو بنفوسنا ثم نرجع مع اخواتنا ونقاتلهم فانا عدد قليل","فقال يهوذا حاش لي ان افعل مثل ذلك واهرب منهم وان كان قد دنا اجلنا فلنموتن بشجاعة عن اخواتنا ولا نبقين على مجدنا وصمة","و برز جيش العدو من المحلة ووقفوا بازائهم وانقسمت الفرسان قسمين وكان الرماة بالمقاليع والقسي يتقدمون الجيش كلها من ذوي الباس","و كان بكيديس في الجناح الايمن فازدلفت الفرقة من الجانبين وهتفوا بالابواق","و نفخ رجال يهوذا ايضا في الابواق فارتجت الارض من جلبة العسكرين والتحم القتال من الصبح الى المساء","و راى يهوذا ان بكيديس وقوة الجيش في الجناح الايمن فقصدهم ومعه كل ذي قلب ثابت","فكسروا الجناح الايمن وتعقبوا اثرهم الى جبل اشدود","فلما راى رجال الجناح الايسر انكسار الجناح الايمن انقلبوا على اثار يهوذا ومن معه","فاشتد القتال وسقط قتلى كثيرون من الفريقين","و سقط يهوذا وهرب الباقون","فحمل يوناتان وسمعان يهوذا اخاهما ودفناه في قبر ابائه في مودين","فبكاه شعب اسرائيل بكاء عظيما ولطموا عليه وناحوا اياما وقالوا","كيف سقط البطل مخلص اسرائيل","و بقية اخبار يهوذا وحروبه وما ابداه من الحماسة وجبروته لم تكتب في هذا الموضع لانها كثيرة جدا","و كان بعد وفاة يهوذا ان المنافقين برزوا في جميع تخوم اسرائيل وظهر كل فاعلي الاثم","و في تلك الايام حدثت مجاعة عظيمة جدا فتخاذلت البلاد اليهم","فاختار بكيديس الكفرة منهم واقامهم رؤساء على البلاد","فكانوا يتطلبون اصحاب يهوذا ويتفقدونهم وياتون بهم الى بكيديس فينتقم منهم ويستهزئ بهم","فحل باسرائيل ضيق عظيم لم يحدث مثله منذ لم يظهر فيهم نبي","فاجتمع جميع اصحاب يهوذا وقالوا ليوناتان","انه منذ وفاة يهوذا اخيك لم يقم له كفؤ يخرج على العدو وعلى بكيديس والمبغضين لامتنا","فنحن نختارك اليوم رئيسا لنا وقائدا مكانه تحارب حربنا","فقبل يوناتان القيادة في ذلك الوقت وقام في موضع يهوذا اخيه","فلما علم بكيديس طلب قتله","و بلغ ذلك يوناتان وسمعان اخاه وجميع من معه فهربوا الى برية تقوع ونزلوا على ماء جب اسفار","فعلم بكيديس فزحف بجميع جيشه الى عبر الاردن يوم سبت","و ارسل يوناتان يوحنا اخاه بجماعة تحت قيادته يسال النباطيين اولياءه ان يعيروهم عدتهم الوافرة","فخرج بنو يمري من ميدابا وقبضوا على يوحنا وكل ما معه وذهبوا بالجميع","و بعد هذه الامور اخبر يوناتان وسمعان اخوه ان بني يمري يقيمون عرسا عظيما ويزفون العروس من ميدابا باحتفال عظيم وهيابنة بعض عظماء كنعان","فذكروا يوحنا اخاهم وصعدوا واختباوا وراء الجبل","ثم رفعوا ابصارهم ونظروا فاذا بجلبة وجهاز كثير والعروس واصحابه واخوته خارجون للقائهم بالدفوف والات الطرب واسلحة كثيرة","فثار عليهم رجال يوناتان من المكمن وضربوهم فسقط قتلى كثيرون وهرب الباقون الى الجبل فاخذوا كل اسلابهم","و تحول العرس الى مناحة وصوت الات طربهم الى نحيب","و لما انتقموا لدم اخيهم رجعوا الى غيضة الاردن","فسمع بكيديس فوفد الى شطوط الاردن يوم سبت في جيش عظيم","فقال يوناتان لمن معه لننهض الان ونقاتل عن نفوسنا فليس الامر اليوم كما كان امس فما قبل","ها ان الحرب امامنا وخلفنا وماء الاردن والغياض والغاب من هنا ومن هناك فليس لنا مناص","و الان فاصرخوا الى السماء فتنقذوا من ايدي اعدائكم ثم التحم القتال","و مد يوناتان يده ليضرب بكيديس فانصاع عنه الى الوراء","فرمى يوناتان ومن معه بانفسهم في الاردن وعاموا الى العبر فلم يعبروا الاردن اليهم","و سقط من رجال بكيديس في ذلك اليوم الف رجل فعاد الى اورشليم","ثم بنى مدائن حصينة في اليهودية وحصن اريحا وعماوس وبيت حورون وبيت ايل وتمنة وفرعتون وتفون باسوار عالية وابواب ومزاليج","و جعل فيها حرسا يراغمون اسرائيل","و حصن مدينة صور وجازر والقلعة وجعل فيها جيوشا وميرة","و اخذ ابناء قواد البلاد رهائن وجعلهم في القلعة باورشليم في الحبس","و في السنة الثالثة والخمسين في الشهر الثاني امر الكيمس ان يهدم حائط دار المقدس الداخلية فهدم اعمال الانبياء وشرع في التدمير","في ذلك الزمان ضرب الكيمس فكف عن صنيعه واعتقل لسانه وفلج ولم يعد يستطيع ان ينطق بكلمة ولا ان يوصي لبنيه","و مات الكيمس في ذلك الزمان في عذاب شديد","فلما راى بكيديس ان الكيمس قد مات رجع الى الملك وهدات ارض يهوذا سنتين","و بعد ائتمر المنافقون كلهم وقالوا ها ان يوناتان والذين معه في منازلهم هادئون مطمئنون فهلموا الان نحمل عليهم بكيديس فيقبض عليهم اجمعين في ليلة واحدة","و انطلقوا واشاروا عليه بذلك","فقام وسار في جيش عظيم وبعث سرا يكتب الى جميع نصرائه في اليهودية ان يقبضوا على يوناتان والذين معه فلم يجدوا الى ذلك سبيلا لان مشورتهم انكشفت لهم","ثم قبضوا على خمسين رجلا من البلاد وهم ارباب الفتنة وقتلوهم","و انصرف يوناتان وسمعان ومن معهما الى بيت حجلة في البرية وبنى مهدومها وحصنها","و لما علم بكيديس حشد جميع جمهوره وراسل حلفاءه في اليهودية","و زحف ونزل على بيت حجلة وحاربها اياما كثيرة ونصب المجانيق","و ان يوناتان ترك سمعان اخاه في المدينة وخرج في عدد من الجند وانتشر في البلاد","و ضرب ادورين واخوته وبني فاسرون في خيامهم وطفق يوقع بالعدو ويزداد قوة","و خرج سمعان ومن معه من المدينة واحرقوا المجانيق","و قاتلوا بكيديس فانكسر وضايقوه جدا واذ ذهبت مشورته وخروجه في الباطل","استشاط غضبا على الرجال المنافقين الذين اشاروا عليه بالخروج من البلاد وقتل كثيرين منهم وازمع الانصراف الى ارضه","و علم يوناتان فانفذ اليه رسلا في عقد المصالحة ورد الاسرى","فاجاب وفعل بحسب كلامه وحلف له انه لن يطلبه بسوء كل ايام حياته","و رد اليه الاسرى الذين اسرهم من قبل في ارض يهوذا ثم عاد الى ارضه ولم يعد يسير الى تخومهم","فزال السيف من اسرائيل وسكن يوناتان في مكماش واخذ يوناتان يحاكم الشعب واستاصل المنافقين من اسرائيل"],["و في السنة المئة والستين صعد الاسكندر الشهير ابن انطيوكس وفتح بطلمايس فقبلوه فملك هناك","فسمع ديمتريوس الملك فجمع جيوشا كثيرة جدا وخرج لملاقاته في الحرب","و انفذ ديمتريوس الى يوناتان كتبا في معنى السلم متقربا اليه بالاطراء","لانه قال لنسبق الى مسالمته قبل ان يسالم الاسكندر علينا","فانه سيذكر كل ما انزلنا به وباخوته وامته من المساوئ","و اذن له ان يجمع جيوشا ويتجهز بالاسلحة ويكون مناصرا له وامر له برد الرهائن الذين في القلعة","فجاء يوناتان الى اورشليم وتلا الكتب على مسامع الشعب كله واهل القلعة","فلما سمع ان الملك اذن له في جمع الجيوش جزعوا جزعا شديدا","و رد اهل القلعة الرهائن الى يوناتان فردهم الى ذوي قرابتهم","و اقام يوناتان باورشليم وطفق يبني ويجدد المدينة","و امر صناع العمل ان يبنوا الاسوار حول جبل صهيون بحجارة منحوتة للتحصين ففعلوا","فهرب الغرباء الذين في الحصون التي بناها بكيديس","و ترك كل واحد مكانه وذهب الى ارضه","غير انه بقي في بيت صور قوم من المرتدين عن الشريعة والرسوم فانها كانت ملجا لهم","و سمع الاسكندر الملك بالمواعيد التي عرضها ديمتريوس على يوناتان وحدث بما صنع هو واخوته من الحروب واعمال الباس وما كابدوه من النصب","فقال انا لا نجد من رجل يماثله فلنتخذه لنا وليا ومناصرا","و كتب كتبا وبعث اليه بها في هذا المعنى قائلا","من الملك الاسكندر الى اخيه يوناتان سلام","لقد بلغنا عنك انك رجل شديد الجبروت وخليق بان تكون لنا وليا","فنحن نقيمك اليوم كاهنا اعظم في امتك وتسمى ولي الملك وتهتم بما لنا وتبقى في مودتنا وارسل اليه ارجوانا وتاجا من ذهب","فلبس يوناتان الحلة المقدسة في الشهر السابع من السنة المئة والستين في عيد المظال وجمع الجيوش وتجهز باسلحة كثيرة","و ذكر ذلك لديمتريوس فشق عليه وقال","كيف تركنا الاسكندر يسبقنا الى مصافاة اليهود والتعزز بهم","فاكتب انا ايضا اليهم بكلام ملاطفة وتعظيم واعدهم بعطايا ليكونوا من مناصري","و كاتبهم بقوله من الملك ديمتريوس الى امة اليهود سلام","لقد بلغنا انكم محافظون على عهودكم لنا ثابتون في مودتنا ولم تتقربوا الى اعدائنا فسرنا ذلك","فاثبتوا في المحافظة على وفائكم لنا فنحسن ثوابكم على ما تفعلون في حقنا","و نحط عنكم كثيرا مما لنا عليكم ونصلكم بالعطايا","و الان فاني اعفيكم واحط عن جميع اليهود كل جزية ومكس الملح والاكاليل وثلث الزرع","و نصف اتاء الشجر الذي يحق لي اخذه اعفيكم من هذه الاشياء من اليوم فصاعد في ارض يهوذا وفي المدن الثلاث الملحقة بها من ارض السامرة والجليل من هذا اليوم على طول الزمان","و لتكن اورشليم مقدسة وحرة هي وتخومها واحط عنها العشور والضرائب","و اتخلى عن القلعة التي باورشليم واعطيها للكاهن الاعظم يقيم فيها من يختاره من الرجال لحراستها","و جميع النفوس التي سبيت من اليهود من ارض يهوذا في مملكتي باسرها اطلقها حرة بلا ثمن وليكن الجميع معفين من اتاوة المواشي","و لتكن الاعياد كلها والسبوت ورؤوس الشهور والايام المخصصة والايام الثلاثة التي قبل العيد والايام الثلاثة التي بعد العيد ايام ابراء وعفو لجميع اليهود الذين في مملكتي","فلا يكون لاحد ان يرافع احدا منهم او يثقل عليه في اي امر كان","و ليكتتب من اليهود في جيوش الملك الى ثلاثين الف رجل تعطى لهم وظائف كما يحق لسائر جنود الملك","فيجعل منهم في حصون الملك العظيمة ويفوض الى البعض منهم النظر في مهام المملكة التي تقتضي الامانة ورؤساؤهم ومدبروهم يكونون من جملتهم ويسلكون بحسب سننهم كما امر الملك لارض يهوذا","و اما المدن الثلاث الملحقة باليهودية من بلاد السامرة فلتبق ملحقة باليهودية فتكون معها خاضعة لواحد ولا تطيع سلطانا اخر الا سلطان الكاهن الاعظم","و قد وهبت بطلمايس وما يتبعها للمقدس الذي باورشليم لاجل نفقة الاقداس","و زدت عليها خمسة عشر الف مثقال فضة كل سنة من دخل الملك من الاماكن التي تختص به","و كل ما بقي مما لم يدفعه وكلاء المال عن السنين السالفة يؤدونه من الان لاعمال البيت","و ما عدا ذلك فخمسة الاف مثقال الفضة التي كانت تؤخذ من دخل المقدس في كل سنة تترك رزقا للكهنة القائمين بالخدمة","و اي من لاذ بالمقدس في اورشليم في جميع حدوده وللملك عليه مال او اي حق كان فليعف وليبق له كل ما ملك في مملكتي","و نفقة البناء واعمال الترميم في المقادس تعطى من حساب الملك","و بناء اسوار اورشليم وتحصينها على محيطها وبناء الاسوار في سائر اليهودية تعطى نفقته من حساب الملك","فلما سمع يوناتان والشعب هذا الكلام لم يثقوا به ولا قبلوه لانهم تذكروا ما انزله ديمتريوس باسرائيل من الشر العظيم والضغط الشديد","فاثروا الاسكندر لانه بداهم بكلام السلام وبقوا على مناصرته كل الايام","و جمع الاسكندر الملك جيوشا عظيمة نزل تجاه ديمتريوس","فانتشب القتال بين الملكين فانهزم جيش ديمتريوس فتعقبه الاسكندر وهجم عليهم","و اشتد القتال جدا الى ان غابت الشمس وسقط ديمتريوس في ذلك اليوم","ثم بعث الاسكندر رسلا الى بطلماوس ملك مصر بهذا الكلام قائلا","اذ قد رجعت الى ارض مملكتي وجلست على عرش ابائي واستتب لي السلطان وكسرت ديمتريوس واستوليت على بلادنا","اذ الحمت عليه القتال فانكسر امامنا هو وجيشه وجلست على عرش ملكه","فهلم الان نوال بعضنا بعضا وهب لي ابنتك زوجة فاصاهرك واهدي اليك هدايا تليق بك","فاجاب بطلماوس الملك قائلا ما اسعد اليوم الذي رجعت فيه الى ارض ابائك وجلست على عرش ملكهم","و اني صانع ما كتبت الى به فهلم الى بطلمايس فنتواجه واصاهرك كما قلت","و خرج بطلماوس من مصر هو وكلوبطرة ابنته ودخلا بطلمايس في السنة المئة والثانية والستين","فلاقاه الاسكندر الملك فاعطاه كلوبطرة ابنته واقام عرسها في بطلمايس على عادة الملوك باحتفال عظيم","و كتب الاسكندر الملك الى يوناتان ان يقدم لملاقاته","فانطلق الى بطلمايس في موكب مجيد ولقى الملكين واهدى لهما ولاصحابهما فضة وذهبا وهدايا كثيرة فنال حظوة لديهما","و اجتمع عليه رجال مفسدون من اسرائيل رجال منافقون ووشوا به فلم يصغ الملك اليهم","و امر الملك ان ينزعوا ثياب يوناتان ويلبسوه ارجوانا ففعلوا واجلسه الملك بجانبه","و قال لعظمائه اخرجوا معه الى وسط المدينة ونادوا ان لا يتعرض له احد في امر من الامور ولا يسوءه بشيء من المكروه","فلما راى الذين وشوا به ما هو فيه من المجد وكيف نودي له والبس الارجون هربوا جميعهم","و اعزه الملك وجعله من اصدقائه الخواص واقامه قائدا وشريكا في الملك","فعاد يوناتان الى اورشليم سالما مسرورا","و في السنة المئة والخامسة والستين جاء ديمتريوس بن ديمتريوس الى ارض ابائه","فسمع بذلك الاسكندر الملك فاغتم جدا ورجع الى انطاكية","و فوض ديمتريوس قيادة الجيش الى ابلونيوس والى بقاع سورية فحشد جيشا عظيما ونزل بيمنيا وراسل يوناتان الكاهن الاعظم قائلا","انه ليس لنا من مقاوم الا انت وبسببك قد اصبحت عرضة للسخرية والتعيير فعلام انت تناهضنا في الجبال","فالان ان كنت واثقا بجيوشك فانزل الينا في السهل فنتبارز هناك فان معي قوة الامصار","سل واعلم من انا ومن الذين يؤازرونني فانه يقال انكم لا تستطيعون الثبات امامنا لان ابائك قد انكسروا في ارضهم مرتين","فلست تطيق الثبات امام الفرسان وجيش في كثرة جيشي في سهل لا حجر فيه ولا حصاة ولا ملجا تهربون اليه","فلما سمع يوناتان كلام ابلونيوس اضطرب غيظا واختار عشرة الاف رجل وخرج من اورشليم ولحق به سمعان اخوه لمظاهرته","و نزل تجاه يافا فاغلقوا في وجهه ابواب المدينة لان حرس ابلونيوس كان فيها فحاصرها","فخاف الذين في المدينة وفتحوا له فاستولى يوناتان على يافا","و سمع ابلونيوس فتقدم في ثلاثة الاف فارس وجيش كثير","و سار نحو اشدود كانه عابر سبيل ثم عطف بغتة الى السهل اذ كان معه كثيرون من الفرسان الذين يعتمد عليهم فتعقبه يوناتان الى اشدود والتحم القتال بين الفريقين","و كان ابلونيوس قد خلف الف فارس وراءهم في خفية","الا ان يوناتان كان عالما ان وراءه كمينا ولم يلبثوا ان احدقوا بجيشه يرمون الشعب بالسهام من الصبح الى المساء","اما الشعب فبقي في مواقفه كما امر يوناتان حتى اعيت خيل اولئك","حينئذ برز سمعان بجيشه والحم القتال على الفرقة لان الخيل كانت قد وهنت فكسرهم فهربوا","و تبددت الخيل في السهل وفروا الى اشدود ودخلوا بيت داجون معبد صنمهم لينجوا بنفوسهم","فاحرق يوناتان اشدود والمدن التي حولها وسلب غنائمهم واحرق هيكل داجون والذين انهزموا اليه بالنار","و كان الذين قتلوا بالسيف مع الذين احرقوا ثمانية الاف رجل","ثم سار يوناتان من هناك ونزل تجاه اشقلون فخرج اهل المدينة للقائه باجلال عظيم","و رجع يوناتان بمن معه الى اورشليم ومعهم غنائم كثيرة","و لمل سمع الاسكندر الملك بهذه الحوادث زاد يوناتان مجدا","و بعث اليه بعروة من ذهب كما كان يعطى لانسباء الملوك ووهب له عقرون وتخومها ملكا"],["و جمع ملك مصر جيوشا كثيرة كالرمل الذي على ساحل البحر وسفنا عديدة وحاول الاستيلاء على مملكة الاسكندر بالمكر والحاقها بمملكته","فقدم سورية متظاهرا بالسلم ففتح له اهل المدن ولاقوه اذ كان الاسكندر الملك قد امر بلقائه لانه صهره","و كان بطلماوس عند دخوله المدن يبقي في كل مدينة حرسا من الجند","و لما وصل الى اشدود اروه هيكل داجون المحرق واشدود وضواحيها المهدومة والجثث المطروحة والذين كان يوناتان قد احرقهم في الحرب وكانوا قد جعلوا رجامهم على طريقه","و حدثوا الملك بما فعل يوناتان يريدون تجرمه فسكت الملك","و لاقى يوناتان الملك في يافا باجلال وسلم بعضهما على بعض وناما هناك","ثم شيع يوناتان الملك الى النهر الذي يقال له الوتارس ورجع الى اورشليم","فاستحوذ الملك بطلماوس على مدن الساحل الى سلوكية الساحلية وكان مضمرا للاسكندر السوء","ثم انفذ رسلا الى ديمتريوس الملك قائلا هلم فنعقد عقدا بيني وبينك واهب لك بنتي التي عند الاسكندر وتملك ملك ابيك","فاني قد ندمت على عطائي ابنتي له لانه رام قتلي","و تجنى عليه طمعا في ملكه","ثم استرد ابنته واعطاها لديمتريوس وتغير على الاسكندر وظهرت عداوتهما","ثم ان بطلماوس دخل انطاكية ووضع على راسه تاجين تاج اسية وتاج مصر","و كان الاسكندر الملك اذ ذاك في كيليكية لان اهل تلك البلاد كانوا قد تمردوا","فلما سمع الاسكندر قدم لمقاتلته فاخرج بطلماوس جيشه ولاقاه بعسكر شديد فكسره","فهرب الاسكندر الى ديار العرب مستجيرا بهم وعظم امر بطلماوس الملك","فقطع زبديئيل العربي راس الاسكندر وبعث به الى بطلماوس","و في اليوم الثالث مات بطلماوس الملك فاهلك رجال الجند الحراس الذين في الحصون","و ملك ديمتريوس في السنة المئة والسابعة والستين","في تلك الايام جمع يوناتان رجال اليهودية لفتح القلعة التي باورشليم ونصب عليها مجانيق كثيرة","فانطلق قوم من مبغضي امتهم من الرجال المنافقين الى الملك واخبروه بان يوناتان يحاصر القلعة","فلما سمع استشاط غضبا وسار من ساعته قاصدا بطلمايس وكتب الى يوناتان ان يكف عن محاصرة القلعة وان يبادر الى ملاقاته في بطلمايس للمواجهة","فلما بلغ ذلك يوناتان امر بان يستمروا على الحصار واختار بعضا من شيوخ اسرائيل والكهنة وخاطر بنفسه","و اخذ من الفضة والذهب والحلل وسائر الهدايا شيئا كثيرا وانطلق الى الملك في بطلمايس فنال حظوة لديه","و وشى به قوم من الامة من اهل النفاق","الا ان الملك عامله كما كان اسلافه يعاملونه وعظمه لدى اصحابه جميعا","و اقره في الكهنوت الاعظم وفي كل ما كان له من الاختصاصات وجعله من اول اصدقائه","و سال يوناتان الملك ان يعفي اليهودية والمدن الثلاث وارض السامرة من كل جزية ووعده بثلاث مئة قنطار","فارتضى الملك وكتب ليوناتان كتبا في ذلك كله وهذه صورتها","من ديمتريوس الملك الى يوناتان اخيه وامة اليهود سلام","نسخة الكتاب الذي كتبناه في حقكم الى لسطانيس قريبنا كتبنا بها اليكم لتقفوا على مضمونها","من ديمتريوس الملك الى لسطانيس ابيه سلام","لقد راينا ان نحسن الى امة اليهود اوليائنا المحافظين على ما يحق لنا وفاء بما سبق من برهم لنا","فجعلنا لهم تخوم اليهودية والمدن الثلاث وهي افيرمة ولدة والرامتائيم التي الحقت باليهودية من ارض السامرة وجميع توابعها فتكون لجميع الذين يذبحون في اورشليم بدل الضرائب الملكية التي كان الملك يستخرجها منهم قبلا في كل سنة من اتاء الارض وثمر الاشجار","و سائر ما يحق لنا من العشور والوضائع ووهاد الملح والاكاليل","هذا كله قد انعمنا عليهم به تبرعا ومن الان لا يلغى شيء من هذا الانعام ما طال الزمان","فالان اكتبوا نسخة من هذا الرسم ولتسلم الى يوناتان ولتوضع في الجبل المقدس في موضع مشهود","و راى ديمتريوس الملك ان الارض قد اطمانت لديه لا ينازعه منازع فسرح جميع جيوشه كل واحد الى موضعه ما خلا الجنود الغرباء الذين جاء بهم من جزائر الامم فمقته جيوش ابائه كلهم","و كان تريفون من احزاب الاسكندر قبلا فلما راى ان الجيوش جميعها تتذمر على ديمتريوس انطلق الى ايملكوئيل العربي وكان يربي انطيوكس بن الاسكندر","فالح عليه ان يسلمه اليه لكي يملك مكان ابيه واخبره بما فعل ديمتريوس وبما له في الجيوش من العداوة ومكث هناك اياما كثيرة","و ارسل يوناتان الى ديمتريوس الملك ان يخرج الجنود الذين في القلعة من اورشليم والذين في الحصون لانهم كانوا يحاربون اسرائيل","فارسل ديمتريوس الى يوناتان قائلا سافعل ذلك لك ولامتك بل ساعظمك انت وامتك تعظيما متى وافقتني فرصة","و الان فانك تحسن الصنيع اذا ارسلت الى رجالا يكونون في نجدتي فاني قد خذلتني جيوشي كلها","فوجه يوناتان ثلاث الاف رجل اشداء الباس الى انطاكية فوافوا الملك ففرح الملك بقدومهم","و اجتمع اهل المدينة في وسط المدينة وكانوا مئة وعشرين الف رجل يحاولون قتل الملك","فهرب الملك الى داره فاستولى اهل المدينة على طرق المدينة وشرعوا في القتال","فدعا الملك اليهود لنجدته فاجتمعوا اليه كلهم ثم تفرقوا بجملتهم في المدينة فقتلوا فى المدينة في ذلك اليوم مئة الف رجل","و احرقوا المدينة واخذوا غنائم كثيرة في ذلك اليوم وخلصوا الملك","فلما راى اهل المدينة ان اليهود قد استولوا على المدينة يفعلون ما شاءوا انخلعت قلوبهم وصرخوا الى الملك متضرعين وقالوا","عاقدنا وليكف اليهود عن الايقاع بنا وبالمدينة","فالقوا السلاح وعقدوا المصالحة فعظم امر اليهود عند الملك وعند جميع اهل مملكته ثم رجعوا الى اورشليم بغنائم كثيرة","و جلس ديمتريوس الملك على عرش ملكه وهدات الارض امامه","فاخلف في جميع ما وعد وتغير على يوناتان وكافاه بخلاف ما صنع اليه من المعروف وضيق عليه جدا","و بعد ذلك رجع تريفون ومعه انطيوكس وهو غلام صغير فملك انطيوكس ولبس التاج","فاجتمع اليه جميع الجيوش التي سرحها ديمتريوس وقاتلوا ديمتريوس ففر منهم منهزما","فاستولى تريفون على الفيلة ثم فتح انطاكية","و كتب انطيوكس الصغير الى يوناتان قائلا اني اقرك في الكهنوت الاعظم واقيمك على المدن الاربع واتخذك من اصدقاءالملك","و ارسل اليه انية من الذهب لخدمته واباح له ان يشرب في الذهب ويلبس الارجوان بعروة الذهب","و اقام سمعان اخاه قائدا من عقبة صور الى حدود مصر","و خرج يوناتان وطاف في عبر النهر وفي المدن فاجتمعت لمظاهرته جميع جيوش سورية وقدم اشقلون فلاقاه اهل المدينة باحتفال","و انصرف من هناك الى غزة فاغلق اهل غزة الابواب في وجهه فحاصرها واحرق ضواحيها بالنار ونهبها","فسال اهل غزة يوناتان الامان فعاقدهم واخذ ابناء رؤسائهم رهائن وارسلهم الى اورشليم ثم جال في البلاد الى دمشق","و سمع يوناتان ان قواد ديمتريوس قد بلغوا الى قادش الجليل في جيش كثيف يريدون ان يعزلوه عن الولاية","فزحف لملاقاتهم وخلف سمعان اخاه في البلاد","فحاصر سمعان بيت صور وحاربها اياما كثيرة واحاط بها","فسالوه المعاقدة فعاقدهم واخرجهم من هناك وفتح المدينة واقام فيها حرسا","و اما يوناتان وجيشه فنزلوا على ماء جناسر وقبل الفجر زحفوا الى سهل حاصور","فاذا بجيش الاجانب يلاقيهم في السهل وقد اقاموا عليهم كمينا في الجبال فبينما هم يتقدمون تجاههم","ثار الكمين من مواضعهم والحموا القتال","ففر رجال يوناتان جميعا ولم يبق منهم احد الا متتيا ابن ابشالوم ويهوذا بن حلفي قائدا الجيوش","فمزق يوناتان ثيابه وحثا التراب على راسه وصلى","ثم عاد اليهم يقاتلهم فانهزموا وهربوا","و لما راى ذلك الذين هربوا من رجاله رجعوا وتعقبوا العدو معه الى قادش الى معسكرهم ونزلوا هناك","فسقط من الاجانب في ذلك اليوم ثلاثة الف رجل ورجع يوناتان الى اورشليم"],["و راى يوناتان ان له فرصة ملائمة فاختار رجالا وسيرهم الى رومية ليقروا الموالاة بينهم ويجددوها","و ارسل معهم الى اسبرطة واماكن اخرى كتبا في هذا المعنى","فانطلقوا الى رومية ودخلوا الشورى وقالوا انا مرسلون من قبل يوناتان الكاهن الاعظم وامة اليهود لنجدد ما بينكم وبينهم من الموالاة والمناصرة كما كان من قبل","فاعطوهم كتبا للعمال في الاقاليم حتى يبلغوهم ارض يهوذا بسلام","و هذه نسخة الكتب التي كتبها يوناتان الى اهل اسبرطة","من يوناتان الكاهن الاعظم وشيوخ الامة ومن الكهنة وسائر شعب اليهود الى اهل اسبرطة اخوتهم سلام","ان اريوس المالك فيكم كان قديما قد انفذ كتبا الى اونيا الكاهن الاعظم يشهد انكم اخوتنا على ما هو في نسختها","فتلقى اونيا الرسول باكرام واخذ الكتب المصرح فيها بالمناصرة والموالاة","فنحن وان لم تكن بنا حاجة الى ذلك بما لنا من التعزية في الاسفار المقدسة التي في ايدينا","قد اثرنا مراسلتكم لنجدد الاخاء والموالاة لئلا نعد من الاجانب عندكم اذ قد مضى على مكاتبتكم لنا زمان مديد","و انا في كل حين في الاعياد وسائر الايام المفروضة لا نزال نذكركم في الذبائح التي نقدمها وفي الصلوات كما ينبغي ويليقان يذكر الاخوة","و يسرنا ما انتم عليه من الاعتزاز","اما نحن فقد احاطت بنا مضايق كثيرة وحروب عديدة وقاتلنا الملوك الذين من حولنا","لكنا كرهنا ان نثقل عليكم وعلى سائر مناصرينا واوليائنا في تلك الحروب","فان لنا من السماء مددا يمدنا وقد تخلصنا من اعدائنا واذللناهم","و الان فقد اخترنا نومانيوس بن انطيوكس وانتيباتير بن ياسون وارسلناهما الى الرومانيين لنجدد ما كان بيننا قبلا من الموالاة والمناصرة","و امرناهما بان يقدما اليكم ويقرئاكم السلام ويسلما اليكم الكتب من قبلنا في تجديد اخائنا","و لكم جميل الصنع ان اجبتمونا الى ذلك","و هذه نسخة الكتب التي ارسلها الى اونيا","من اريوس ملك الاسبرطيين الى اونيا الكاهن الاعظم سلام","و بعد فقد وجد في بعض الكتب ان الاسبرطيين واليهود اخوة من نسل ابراهيم","و اذ قد علمنا ذلك فلكم جميل الصنع ان راسلتمونا فيما انتم عليه من السلام","و الان فان جوابنا اليكم ان مواشيكم واملاككم هي لنا وان ما لنا هو لكم هذا ما اوصينا بان تبلغوه","و بلغ يوناتان ان قواد ديمتريوس قد عادوا لمحاربته بجيش يزيد على جيشه الاول","فخرج من اورشليم ووافاهم في ارض حماة ولم يمهلهم ان يطاوا ارضه","ثم ارسل جواسيس الى محلتهم فرجعوا واخبروه انهم مزمعون ان يهجموا عليهم في الليل","فلما غربت الشمس امر يوناتان الذين معه بان يسهروا تحت السلاح الليل كله استعدادا للقتال وفرق الحرس حول المحلة","و سمع العدو بان يوناتان والذين معه متاهبون للقتال فداخل قلوبهم الرعب والرعدة فاضرموا النيران في محلتهم وهربوا","الا ان يوناتان والذين معه لم يعلموا بما كان الا عند الصبح لانهم كانوا يرون ضوء النيران","فتعقبهم يوناتان فلم يدركهم لانهم كانوا قد قطعوا نهر الوطارس","فارتد يوناتان الى العرب المسمين بالزبديين وضربهم وسلب غنائمهم","ثم ارتحل واتى دمشق وجال في البلاد كلها","و اما سمعان فخرج وبلغ الى اشقلون والحصون التي بالقرب منها ثم ارتد الى يافا واستحوذ عليها","لانه سمع انهم يريدون ان يسلموا الحصن الى احزاب ديمتريوس واقام هناك حرسا يحافظون على المدينة","ثم رجع يوناتان وجمع شيوخ الشعب واتمر معهم ان يبني حصونا في اليهودية","و يرفع اسوار اورشليم ويشيد حائطا عاليا بين القلعة والمدينة ليفصلها عن المدينة وتبقى على حدتها حتى لا يشتروا ويبيعوا","فاتفقوا على ان يبنوا المدينة وتقدم اليهم ان يبنوا سور الوادي شرقا ورمموا السور المسمى كافيناطا","و ابتنى سمعان حاديد في السهل وحصنها بالابواب والمزاليج","و حاول تريفون ان يملك على اسية ويلبس التاج ويلقي يده على انطيوكس الملك","لكنه خشي من يوناتان ان يمنعه ويحاربه فطلب سبيلا لان يقبض على يوناتان ويهلكه فسار واتى الى بيت شان","فخرج يوناتان لملتقاه في اربعين الف رجل منتخبين للقتال واتى الى بيت شان","فلما راى تريقون ان يوناتان قد اقبل في جيش كثيف لم يجسر ان يمد يده اليه","فتلقاه باكرام واوصى به جميع اصحابه واهدى اليه هدايا وامر جيوشه بان يطيعوه طاعتهم لنفسه","و قال ليوناتان لم ثقلت على هؤلاء الشعب كلهم وليس بيننا حرب","اطلقهم الى بيوتهم وانتخب لك نفرا قليلا يكونون معك وهلم معي الى بطلمايس فاسلمها اليك هي وسائر الحصون ومن بقي من الجيوش وجميع المقلدين على الامور ثم انصرف راجعا فاني لهذا جئت","فصدقه وفعل كما قال واطلق الجيوش فانصرفوا الى ارض يهوذا","و استبقى لنفسه ثلاثة الاف رجل ترك الفين منهم في الجليل وصحبه الف","فلما دخل يوناتان بطلمايس اغلق اهل بطلمايس الابواب وقبضوا عليه وقتلوا جميع الذين دخلوا معه بالسيف","و ارسل تريفون جيشا وفرسانا الى الجليل والصحراء الواسعة لاهلاك جميع رجال يوناتان","لكنهم لما علموا ان يوناتان والذين معه قد قبض عليهم وهلكوا شجعوا انفسهم وتقدموا وهم متضامون متاهبون للقتال","و اذ راى طالبوهم انهم مستبسلون رجعوا عنهم","فوفدوا جميعهم بالسلام الى ارض يهوذا وناحوا على يوناتان والذين معه واشتد خوفهم وكانت عند جميع اسرائيل مناحة عظيمة","و طلب كل الامم الذين حولهم ان يدمروهم لانهم قالوا","انهم لا رئيس لهم ولا ناصر فلنقاتلهم ولنمح ذكرهم من البشر"],["و بلغ سمعان ان تريفون قد جمع جيشا عظيما ليغير على ارض يهوذا ويدمرها","و راى ان شعبه قد داخله الرعب والرعدة فصعد الى اورشليم وجمع الشعب","و شجعهم وقال لهم قد علمتم ما فعلت انا واخوتي واهل بيت ابي من اجل السنن والاقداس وما لقينا من الحروب والشدائد","و قد كان في ذلك هلاك اخوتي جميعا لاجل اسرائيل وبقيت انا وحدي","و الان فحاش لي ان اضن بنفسي في كل موقع ضيق فاني لست خيرا من اخوتي","بل انتقم لامتي وللاقداس ولنسائنا واولادنا لان الامم باسرها قد اجتمعت لتدميرنا بغضا","فلما سمع الشعب هذا الكلام ثارت نفوسهم","و اجابوا بصوت عظيم قائلين انت قائد لنا مكان يهوذا ويوناتان اخيك","فحارب حربنا ومهما قلت لنا فانا نفعله","فحشد جميع رجال القتال وجد في اتمام اسوار اورشليم وحصنها مما حولها","ثم وجه يوناتان بن ابشالوم الى يافا في عدد واف من الجيش فطرد الذين كانوا فيها واقام هناك","و زحف تريفون من بطلمايس في جيش عظيم قاصدا ارض يهوذا ومعه يوناتان تحت الحفظ","و كان سمعان حالا بحاديد قبالة السهل","و علم تريفون ان سمعان قد قام في موضع يوناتان اخيه وانه مزمع ان يلحم الحرب معه فانفذ اليه رسلا","يقول انا انما قبضنا على يوناتان اخيك لمال كان عليه للملك فيما باشره من الامور","فالان ارسل مئة قنطار فضة وابنيه رهينة لئلا يغدر بنا اذا اطلقناه وحينئذ نطلقه","و علم سمعان انهم انما يكلمونه بمكر الا انه ارسل المال والولدين مخافة ان يجلب على نفسه عداوة عظيمة من قبل الشعب ويقولوا","لسبب انه لم يرسل اليه المال والولدين هلك","فوجه الولدين ومئة القنطار الا ان تريفون اخلف ولم يطلق يوناتان","و جاء تريفون بعد ذلك ليغير على البلاد ويدمرها ودار في الطريق الى ادورا وكان سمعان وجيشه يقاومونه حيثما تقدم","و انفذ الذين في القلعة رسلا الى تريفون يلحون عليه ان ياتيهم في طريق البرية وينفذ اليهم ميرة","فجهز تريفون جميع فرسانه للمسير في ذلك الليل لكن اذ تكاثر الثلج جدا منعهم الثلج من المسير فارتحل واتى الى ارض جلعاد","و لما ان قارب بسكاما قتل يوناتان ودفنوه هناك","ثم رجع تريفون وانصرف الى ارضه","فارسل سمعان واخذ عظام يوناتان اخيه ودفنها في مودين مدينة ابائه","و ناح عليه كل اسرائيل نوحا عظيما وندبوه اياما كثيرة","و شيد سمعان على قبر ابيه واخوته بناء عاليا منظورا بحجارة نحتت من وراء ومن امام","و نصب على القبور سبعة اهرام واحدا بازاء واحد لابيه وامه واخوته الاربعة","و زينها بفنون ونقوش وجعل حولها اعمدة عظيمة مرسوما على الاعمدة اسلحة تخليدا لذكرهم وبجانب الاسلحة سفن منقوشة وكانت منظورة لجميع ركاب البحر","هذا هو القبر الذي صنعه بمودين باقيا الى هذا اليوم","و سلك تريفون بالغدر مع انطيوكس الملك الصغير وقتله","و ملك مكانه ولبس تاج اسية وضرب الارض ضربة عظيمة","و بنى سمعان حصون اليهودية وعززها بالبروج الرفيعة والاسوار العظيمة والابواب والمزاليج وادخر ميرة في الحصون","و انتخب سمعان رجالا وارسل الى ديمتريوس الملك ان يعفي البلاد لان كل ما فعله تريفون انما كان اختلاسا","فبعث اليه ديمتريوس الملك بهذا الكلام واجابه وكتب اليه كتابا هذه صورته","من ديمتريوس الملك الى سمعان الكاهن الاعظم وصديق الملوك والى الشيوخ وشعب اليهود سلام","قد وصل الينا اكليل الذهب والسعفة التي بعثت بها الينا وفي عزمنا ان نعقد معكم سلما وثيقا ونكاتب ارباب الامور ان يعفوكم مما عليكم","و كل ما رسمنا لكم يبقى مرسوما والحصون التي بنيتموها تكون لكم","و لكن ما فرط من هفوة وخطا الى هذا اليوم نتجاوز عنه والاكليل الذي لنا عليكم وكل وضيعة اخرى على اورشليم نعفيكم منها","و ان كان فيكم اهل للاكتتاب في جندنا فليكتتبوا ولكن فيما بيننا سلم","و في السنة المئة والسبعين خلع نير الامم عن اسرائيل","و بدا شعب اسرائيل يكتب في توقيع الصكوك والعقود في السنة الاولى لسمعان الكاهن الاعظم قائد اليهود ورئيسهم","في تلك الايام نزل سمعان على غزة وحاصرها بجيوشه وصنع دبابات وادناها من المدينة وضرب احد البروج واستولى عليه","و هجم الذين في الدبابة على المدينة فوقع اضطراب عظيم في المدينة","و صعد الذين في المدينة مع النساء الى السور ممزقة ثيابهم وصرخوا بصوت عظيم الى سمعان يسالونه الامان","و قالوا لا تعاملنا بحسب مساوئنا بل بحسب رافتك","فرق لهم سمعان وكف عن قتالهم واخرجهم من المدينة وطهر البيوت التي كانت فيها اصنام ثم دخلها بالتسبيح والشكر","و ازل منها كل رجاسة واسكن هناك رجالا من المتمسكين بالشريعة وحصنها وبنى له فيها منزلا","و اما الذين في قلعة اورشليم فاذ كانوا قد منعوا من الخروج ودخول البلد ومن البيع والشراء اشتدت مجاعتهم ومات كثير منهم","فصرخوا الى سمعان يسالون الامان فامنهم واخرجهم من هناك وطهر القلعة من النجاسات","و دخلها في اليوم الثالث والعشرين من الشهر الثاني في السنة المئة والحادية والسبعين بالحمد والسعف والكنارات والصنوج والعيدان والتسابيح والاناشيد لانحطام العدو الشديد من اسرائيل","و رسم ان يعيد ذلك اليوم بسرور كل سنة","ثم حصن جبل الهيكل الذي بجانب القلعة وسكن هناك هو والذين معه","و راى سمعان ان يوحنا ابنه رجل باس فجعله قائدا على جميع الجيوش واقام بجازر"],["و في السنة المئة والثانية والسبعين جمع ديمتريوس الملك جيوشه وسار الى ماداي يستمد نجدة لمحاربة تريفون","و بلغ ارساكيس ملك فارس وماداي ان ديمتريوس قد دخل تخومه فارسل بعض رؤسائه ليقبض عليه حيا","فذهب وضرب جيش ديمتريوس وقبض عليه واتى به ارساكيس فجعله في السجن","فهدات ارض يهوذا كل ايام سمعان وجعل همه مصلحة امته فكانوا مبتهجين بسلطانه ومجده كل الايام","و فضلا عن ذلك المجد كله جعل يافا مرسى وفتح مجازا لجزائر البحر","و وسع تخوم امته واستحوذ على البلاد","و جمع اسرى كثيرين وامتلك جازر وبيت صور والقلعة واخرج منها النجاسات ولم يكن من يقاومه","و كانوا يفلحون ارضهم بسلام والارض تعطي اتاءها واشجار الحقول اثمارها","و كان الشيوخ يجلسون في الساحات يتفاوضون جميعا في مصالح الامة والشبان متسربلين بالبهاء وعليهم حلل الحرب","و كان سمعان يمير المدن بالطعام ويهيئ فيها اسباب التحصين حتى صار ذكر مجده الى اقاصي الارض","و قرر السلم في ارضه فلبث اسرائيل في فرح عظيم","و جلس كل واحد تحت كرمته وتينته ولم يكن من يذعرهم","و لم يبق في الارض من يحاربهم وقد انكسرت الملوك في تلك الايام","و قوى كل من كان ضعيفا في شعبه وغار على الشريعة واستاصل كل اثيم وشرير","و عظم الاقداس واكثر من الانية المقدسة","و بلغ خبر وفاة يوناتان الى رومية واسبرطة فاسفوا اسفا شديدا","و اذ بلغهم ان سمعان اخاه قد تقلد الكهنوت الاعظم مكانه وصارت البلاد وما بها من المدن تحت سلطانه","كتبوا اليه على الواح من نحاس يجددون معه ما كانوا قد قرروه مع يهوذا ويوناتان اخويه من الموالاة والمناصرة","فقرئت الالواح بمشهد الجماعة في اورشليم وهذه صورة الكتب التي انفذها الاسبرطيون","من رؤساء الاسبرطيين ومن المدينة الى سمعان الكاهن الاعظم والى الشيوخ والكهنة وسائر شعب اليهود اخوتنا سلام","لقد اخبرنا الرسل الذين انفذتموهم الى شعبنا بما انتم فيه من العزة والكرامة فسررنا بوفدهم","و دونا ما قالوه في دواوين الشعب هكذا قد قدم علينا نومانيوس بن انطيوكس وانتيباتير ابن ياسون رسولا اليهود ليجددا مابيننا من الموالاة","فحسن لدى الشعب ان يلتقي الرجلين باكرام ويثبت صورة كلامهما في سجلات الشعب المخصصة لتكون تذكارا عند شعب الاسبرطيين وقد كتبنا بنسختها الى سمعان الكاهن الاعظم","و بعد ذلك ارسل سمعان نومانيوس الى رومية ومعه ترس عظيم من الذهب وزنه الف منا ليقرر المناصرة بينه وبينهم","فلما سمع الشعب ذلك الكلام قالوا بماذا نكافئ سمعان وبنيه","على ثباته هو واخوته وبيت ابيه ودفعه عن اسرائيل اعداءه وتمتيعه له بالحرية وكتب في الواح من نحاس جعلوها على انصابفي جبل صهيون","ما صورته في اليوم العاشر من شهر ايلول في السنة المئة والثانية والسبعين وهي السنة الثالثة لسمعان الكاهن الاعظم في سرمال","في مجمع عظيم من الكهنة والشعب ورؤساء الامة وشيوخ البلاد ثبت عندنا ان قد وقعت حروب كثيرة في البلاد","و ان سمعان بن متتيا من بني ياريب واخوته قد القوا بانفسهم في المخاطر وناهضوا اعداء امتهم صيانة لاقداسهم والشريعة واولوا امتهم مجدا كبيرا","و ان يوناتان جمع شمل امته وتقلد فيهم الكهنوت الاعظم ثم انضم الى قومه","فهم اعداؤهم بالغارة على ارضهم ليدمروا بلادهم ويلقوا ايديهم على اقداسهم","حينئذ نهض سمعان وقاتل عن امته وانفق كثيرا من امواله وسلح رجال الباس من امته واجرى عليهم الارزاق","و حصن مدن اليهودية وبيت صور التي عند حدود اليهودية حيث كانت اسلحة الاعداء من قبل وجعل هناك حرسا من رجال اليهود","و حصن يافا التي على البحر وجازر التي عند حدود اشدود حيث كان الاعداء مقيمين من قبل واسكن هناك يهودا وجعل فيهما كل ما ياول الى اعزاز شانهما","فلما راى الشعب ما فعل سمعان والمجد الذي شرع في انشائه لامته اقاموه قائدا لهم وكاهنا اعظم لما صنعه من ذلك كله ولاجل عدله والوفاء الذي حفظه لامته والتماسه اعزاز شعبه بجميع الوجوه","و في ايامه تم النجح على يديه باجلاء الامم عن البلاد وطرد الذين في مدينة داود باورشليم وكانوا قد بنوا لانفسهم قلعة يخرجون منها وينجسون ما حول الاقداس ويفسدون الطهارة افسادا عظيما","و اسكن فيها رجالا من اليهود وحصنها لصيانة البلاد والمدينة ورفع اسوار اورشليم","و اقره الملك ديمتريوس في الكهنوت الاعظم","و جعله من اصدقائه وعظمه جدا","اذ بلغه ان الرومانيين يسمون اليهود اولياء لهم ومناصرين واخوة وقد تلقوا رسل سمعان باكرام","و ان اليهود وكهنتهم قد حسن لديهم ان يكون سمعان رئيسا وكاهنا اعظم مدى الدهر الى ان يقوم نبي امين","و يكون قائدا لهم ويهتم بالاقداس ويقيم منهم اناسا على الاعمال والبلاد والاسلحة والحصون","و يتولى امر الاقداس وان يطيعه الجميع وتكتب باسمه جميع الصكوك في البلاد ويلبس الارجوان والذهب","و لا يحل لاحد من الشعب والكهنة ان ينقض شيئا من ذلك او يخالف شيئا مما يامر به او يجمع مجمعا بدونه في البلاد او يلبس الارجوان وعروة الذهب","و من فعل خلاف ذلك ونقض شيئا منه فهو مجرم","و قد رضي الشعب كله بان يقلد سمعان جميع ما ذكر","و قبل سمعان ورضي ان يكون كاهنا اعظم وقائدا ورئيسا لامة اليهود وللكهنة وحاكما على الجميع","و رسموا بان تدون هذه الكتابة في الواح من نحاس توضع في رواق الاقداس في موضع مشهود","و توضع صورها في الخزانة حتى تبقى لسمعان وبنيه"],["و انفذ انطيوكس بن ديمتريوس الملك كتبا من جزائر البحر الى سمعان الكاهن رئيس امة اليهود والى الشعب اجمع","و هذه فحواها من انطيوكس الملك الى سمعان الكاهن الاعظم رئيس الامة والى شعب اليهود سلام","انه اذ كان قوم من ذوي الفساد قد تسلطوا على مملكة ابائنا كان من همي الان ان استخلص المملكة حتى اعيدها الى ما كانت عليه منقبل وقد حشدت جيوشا كثيرة وجهزت اسطولا للحرب","و انا عازم ان اتقدم على البلاد لانتقم من الذين افسدوا في بلادنا وخربوا مدنا كثيرة في المملكة","فالان اقرر لك كل حطيطة حطها عنك الملوك من قبلي وكل ما اعفوك منه من التقادم","و قد ابحت لك ان تضرب في بلادك سكة خاصة","و ان تكون اورشليم والاقداس حرة وكل ما جهزته من الاسلحة وبنيته من الحصون التي في يدك فليبق لك","و كل ضريبة ملكية كانت فيما سلف او تكون فيما ياتي تفعى منها من الان على طول الزمان","و اذا فزنا بمملكتنا اعززناك انت وامتك والهيكل اعزازا عظيما حتى يتلالا مجدكم في الارض كلها","و في السنة المئة والرابعة والسبعين خرج انطيوكس الى ارض ابائه فاجتمع اليه جميع الجيوش حتى لم يبق مع تريفون الا نفر يسير","فتعقبه انطيوكس الملك فانطلق هاربا الى دورا التي على البحر","اذ ايقن ان قد تراكم عليه الشر وخذلته الجيوش","فنزل انطيوكس على دورا ومعه مئة وعشرون الفا من رجال الحرب وثمانية الاف فارس","و احاط بالمدينة وتقدم الاسطول من البحر فضايق المدينة برا وبحرا ولم يدع احدا يدخل او يخرج","و قدم نومانيوس والذين معه من رومية كتبا الى الملوك والبلاد كتب فيها هكذا","من لوكيوس وزير الرومانيين الى بطلماوس الملك سلام","لقد اتانا رسل اليهود اوليائنا ومناصرينا يجددون قديم الموالاة والمناصرة مرسلين من قبل سمعان الكاهن وشعب اليهود","و معهم ترس من ذهب وزنه الف منا","فلذلك راينا ان نكتب الى الملوك والبلاد ان لا يطلبوهم بسوء ولا يقيموا عليهم حربا ولا على شيء من مدنهم وبلادهم ولا يناصروا من يحاربهم","و حسن لدينا ان نقبل منهم الترس","فان فر اليكم من بلادهم بعض من رجال الفساد فاسلموهم الى سمعان الكاهن الاعظم لينتقم منهم على مقتضى شريعتهم","و كتب مثل ذلك الى ديمتريوس الملك واتالس وارياراطيس وارساكيس","و الى جميع البلاد الى لمساكس واسبرطة وديلس ومندس وسيكيون وكارية وسامس وبمفيلية وليكية واليكرنسس ورودس وفسيليس وكوس وسيدن وارادس وجرتينة وكنيدس وقبرس والقيروان","و كتبوا بنسخة تلك الكتب الى سمعان الكاهن الاعظم","و عاد انطيوكس الملك فحاصر دورا ولم يزل يضايقها وينصب عليها المجانيق واحاط بالتريفون لئلا يدخل ويخرج","فارسل اليه سمعان الفي رجل منتخبين نصرة له وفضة وذهبا وانية كثيرة","فابى انطيوكس ان يقبلها ونقض كل ما كان عاهده به من قبل وتغير عليه","و ارسل اليه اتينوبيوس احد اصحابه ليفاوضه قائلا انكم مستولون على يافا وجازر والقلعة التي باورشليم وهي من مدن مملكتي","و قد خربتم تخومها وضربتم الارض ضربة عظيمة وتسلطتم على اماكن كثيرة في مملكتي","فالان اسلموا المدن التي استحوذتم عليها وادوا خراج الاماكن التي تسلطتم عليها في خارج تخوم اليهودية","و الا فادوا عنها خمس مئة قنطار فضة وعن الاتلاف الذي اتلفتموه وعن خراج المدن خمس مئة قنطار اخرى والا وفدنا عليكم مقاتلين","فجاء اتينوبيوس صاحب الملك الى اورشليم وشاهد مجد سمعان وخزانة انيته الفضية والذهبية واثاثا وافرا فبهت واخبرهبكلام الملك","فاجاب سمعان وقال له انا لم ناخذ ارضا لغريب ولم نستول على شيء لاجنبي ولكنه ميراث ابائنا الذي كان اعداؤنا قد استولوا عليه ظلما حينا من الدهر","فلما اصبنا الفرصة استرددنا ميراث ابائنا","فاما يافا وجازر اللتان تطالب بهما فانهما كانتا تجلبان على الشعب في بلادنا نكبات شديدة غير انا نؤدي عنهما مئة قنطار فلم يجبه اتينوبيوس بكلمة","و رجع الى الملك مغضبا واخبره بهذا الكلام وبمجد سمعان وكل ما شاهده فغضب الملك غضبا شديدا","و ركب تريفون في سفينة وفر الى ارطوسياس","ففوض الملك قيادة الساحل الى كندباوس وجعل تحت يده جنودا من الرجالة وفرسانا","و امره ان يزحف على اليهودية واوعز اليه ان يبني قدرون ويحصن الابواب ويقاتل الشعب ثم ان الملك تعقب تريفون","فبلغ كندباوس الى يمنيا وجعل يرغم الشعب ويغير على اليهودية ويسبي في الشعب ويقتل وبني قدرون","و جعل فيها فرسانا وجنودا ليخرجوا وينتشروا في طرق اليهودية كما رسم له الملك"],["فصعد يوحنا من جازر واخبر سمعان اباه بما صنع كندباوس","فدعا سمعان ابنيه الاكبرين يهوذا ويوحنا وقال لهما انا لم نزل انا واخوتي وبيت ابي نحارب حروب اسرائيل منذ صغرنا الى هذا اليوم وقد انجح على ايدينا خلاص اسرائيل مرارا كثيرة","و الان فاني قد شخت وانتما برحمة الله قد بلغتما اشدكما فقوما مقامي ومقام اخي واخرجا وقاتلا عن امتكما وليؤازركما النصر من السماء","و انتخب من البلاد عشرين الفا من رجال الحرب والفرسان فزحفوا على كندباوس وباتوا بمودين","ثم قاموا في الغد وانطلقوا الى السهل فاذا تلقائهم جيش عظيم من الرجالة والفرسان وكان بين الفريقين واد","فنزل يوحنا بازائهم هو وشعبه واذ راى الشعب خائفا من عبور الوادي عبر هو اولا فلما راه الرجال عبروه وراءه","ففرق الشعب وجعل الفرسان في وسط الرجالة وكانت فرسان العدو كثيرة جدا","ثم نفخوا في الابواق المقدسة فانكسر كندباوس وجيشه وسقط منهم قتلى كثيرين وفر الباقون الى الحصن","حينئذ جرح يهوذا اخو يوحنا وتعقبهم يوحنا حتى بلغ كندباوس الى قدرون التي بناها","ففروا الى البروج التي بارض اشدود فاحرقها بالنار فسقط منهم الفا رجل ثم رجع الى ارض يهوذا بسلام","و كان بطلماوس بن ابوبس قد اقيم قائدا في بقعة اريحا وكان عنده من الفضة والذهب شيء كثير","و كان صهر الكاهن الاعظم","فتشامخ في قلبه وطلب ان يستولي على البلاد وقد نوى الغدر بسمعان وبنيه حتى يهلكهم","و كان سمعان يجول في مدن البلاد ينظر في مهماتها فنزل الى اريحا هو ومتتيا ويهوذا ابناه في السنة المئة والسابعة والسبعين في شهر شباط","فانزلهم ابن ابوبس بحصين كان قد بناه يقال له دوق وهو يضمر لهم الغدر وصنع لهم مادبة عظيمة واخفى هناك رجالا","فلما سكر سمعان وبنوه قام بطلماوس ومن معه واخذوا سلاحهم ووثبوا على سمعان في المادبة وقتلوه هو وابنيه وبعضا من غلمانه","و خان خيانة فظيعة وكافا الخير بالشر","ثم كتب بطلماوس بذلك وارسل الى الملك ان يوجه اليه جيشا لنصرته فيسلم اليه البلاد والمدن","و وجه قوما الى جازر لاهلاك يوحنا وانفذ كتبا الى رؤساء الالوف ان ياتوه حتى يعطيهم فضة وذهبا وهدايا","و ارسل اخرين ليستولوا على اورشليم وجبل الهيكل","فسبق واحد واخبر يوحنا في جازر بهلاك ابيه واخويه وان بطلماوس قد بعث من يقتله","فلما سمع ذلك بهت جدا وقبض على الرجال الذين اتوا ليقتلوه وقتلهم لعلمه انهم يريدون اهلاكه","و بقية اخبار يوحنا وحروبه وما ابداه من الحماسة وبناؤه الاسوار التي بناها واعماله","مكتوبة في كتاب ايام كهنوته الاعظم منذ تقلد الكهنوت الاعظم بعد ابيه"]]},{"id":909,"code":"2Mac","name":"المكابيين الثاني (قانوني ثانٍ)","t":"OT","deutero":true,"chapters":[["الى الاخوة اليهود الذين في مصر سلام اليكم من الاخوة اليهود الذين في اورشليم وبلاد اليهودية اطيب السلام","ليبارككم الله ويذكر عهده مع ابراهيم واسحق ويعقوب عبيده الامناء","و ليؤتكم جميعا قلبا لان تعبدوه وتصنعوا مشيئته بصدر مشروح ونفس راضية","و يفتح قلوبكم لشريعته ووصاياه ويجعلكم في سلام","و ليستجب لصلواتكم ويتب عليكم ولا يخذلكم في اوان السوء","و نحن ههنا نصلي من اجلكم","كنا نحن اليهود قد كتبنا اليكم في عهد ديمتريوس في السنة المئة والتاسعة والستين حين الضيق والشدة التي نزلت بنا في تلك السنين بعد انصراف ياسون والذين معه من الارض المقدسة والمملكة","فانهم احرقوا الباب وسفكوا الدم الزكي فابتهلنا الى الرب فاستجاب لنا وقربنا الذبيحة والسميذ واوقدنا السرج وقدمنا الخبز","فالان عليكم ان تعيدوا ايام المظال التي في شهر كسلو","في السنة المئة والثامنة والثمانين من سكان اورشليم واليهودية والشيوخ ويهوذا الى ارسطوبولس مؤدب بطلماوس الملك الذي من ذرية الكهنة المسحاء والى اليهود الذين في مصر سلام وعافية","نشكر الله الشكر الجزيل على انه خلصنا من اخطار جسيمة عند مناصبتنا للملك","و دحر الذين يقاتلوننا في المدينة المقدسة","فانه اذ كان الملك في فارس يقود جيشا لا يثبت امامه احد نكبوا في هيكل النناية بحيلة احتالها عليهم كهنة النناية","و ذلك انه جاء انطيوكس ومن معه من اصحابه الى هناك متظاهرا بانه يريد ان يقارنها وفي نفسه ان ياخذ الاموال على سبيل الصداق","فابرز كهنة النناية الاموال ودخل هو مع نفر يسير الى داخل المعبد ثم اغلقوا الهيكل","فلما دخل انطيوكس فتحوا بابا خفيا كان في ارض الهيكل وقذفوا حجارة رجموا بها القائد ثم قطعوهم قطعا وحزوا رؤوسهم والقوها الى الذين كانوا في الخارج","ففي كل شيء تبارك الهنا الذي اسلم الكفرة","وبعد فإذ كنا مزمعين ان نعيد عيد تطهير الهيكل في اليوم الخامس والعشرين من شهر كسلو راينا من الواجب ان نعلن اليكم انتعيدوا انتم ايضا عيد المظال والنار التي ظهرت حين بنى نحميا الهيكل والمذبح وقدم الذبيحة","فانه حين اجلي اباؤنا الى فارس اخذ بعض اتقياء الكهنة من نار المذبح سرا وخباوها في جوف بئر لا ماء فيها وحافظوا عليها بحيث بقي الموضع مجهولا عند الجميع","و بعد انقضاء سنين كثيرة حين شاء الله ارسل ملك فارس نحميا الى هنا فبعث اعقاب الكهنة الذين خباوا النار لالتماسها الا انهم كما حدثونا لم يجدوا نارا بل ماء خاثرا","فامرهم ان يغرفوا وياتوا به ولما احضرت الذبائح امر نحميا الكهنة ان ينضحوا بهذا الماء الخشب والموضوع عليه","فصنعوا كذلك ولما برزت الشمس وقد كانت محجوبة بالغيم اتقدت نار عظيمة حتى تعجب الجميع","و عند احراق الذبيحة كان الكهنة كلهم يصلون وكان يوناتان يبدا والباقون يجيبونه","و هذا ما صلى به نحميا ايها الرب الرب الاله خالق الكل المرهوب القوي العادل الرحيم يا من هو وحده الملك والبار","يا من هو وحده المتفضل العادل القدير الازلي مخلص اسرائيل من كل شر الذي اصطفى اباءنا وقدسهم","تقبل الذبيحة من اجل جميع شعبك اسرائيل وصن ميراثك وقدسه","و اجمع شتاتنا واعتق المستعبدين عند الامم وانظر الى الممتهنين والممقوتين ولتعلم الامم انك انت الهنا","و عاقب الظالمين والقاذفين بتجبر","و اغرس شعبك في مكانك المقدس كما قال موسى","و كان الكهنة يرنمون بالاناشيد","و لما احرقت الذبيحة امر نحميا بان يريقوا ما بقي من الماء على الحجارة الكبيرة","فلما صنعوا ذلك اتقد اللهيب فاطفاه النور المنبعث من المذبح","فشاع ذلك واخبر ملك فارس ان الموضع الذي خبا فيه الكهنة النار حين جلائهم قد ظهر فيه ماء وبه طهر الذين مع نحميا الذبيحة","فسيجه الملك وصيره مقدسا بعد الفحص عن الامر","و انعطف الملك اليهم واخذ عطايا كثيرة ووهبها لهم","و سماه الذين مع نحميا نفطار اي تطهيرا ويعرف عند كثيرين بنفطاي"],["قد جاء في السجلات ان ارميا النبي امر اهل الجلاء ان ياخذوا النار كما ذكر وكما امر النبي اهل الجلاء","اذ اوصاهم ان لا ينسوا وصايا الرب ولا تغوى قلوبهم اذا راوا تماثيل الذهب والفضة وما عليها من الزينة","و حرضهم بمثل هذا الكلام على ان لا يزيلوا الشريعة من قلوبهم","و جاء في هذه الكتابة ان النبي بمقتضى وحي سار اليه امر ان يذهب معه بالمسكن والتابوت حتى يصل الى الجبل الذي صعد اليه موسى وراى ميراث الله","و لما وصل ارميا وجد كهفا فادخل اليه المسكن والتابوت ومذبح البخور ثم سد الباب","فاقبل بعض من كانوا معه ليسموا الطريق فلم يستطيعوا ان يجدوه","فلما اعلم بذلك ارميا لامهم وقال ان هذا الموضع سيبقى مجهولا الى ان يجمع الله شمل الشعب ويرحمهم","و حينئذ يبرز الرب هذه الاشياء ويبدو مجد الرب والغمام كما ظهر في ايام موسى وحين سال سليمان ان يقدس الموضع تقديسا بهيا","اذ اشتهر وابدى حكمته بتقديم الذبيحة لتدشين الهيكل وتتميمه","فكما دعا موسى الرب فنزلت النار من السماء وافنت الذبيحة كذلك دعا سليمان فنزلت النار من السماء وافنت المحرقات","و قال موسى انما افنيت ذبيحة الخطيئة لانها لم تؤكل","و كذلك عيد سليمان للتدشين ثمانية الايام","و قد شرح ذلك في السجلات والتذاكر التي لنحميا وكيف انشا مكتبة جمع فيها اخبار الملوك والانبياء وكتابات داود ورسائل الملوك في التقادم","و كذلك جمع يهوذا كل ما فقد منا في الحرب التي حدثت لنا وهو عندنا","فان كانت لكم حاجة بذلك فارسلوا من ياخذه اليكم","و اذ قد ازمعنا ان نعيد عيد التطهير كتبنا اليكم وانكم لتحسنون الصنع اذا عيدتم هذه الايام","و الله الذي خلص جميع شعبه ورد على الجميع الميراث والملك والكهنوت والمقدس","كما وعد في الشريعة نرجو منه ان يرحمنا قريبا ويجمعنا مما تحت السماء الى الموضع المقدس","فانه قد انقذنا من شرور عظيمة وطهر الموضع","ان الحوادث التي وقعت ليهوذا المكابي واخوته وتطهير الهيكل العظيم وتدشين المذبح","و الحروب التي وقعت مع انطيوكس الشهير وابنه اوباطور","و الايات التي ظهرت من السماء في حقل الذين تحمسوا لدين اليهود حتى انهم مع قلتهم تسلطوا على البلاد بجملتها وطردوا جماهير الاعاجم","و استردوا الهيكل الذي اشتهر ذكره في المسكونة باسرها وحرروا المدينة واحيوا الشرائع التي كادت تضمحل لان الرب عطف عليهم بكثرة مراحمه","تلك الامور التي شرحها ياسون القيرواني في خمسة كتب قد اقبلنا نحن على اختصارها في درج واحد","و لما راينا تكاثر الحوادث والصعوبة التي تعترض من اراد الخوض في اخبار التاريخ لكثرة المواد","كان من همنا ان نجعل فيما كتبناه فكاهة للمطالع وسهولة للحافظ وفائدة للجميع","فلم يكن تكلفنا لهذا الاختصار امرا سهلا وانما تم بالعرق والسهر","كما ان الذي يعد مادبة ويبتغي بها منفعة الناس لا يكون الامر عليه سهلا غير انا لاجل مرضاة الكثيرين سنتحمل هذا النصب عن طيبة نفس","تاركين التدقيق في تفاصيل الحوادث لاصحاب التاريخ وملتزمين في الاختصار استقراء اهم الوقائع","فانه كما ينبغي لمن يهندس بيتا جديدا ان يهتم بجميع اجزاء البنيان ولمن يباشر الوسم والتصوير ان يتطلب اسباب الزينة هكذا ما نحن فيه على ما ارى","فان التبحر والكلام على كل امر والبحث عن جزء فجزء من شان مصنف التاريخ","و اما الملخص فمرخص له ان يسوق الحديث باختصار مع اهمال التدقيق في المباحث","و ههنا نشرع في ايراد الحوادث مقتصرين من التمهيد على ما ذكرناه اذ ليس من الاصابة الاطناب فيما قبل التاريخ والايجاز في التاريخ"],["حين كانت المدينة المقدسة عامرة امنة والشرائع محفوظة غاية الحفظ لما كان عليه اونيا الكاهن الاعظم من الورع والبغض للشر","كان الملوك انفسهم يعظمون المقدس ويكرمون الهيكل بافخر التقادم","حتى ان سلوقس ملك اسية كان يؤدي من دخله الخاص جميع النفقات المختصة بتقديم الذبائح","و ان رجلا اسمه سمعان من سبط بنيامين كان مقلدا الوكالة على الهيكل وقعت مخاصمة بينه وبين الكاهن الاعظم لاجل ظلم جناه علىالمدينة","و اذ لم يمكنه التغلب على اونيا انطلق الى ابلونيوس بن ترساوس وكان اذ ذاك قائدا في بقاع سورية وفينيقية","و اخبره ان الخزانة التي في اورشليم مشحونة من الاموال بما لا يستطاع وصفه حتى ان الدخل لا يحصى لكثرته وان ذلك ليس بمختص بنفقة الذبائح فيتهيا للملك ادخال ذلك كله في حوزته","ففاوض ابلونيوس الملك واعلمه بالاموال التي وصفت له فاختار هليودورس قيم المصالح وارسله وامره بجلب الاموال المذكورة","فتوجه هليودورس لساعته قاصدا في الظاهر التطوف في مدن بقاع سورية وفينيقية وكان في الواقع يقصد انفاذ مرام الملك","فلما جاء اورشليم احسن الكاهن الاعظم ملتقاه فحدثه بما كوشفوا به وصرح له بسبب قدومه وساله هل الامر في الحقيقة كماذكر له","فذكر له الكاهن الاعظم ان المال هو ودائع للارامل واليتامى","و ان قسما منه لهركانس بن طوبيا احد عظماء الاشراف ثم ان الامر ليس على ما وشى به سمعان المنافق وانما المال كله اربعون قنطار فضة ومئتا قنطار ذهب","فلا يجوز بوجه من الوجوه هضم الذين ائتمنوا قداسة الموضع ومهابة وحرمة الهيكل المكرم في المسكونة كلها","لكن هليودورس بناء على امر الملك اصر على حمل الاموال الى خزانة الملك","و عين يوما دخل فيه للفحص عن ذلك فكان في جميع المدينة ارتعاش شديد","و انطرح الكهنة امام المذبح بحللهم الكهنوتية يبتهلون نحو السماء الى الذي سن في الودائع ان تصان لمستودعها","و كان من راى وجه الكاهن الاعظم يتفطر فؤاده لان منظره وامتقاع لونه كانا ينبئان بما في نفسه من الارتعاش","اذ كان الرجل قد اشتمل عليه الرعب والقشعريرة فكانا يدلان الرائين على ما في قلبه من الكابة","و كان الناس يتبادرون من البيوت افواجا ليصلوا صلاة عامة لسبب الهوان المشرف على الموضع","و كانت النساء يزدحمن في الشوارع وهن متحزمات بالمسوح تحت ثديهن والعذارى ربات الخدور يتجارين بعضهن الى الابواب وبعضهن الى الاسوار واخريات يتطلعن من الكوى","و كلهن باسطات ايديهن الى السماء يتضرعن بالابتهال","فكان انكسار الجمهور وانتظار الكاهن الاعظم وهو في ارتعاش شديد مما يصدع القلب رحمة","و كانوا يتضرعون الى الاله القدير ان يحفظ الودائع موفوره لمستودعيها","اما هليودورس فكان اخذا في اتمام ما قضى به وقد حضر هناك مع شرطه في الخزانة","فصنع رب ابائنا وسلطان كل قدرة اية عظيمة حتى ان جميع الذين اجتراوا على الدخول صرعتهم قدرة الله واخذهم الانحلال والرعب","و ذلك انه ظهر لهم فرس عليه راكب مخيف وجهازه فاخر فوثب وضرب هليودورس بحوافر يديه وكانت عدة الراكب كانها من ذهب","و تراءى ايضا لهليودورس فتيان عجيبا القوة بديعا البهاء حسنا اللباس فوقفا على جانبيه يجلدانه جلدا متواصلا حتى اثخناه بالضرب","فسقط لساعته على الارض وغشيه ظلام كثيف فرفعوه وجعلوه على محمل","فاذا به بعد ان دخل الخزانة المذكورة في موكب حافل وجند كثير قد اصبح محمولا لا مغيث له وقد تجلت لهم قدرة الله علانية","فكان مطروحا بالقوة الالهية ابكم منقطع الرجاء من الخلاص","و اليهود يباركون الرب الذي مجد مقدسه وقد امتلا الهيكل ابتهاجا وتهللا اذ تجلى فيه الرب القدير بعدما كان قبيل ذلك مملوء اخوفا واضطرابا","فبادر بعض من اصحاب هليودورس وسالوا اونيا ان يبتهل الى العلي ويمن عليه بالحياة اذ كان قد اصبح على اخر رمق","فخالج قلب الكاهن الاعظم ان الملك ربما اتهم اليهود بمكيدة كادوها لهليودورس فقدم الذبيحة من اجل خلاص الرجل","و بينما الكاهن الاعظم يقدم الكفارة اذ عاد ذانك الفتيان فظهر لهليودورس بلباسهما الاول ووقفا وقالا عليك بجزيل الشكر لاونيا الكاهن الاعظم فان الرب قد من عليك بالحياة من اجله","و انت ايها المجلود فاخبر الجميع بقدرة الله العظيمة قالا ذلك وغابا عن النظر","فقدم هليودورس ذبيحة للرب وصلى اليه صلوات عظيمة على انه من عليه بالحياة وشكر اونيا ورجع بجيشه الى الملك","و كان يعترف امام الجميع بما عاينه من اعمال الله العظيم","و سال الملك هليودورس من ترى يكون اهلا لان نعود فنرسله الى اورشليم فقال","ان كان لك عدو او صاحب دسيسة في المملكة فارسله الى هناك فيرجع اليك مجلودا ان نجا فان في ذلك الموضع قدرة الهية لا محالة","لان الذي مسكنه في السماء هو يراقب الموضع ويدافع عنه فيضرب الذين يقصدون بالشر ويهلكهم","هذا ما كان من امر هليودورس وحماية الخزانة"],["و كان سمعان المذكور الذي وشى في امر الاموال والوطن يقذف اونيا كانه هو اغرى هليودورس بذلك وجلب عليه ذلك الشر","و بلغ من وقاحته انه وصف المحسن الى المدينة والقائم بمصلحة اهل وطنه والغيور على الشريعة بانه صاحب دسيسة","فاشتدت العداوة حتى ان احد خواص سمعان شرع في القتل","فلما تبين اونيا ما في ذلك الخصام من الخطر مع حماقة ابلونيوس قائد بقاع سورية وفينيقية الذي كان يمد سمعان في خبثه قصد الملك","لا واشيا باهل وطنه ولكن ابتغاء لمصالح تعم الشعب برمته","لانه راى انه بغير عناية الملك لا يمكن ان تكون الاحوال في سلام ولا ان يقلع سمعان عن رعونته","و كان انه بعد وفاة سلوقس واستيلاء انطيوكس الملقب بالشهير على الملك طمع ياسون اخو اونيا في الكهنوت الاعظم","فوفد على الملك ووعده بثلاث مئة وستين قنطار فضة وبثمانين قنطارا من دخل اخر","و ما عدا ذلك ضمن له مئة وخمسين قنطارا غيرها ان رخص له بسلطة الملك في اقامة مدرسة للتروض وموضع للغلمان وان يكتتب اهل اورشليم في رعوية انطاكية","فاجابه الملك الى ذلك فتقلد الرئاسة وما لبث ان صرف شعبه الى عادات الامم","و الغى الاختصاصات التي انعم بها الملوك على اليهود على يد يوحنا ابي اوبولمس الذي قلد السفارة الى الرومانيين في عقد الموالاة والمناصرة وابطل رسوم الشريعة وادخل سننا تخالف الشريعة","و بادر فاقام مدرسة للتروض تحت القلعة وساق نخبة الغلمان فجعلهم تحت القبعة","فتمكن الميل الى عادات اليونان والتخلق باخلاق الاجانب بشدة فجور ياسون الذي هو كافر لا كاهن اعظم","حتى ان الكهنة لم يعودوا يحرصون على خدمة المذبح واستهانوا بالهيكل واهملوا الذبائح لينالوا حظا في جوائز الملعب المحرمة بعد المباراة في رمي المطاث","و كانوا يستخفون بماثر ابائهم ويتنافسون بمفاخر اليونان","فلذلك احاقت بهم رزيئة شديدة فان الذين اولعوا برسومهم وحرصوا على التشبه بهم هم صاروا اعداء لهم ومنتقمين","لان النفاق في الشريعة الالهية لا يذهب سدى كما يشهد بذلك ما سيجيء","و لما جرت في صور المصارعة التي تجري كل سنة خامسة والملك حاضر","انفذ ياسون الخبيث رسلا من اورشليم انطاكيي الرعوية ومعهم ثلاث مئة درهم فضة لذبيحة هركليس لكن هؤلاء طلبوا ان لا تنفق على الذبيحة لان ذلك كان غير لائق بل تنفق في شيء اخر","فكان هذا المال في قصد مرسله لذبيحة هركليس لكنه بسعي الذين حملوه انفق في بناء سفن ثلاثية","و ارسل ابولنيوس بن منستاوس الى مصر لمبايعة بطلماوس فيلوماتور الملك فعلم انطيوكس انه قد نحي عن تدبير الامور فوجه اهتمامه الى تحصين نفسه ورجع الى يافا ثم سار الى اورشليم","فاستقبله ياسون واهل المدينة استقبالا جليلا ودخل بين المشاعل والهتاف ثم انصرف من هناك بالجيش الى فينيقية","و بعد مدة ثلاث سنين وجه ياسون منلاوس اخا سمعان المذكور ليحمل اموالا للملك ويفاوضه في امور مهمة","فتزلف الى الملك واطرا عظمة سلطانه واحال الكهنوت الاعظم الى نفسه بان زاد ثلاث مئة قنطار فضة على ما اعطى ياسون","ثم رجع ومعه اوامر الملك ولم يكن على شيء مما يليق بالكهنوت الاعظم وانما كانت له اخلاق غاشم عنيف واحقاد وحش ضار","و هكذا فان ياسون الذي ختل اخاه ختله اخر فطرد وفر الى ارض بني عمون","و استولى منلاوس على الرئاسة الا انه لم يوف شيئا من الاموال التي كان وعد بها الملك","فكان سستراتس رئيس القلعة يطالبه لانه كان مولي امر الجباية ولهذا السبب استدعيا كلاهما الى الملك","فاستخلف منلاوس ليسيماكس اخاه على الكهنوت الاعظم واستخلف سستراتس كراتيس والي القبرسيين","و حدث بعد ذلك ان اهل طرسوس وملو تمردوا لانهم جعلوا هبة لانطيوكيس سرية الملك","فبادر الملك لاطفاء الفتنة واستخلف مكانه اندرونكس احد ذوي المناصب","فراى منلاوس انه قد اصاب فرصة فسرق من الهيكل انية من الذهب اهدى بعضها الى اندرونكس وباع بعضها في صور والمدن التيبجوارها","و لما تيقن اونيا ذلك حجه به وكان قد انصرف الى حمى بدفنة بالقرب من انطاكية","فخلا منلاوس باندرونكس واغراه ان يقبض على اونيا فصار الى اونيا وخدعه بمكره وعاقده بقسم حتى حمله على الخروج من الحمى وان كان غير واثق به ثم اغتاله من ساعته ولم يرع للعدل حرمة","فوقع ذلك موقع المقت عند اليهود بل عند كثير من سائر الامم وشق عليهم قتل الرجل بغيا","فلما رجع الملك من نواحي قيلقية رفع اليه يهود المدينة مع ساءته هذه الجناية من اليونانيين مقتل اونيا عدوانا","فتاسف انطيوكس ورق رحمة وبكى على حكمة ذلك المفقود وكثرة ادبه","و اضطرم غضبا ولساعته نزع الارجوان عن اندرونكس ومزق حلله واطافه في المدينة كلها ثم اباد ذلك القاتل في الموضع الذي فتك فيه باونيا فانزل به الرب العقوبة التي استحقها","و كان ليسيماكس في المدينة قد سلب باغراء منلاوس كثيرا من مال الاقداس فذاع الخبر في الخارج بان قد اخذ كثير من الذهب فاجتمع الجمهور على ليسيماكس","فلما راى ليسيماكس هيجان الجموع وشدة غضبهم سلح ثلاثة الاف رجل واعمل ايدي الظلم تحت قيادة رجل عات قد تناهى في السن والحماقة جميعا","فلما راوا ما عزم عليه ليسيماكس تناول بعضهم حجارة وبعضهم هراوى وبعضهم رمادا حثوه من كل جانب على اصحاب ليسيماكس","فجرحوا كثيرين منهم وصرعوا بعضا وهزموهم باجمعهم وقتلوا سالب الاقداس عند الخزانة","و اقيم الحكم في هذه الامور على منلاوس","فلما قدم الملك الى صور ارسلت المشيخة ثلاثة رجال فرفعوا عليه الدعوى","و اذ راى منلاوس انه مغلوب وعد بطلماوس بن دوريمانس بمال جزيل ليستميل الملك","فدخل بطلماوس على الملك وهو في بعض الاروقة يتنسم الهواء وصرفه عن رايه","فحكم لمنلاوس الذي هو علة الشر كله بالبراءة مما شكى به وقضى بالموت على اولئك المساكين الذين لو رفعوا دعواهم الى الاسكوتيين لحكم لهم بالبراءة","و لم يلبث اولئك المحاجون عن المدينة والشعب والاقداس ان حل بهم العقاب الجائر","فشق هذا التعدى حتى على الصوريين وبذلوا نفقات دفنهم بسخاء","و استقر منلاوس في الرئاسة بشره ذوي الاحكام وكان لا يزداد الا خبثا ولم يزل لاهل وطنه كمينا مهلكا"],["في ذلك الزمان تجهز انطيوكس لغزو مصر ثانية","فحدث انه ظهر في المدينة كلها مدة اربعين يوما فرسان تعدو في الجو وعليهم ملابس ذهبية وفي ايديهم رماح وهم مكتبون كتائب","و قنابل من الخيل مصطفة وهجوم وكر بين الفريقين وتقليب تروس وحراب كثيرة واستلال سيوف ورشق نبال ولمعان حلي ذهبية ودروع من كل صنف","فكان الجميع يسالون ان يكون مال هذه الاية خيرا","و ارجف قوم ان انطيوكس قد مات فاتخذ ياسون جيشا ليس باقل من الف نفس وهجم على المدينة بغتة حتى اذا دفع الذين على الاسوار واوشك ان ياخذ المدينة هرب منلاوس الى القلعة","فطفق ياسون يذبح اهل وطنه بغير رحمة ولم يفطن ان الظفر بالاخوان هو عين الخذلان حتى كان نصرته هذه انما كانت على اعداء لا على بني امته","لكنه لم يحز الرئاسة وانما احاق به اخيرا خزي كيده فهرب ثانية الى ارض بني عمون","و كانت خاتمة امره منقلبا سيئا لان ارتاس زعيم العرب طرده فجعل يفر من مدينة الى مدينة والجميع ينبذونه ويبغضونه بغضة من ارتد عن الشريعة ويمقتونه مقت من هو قتال لاهل وطنه حتى دحر الى مصر","فكان ان الذي غرب كثيرين هلك في الغربة في ارض لكديمون اذ لجا الى هناك بوسيلة القرابة","و الذي طرح كثيرين بغير قبر اصبح لم يبك عليه ولم يدفن ولم يكن له قبر في وطنه","فلما بلغت الملك هذه الحوادث اتهم اليهود بالانتقاض عليه فزحف من مصر وقد تنمر في قلبه واخذ المدينة عنوة","و امر الجنود ان يقتلوا كل من صادفوه دون رحمة ويذبحوا المختبئين في البيوت","فطفقوا يهلكون الشبان والشيوخ ويبيدون الرجال والنساء والاولاد ويذبحون العذارى والاطفال","فهلك ثمانون الف نفس في ثلاثة ايام منهم اربعون الفا في المعركة وبيع منهم عدد ليس باقل من القتلى","و لم يكتف بذلك بل اجترا ودخل الهيكل الذي هو اقدس موضع في الارض كلها وكان دليله منلاوس الخائن للشريعة والوطن","و اخذ الانية المقدسة بيديه الدنستين مع ما اهدته ملوك الاجانب لزينة الموضع وبهائه وكرامته وقبض عليها بيديه النجستين ومضى","فتشامخ انطيوكس في نفسه ولم يفطن الى ان الله غضب حينا لاجل خطايا سكان المدينة وانه لذلك اهمل الموضع","و لولا انهم انهمكوا بخطايا كثيرة لجلد حال دخوله وردع عن جسارته كما وقع لهليودورس الذي بعثه سلوقس الملك لافتقاد الخزانة","و لكن الرب لم يتخذ الامة لاجل الموضع بل الموضع لاجل الامة","و لذلك بعدما اشترك الموضع في مصائب الامة عاد فاشترك في نعم الرب وبعدما خذله القدير في غضبه ادرك كل مجد عند توبته تعالى","و حمل انطيوكس من الهيكل الفا وثماني مئة قنطار وبادر الرجوع الى انطاكية وقد خيلت اليه كبرياؤه وتشامخ نفسه انه يقطع البر بالسفن والبحر بالقدم","و ترك عمالا يراغمون الامة منهم فيلبس في اورشليم وهو فريجي الاصل وكان اشرس اخلاقا من الذي نصبه","و اندرونكس في جرزيم وايضا منلاوس الذي كان اشد جورا على الرعية من كليهما","ثم حمله ما كان عليه من المقت لرعايا اليهود على ان ارسل ابلونيوس الرئيس البغيض في اثنين وعشرين الف جندي وامره ان يذبح كل بالغ منهم ويبيع النساء والصبيان","فلما وفد الى اورشليم اظهر السلام وتربص الى يوم السبت المقدس حتى اذا دخل اليهود في عطلتهم امر اصحابه بان يتسلحوا","و ذبح جميع الخارجين للتفرج ثم اقتحم المدينة بالسلاح واهلك خلقا كثيرا","و ان يهوذا المكابي كان قد انصرف الى البرية وهو عاشر عشرة فلبث مع اصحابه في الجبال يعيشون عيشة الوحوش وياكلون العشب لئلا يشتركوا في النجاسة"],["و بعد ذلك بيسير ارسل الملك شيخا اثينيا ليضطر اليهود ان يرتدوا عن شريعة ابائهم ولا يتبعوا شريعة الله","و ليدنس هيكل اورشليم ويجعله على اسم زوس الاولمبي ويجعل هيكل جرزيم على اسم زوس مؤوي الغرباء لان اهل الموضع كانوا غرباء","فاشتد انفجار الشر وعظم على الجماهير","و امتلا الهيكل عمرا وقصوفا واخذ الامم يفسقون بالمابونين ويضاجعون النساء في الدور المقدسة ويدخلون اليها ما لا يحل","و كان المذبح مغطى بالمحارم التي نهت الشريعة عنها","و لم يكن لاحد ان يعيد السبت ولا يحفظ اعياد الاباء ولا يعترف بانه يهودي اصلا","و كانوا كل شهر يوم مولد الملك يساقون قسرا للتضحية وفي عيد ديونيسيوس يضطرون الى الطواف اجلالا له وعليهم اكاليل من اللبلاب","و صدر امر الى المدن اليونانية المجاورة باغراء البطالمة ان يلزموا اليهود بمثل ذلك وبالتضحية","و ان من ابى ان يتخذ السنن اليونانية يقتل فذاقوا بذلك امر البلاء","فان امراتين سعي بهما انهما ختنتا اولادهما فعلقوا اطفالهما على اثديهما وطافوا بهما في المدينة علانية ثم القوهما عن السور","و لجا قوم الى مغاور كانت بالقرب منهم لاقامة السبت سرا فوشي بهم الى فيلبس فاحرقهم بالنار وهم لا يجترئون ان يدافعواعن انفسهم اجلالا لهذا اليوم العظيم","و اني لارجو من مطالعي هذا الكتاب ان لا يستوحشوا من هذه الضربات وان يحسبوا هذه النقم ليست للهلاك بل لتاديب امتنا","فانه اذا لم يهمل الكفرة زمنا طويلا بل عجل عليهم بالعقاب فذلك دليل على رحمة عظيمة","لان الرب لا يمهل عقابنا بالاناة الى ان يستوفى كيل الاثام كما يفعل مع سائر الامم","فقد قضى فينا بذلك لئلا تبلغ اثامنا غايتها وينتقم منا اخيرا","فهو لا يزيل عنا رحمته ابدا واذا ادب شعبه بالشدائد فلا يخذله","نقول هذا على سبيل التذكرة ونرجع الى تتمة الحديث بكلام موجز","كان رجل يقال له العازار من متقدمي الكتبة طاعن في السن رائع المنظر في الغاية فاكرهوه بفتح فيه على اكل لحم الخنزير","فاختار ان يموت مجيدا على ان يحيا ذميما وانقاد الى العذاب طائعا","و قذف لحم الخنزير من فيه ثم تقدم كما يليق بمن يتمنع بشجاعة عما لا يحل ذوقه رغبة في الحياة","فخلا به الموكلون بامر الضحايا الكفرية لما كان بينهم وبينه من قديم المعرفة وجعلوا يحثونه ان ياتي بما يحل له تناوله من اللحم مهيأ بيده ويتظاهر بانه ياكل من لحم الضحايا التي امر بها الملك","لينجو من الموت اذا فعل ذلك وينال منهم الجميل لاجل مودته القديمة لهم","لكنه عول على الراي النزيه الجدير بسنه وكرامة شيخوخته وما بلغ اليه من جلالة المشيب وبكمال سيرته الحسنة منذ حداثته بلب الشريعة المقدسة الالهية واجاب بغير توقف وقال بل اسبق الى الجحيم","لانه لا يليق بسننا الرئاء لئلا يظن كثير من الشبان ان العازار وهو ابن تسعين سنة قد انحاز الى مذهب الاجانب","و يضلوا بسببي لاجل رئائي وحبي لحياة قصيرة فانية فاجلب على شيخوختي الرجس والفضيحة","فاني ولو نجوت الان من نكال البشر لا افر من يدي القدير لا في الحياة ولا بعد الممات","و لكن اذا فارقت الحياة ببسالة فقد وفيت بحق شيخوختي","و ابقيت للشبان قدوة شهامة ليتلقوا المنية ببسالة وشهامة في سبيل الشريعة الجليلة المقدسة ولما قال هذا انطلق من ساعته الى عذاب التوتير والضرب","فتحول اولئك الذين ابدوا له الرافة قبيل ذلك الى القسوة لحسبانهم ان كلامه كان عن كبر","و لما اشرف على الموت من الضرب تنهد وقال يعلم الرب وهو ذو العلم المقدس اني وانا قادر على التخلص من الموت اكابد في جسدي عذاب الضرب الاليم واما في نفسي فاني احتمل ذلك مسرورا لاجل مخافته","و هكذا قضى هذا الرجل تاركا موته قدوة شهامة وتذكار فضيلة لامته باسرها فضلا عن الشبان بخصوصهم"],["و قبض على سبعة اخوة مع امهم فاخذ الملك يكرههم عل تناول لحوم الخنزير المحرمة ويعذبهم بالمقارع والسياط","فانتدب احدهم للكلام وقال ماذا تبتغي وعم تستنطقنا انا لنختار ان نموت ولا نخالف شريعة ابائنا","فحنق الملك وامر باحماء الطواجن والقدور ولما احميت","امر لساعته بان يقطع لسان الذي انتدب للكلام ويسلخ جلد راسه وتجدع اطرافه على عيون اخوته وامه","و لما عاد جذمة امر بان يؤخذ الى النار وفيه رمق من الحياة ويقلى وفيما كان البخار منتشرا من الطاجن كانوا هم وامهم يحض بعضهم بعضا ان يقدموا على الموت بشجاعة","قائلين ان الرب الاله ناظر وهو يتمجد بنا كما صرح موسى في نشيده الشاهد في الوجوه اذ قال ويستمجد بعبيده","و لما قضى الاول على هذه الحال ساقوا الثاني الى الهوان ونزعوا جلد راسه مع شعره ثم سالوه هل ياكل قبل ان يعاقب في جسده عضوا عضوا","فاجاب بلغة ابائه وقال لا فاذاقوه بقية العذاب كالاول","و فيما كان على اخر رمق قال انك ايها الفاجر تسلبنا الحياة الدنيا ولكن ملك العالمين اذا متنا في سبيل شريعته فسيقيمنا لحياة ابدية","و بعده شرعوا يستهينون بالثالث وامروه فدلع لسانه وبسط يديه بقلب جليد","و قال اني من الرب السماء اوتيت هذه الاعضاء ولاجل شريعته ابذلها واياه ارجو ان استردها من بعد","فبهت الملك والذين معه من بسالة قلب ذلك الغلام الذي لم يبال بالعذاب شيئا","و لما قضى عذبوا الرابع ونكلوا به بمثل ذلك","و لما اشرف على الموت قال حبذا ما يتوقعه الذي يقتل بايدي الناس من رجاء اقامة الله له اما انت فلا تكون لك قيامة للحياة","ثم ساقوا الخامس وعذبوه فالتفت الى الملك وقال","انك بما لك من السلطان على البشر مع كونك فانيا تفعل ما تشاء ولكن لا تظن ان الله قد خذل ذريتنا","اصبر قليلا فترى باسه الشديد كيف يعذبك انت ونسلك","و بعده ساقوا السادس فلما قارب ان يموت قال لا تغتر بالباطل فانا نحن جلبنا على انفسنا هذا العذاب لانا خطانا الى الهنا ولذلك وقع لنا ما يقضي بالعجب","و اما انت لا تحسب انك تترك سدى بعد تعرضك لمناصبة الله","و كانت امهم اجدر الكل بالعجب والذكر الحميد فانها عاينت بنيها السبعة يهلكون في مدة يوم واحد وصبرت على ذلك بنفس طيبة ثقة بالرب","و كانت تحرض كلا منهم بلغة ابائها وهي ممتلئة من الحكمة السامية وقد القت على كلامها الانثوي بسالة رجلية","قائلة لهم اني لست اعلم كيف نشاتم في احشائي ولا انا منحتكم الروح والحياة ولا احكمت تركيب اعضائكم","على ان خالق العالم الذي جبل تكوين الانسان وابدع لكل شيء تكوينه سيعيد اليكم برحمته الروح والحياة لانكم الان تبذلون انفسكم في سبيل شريعته","و ان انطيوكس اذ تخيل انه يستخف به وخشي صوت معير يعيره اخذ يحرض بالكلام اصغرهم الباقي بل اكد له بالايمان انه يغنيه ويسعده اذا ترك شريعة ابائه ويتخذه خليلا له ويقلده المناصب","و لمل لم يصخ الغلام لذلك البتة دعا الملك امه وحثها ان تشير على الغلام بما يبلغ الي خلاصه","و الح عليها حتى وعدت بانها تشير على ابنها","ثم انحنت اليه واستهزات بالملك العنيف وقالت بلغة ابائها يا بني ارحمني انا التي حملتك في جوفها تسعة اشهر وارضعتك ثلاث سنين وعالتك وبلغتك الى هذه السن وربتك","انظر يا ولدي الى السماء والارض واذا رايت كل ما فيهما فاعلم ان الله صنع الجميع من العدم وكذلك وجد جنس البشر","فلا تخف من هذا الجلاد لكن كن مستاهلا لاخوتك واقبل الموت لاتلقاك مع اخوتك بالرحمة","و فيما هي تتكلم قال الغلام ماذا انتم منتظرون اني لا اطيع امر الملك وانما اطيع امر الشريعة التي القيت الى ابائنا على يد موسى","و انت ايها المخترع كل شر على العبرانيين انك لن تنجو من يدي الله","فنحن انما نعاقب على خطايانا","و ربنا الحي وان سخط علينا حينا يسيرا لتوبيخنا وتاديبنا سيتوب على عبيده من بعد","و اما انت ايها المنافق يا اخبث كل بشر فلا تتشامخ باطلا وتتنمر بامالك الكاذبة وانت رافع يدك على عبيده","لانك لم تنج من دينونة الله القدير الرقيب","و لقد صبر اخوتنا على الم ساعة ثم فازوا بحياة ابدية وهم في عهد الله واما انت فسيحل بك بقضاء الله العقاب الذي تستوجبه بكبريائك","و انا كاخوتي ابذل جسدي ونفسي في سبيل شريعة ابائنا وابتهل الى الله ان لا يبطئ في توبته على امتنا وان يجعلك بالمحن والضربات تعترف بانه هو الاله وحده","و ان ينتهي في وفي اخوتي غضب القدير الذي حل على امتنا عدلا","فحنق الملك ولم يحتمل ذلك الاستهزاء فزاده نكالا على اخوته","و هكذا قضى هذا الغلام طاهرا وقد وكل الى الرب كل امره","و في اخر الامر هلكت الام على اثر بنيها","و بما اوردناه عن الضحايا والتعذيبات المبرحة كفاية"],["و كان يهوذا المكابي ومن معه يتسللون الى القرى ويندبون ذوي قرابتهم ويستضمون الذين ثبتوا على دين اليهود حتى جمعوا ستة الاف","و كانوا يبتهلون الى الرب ان ينظر الى شعبه الذي اصبح يدوسه كل احد ويعطف على الهيكل الذي دنسه اهل النفاق","و يرحم المدينة المتهدمة التي اشرفت على الامحاء ويصغي الى صوت الدماء الصارخة اليه","و يذكر اهلاك الاطفال الابرئاء ظلما والتجاديف على اسمه ويجهر ببغضته للشر","و لما اصبح المكابي في جيش لم تعد الامم تثبت امامه اذ كان سخط الرب قد استحال الى رحمة","فجعل يفاجئ المدن والقرى ويحرقها حتى اذا استولى على مواضع توافقه تغلب على الاعداء في مواقع جمة","و كان اكثر غاراته ليلا فذاع خبر شجاعته في كل مكان","فلما راى فيلبس ان الرجل اخذ في التقدم شيئا فشيئا وقد اوتي الفوز في اكثر اموره كتب الى بطلماوس قائد بقاع سورية فينيقية يساله المناجدة لصيانة مصالح الملك","فاختار لساعته نكانور بن بتركلس من خواص اصدقاء الملك وجعل تحت يده لفيفا من الامم يبلغ عشرين الفا ليستاصل ذرية اليهود عن اخرهم وضم اليه جرجياس وهو من القواد المحنكين في امر الحرب","فرسم نكانور ان يؤخذ من مبيع سبي اليهود الفا القنطار التي كانت للرومانيين على الملك","و ارسل في الحال الى مدن الساحل يدعو الى مشتري رقاب اليهود مسعرا كل تسعين رقبة بقنطار ولم يخطر له ما سيحل به من نقمة القدير","فاتصل بيهوذا خبر مقدم نكانور فاخبر الذين معه بمجيء الجيش","فبدا الذين خافوا ولم يثقوا بعدل الله ينسابون كل واحد من مكانه","و باع اخرون كل ما كان باقيا لهم وكانوا يبتهلون الى الرب ان ينقذهم من نكانور الكافر الذي باعهم قبل الملتقى","و ذلك ان لم يكن من اجلهم فمن اجل عهده مع ابائهم وحرمة اسمه العظيم الذي هم مسمون به","فحشد المكابي اصحابه وهم ستة الاف وحرضهم ان لا يرتاعوا من الاعداء ولا يخافوا من كثرة الامم المجتمعة عليهم بغيا وان يقاتلوا بباس","جاعلين نصب عيونهم الاهانة التي الحقوها بالموضع المقدس عدوانا وما انزلوه بالمدينة من القهر والعار مع نقض سنن الاباء","و قال ان هؤلاء انما يتوكلون على سلاحهم وجسارتهم واما نحن فنتوكل على الله القدير الذي يستطيع في لمحة ان يبيد الثائرين علينا بل العالم باسره","ثم ذكر لهم النجدات التي امد بها اباؤهم وما كان من ابادة المئة والخمسة والثمانين الفا على عهد سنحاريب","و الواقعة التي كانت لهم في بابل مع الغلاطيين كيف برزوا للقتال وهم ثمانية الاف رجل ومعهم اربعة الاف من المكدونيين وكيف حين وهل المكدونيين اهلك اولئك الثمانية الالاف مئة وعشرين الفا بالنجدة التي اوتها من السماء وعادوا بخير جزيل","و بعدما شددهم بهذا الكلام حتى اضحوا مستعدين للموت في سبيل الشريعة والوطن قسمهم اربع فرق","و اقام كل واحد من اخوته سمعان ويوسف ويوناتان قائدا على فرقة وجعل تحت يده الفا وخمس مئة","ثم امر العازار ان يتلو عليهم الكتاب المقدس وجعل لهم كلمة السر نصرة الله ثم اتخذ قيادة الكتيبة الاولى وحمل على نكانور","فايدهم القدير فقتلوا من الاعداء ما يزيد على تسعة الاف وتركوا اكثر جيش نكانور مجرحين مجدعي الاعضاء والجاوا الجميع الى الهزيمة","و غنموا اموال الذين جاءوا لشرائهم ثم تعقبوهم مسافة غير قصيرة","الى ان حضرت الساعة فامسكوا وعادوا وقد ادركوا السبت ولذلك لم يطيلوا تعقبهم","و جمعوا اسلحة الاعداء واخذوا اسلابهم ثم حفظوا السبت وهم يباركون الرب كثيرا ويعترفون له اذ انقذهم ليعيدوا ذلك اليوم ومن عليهم باستئناف رحمته","و لما انقضى السبت وزعوا على الضعفاء والارامل واليتامى نصيبهم من الغنائم واقتسموا الباقي بينهم وبين اولادهم","و بعدما فرغوا من ذلك اقاموا صلاة عامة سائلين الرب الرحيم ان يعود فيتوب على عبيده","و قتلوا ما يزيد على عشرين الفا من جيوش تيموتاوس وبكيديس واستولوا على حصون مشيدة واقتسموا كثيرا من الاسلاب جعلوها سهاما متساوية لهم وللضعفاء واليتامى والارامل والشيوخ","و لما جمعوا اسلحة العدو رتبوا كل شيء في موضعه اللائق به وحملوا ما بقي من الغنائم الى اورشليم","و قتلوا رئيس جيش تيموتاوس وكان رجلا شديد النفاق الحق باليهود اضرارا كثيرة","و بينا هم يحتفلون بالظفر في وطنهم احرقوا كلستانيس وقوما معه في بيت كانوا قد فروا اليه وكانوا قد احرقوا الابواب المقدسة فنالهم الجزاء الذي استوجبوه بكفرهم","و اما نكانور الشديد الفجور الذي كان قد استصحب معه الف تاجر لمشتري اليهود","فلما راى الذين كان يحتقرهم قد اذلوه بامداد الرب خلع ما عليه من الثياب الفاخرة وانساب في كبد البلاد منفردا كالابق حتى لحق بانطاكية وهو متفجع غاية التفجع لانقراض جيشه","و بعدما كان قد وعد الرومانيين بان يفيهم الخراج من سبي اورشليم عاد يذيع ان اليهود لهم الله نصير وانهم لذلك لا يغلبون اذ هم متبعون ما رسم لهم من الشرائع"],["و اتفق في ذلك الزمان ان انطيوكس كان منصرفا عن بلاد فارس بالخزي","و كان قد زحف على مدينة اسمها برسابوليس وشرع يسلب الهياكل ويعسف المدينة فثار الجموع الى السلاح ودفعوه فانهزم انطيوكس منقلبا بالعار","و لما كان عند احمتا بلغه ما وقع لنكانور واصحاب تيموتاوس","فاستشاط غضبا وازمع ان يحيل على اليهود ما الحقه به الذين هزموه من الشر فامر سائق عجلته بان يجد في السير بغير انقطاع وقد حلبه القضاء من السماء فانه قال في تجبره لآتين اورشليم ولأجعلنها مدفنا لليهود","لكن الرب اله اسرائيل البصير بكل شيء ضربه ضربة معضلة غير منظورة فانه لم يفرغ من كلامه ذاك حتى اخذه داء في احشائه لا دواء له ومغص اليم في جوفه","و كان ذلك عين العدل في حقه لانه عذب احشاء كثيرين بالالام المتنوعة الغريبة لكنه لم يكن ليكف عن عتيه","و انما بقي صدره ممتلئا من الكبرياء ينفث نار الحنق على اليهود ويحث على الاسراع في السير حتى انه من شدة الجري سقط من عجلته فترضضت بتلك السقطة الهائلة جميع اعضاء جسمه","فاصبح بعدما خيل له بزهوه الذي لم يبلغ اليه انسان انه يحكم على امواج البحر ويجعل قمم الجبال في كفة الميزان مصروعا على الارض محمولا في محفة شهادة للجميع بقدرة الله الجليلة","حتى كانت الديدان تنبع من جسد ذلك المنافق ولحمه يتساقط وهو حي بالالام والاوجاع وصار الجيش كله يتكره نتن رائحته","حتى انه بعدما كان قبيل ذلك يزين له انه يمس كواكب السماء لم يكن احد يطيق حمله لشدة رائحته التي لا تحتمل","فلما راى نفسه في تلك الحال من تمزق جسمه اخذ ينزل عن كبريائه المفرطة ويتعقل الحق اذ كانت الاوجاع تزداد فيه على الساعات بالضربة الالهية","حتى انه هو نفسه امسى لا يطيق نتنه فقال حق على الانسان ان يخضع لله وان لا يحمله الكبر وهو فان على ان يحسب نفسه معادلا لله","و كان ذلك الفاجر يتضرع الى الرب لكن الرب لم يكن ليرحمه من بعد ونذر","ان المدينة المقدسة التي كان يقصدها حثيثا ليمحو اثارها ويجعلها مدفنا سيجعلها حرة","و ان اليهود الذين كان قد قضى عليهم بان لا يدفنوا بل يلقوا مع اطفالهم ماكلا للطيور والوحوش سيسويهم جميعا بالاثينيين","و ان الهيكل المقدس الذي كان قد انتهبه سيزينه بافخر التحف ويرد الانية المقدسة اضعافا ويؤدي النفقات المفروضة للذبائح من دخله الخاص","بل انه هو نفسه يتهود ويطوف كل معمور في الارض ينادي بقدرة الله","و اذ لم تسكن الامه لان قضاء الله العادل كان قد حل عليه قنط من نفسه وكتب الى اليهود رسالة في معنى التوسل وهذه صورتها","من انطيوكس الملك القائد الى رعايا اليهود الافاضل السلام الكثير والعافية والغبطة","اذا كنتم في سلامة وكان اولادكم وكل شيء لكم على ما تحبون فاني اشكر الله شكرا جزيلا اما انا فرجائي منوط بالسماء","و بعد فاني منذ اعتللت لم ازل اذكركم بالمودة ناويا لكم الكرامة والخير فاني في ايابي من نواحي فارس اصابني داء شديد فرايت من الواجب ان اصرف العناية الى مصلحة الجميع","ليس لاني قانط من نفسي فان لي رجاء وثيقا ان اتخلص من علتي","ثم اني تذكرت ان ابي حين سار بجيشه الى الاقاليم العليا عين الولي لعهده","و انا اخاف ان يقع امر غير منتظر او يذيع خبر مشؤوم فيضطرب مقلدوا الامور في البلاد عند بلوغه اليهم","و قد تبين لي ان من حولنا من ذوي السلطان ومجاوري المملكة يترصدون الفرص ويتوقعون حادثا يحدث فلذلك عينت للملك ابني انطيوكسالذي سلمته غير مرة الى كثيرين منكم واوصيتهم به عند مسيري الى الاقاليم العليا وقد كتبت اليه في هذا المعنى","فانشدكم وارغب اليكم ان تذكروا ما اوليتكم من النعم العامة والخاصة وان يبقى كل منكم على ما كان له من الولاء لي ولابني","و لي الثقة بانه سياتم بقصدي فيعاملكم بالرفق والمرؤة","ثم قضى هذا السفاك الدماء المجدف بعد الام مبرحة كما كان يفعل بالناس ومات ميتة شقاء على الجبال في ارض غربة","فنقل جثته فيلبس رضيعه ثم انصرف الى مصر الى بطلماوس فيلوماتور خوفا من ابن انطيوكس"],["اما المكابي والذين معه فبامداد الرب استردوا الهيكل والمدينة","و هدموا المذابح التي كان الاجانب قد بنوها في الساحة وخربوا المعابد","و طهروا الهيكل وصنعوا مذبحا اخر واقتدحوا حجارة اقتبسوا منها نارا وقدموا ذبيحة بعد فترة سنتين وهياوا البخور والسرج وخبز التقدمة","و بعدما اتموا ذلك ابتهلوا الى الرب وقد خروا بصدورهم ان لا يصابوا بمثل تلك الشرور لكن اذا خطئوا يؤدبهم هو برفق ولا يسلمهم الى امم كافرة وحشية","و اتفق انه في مثل اليوم الذي فيه نجست الغرباء الهيكل في ذلك اليوم عينه ثم تطهير الهيكل وهو اليوم الخامس والعشرون من ذلك الشهر الذي هو شهر كسلو","فعيدوا ثمانية ايام بفرح كما في عيد المظال وهم يذكرون كيف قضوا عيد المظال قبيل ذلك في الجبال والمغاور مثل وحوش البرية","و لذلك سبحوا لمن يسر تطهير هيكله وفي ايديهم غصون ذات اوراق وافنان خضر وسعف","و رسموا رسما عاما على جميع امة اليهود ان يعيدوا هذه الايام في كل سنة","هكذا كانت وفاة انطيوكس الملقب بالشهير","و لنشرع الان في خبر ابن ذاك المنافق ونذكر ما كان من رزايا الحروب بالايجاز","انه لما استولى هذا على الملك فوض تدبير الامور الى ليسياس قائد القواد في بقاع سورية وفينيقية","و ذلك ان بطلماوس المسمى بمكرون عزم على ان ينصف اليهود مما كانوا فيه من الظلم واجتهد في معاملتهم بالسلم","فلذلك سعى به اصحابه الى اوباطور وكثر كلام الناس فيه بانه خائن لانه تخلى عن قبرس التي كان فيلوماطور قد استعمله عليها وانحاز الى انطيوكس الشهير واذ ذهبت عنه كرامة السلطان بلغ منه الكمد فقتل نفسه بسم","فولى جرجياس قيادة البلاد وشرع يجيش من الاجانب وناصب اليهود حربا متواصلة","و كذلك الادوميون الذين كانت لهم حصون ملائمة كانوا يرغمون اليهود ويقبلون المهاجرين من اورشليم ويتجهزون للحرب","فابتهل الذين مع المكابي وتضرعوا الى الله ان يكون لهم نصيرا ثم هجموا على حصون الادوميين","و اندفعوا عليها بشدة وامتلكوا مواضع منها وصدموا جميع الذين كانوا يقاتلون على السور وكل من اقتحمهم قتلوه فاهلكوا منهم عشرين الفا","و فر تسعة الاف منهم الى برجين حصينين جدا مجهزين بكل اسباب الدفاع","فخلف المكابي سمعان ويوسف وزكا وعددا من اصحابه كافيا لمحاصرتهما وانصرف الى مواضع اخرى كانت اشد اقتضاء له","غير ان الذين كانوا مع سمعان استغواهم حب المال فارتشوا من بعض الذين في البرجين وخلوا سبيلهم بعد ان اخذوا منهم سبعين الف درهم","فلما اخبر المكابي بما وقع جمع رؤساء الشعب وشكا ما فعلوا من بيع اخوتهم بالمال اذ اطلقوا اعدائهم عليهم","ثم قتل اولئك الخونة ومن فوره استولى على البرجين","و قرنت اسلحته بكل فوز على يده فاهلك في البرجين ما يزيد على عشرين الفا","ثم ان تيموتاوس الذي كان اليهود قد قهروه من قبل حشد جيشا عظيما من الغرباء وجمع من فرسان اسية عددا غير قليل ونزل على اليهودية نزول مستفتح قهرا","فعندما اقترب توجه اصحاب المكابي الى الابتهال الى الله وقد حثوا التراب على رؤوسهم وحزموا احقاءهم بالمسوح","و خروا عند رجل المذبح وابتهلوا اليه ان يكون راحما لهم ومعاديا لاعدائهم ومضايقا لمضايقيهم كما ورد في الشريعة","و لما فرغوا من الدعاء اخذوا السلاح وتقدموا حتى صاروا عن المدينة بمسافة بعيدة ولما قاربوا العدو وقفوا","و عند طلوع الشمس تلاحم الفريقان وهؤلاء متوكلون على الرب كفيلا بالفوز والنصر مع بسالتهم واولئك متخذون البأس قائدهم في الحروب","فلما اشتد القتال تراءى للاعداء من السماء خمسة رجال رائعي المنظر على خيل لها لجم من ذهب فجعل اثنان منهم يقدمان اليهود","و هما قد اكتنفا المكابي يحفزانه باسلحتهما ويقيانه الجراح وهم يرمون بالسهام والصواعق حتى عميت ابصارهم وجعلوا يخبطون ويتصرعون","فقتل عشرون الفا وخمس مئة ومن الفرسان ست مئة","و انهزم تيموتاوس الى الحصن المسمى بجازر وهو حصن منيع وكان تحت امرة كيراوس","فاستبشر اصحاب المكابي وحاصروا المعقل اربعة ايام","و ان الذين في داخله لثقتهم بمناعة المكان تمادوا في التجديف وافحشوا في الكلام","فلما كان صباح اليوم الخامس هجم عشرون فتى من اصحاب المكابي على السور وهم متقدون غيظا من التجاديف وطفقوا يذبحون ببسالة وتنمر كل من عرض امامهم","و عطف اخرون فتسلقوا الى الذين في الداخل واضرموا البرجين واحرقوا اولئك المجدفين احياء في النيران المتقدة","و كسر اخرون الابواب وادخلوا بقية الجيش فاستحوذوا على المدينة وكان تيموتاوس مستخفيا في جب فذبحوه هو وكيراوس اخاه وابلوفانيس","و بعد ذلك باركوا الرب بالنشيد والاعتراف على احسانه العظيم الى اسرائيل وتاييده لهم بالنصر"],["و بعد ذلك بزمان يسير اذ كانت هذه الحوادث قد شقت جدا ليسياس وكيل الملك وذي قرابته والمقلد تدبير الامور","جمع نحو ثمانين الفا والفرسان كلهم وزحف على اليهود زاعما انه يجعل المدينة مسكنا لليونانيين","و يجعل الهيكل موضعا للكسب كسائر معابد الامم ويعرض الكهنوت الاعظم للبيع سنة فسنة","غير متفكر في قدرة الله لكن متوكلا برعونة قلبه على ربوات الرجالة والوف الفرسان وفيلته الثمانين","فدخل اليهودية وبلغ الى بيت صور وهي موضع منيع على نحو خمس غلوات من اورشليم وضايقها","فلما علم اصحاب المكابي انه يحاصر الحصون ابتهلوا الى الرب مع الجموع بالنحيب والدموع ان يرسل ملاكه الصالح لخلاص اسرائيل","ثم اخذ المكابي سلاحه اولا وحرض الاخرين على الاقتحام معه لنجدة اخوتهم","فاندفعوا متحمسين بقلب واحد وفيما هم بعد عند اورشليم تراءى فارس عليه لباس ابيض يتقدمهم وهو يخطر بسلاح من ذهب","فطفقوا باجمعهم يباركون الله الرحيم وتشجعوا في قلوبهم حتى كانوا مستعدين ان يبطشوا باضرى الوحوش فضلا عن الناس ويخترقوا الاسوار الحديدية","و اخذوا يتقدمون بانتظام وقد اتتهم السماء نصرة والرب رحمة","و حملوا على الاعداء حملة الاسود وصرعوا منهم احد عشر الفا ومن الفرسان الفا وست مئة","و الجاوا سائرهم الى الفرار وكان اكثر الذين نجوا بانفسهم جرحى عراة وانهزم ليسياس اقبح هزيمة","و اذ كان الرجل صاحب دهاء اخذ يفكر فيما اصابه من الخسران وفطن ان العبرانيين قوم لا يقهرون لان الله القدير مناصر لهم فراسلهم","و وعد بانه يسلم بكل ما هو حق ويستميل الملك الى موالاتهم","فرضي المكابي بكل ما سال ليسياس ابتغاء لما هو انفع وكل ما طلب المكابي من ليسياس بالكتابة ان يقضى لليهود قضاه الملك","و هذا نص الرسائل التي كتب بها ليسياس الى اليهود من ليسياس الى شعب اليهود سلام","قد سلم الينا يوحنا وابشالوم الموجهان من قبلكم كتاب جوابكم وسالا قضاء فحواه","فشرحت للملك ما ينبغي انهاؤه اليه فامضى منه ما تحتمله الحال","و ان بقيتم على الاخلاص فيما بيننا من الامور فاني اتوخى ان اكون لكم فيما ياتي سببا للخير","و اما تفصيل الامور فقد اوصيناهما مع من نحن مرسلون من قبلنا ان يفاوضوكم فيه","و السلام في السنة المئة والثامنة والاربعين في الرابع والعشرين من شهر ديوس كورنتي","و هذه صورة رسالة الملك من الملك انطيوكس الى اخينا ليسياس سلام","انا منذ انتقل والدنا الى الالهة لم يزل همنا ان يكون اهل مملكتنا بغير بلبال منقطعين الى شؤونهم","و اذ قد بلغنا ان اليهود غير راضين بما امرهم والدنا من التحول الى سنن اليونان لكنهم متمسكون بمذهبهم ولذلك يسالون انتباح لهم سننهم","و نحن نريد لهذا الشعب ان يكون كغيره خاليا عن البلبال فانا نحكم بان يرد لهم الهيكل وان يساسوا بمقتضى عادات ابائهم","فاذا ارسلت اليهم وعاقدتهم ليطمئنوا اذا علموا راينا فيهم ويقبلوا على مصالحهم بارتياح فنعما تفعل","و هذه رسالة الملك الى الامة من الملك انطيوكس الى مشيخة اليهود وسائر اليهود سلام","ان كنتم في خير فهذا ما نحب ونحن ايضا في عافية","قد اطلعنا منلاوس انكم تودون ان تنزلوا فتقيموا مع قومكم","فالذين يرتحلون الى اليوم الثلاثين من شهر كسنتكس يكونون في امان","و قد ابحنا لليهود اطعمتهم وشرائعهم كما كانوا عليه من قبل وكل من هفا منهم فيما سلف فلا اعنات عليه","و انا مرسل اليكم منلاوس ليشافهكم","و السلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس","و ارسل الرومانيون اليهم رسالة هذه صورتها من كونتس مميوس وتيطس منليوس رسولي الرومانيين الى شعب اليهود سلام","ما رخص لكم فيه ليسياس نسيب الملك نحن موافقون عليه","و ما استحسن ان يرفع الى الملك تشاوروا فيه وبادروا بارسال واحد لنقضي ما يوافقكم فانا متوجهان الى انطاكية","فعجلوا في ارسال من ترسلون لنكون على بصيرة مما تبتغون","و السلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس"],["و بعد ابرام هذه المواثيق انصرف ليسياس الى الملك واقبل اليهود على حرث اراضيهم","الا ان القواد الذين في البلاد وهم تيموتاوس وابلونيوس بن جنايوس وايرونيمس وديمفون وكذلك نكانور حاكم قبرس لميدعوا لهم راحة ولا سكينة","و اتى اهل يافا اغتيالا فظيعا وذلك انهم دعوا اليهود المساكنين لهم ان يركبوا هم ونساؤهم واولادهم قوارب كانوا اعدوها لهم كان لا عداوة بينهم","و اذ كان ذلك باجماع اهل المدينة كلهم رضي به اليهود وهم واثقون منهم بالاخلاص وغير متهمين لهم بسوء فلما امعنوا في البحر اغرقوهم وكان عددهم يبلغ المئتين","فلما بلغ يهوذا ما وقع على بني امته من الغدر الوحشي نادى فيمن معه من الرجال ودعا الله الديان العادل","و سار على الذين اهلكوا اخوته واضرم النار في المرفا ليلا واحرق القوارب وقتل الذين فروا الى هناك","و لما كانت المدينة مغلقة انصرف في نية الرجوع ومحو دولة اليافيين من اصلها","لكن لما علم ان اهل يمنيا ناوون ان يصنعوا بمساكنيهم من اليهود مثل ذلك","نزل على اهل يمنيا ليلا واحرق المرفا مع الاسطول حتى رؤى ضوء النار من اورشليم على بعد مئتين واربعين غلوة","ثم ساروا من هناك تسع غلوات زاحفين على تيموتاوس فتصدى لهم قوم من العرب يبلغون خمسة الاف ومعهم خمس مئة فارس","فاقتتلوا قتالا شديدا وكان الفوز لاصحاب يهوذا بنصرة الله فانكسر عرب البادية وسالوا يهوذا ان يعاقدهم على ان يؤدوا اليهم مواشي ويمدوهم بمنافع اخرى","و لم يشك يهوذا انه يحصل منهم على جدوى طائلة فرضي بمصالحتهم فعاقدهم فانصرفوا الى اخبيتهم","ثم اغار على مدينة حصينة ممنعة بالجسور والاسوار يسكتها لفيف من الامم اسمها كسفيس","و اذ كان الذين فيها واثقين بمناعة الاسوار ووفرة الميرة اخذوا الامر بالتهاون وطفقوا يشتمون اصحاب يهوذا ويجدفون وينطقون بما لا يحل","فدعا اصحاب يهوذا رب العالمين العظيم الذي اسقط اريحا على عهد يشوع بغير كباش ولا مجانيق ثم وثبوا على السور كالاسود","و فتحوا المدينة بمشيئة الله وقتلوا من الخلق ما لا يحصى حتى ان البحيرة التي هناك وعرضها غلوتان امتلات وطفحت بالدماء","ثم ساروا من هناك مسيرة سبع مئة وخمسين غلوة حتى انتهوا الى الكرك الى اليهود الذين يعرفون بالطوبيين","فلم يظفروا بتيموتاوس في تلك المواضع لانه كان قد انصرف عنها دون ان يصنع شيئا لكنه ترك في بعض المواضع محرسا منيعا","فخرج دوسيتاوس وسوسيباتير من قواد المكابي واهلكا من الجند الذي تركه تيموتاوس في الحصن ما ينيف على عشرة الاف","و قسم المكابي جيشه فرقا واقامهما على الفرق وحمل على تيموتاوس وكان معه مئة وعشرون الف راجل والفان وخمس مئة فارس","فلما بلغ تيموتاوس مقدم يهوذا وجه النساء والاولاد وسائر الثقل الى مكان يسمى قرنيم وكان موضعا منيعا يصعب فتحه والاقدام عليه لانه محاط بالمضايق","و لما بدت اول فرقة من جيش يهوذا داخل الاعداء الرعب والرعدة اذ تراءى لهم من يرى كل شيء فبادروا المفر من كل وجه حتى انبعضهم كان يؤذي بعضا واصاب بعضهم بعضا بحد السيوف","و شد يهوذا في اثارهم يثخن في اولئك الكفرة حتى اهلك منهم ثلاثين الف رجل","و وقع تيموتاوس في ايدي اصحاب دوسيتاوس وسوسيباتير فطفق يتضرع اليهم بكل وسيلة ان يطلقواه حيا بحجة ان عنده كثيرين من ابائهم واخوتهم اذا هلك يخذلون","و اكد لهم العهد بضمانات كثيرة انه يطلقهم سالمين فخلوا سبيله لاجل خلاص اخوتهم","ثم اغار يهوذا على قرنيم وهيكل اترجتيس وقتل خمسة وعشرون الف نفس","و بعد انكسار اولئك وهلكتهم زحف يهوذا على عفرون احدى المدن الحصينة وكان يسكنها ليسياس وامم شتى وكان على اسوارها شبان من ذوي الباس يقاتلون بشدة ومعهم كثير من المجانيق والسهام","فدعا اصحاب يهوذا القدير الذي يحطم باس العدو بشدة فاخذوا المدينة وصرعوا من الذين في داخلها خمسة وعشرين الفا","ثم ارتحلوا من هناك وهجموا على مدينة بيت شان وهي على ست مئة غلوة من اورشليم","الا ان اليهود المقيمين هناك شهدوا بان اهل بيت شان مصافون لهم وانهم عاملوهم بالاحسان في ازمنة الضيق","فشكروهم على صنيعهم واوصوهم ان لا يزالوا معهم على المصافاة ثم جاءوا اورشليم لقرب عيد الاسابيع","و بعد العيد المعروف بعيد الخمسين اغاروا على جرجياس قائد ارض ادوم","فبرز اليهم في ثلاثة الاف راجل واربع مئة فارس","و اقتتل الفريقان فسقط من اليهود نفر قليل","و كان فيهم فارس ذو باس يقال له دوسيتاوس من رجال بكينور فادرك جرجياس وقبض على ثوبه واجتذبه بقوة يريد ان ياسر ذلك المنافق حيا فعدا عليه فارس من التراكيين وقطع كتفيه وفر جرجياس الى مريشة","و تمادى القتال على اصحاب اسدرين حتى كلوا فدعا يهوذا الرب لياخذ بنصرتهم ويقاتل في مقدمتهم","و جعل يهتف بالاناشيد بلسان ابائه ثم صرخ وحمل على اصحاب جرجياس بغتة وكسرهم","ثم جمع يهوذا جيشه وسار به الى مدينة عدلام ولما كان اليوم السابع تطهروا بحسب العادة وقضوا السبت هناك","و في الغد جاء يهوذا ومن معه على ما تقتضيه السنة ليحملوا جثث القتلى ويدفنوهم مع ذوي قرابتهم في مقابر ابائهم","فوجدوا تحت ثياب كل واحد من القتلى انواطا من اصنام يمنيا مما تحرمه الشريعة على اليهود فتبين للجميع ان ذلك كان سبب قتلهم","فسبحوا كلهم الرب الديان العادل الذي يكشف الخفايا","ثم انثنوا يصلون ويبتهلون ان تمحى تلك الخطيئة المجترمة كل المحو وكان يهوذا النبيل يعظ القوم ان ينزهوا انفسهم عن الخطيئة اذ راوا بعيونهم ما اصاب الذي سقطوا لاجل الخطيئة","ثم جمع من كل واحد تقدمة فبلغ المجموع الفي درهم من الفضة فارسلها الى اورشليم ليقدم بها ذبيحة عن الخطيئة وكان ذلك من احسن الصنيع واتقاه لاعتقاده قيامة الموتى","لانه لو لم يكن مترجيا قيامة الذين سقطوا لكانت صلاته من اجل الموتى باطلا وعبثا","و لاعتباره ان الذين رقدوا بالتقوى قد ادخر لهم ثواب جميل","و هو راي مقدس تقوي ولهذا قدم الكفارة عن الموتى ليحلوا من الخطيئة"],["في السنة المئة والتاسعة والاربعين بلغ اصحاب يهوذا ان انطيوكس اوباطور قادم على اليهودية بجيش كثيف","و معه ليسياس الوكيل وقيم المصالح ومعهما جيش من اليونان مؤلف من مئة وعشرة الاف راجل وخمسة الاف وثلاث مئة فارس واثنين وعشرين فيلا وثلاث مئة عجلة ذات مناجل","فانضم اليهم منلاوس وجعل يحرض انطيوكس بكل نوع من المؤالسة غير مبال بخلاص الوطن بل كان همه ان يرد الى الرئاسة","و لكن ملك الملوك هيج سخط انطيوكس على ذلك الكافر فان ليسياس اشربه ان الرجل كان هو السبب في تلك النوازل باسرها فامر بان يذهب به الى بيرية ليقتل على عادة البلاد","و هناك برج علوه خمسون ذراعا مملوء رمادا وفيه الة مستديرة تهوي براكبها من جميع جهاتها الى الرماد","ففي ذلك الموضع اهلك ذلك المختاس للهيكل الذي كان سببا لشرور شتى مدفوعا اليه بايدي الجميع","و بهذه المنية هلك منلاوس المنافق ولم يحصل على تربة يوارى فيها","و كان ذلك بكل عدل فانه اذ كان قد اجترم جرائم كثيرة على المذبح الذي ناره ورماده مطهران ذاق منيته في الرماد","و اما الملك فما زال متقدما بعتوه وقساوته متوعدا اليهود بامر من البلايا التي انزلها بهم ابوه","فلما علم يهوذا بذلك امر الشعب بالابتهال الى الرب نهارا وليلا ان ينصرهم في ذلك اليوم كما كان يفعل من قبل","اذ قد اشرفوا على اضمحلال الشريعة والوطن والهيكل المقدس وان لا يدع الامم المجدفة تذل شعبه الذي لم يفرج عنه الا من امديسير","ففعلوا كلهم وتضرعوا الى الرب الرحيم بابكاء والصوم والسجود مدة ثلاثة ايام بلا انقطاع ثم حرضهم يهوذا وامرهم بالاجتماع","و خلا بالشيوخ وابرم معهم مشورة ان يخرجوا ويقضوا الامر بتاييد الرب قبل ان يدخل جيش الملك اليهودية ويستحوذ على المدينة","ففوض الامر الى خالق الكائنات وحض اصحابه ان يقاتلوا ببسالة ويبذلوا انفسهم دون الشريعة والهيكل والمدينة والوطن والدولة ونصب محلته عند مودين","و جعل لهم كلمة السر النصر بالله ثم اختار قوما من نخب الشبان وهجم ليلا على مخيم الملك في المحلة وقتل اربعة الاف رجل واهلك اول الفيلة مع القوم الذين كانوا في برجه","و ملاوا المحلة رعبا واضطرابا وانقلبوا فائزين بوقاية الرب التي كانت تكتنفه","و تمت له هذه النصرة عند طلوع الفجر","فلما ذاق الملك ما عند اليهود من البطش عمد الى اخذ المعاقل بالحيلة","فحاصر بيت صور وهي محرس منيع ليهود فانكسر وارتد منكوسا خاسرا","و كان يهوذا يمد الذين فيها بما يحتاجون اليه","و ان رجلا من جيش اليهود اسمه رودكس كاشف العدو باسرارهم فطلبوه وقبضوا عليه وسجنوه","فعاد الملك وخاطب اهل بيت صور وعرض عليهم الصلح فعاقدوه وانصرف","و بعد ان قاتل يهوذا وانكسر بلغه ان فيلبس الذي كان قد ترك في انطاكية لتدبير الامور قد تمرد عليه فوقع في حيرة وتوسل الى اليهود ودان لهم وحالفهم على اعطاء حقوقهم كلها وسالمهم وقدم ذبيحة واكرم الهيكل واحسن الى الموضع","و صافى المكابي ونصبه قائدا وحاكما على البلاد من بطلمايس الى حدود الجرانيين","ثم جاء الى بطلمايس وكان اهل المدينة قد شق عليهم ذلك العهد وانكروا عليه فسخ عهودهم","فانطلق ليسياس الى الديوان واورد ما استطاع من الحجج فاقنعهم وسكنهم وميلهم الى الرفق ثم عاد الى انطاكية وهكذا انقضى مقدم الملك ورجوعه"],["و بعد مدة ثلاث سنين بلغ اصحاب يهوذا ان ديمتريوس بن سلوقس قد ركب البحر من ميناء طرابلس بجيش كثيف واسطول","و استولى على البلاد بعد ما قتل انطيوكس وليسياس وكيله","و ان الكيمس الذي كان قد قلد الكهنوت الاعظم ثم انقاد الى النجاسة ايام الاختلاط ايقن ان لا خلاص له البتة ولا سبيل الى ارتقاء المذبح المقدس","فاتى ديمتريوس الملك في السنة المئة والحادية والخمسين واهدى اليه اكليلا من ذهب وسعفة واغصانا من زيتون مما يختص بالهيكل وبقي في ذلك اليوم ساكتا","ثم اصاب فرصة توافق رعونة مقاصده فان ديمتريوس دعاه الى ديوانه وساله عن احوال اليهود وما في نياتهم","فقال ان الحسيديين من اليهود الذين عليهم يهوذا المكابي لا يزالون في الحروب والفتن ولا يدعون للملكة راحة","و هاءنذا قد سلبت كرامة ابائي اعني الكهنوت الاعظم فقدمت الى هنا","اولا لاوفي خدمتي فيما ياول الى مصلحة الملك وثانيا للسعي في مصلحة قومي لان سفه اولئك الناس قد انزل بامتنا البلاء الشديد","فاذ قد اطلعت ايها الملك على تفصيل ذلك فالتفت الى بلادنا وامتنا المبغي عليها بما فيك من الرفق والاحسان الى الجميع","فانه ما دام يهوذا باقيا فمن المحال ان تكون الاحوال في دعة","و لما اتم مقاله جعل سائر اصدقاء ديمتريوس وهم اعداء ليهوذا ويوغرونه عليه","فاستحضر من ساعته نكانور مدبر الفيلة واقامه قائدا على اليهودية وارسله","و امره ان يقتل يهوذا ويبدد اصحابه ويقيم الكيمس كاهنا اعظم للهيكل الشهير","فاخذ الامم الذين في اليهودية يفرون عن يهوذا وينضمون افواجا الى نكانور وهم يعدون نكبات اليهود ورزاياهم حظا لهم","و لما بلغ اليهود قدوم نكانور وانضمام الامم اليه حثوا التراب على رؤوسهم وابتهلوا الى الذي اقام شعبه ليبقى مدى الدهر مدافعا عن ميراثه بايات بينة","ثم امرهم القائد فبادروا المسير من هناك والتقوهم عند قرية دساو","و كان سمعان اخو يهوذا قد نازل نكانور فجاءته نجدة على حين بغتة فادركه بعض الفشل","و لكن لما سمع نكانور بما ابداه اصحاب يهوذا من الباس والبسالة في مدافعاتهم عن الوطن اشفق من ان يفصل الامر بالسلاح","فارسل بوسيدونيوس وتاودوتس ومتتيا لعرض الصلح وامضائه","فبحثوا في الامر طويلا وعرض القائد ذلك على الجمهور فاجمعوا كلهم على راي واحد وقبلوا العهد","و عينوا يوما يواجهونهم فيه سرا فاقبل نكانور وجيء بالكراسي من الجانبين","و اقام يهوذا رجالا متسلحين متاهبين في المواضع الموافقة مخافة ان يدهمهم الاعداء بشر ثم تفاوضوا وعقدوا الاتفاق","و اقام نكانور باورشليم لا ياتي منكرا واطلق الجيوش التي اجتمعت اليه افواجا","و كان كثير التردد الى يهوذا وصبا اليه بقلبه","و حثه على الزواج والاستيلاد فتزوج ولبث في راحة وطيب عيش","و لما راى الكيمس ما هما فيه من التصافي والتعاهد عاد فاتى الى ديمتريوس وقال ان نكانور يرى في الامور راي الفساد وانه قد عين في موضعه يهوذا الكامن للملكة كاهنا اعظم","فاستشاط الملك غضبا ووغر صدره بسعاية ذلك الفاجر فكتب الى نكانور يقول انه ساخط من ذلك العهد ويامره بان يبادر الى ارسال المكابي مقيدا الى انطاكية","فلما وقف نكانور على ذلك ادركته الحيرة وصعب عليه ان ينقض عهده ولم ير من الرجل ظلما","و لكن اذ لم يجد سبيلا الى مقاومة الملك تربص فرصة ليمضي الامر بالمكيدة","و راى المكابي ان نكانور قد تغير عليه ولم يعد يتلقاه ببشاشته المالوفة ففطن ان هذا التغير ليس عن خير فجمع عددا من اصحابه وتغيب عن نكانور","فلما راى نكانور ان الرجل قد سبقه بحزمه ودهائه انطلق الى الهيكل العظيم المقدس وكان الكهنة يقدمون الذبائح على عادتهم فامرهم ان يسلموا اليه الرجل","فاقسموا وقالوا انهم لا يعلمون اين الذي يطلبه فمد يمينه على الهيكل","و اقسم قائلا لئن لم تسلموا الي يهوذا موثقا لاهدمن بيت الله هذا الى الارض ولاقلعن المذبح واشيدن هنا هيكلا شهيرا لديونيسيوس","قال هذا وانصرف فرفع الكهنة ايديهم الى السماء ودعوا من هو نصير امتنا على الدوام قائلين","يا من هو رب الجميع الغني عن كل شيء لقد حسن لديك ان يكون هيكل سكناك فيما بيننا","فالان ايها الرب يا قدوس كل قداسة صن هذا البيت الذي قد طهر عن قليل واحفظه طاهرا الى الابد","و كان في اورشليم شيخ اسمه رازيس وهو رجل محب لوطنه محمود السمعة يسمى بابي اليهود لما كان عنده من الغيرة عليهم فوشي به الى نكانور","و كان فيما سلف من ايام الاختلاط مخلص التمسك بدين اليهود ولم يزل يبذل جسمه ونفسه في سبيل الدين","و اراد نكانور ان يبدي ما كان عنده من الحنق على اليهود فارسل اكثر من خمس مئة جندي ليقبضوا عليه","لاعتقاده انه ان امسكه فقد انزل بهم مصيبة عظيمة","فلما راى الجنود قد اوشكوا ان يستولوا على البرج ويفتحوا باب الدار وقد اطلقوا النار لاحراق الابواب واصبح محاطا من كل جانب وجا نفسه بالسيف","و اختار ان يموت بكرامة ولا يصير في ايدي المجرمين ويشتم بما لا يليق باصله الكريم","و لكنه لعجلته اخطا المقتل واذ كانت الجنود قد هجمت الى داخل الابواب رقي الى السور بقلب جليد والقى بنفسه من فوق الجنود","فانفرجوا لحينهم فسقط في وسط الفرجة","و اذ كان به رمق وقد اشتعلت فيه الحمية قام ودمه يتفجر كالينبوع وجراحه بالغة واخترق الجنود عدوا","و استولى قائما على صخرة عالية وقد نزف دمه ثم اخرج امعاءه وحملها بيديه وطرحها على الجند ودعا رب الحياة والروح ان يردهما عليه ثم فاضت نفسه"],["و بلغ نكانور ان اصحاب يهوذا في نواحي السامرة فعزم على مفاجاته يوم السبت دون تعرض لخطر الحرب","فقال له اليهود الذين شايعوه اضطرارا لا تاخذ القوم بهذه القسوة والخشونة بل ارع حرمة يوم قد اكرمه وقدسه الرقيب على كل شيء","فسال ذلك الفاجر وهل في السماء قدير امر بحفظ يوم السبت","فقالوا ان في السماء الرب الحي القدير وهو الذي اوصى بحفظ اليوم السابع","فقال الرجل وانا ايضا قدير في الارض فامر باخذ السلاح وامضاء اوامر الملك ولكنه لم يتمكن من قضاء ماربه الخبيث","و كان نكانور بما عنده من الزهو والصلف مضمرا ان ينصب تذكارا يشير به الى جميع غلباته على اصحاب يهوذا","و اما المكابي فلم يزل يثق كل الثقة بان الرب سيؤتيه النصر","فحرض اصحابه ان لا يجزعوا من غارة الامم بل يذكروا النجدات التي طال ما امدوا بها من السماء وينتظروا الظفر والنصرة التي سيؤتونها من عند القدير","ثم كلمهم عن الشريعة والانبياء وذكر لهم الوقائع التي باشروها حتى اذكى حماستهم","و بعدما ثبت عزائمهم شرح لهم كيف نقضت الامم عهودها وحنثت بايمانها","و سلح كلا منهم بتعزية كلامه الصالح اكثر مما سلحهم بالتروس والرماح ثم قص عليهم رؤيا يقينية تجلت له في الحلم فشرح بها صدورهم اجمعين","و هذه هي الرؤيا قال رايت اونيا الكاهن الاعظم رجل الخير والصلاح المهيب المنظر الحليم الاخلاق صاحب الاقوال الرائعة المواظب منذ صبائه على جميع ضروب الفضائل باسطا يديه ومصليا لاجل جماعة اليهود باسرها","ثم تراءى لي رجل كريم الشيبة اغر البهاء عليه جلالة عجيبة سامية","فاجاب اونيا وقال هذا محب الاخوة المكثر من الصلوات لاجل الشعب والمدينة المقدسة ارميا نبي الله","ثم ان ارميا مد يمينه وناول يهوذا سيفا من ذهب وقال","خذ هذا السيف المقدس هبة من عند الله به تحطم الاعداء","فطابت قلوبهم باقوال يهوذا الصالحة التي حركت بقوتها حماستهم واثارت نفوس الشبان وعقدوا عزمهم على ان لا يعسكروا بل يهجموا بشجاعة ويحاربوا بكل بسالة حتى يفصلوا الامر اذ كانت المدينة والاقداس والهيكل في خطر","و كان اضطرابهم على النساء والاولاد والاخوة وذوي القرابات ايسر وقعا من خوفهم على الهيكل المقدس الذي كان هو الخوف الاعظم والاول","و كان الباقون في المدينة في اضطراب شديد من قبل القتال الذي كانوا يتوقعونه في الفضاء","و بينا كان الجميع ينتظرون ما ياول اليه الامر وقد ازدلف العدو واصطف الجيش واقيمت الفيلة في مواضعها وترتبت الفرسان على الجناحين","تفرس المكابي في كثرة الجيوش وتوفر الاسلحة المختلفة وضراوة الفيلة فرفع يديه الى السماء ودعا الرب الرقيب صانع المعجزات لعلمه ان ليس الظفر بالسلاح ولكنه بقضائه يؤتي الظفر من يستحقه","و صلى قائلا انك يا رب قد ارسلت ملاكك في عهد حزقيا ملك يهوذا فقتل من جند سنحاريب مئة وخمسة وثمانين الفا","و الان يا ملك السماوات ارسل ملاكا صالحا امامنا يوقع الرعب والرعدة وبعظمة ذراعك","ليتروع الذين وافوا على شعبك المقدس مجدفين وكان يهوذا يصلي هكذا","و اصحاب نكانور يتقدمون بالابواق والاغاني","فواقعهم اصحاب يهوذا بالدعاء والصلوات","و فيما هم يقاتلون بالايدي كانوا يصلون الى الله في قلوبهم فصرعوا خمسة وثلاثين الفا وهم في غاية التهلل بمحضر الله ونصرته","و لما فرغوا من الجهاد ورجعوا مبتهجين وجدوا نكانور بسلاحه وقد خر قتيلا","حينئذ ارتفع الهتاف والزجل وسبحوا الملك العظيم بلسان ابائهم","ثم ان يهوذا الذي لم يزل في مقدمة اهل وطنه باذلا دونهم جسده ونفسه وراعيا لبني امته المودة التي اثرهم بها منذ حداثته امر بقطع راس نكانور ويده مع كتفه وحملهما الى اورشليم","و لما بلغ الى هناك دعا بني امته والكهنة وقام امام المذبح واستحضر الذين في القلعة","و اراهم راس نكانور الفاحش ويد ذلك الفاجر التي مدها متجبرا على بيت القدير المقدس","ثم قطع لسان نكانور المنافق وامر بان يقطع قطعا ويطرح الى الطيور وتعلق يد ذلك الاحمق تجاه الهيكل","و كان الجميع يباركون الى السماء الرب الحاضر لنصرتهم قائلين تبارك الذي حفظ موضعه من كل دنس","و ربط راس نكانور على القلعة ليكون دليلا بينا جليا على نصرة الله","ثم رسم الجميع بتوقيع عام ان لا يترك ذلك اليوم بدون احتفال","بل يكون عيدا وهو اليوم الثالث عشر من الشهر الثاني عشر الذي يقال له اذار بلسان ارام قبل يوم مردكاي بيوم واحد","هذا ما تم من امر نكانور ومنذ تلك الايام عادت المدينة في حوزة العبرانيين وههنا انا ايضا اجعل ختام الكلام","فان كنت قد احسنت التاليف واصبت الغرض فذلك ما كنت اتمنى وان كان قد لحقني الوهن والتقصير فاني قد بذلت وسعي","ثم كما ان اشرب الخمر وحدها او شرب الماء وحده مضر وانما تطيب الخمر ممزوجة بالماء وتعقب لذة وطربا كذلك تنميق الكلام على هذا الاسلوب يطرب مسامع مطالعي التاليف . انتهى ."]]}]};
